INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36820, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母に新しい道が教えてもらった。", "corrected_sentence": "母に新しい道を教えてもらった。", "error_description": "「教える」は目的語に「を」をとる。「道が」は誤りで、正しくは「道を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "教えて", "is_correct": true, "explanation": "「時間を教えてくれた」で、て形に「くれた」が続く形。"}, {"text": "教えた", "is_correct": false, "explanation": "過去形だけでは「くれた」と続かず、授受の文の形にならない。"}, {"text": "教えない", "is_correct": false, "explanation": "否定形にすると教えなかったという意味になり、文の内容と逆になる。"}, {"text": "教えられる", "is_correct": false, "explanation": "受身形にすると教えてもらう側の行為になり、文の主語と合わない。"}], "correct_form": "教えて", "base_form": "教える", "form_label": "て形", "sentence_index": 1, "explanations": {"教えて": "「時間を教えてくれた」で、て形に「くれた」が続く形。", "教えた": "過去形だけでは「くれた」と続かず、授受の文の形にならない。", "教えない": "否定形にすると教えなかったという意味になり、文の内容と逆になる。", "教えられる": "受身形にすると教えてもらう側の行為になり、文の主語と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36820, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友達が駅までの道を教えくれた。", "corrected_sentence": "友達が駅までの道を教えてくれた。", "error_description": "「教えてくれた」の「て」が抜けている。て形が必要なので、正しくは「教えてくれた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "教えて", "is_correct": true, "explanation": "「住所を教えてもらった」で、て形に「もらった」が続く形。"}, {"text": "教えます", "is_correct": false, "explanation": "丁寧形は「もらった」と続かず、後ろの普通体の文と合わない。"}, {"text": "教えよう", "is_correct": false, "explanation": "意志形は話し手の意向を表し、もらった出来事の文と合わない。"}, {"text": "教えず", "is_correct": false, "explanation": "連用否定は「教えないで」の意味になり、もらった事実と逆になる。"}], "correct_form": "教えて", "base_form": "教える", "form_label": "て形", "sentence_index": 7, "explanations": {"教えて": "「住所を教えてもらった」で、て形に「もらった」が続く形。", "教えます": "丁寧形は「もらった」と続かず、後ろの普通体の文と合わない。", "教えよう": "意志形は話し手の意向を表し、もらった出来事の文と合わない。", "教えず": "連用否定は「教えないで」の意味になり、もらった事実と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36821, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「つり方を教えてくれた」で、教える内容（目的語）を示す。"}, {"text": "に", "is_correct": false, "explanation": "「つり方に教えてくれた」は不自然。に は相手を示し、教える内容の位置には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「つり方で教えてくれた」は不自然。で は手段を示し、目的語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「つり方へ教えてくれた」は方向の意味になり、教える内容を示せない。"}], "correct_answer": "を", "explanations": {"を": "「つり方を教えてくれた」で、教える内容（目的語）を示す。", "に": "「つり方に教えてくれた」は不自然。に は相手を示し、教える内容の位置には合わない。", "で": "「つり方で教えてくれた」は不自然。で は手段を示し、目的語にはならない。", "へ": "「つり方へ教えてくれた」は方向の意味になり、教える内容を示せない。"}, "error_tags": {"に": "相手", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36821, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「英語を教える先生」で、教える内容（目的語）を示す。"}, {"text": "が", "is_correct": false, "explanation": "「英語が教える先生」は不自然。が は主語を示し、教える内容の位置には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「英語と教える先生」は並列の意味になり、目的語を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「英語に教える先生」は成り立たない。に は教える相手を示すが、ここは教える内容の位置。"}], "correct_answer": "を", "explanations": {"を": "「英語を教える先生」で、教える内容（目的語）を示す。", "が": "「英語が教える先生」は不自然。が は主語を示し、教える内容の位置には合わない。", "と": "「英語と教える先生」は並列の意味になり、目的語を示せない。", "に": "「英語に教える先生」は成り立たない。に は教える相手を示すが、ここは教える内容の位置。"}, "error_tags": {"が": "主語", "と": "並列", "に": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36821, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「教える」は、知識や方法を相手に伝えて、理解させたりできるようにしたりすること。", "primary_collocate": null, "pronunciation": "おしえる", "ipa": "oɕieɾɯ", "syllable_count": 4, "sentences": [{"text": "姉は小学生に算数を教える仕事をしている。", "target_word": "教える", "complexity_tier": "T3", "furigana": "姉[あね]は小学生[しょうがくせい]に算数[さんすう]を教[おし]える仕事[しごと]をしている。", "sentence_source": "generated"}, {"text": "祖父は私に魚のつり方を教えてくれた。", "target_word": "教えて", "complexity_tier": "T3", "furigana": "祖父[そふ]は私[わたし]に魚[さかな]のつり方[かた]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "先生は生徒たちに、漢字の書き方を丁寧に教えた。", "target_word": "教えた", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]たちに、漢字[かんじ]の書[か]き方[かた]を丁寧[ていねい]に教[おし]えた。", "sentence_source": "generated"}, {"text": "母は料理を教えるために、毎週教室を開いている。", "target_word": "教える", "complexity_tier": "T3", "furigana": "母[はは]は料理[りょうり]を教[おし]えるために、毎週[まいしゅう]教室[きょうしつ]を開[ひら]いている。", "sentence_source": "generated"}, {"text": "兄にピアノを教えてもらって、簡単な曲が弾けるようになった。", "target_word": "教えて", "complexity_tier": "T3", "furigana": "兄[あに]にピアノを教[おし]えてもらって、簡単[かんたん]な曲[きょく]が弾[ひ]けるようになった。", "sentence_source": "generated"}, {"text": "彼は大学で歴史を教えながら、本も書いている。", "target_word": "教えながら", "complexity_tier": "T3", "furigana": "彼[かれ]は大学[だいがく]で歴史[れきし]を教[おし]えながら、本[ほん]も書[か]いている。", "sentence_source": "generated"}, {"text": "父が自転車の乗り方を教えてくれたので、すぐ乗れた。", "target_word": "教えて", "complexity_tier": "T3", "furigana": "父[ちち]が自転車[じてんしゃ]の乗[の]り方[かた]を教[おし]えてくれたので、すぐ乗[の]れた。", "sentence_source": "generated"}, {"text": "英語を教える先生が、ゆっくり発音を直してくれた。", "target_word": "教える", "complexity_tier": "T3", "furigana": "英語[えいご]を教[おし]える先生[せんせい]が、ゆっくり発音[はつおん]を直[なお]してくれた。", "sentence_source": "generated"}, {"text": "新人に仕事のやり方を教えるのは、時間がかかる。", "target_word": "教える", "complexity_tier": "T3", "furigana": "新人[しんじん]に仕事[しごと]のやり方[かた]を教[おし]えるのは、時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "先輩がパソコンの使い方を教えてくれたおかげで、仕事が早くなった。", "target_word": "教えて", "complexity_tier": "T3", "furigana": "先輩[せんぱい]がパソコンの使[つか]い方[かた]を教[おし]えてくれたおかげで、仕事[しごと]が早[はや]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教えて", "label": "て形"}, {"form": "教えた", "label": "過去形"}, {"form": "教えない", "label": "否定形"}, {"form": "教えられる", "label": "受身形"}], "register": "neutral（普通体）", "sense_fingerprint": "知識や技術ややり方を相手が身につけられるように伝える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52abfa19-f32b-4331-8603-e7d9dc026dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36821, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教える", "is_correct": true, "explanation": "「算数を教える仕事」で、知識を相手が身につけられるように伝えるという意味に合う。"}, {"text": "運ぶ", "is_correct": false, "explanation": "「算数を運ぶ」は成り立たない。運ぶは物の移動で、知識には使わない。"}, {"text": "洗う", "is_correct": false, "explanation": "「算数を洗う」は成り立たない。洗うは汚れを落とす動作で、知識には使わない。"}, {"text": "売る", "is_correct": false, "explanation": "「算数を売る」は不自然。売るは物を金銭と交換する意味で、教える仕事の文脈に合わない。"}], "explanations": {"教える": "「算数を教える仕事」で、知識を相手が身につけられるように伝えるという意味に合う。", "運ぶ": "「算数を運ぶ」は成り立たない。運ぶは物の移動で、知識には使わない。", "洗う": "「算数を洗う」は成り立たない。洗うは汚れを落とす動作で、知識には使わない。", "売る": "「算数を売る」は不自然。売るは物を金銭と交換する意味で、教える仕事の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "教える"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は荷物を教えるために、毎週車を借りている。", "explanation": "〈運ぶ〉が合う。教えるは知識や技術を伝える語で、荷物は教える対象にならないので不自然。"}, {"text": "弟は魚を教えるために、毎朝港へ行く。", "explanation": "〈釣る〉など魚を扱う語が合う。教えるは知識や技術を伝える語で、魚は教える対象にならない。"}, {"text": "祖母は庭の花を教えるために、毎日水をやる。", "explanation": "〈育てる〉が合う。教えるは知識や技術を伝える語で、花には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36821, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教えて", "is_correct": true, "explanation": "「乗り方を教えてくれたので」で、乗り方を相手が身につけられるように伝えてもらったという意味に合う。"}, {"text": "預けて", "is_correct": false, "explanation": "「乗り方を預けて」は成り立たない。預けるは物を保管させる意味で、技術には使わない。"}, {"text": "測って", "is_correct": false, "explanation": "「乗り方を測って」は不自然。測るは量を調べる動作で、技術の伝達とは関係しない。"}, {"text": "撮って", "is_correct": false, "explanation": "「乗り方を撮って」は不自然。撮るは写真や映像にする動作で、伝える文脈に合わない。"}], "explanations": {"教えて": "「乗り方を教えてくれたので」で、乗り方を相手が身につけられるように伝えてもらったという意味に合う。", "預けて": "「乗り方を預けて」は成り立たない。預けるは物を保管させる意味で、技術には使わない。", "測って": "「乗り方を測って」は不自然。測るは量を調べる動作で、技術の伝達とは関係しない。", "撮って": "「乗り方を撮って」は不自然。撮るは写真や映像にする動作で、伝える文脈に合わない。"}, "sentence_index": 6, "correct_answer": "教えて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先輩は新人に靴を教えた。", "explanation": "〈貸す〉は物を一時的に相手に使わせること。教えるは情報や知識を伝える語で、物を貸す場面には使わない。"}, {"text": "先輩は新人の頭を教えた。", "explanation": "〈なでる〉は頭などに手を当てて軽く動かすこと。教えるは知識や情報を伝える語で、頭を撫でる行為には使わない。"}, {"text": "先輩は子どもを公園まで教えてくれたおかげで、仕事が早くなった。", "explanation": "〈案内〉は人を連れて行くこと。教えるは言葉で伝える語なので、人を連れていく場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36821, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は生徒に英語を教えるた。", "corrected_sentence": "先生は生徒に英語を教えた。", "error_description": "過去形は「教えた」が正しい。「教えるた」は動詞の活用形の誤りで、「る」を取って「た」をつける必要がある。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "教えて", "is_correct": true, "explanation": "「つり方を教えてくれた」で、て形に「くれた」が続く形。"}, {"text": "教えた", "is_correct": false, "explanation": "過去形だけでは「くれた」と続かず、授受の文の形にならない。"}, {"text": "教えない", "is_correct": false, "explanation": "否定形にすると教えなかったという意味になり、文の内容と逆になる。"}, {"text": "教えられる", "is_correct": false, "explanation": "受身形にすると教えてもらう側の行為になり、文の主語と合わない。"}], "correct_form": "教えて", "base_form": "教える", "form_label": "て形", "sentence_index": 1, "explanations": {"教えて": "「つり方を教えてくれた」で、て形に「くれた」が続く形。", "教えた": "過去形だけでは「くれた」と続かず、授受の文の形にならない。", "教えない": "否定形にすると教えなかったという意味になり、文の内容と逆になる。", "教えられる": "受身形にすると教えてもらう側の行為になり、文の主語と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36821, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社員に仕事のやり方が教えてくれた。", "corrected_sentence": "社員に仕事のやり方を教えてくれた。", "error_description": "「教える」は目的語に「を」をとる。「やり方が」は誤りで、正しくは「やり方を」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "教える", "is_correct": true, "explanation": "「英語を教える先生」で、後ろの名詞「先生」を修飾する辞書形。"}, {"text": "教えます", "is_correct": false, "explanation": "丁寧形は名詞を修飾できず、「先生」にかかる形として使えない。"}, {"text": "教えよう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、文の中で先生を説明する形にならない。"}, {"text": "教えず", "is_correct": false, "explanation": "連用否定は名詞を修飾できず、教えない先生という意味になり文の内容と異なる。"}], "correct_form": "教える", "base_form": "教える", "form_label": "辞書形", "sentence_index": 7, "explanations": {"教える": "「英語を教える先生」で、後ろの名詞「先生」を修飾する辞書形。", "教えます": "丁寧形は名詞を修飾できず、「先生」にかかる形として使えない。", "教えよう": "意志形は名詞を修飾できず、文の中で先生を説明する形にならない。", "教えず": "連用否定は名詞を修飾できず、教えない先生という意味になり文の内容と異なる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
