INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36822, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "あまい あじが する こと。", "primary_collocate": null, "pronunciation": "あまい", "ipa": "amai", "syllable_count": 3, "sentences": [{"text": "これは甘い。", "target_word": "甘い", "complexity_tier": "T1", "furigana": "これは甘[あま]い。", "sentence_source": "generated"}, {"text": "りんごが甘い。", "target_word": "甘い", "complexity_tier": "T1", "furigana": "りんごが甘[あま]い。", "sentence_source": "generated"}, {"text": "ジュースは甘くない。", "target_word": "甘く", "complexity_tier": "T1", "furigana": "ジュースは甘[あま]くない。", "sentence_source": "generated"}, {"text": "甘いパンを買いました。", "target_word": "甘い", "complexity_tier": "T2", "furigana": "甘[あま]いパンを買[か]いました。", "sentence_source": "generated"}, {"text": "このお茶は甘すぎます。", "target_word": "甘すぎ", "complexity_tier": "T2", "furigana": "このお茶[ちゃ]は甘[あま]すぎます。", "sentence_source": "generated"}, {"text": "昨日食べたケーキは甘かったです。", "target_word": "甘かった", "complexity_tier": "T2", "furigana": "昨日[きのう]食[た]べたケーキは甘[あま]かったです。", "sentence_source": "generated"}, {"text": "甘い物を食べすぎると、歯が痛くなる。", "target_word": "甘い", "complexity_tier": "T4", "furigana": "甘[あま]い物[もの]を食[た]べすぎると、歯[は]が痛[いた]くなる。", "sentence_source": "generated"}, {"text": "甘くておいしいみかんをもらった。", "target_word": "甘くて", "complexity_tier": "T3", "furigana": "甘[あま]くておいしいみかんをもらった。", "sentence_source": "generated"}, {"text": "砂糖を入れすぎて、スープが甘くなった。", "target_word": "甘く", "complexity_tier": "T3", "furigana": "砂糖[さとう]を入[い]れすぎて、スープが甘[あま]くなった。", "sentence_source": "generated"}, {"text": "もっと甘ければ、娘も食べるだろう。", "target_word": "甘ければ", "complexity_tier": "T4", "furigana": "もっと甘[あま]ければ、娘[むすめ]も食[た]べるだろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "甘かった", "label": "活用"}, {"form": "甘くない", "label": "活用"}, {"form": "甘さ", "label": "派生"}, {"form": "甘み", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 砂糖のようなあまい味がすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6ab7e1-b183-4ad7-bb07-3e9856366fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36822, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "甘い", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "浅い", "is_correct": false, "explanation": "「あさい」で二拍目が異なる。"}, {"text": "青い", "is_correct": false, "explanation": "「あおい」で二拍目が異なる。"}, {"text": "赤い", "is_correct": false, "explanation": "「あかい」で二拍目が異なる。"}], "explanations": {"甘い": "見出し語そのもの。", "浅い": "「あさい」で二拍目が異なる。", "青い": "「あおい」で二拍目が異なる。", "赤い": "「あかい」で二拍目が異なる。"}, "sentence_index": null, "correct_answer": "甘い"}, "level_3": {"options": [{"text": "甘い", "is_correct": true, "explanation": "「これは」の述語として味を表す。"}, {"text": "眠い", "is_correct": false, "explanation": "形は合うが意味が合わない。物を指して眠いとは言えない。"}, {"text": "忙しい", "is_correct": false, "explanation": "形は合うが意味が合わない。物を指して忙しいとは言えない。"}, {"text": "若い", "is_correct": false, "explanation": "形は合うが意味が合わない。食べ物の性質として不自然。"}], "explanations": {"甘い": "「これは」の述語として味を表す。", "眠い": "形は合うが意味が合わない。物を指して眠いとは言えない。", "忙しい": "形は合うが意味が合わない。物を指して忙しいとは言えない。", "若い": "形は合うが意味が合わない。食べ物の性質として不自然。"}, "sentence_index": 0, "correct_answer": "甘い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この道は甘くて歩きにくい。", "explanation": "「甘い」は砂糖のような味を表し、道の状態には使えない。"}, {"text": "甘い犬が庭を走っている。", "explanation": "味を表す「甘い」は犬の形容に使えない。"}, {"text": "窓の甘いガラスを拭いた。", "explanation": "ガラスは味の対象ではなく、「甘い」と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36822, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "甘い", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "荒い", "is_correct": false, "explanation": "「あらい」で二拍目が異なる。"}, {"text": "暑い", "is_correct": false, "explanation": "「あつい」で二拍目が異なる。"}, {"text": "値", "is_correct": false, "explanation": "「あたい」で二拍目が異なる。"}], "explanations": {"甘い": "見出し語そのもの。", "荒い": "「あらい」で二拍目が異なる。", "暑い": "「あつい」で二拍目が異なる。", "値": "「あたい」で二拍目が異なる。"}, "sentence_index": null, "correct_answer": "甘い"}, "level_3": {"options": [{"text": "甘い", "is_correct": true, "explanation": "食べすぎると歯が痛くなる物の性質として合う。"}, {"text": "眠い", "is_correct": false, "explanation": "形は合うが意味が合わない。「眠い物」を食べるとは言えない。"}, {"text": "若い", "is_correct": false, "explanation": "形は合うが意味が合わない。歯が痛くなる理由にならない。"}, {"text": "狭い", "is_correct": false, "explanation": "形は合うが意味が合わない。食べ物の性質として不自然。"}], "explanations": {"甘い": "食べすぎると歯が痛くなる物の性質として合う。", "眠い": "形は合うが意味が合わない。「眠い物」を食べるとは言えない。", "若い": "形は合うが意味が合わない。歯が痛くなる理由にならない。", "狭い": "形は合うが意味が合わない。食べ物の性質として不自然。"}, "sentence_index": 6, "correct_answer": "甘い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "甘い鉛筆で手紙を書いた。", "explanation": "鉛筆は味わうものではなく、「甘い」と合わない。"}, {"text": "その山は甘くて高い。", "explanation": "山の高さや様子に味の「甘い」は使えない。"}, {"text": "今日は空が甘いので傘を持っていく。", "explanation": "天気を味の「甘い」で表すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
