INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36823, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "味覚で、砂糖のように感じられること。", "primary_collocate": null, "pronunciation": "あまい", "ipa": "amai", "syllable_count": 3, "sentences": [{"text": "冷たくて甘いレモネードは、暑さに疲れた人々の喉を潤し、少年の努力は小さな売上となって確実に実を結んでいった。", "target_word": "甘い", "complexity_tier": "T6", "furigana": "冷[つめ]たくて甘[あま]いレモネードは、暑[あつ]さに疲[つか]れた人々[ひとびと]の喉[のど]を潤[うるお]し、少年[しょうねん]の努力[どりょく]は小[ちい]さな売上[うりあげ]となって確実[かくじつ]に実[み]を結[むす]んでいった。", "sentence_source": "mined"}, {"text": "このケーキは甘いです。", "target_word": "甘い", "complexity_tier": "T2", "furigana": "このケーキは甘[あま]いです。", "sentence_source": "generated"}, {"text": "甘いお菓子が好きだ。", "target_word": "甘い", "complexity_tier": "T1", "furigana": "甘[あま]いお菓子[かし]が好[す]きだ。", "sentence_source": "generated"}, {"text": "コーヒーに砂糖を入れたら甘くなった。", "target_word": "甘く", "complexity_tier": "T4", "furigana": "コーヒーに砂糖[さとう]を入[い]れたら甘[あま]くなった。", "sentence_source": "generated"}, {"text": "甘すぎて、全部は食べられなかった。", "target_word": "甘すぎて", "complexity_tier": "T3", "furigana": "甘[あま]すぎて、全部[ぜんぶ]は食[た]べられなかった。", "sentence_source": "generated"}, {"text": "この桃は思ったより甘かった。", "target_word": "甘かった", "complexity_tier": "T3", "furigana": "この桃[もも]は思[おも]ったより甘[あま]かった。", "sentence_source": "generated"}, {"text": "もう少し甘くしてください。", "target_word": "甘く", "complexity_tier": "T2", "furigana": "もう少[すこ]し甘[あま]くしてください。", "sentence_source": "generated"}, {"text": "甘ければ、ミルクを足さなくてもいいです。", "target_word": "甘ければ", "complexity_tier": "T4", "furigana": "甘[あま]ければ、ミルクを足[た]さなくてもいいです。", "sentence_source": "generated"}, {"text": "子どもたちは甘いジュースをよく飲まされる。", "target_word": "甘い", "complexity_tier": "T4", "furigana": "子[こ]どもたちは甘[あま]いジュースをよく飲[の]まされる。", "sentence_source": "generated"}, {"text": "この果物は砂糖のように甘い。", "target_word": "甘い", "complexity_tier": "T3", "furigana": "この果物[くだもの]は砂糖[さとう]のように甘[あま]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "甘かった", "label": "活用"}, {"form": "甘くない", "label": "活用"}, {"form": "甘さ", "label": "派生"}, {"form": "甘み", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 砂糖のような味がするさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6ab7e1-b183-4ad7-bb07-3e9856366fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36823, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "甘い", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "浅い", "is_correct": false, "explanation": "「あさい」で二拍目が異なる。"}, {"text": "青い", "is_correct": false, "explanation": "「あおい」で二拍目が異なる。"}, {"text": "赤い", "is_correct": false, "explanation": "「あかい」で二拍目が異なる。"}, {"text": "余り", "is_correct": false, "explanation": "「あまり」で最後の一拍が異なる。"}], "explanations": {"甘い": "見出し語そのもの。", "浅い": "「あさい」で二拍目が異なる。", "青い": "「あおい」で二拍目が異なる。", "赤い": "「あかい」で二拍目が異なる。", "余り": "「あまり」で最後の一拍が異なる。"}, "sentence_index": null, "correct_answer": "甘い"}, "level_3": {"options": [{"text": "甘い", "is_correct": true, "explanation": "レモネードの味を表し、文脈に合う。"}, {"text": "狭い", "is_correct": false, "explanation": "形は合うが意味が合わない。飲み物の性質として不自然。"}, {"text": "若い", "is_correct": false, "explanation": "形は合うが意味が合わない。飲み物を形容できない。"}, {"text": "丸い", "is_correct": false, "explanation": "形は合うが意味が合わない。レモネードの性質にならない。"}], "explanations": {"甘い": "レモネードの味を表し、文脈に合う。", "狭い": "形は合うが意味が合わない。飲み物の性質として不自然。", "若い": "形は合うが意味が合わない。飲み物を形容できない。", "丸い": "形は合うが意味が合わない。レモネードの性質にならない。"}, "sentence_index": 0, "correct_answer": "甘い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このドアは甘くて、なかなか開かない。", "explanation": "「甘い」は砂糖のような味を表し、ドアの状態には使えない。"}, {"text": "この石は甘くて、触ると冷たかった。", "explanation": "石は味の対象ではなく、砂糖のような味を表す「甘い」とは合わない。"}, {"text": "彼の足は甘くて、走るのが速い。", "explanation": "足の速さは味覚の「甘い」で表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36823, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "甘い", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "荒い", "is_correct": false, "explanation": "「あらい」で二拍目が異なる。"}, {"text": "暑い", "is_correct": false, "explanation": "「あつい」で二拍目が異なる。"}, {"text": "値", "is_correct": false, "explanation": "「あたい」で二拍目が異なる。"}], "explanations": {"甘い": "見出し語そのもの。", "荒い": "「あらい」で二拍目が異なる。", "暑い": "「あつい」で二拍目が異なる。", "値": "「あたい」で二拍目が異なる。"}, "sentence_index": null, "correct_answer": "甘い"}, "level_3": {"options": [{"text": "甘く", "is_correct": true, "explanation": "味を甘くしてほしいという依頼に合う。"}, {"text": "悔しく", "is_correct": false, "explanation": "形は合うが意味が合わない。「悔しくする」は依頼にならない。"}, {"text": "恋しく", "is_correct": false, "explanation": "形は合うが意味が合わない。「恋しくしてください」は不自然。"}, {"text": "眠く", "is_correct": false, "explanation": "形は合うが意味が合わない。味の調整にならない。"}], "explanations": {"甘く": "味を甘くしてほしいという依頼に合う。", "悔しく": "形は合うが意味が合わない。「悔しくする」は依頼にならない。", "恋しく": "形は合うが意味が合わない。「恋しくしてください」は不自然。", "眠く": "形は合うが意味が合わない。味の調整にならない。"}, "sentence_index": 6, "correct_answer": "甘く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この机は甘くて、三メートルもある。", "explanation": "「甘い」は砂糖のような味を表し、机の長さには使えない。"}, {"text": "この部屋は甘くて、とても広い。", "explanation": "「甘い」は味を表し、部屋の広さには使えない。"}, {"text": "この箱は甘くて、一人では持てない。", "explanation": "「甘い」は味を表し、物の重さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36823, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このお菓子はとても甘いなので、子どもに人気だ。", "corrected_sentence": "このお菓子はとても甘いので、子どもに人気だ。", "error_description": "形容詞「甘い」に「ので」が続くときは「なので」にしない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "甘い", "is_correct": true, "explanation": "「甘いです」と終止形に「です」が続く。"}, {"text": "甘く", "is_correct": false, "explanation": "「甘くです」は非文。"}, {"text": "甘けれ", "is_correct": false, "explanation": "仮定形は「ば」が続く形で「です」に続かない。"}, {"text": "甘かろ", "is_correct": false, "explanation": "未然形は「う」が続く形で「です」に続かない。"}], "correct_form": "甘い", "base_form": "甘い", "form_label": "終止形", "sentence_index": 1, "explanations": {"甘い": "「甘いです」と終止形に「です」が続く。", "甘く": "「甘くです」は非文。", "甘けれ": "仮定形は「ば」が続く形で「です」に続かない。", "甘かろ": "未然形は「う」が続く形で「です」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36823, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このメロンは甘いだった。", "corrected_sentence": "このメロンは甘かった。", "error_description": "形容詞「甘い」の過去形は「甘かった」で、「甘いだった」とは言わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "甘ければ", "is_correct": true, "explanation": "「ミルクを足さなくてもいい」に続く仮定形。"}, {"text": "甘かった", "is_correct": false, "explanation": "過去形では仮定の意味にならず、後の文と合わない。"}, {"text": "甘さ", "is_correct": false, "explanation": "名詞形で、文頭の条件として成り立たない。"}, {"text": "甘かろう", "is_correct": false, "explanation": "推量形で、「ミルクを足さなくてもいい」の条件にならない。"}], "correct_form": "甘ければ", "base_form": "甘い", "form_label": "仮定形", "sentence_index": 7, "explanations": {"甘ければ": "「ミルクを足さなくてもいい」に続く仮定形。", "甘かった": "過去形では仮定の意味にならず、後の文と合わない。", "甘さ": "名詞形で、文頭の条件として成り立たない。", "甘かろう": "推量形で、「ミルクを足さなくてもいい」の条件にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36824, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「果物を食べましょう」で、食べる対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「果物が食べましょう」では果物が食べる主体になり、誤り。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「果物へ食べましょう」は食べる動作と合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示す。「果物の食べましょう」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「果物を食べましょう」で、食べる対象を表す。", "が": "主語を示す。「果物が食べましょう」では果物が食べる主体になり、誤り。", "へ": "方向を示す。「果物へ食べましょう」は食べる動作と合わない。", "の": "連体修飾を示す。「果物の食べましょう」は文として成り立たない。"}, "error_tags": {"が": "主語を示す", "へ": "方向を示す", "の": "連体修飾を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
