INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36824, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あまくて おいしい たべものです。", "primary_collocate": null, "pronunciation": "くだもの", "ipa": "kɯdamono", "syllable_count": 4, "sentences": [{"text": "わたしは果物の中で、いちごがいちばん好きです。", "target_word": "果物", "complexity_tier": "T2", "furigana": "わたしはくだもののなかで、いちごがいちばんすきです。", "sentence_source": "generated"}, {"text": "おやつに果物を食べましょう。", "target_word": "果物", "complexity_tier": "T2", "furigana": "おやつにくだものをたべましょう。", "sentence_source": "generated"}, {"text": "市場で新しい果物を買いました。", "target_word": "果物", "complexity_tier": "T2", "furigana": "いちばであたらしいくだものをかいました。", "sentence_source": "generated"}, {"text": "この果物はとても甘くて、おいしいです。", "target_word": "果物", "complexity_tier": "T2", "furigana": "このくだものはとてもあまくて、おいしいです。", "sentence_source": "generated"}, {"text": "子どもたちは、デザートの果物を楽しみにしている。", "target_word": "果物", "complexity_tier": "T3", "furigana": "こどもたちは、デザートのくだものをたのしみにしている。", "sentence_source": "generated"}, {"text": "冷たい果物は、暑い夏にぴったりだ。", "target_word": "果物", "complexity_tier": "T3", "furigana": "つめたいくだものは、あついなつにぴったりだ。", "sentence_source": "generated"}, {"text": "母は毎週日曜日に、果物をたくさん買ってくる。", "target_word": "果物", "complexity_tier": "T3", "furigana": "はははまいしゅうにちようびに、くだものをたくさんかってくる。", "sentence_source": "generated"}, {"text": "りんごやみかんは、日本でよく食べられる果物です。", "target_word": "果物", "complexity_tier": "T3", "furigana": "りんごやみかんは、にほんでよくたべられるくだものです。", "sentence_source": "generated"}, {"text": "病院に果物を持っていくと、とても喜ばれた。", "target_word": "果物", "complexity_tier": "T3", "furigana": "びょういんにくだものをもっていくと、とてもよろこばれた。", "sentence_source": "generated"}, {"text": "果物が好きな妹は、お菓子よりもぶどうを選んだ。", "target_word": "果物", "complexity_tier": "T3", "furigana": "くだものがすきないもうとは、おかしよりもぶどうをえらんだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "果物", "label": "基本形"}], "register": "中立", "sense_fingerprint": "いちご・りんごなど、甘くておいしい食べ物(果物が好き・果物を買う)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d830dd3-4726-462f-b993-0f6b9ed00287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36824, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "果物", "is_correct": true, "explanation": "名詞。「果物の中で、いちごが一番好き」と、いちごを含む食べ物の範囲を示す。"}, {"text": "宿題", "is_correct": false, "explanation": "「宿題の中で、いちごが一番好き」は意味が通らず、いちごを含む範囲にならない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の中で、いちごが一番好き」は意味が通らず、文として成り立たない。"}, {"text": "掃除", "is_correct": false, "explanation": "「掃除の中で、いちごが一番好き」は意味が通らず、文として成り立たない。"}], "explanations": {"果物": "名詞。「果物の中で、いちごが一番好き」と、いちごを含む食べ物の範囲を示す。", "宿題": "「宿題の中で、いちごが一番好き」は意味が通らず、いちごを含む範囲にならない。", "天気": "「天気の中で、いちごが一番好き」は意味が通らず、文として成り立たない。", "掃除": "「掃除の中で、いちごが一番好き」は意味が通らず、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "果物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女の果物はとても甘くて、やさしい。", "explanation": "ここは〈声〉の意味。甘い声という表現で、〈果物〉は声には使わないので合わない。"}, {"text": "彼の果物は少し甘くて、現実的でない。", "explanation": "ここは〈考え〉の意味。考えが甘いという意味で、〈果物〉は使わない。"}, {"text": "彼は相手の果物を甘く見て、負けた。", "explanation": "ここは〈実力〉の意味。相手の実力を甘く見るという意味で、〈果物〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36824, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "果物", "is_correct": true, "explanation": "名詞。「果物をたくさん買ってくる」で、買う対象を示す。"}, {"text": "雨", "is_correct": false, "explanation": "「雨をたくさん買ってくる」は成り立たず、買える物ではない。"}, {"text": "空気", "is_correct": false, "explanation": "「空気をたくさん買ってくる」は文として成り立たない。"}, {"text": "感動", "is_correct": false, "explanation": "「感動をたくさん買ってくる」は意味が通らず、買える物ではない。"}], "explanations": {"果物": "名詞。「果物をたくさん買ってくる」で、買う対象を示す。", "雨": "「雨をたくさん買ってくる」は成り立たず、買える物ではない。", "空気": "「空気をたくさん買ってくる」は文として成り立たない。", "感動": "「感動をたくさん買ってくる」は意味が通らず、買える物ではない。"}, "sentence_index": 6, "correct_answer": "果物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "果物の変わり目は体調を崩しやすい。", "explanation": "ここは〈季節〉の意味。季節の変わり目という意味で、〈果物〉は合わない。"}, {"text": "この料理は果物が薄いので、塩を足した。", "explanation": "ここは〈味〉の意味。料理の味の薄さを表すので、〈果物〉は合わない。"}, {"text": "彼は果物が明るく、誰とでも話せる。", "explanation": "ここは〈性格〉の意味。性格が明るいという意味で、〈果物〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36824, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕食のあとに果物に食べましょう。", "corrected_sentence": "夕食のあとに果物を食べましょう。", "error_description": "「食べる」の目的語は「を」で示す。「果物に」は誤った格助詞で、「果物を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36824, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "果物が好くな妹は、お菓子より果物を選ぶ。", "corrected_sentence": "果物が好きな妹は、お菓子より果物を選ぶ。", "error_description": "「果物が好き」の「好き」は形容動詞で、「好きな」と活用する。「好くな」は誤った形で、「好きな」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
