INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36825, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "主に木になる、甘みがあってそのまま食べられる実のこと。りんごやみかんなど。", "primary_collocate": null, "pronunciation": "くだもの", "ipa": "kɯdamono", "syllable_count": 4, "sentences": [{"text": "秋の気配が色濃く漂う古びた縁側にて、一人の幼子が無心なる眼差しを向けているのは、掌に収められた一つの赤い果物である。", "target_word": "果物", "complexity_tier": "T4", "furigana": "あきのけはいがいろこくただようふるびたえんがわにて、ひとりのおさなごがむしんなるまなざしをむけているのは、てのひらにおさめられたひとつのあかいくだものである。", "sentence_source": "mined"}, {"text": "毎朝、朝ごはんのあとに果物を食べるようにしている。", "target_word": "果物", "complexity_tier": "T3", "furigana": "まいあさ、あさごはんのあとにくだものをたべるようにしている。", "sentence_source": "generated"}, {"text": "この店は季節の果物を使ったケーキが人気だ。", "target_word": "果物", "complexity_tier": "T3", "furigana": "このみせはきせつのくだものをつかったケーキがにんきだ。", "sentence_source": "generated"}, {"text": "祖母から果物がたくさん届いたので、近所にも分けた。", "target_word": "果物", "complexity_tier": "T3", "furigana": "そぼからくだものがたくさんとどいたので、きんじょにもわけた。", "sentence_source": "generated"}, {"text": "果物は冷蔵庫に入れすぎると、甘みが落ちることがある。", "target_word": "果物", "complexity_tier": "T3", "furigana": "くだものはれいぞうこにいれすぎると、あまみがおちることがある。", "sentence_source": "generated"}, {"text": "秋は柿や梨など、おいしい果物が出回る季節である。", "target_word": "果物", "complexity_tier": "T3", "furigana": "あきはかきやなしなど、おいしいくだものがでまわるきせつである。", "sentence_source": "generated"}, {"text": "果物の皮をむくのが苦手なので、いつも夫に頼んでいる。", "target_word": "果物", "complexity_tier": "T3", "furigana": "くだもののかわをむくのがにがてなので、いつもおっとにたのんでいる。", "sentence_source": "generated"}, {"text": "果物を育てる農家は、台風が来るたびに雨と風を心配している。", "target_word": "果物", "complexity_tier": "T3", "furigana": "くだものをそだてるのうかは、たいふうがくるたびにあめとかぜをしんぱいしている。", "sentence_source": "generated"}, {"text": "彼女は病気の友人のために、新鮮な果物を選んで見舞いに持っていった。", "target_word": "果物", "complexity_tier": "T3", "furigana": "かのじょはびょうきのゆうじんのために、しんせんなくだものをえらんでみまいにもっていった。", "sentence_source": "generated"}, {"text": "この果樹園では、収穫した果物をその場で味わえる。", "target_word": "果物", "complexity_tier": "T3", "furigana": "このかじゅえんでは、しゅうかくしたくだものをそのばであじわえる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "果物", "label": "基本形"}], "register": "中立", "sense_fingerprint": "りんご・みかんなど、甘くそのまま食べられる木の実(果物を食べる・季節の果物)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 6 words above tier T3 (max 3): 色濃く (Zipf 3.13), 古び (Zipf 2.76), 縁側 (Zipf 3.0), 幼子 (Zipf 2.71), 無心 (Zipf 3.09), 眼差し (Zipf 3.38)']::text[], '1d830dd3-4726-462f-b993-0f6b9ed00287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36825, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "果物", "is_correct": true, "explanation": "名詞。掌に収まる赤い食べ物を指し、「一つの赤い果物である」と文が成り立つ。"}, {"text": "感情", "is_correct": false, "explanation": "抽象的な名詞。掌に収まる赤いものにはならず、文が成り立たない。"}, {"text": "理論", "is_correct": false, "explanation": "抽象的な名詞。掌に収まる赤いものにはならず、文が成り立たない。"}, {"text": "時間", "is_correct": false, "explanation": "抽象的な名詞。掌に収まる赤いものにはならず、文が成り立たない。"}], "explanations": {"果物": "名詞。掌に収まる赤い食べ物を指し、「一つの赤い果物である」と文が成り立つ。", "感情": "抽象的な名詞。掌に収まる赤いものにはならず、文が成り立たない。", "理論": "抽象的な名詞。掌に収まる赤いものにはならず、文が成り立たない。", "時間": "抽象的な名詞。掌に収まる赤いものにはならず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "果物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試験の果物が出るまで、一週間かかった。", "explanation": "ここは〈結果〉の意味。試験の結果が出るという意味で、〈果物〉は合わない。"}, {"text": "研究の果物がようやく出た。", "explanation": "ここは〈成果〉の意味。研究の成果が出るという意味で、〈果物〉は使わない。"}, {"text": "春になると庭の果物が咲く。", "explanation": "ここは〈花〉の意味。花が咲くという表現で、果物は咲かないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36825, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "果物", "is_correct": true, "explanation": "名詞。「果物の皮をむく」で、皮をむく対象を示す。"}, {"text": "空気", "is_correct": false, "explanation": "皮のある物ではなく、「空気の皮をむく」は成り立たない。"}, {"text": "音楽", "is_correct": false, "explanation": "皮のある物ではなく、「音楽の皮をむく」は成り立たない。"}, {"text": "会議", "is_correct": false, "explanation": "皮のある物ではなく、「会議の皮をむく」は成り立たない。"}], "explanations": {"果物": "名詞。「果物の皮をむく」で、皮をむく対象を示す。", "空気": "皮のある物ではなく、「空気の皮をむく」は成り立たない。", "音楽": "皮のある物ではなく、「音楽の皮をむく」は成り立たない。", "会議": "皮のある物ではなく、「会議の皮をむく」は成り立たない。"}, "sentence_index": 6, "correct_answer": "果物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は喜びの果物を素直に表す。", "explanation": "ここは〈気持ち〉の意味。喜びの気持ちを表すという意味で、〈果物〉は合わない。"}, {"text": "彼の果物が心に響く。", "explanation": "ここは〈言葉〉の意味。言葉が心に響くという意味で、〈果物〉は使わない。"}, {"text": "二人の話は最後まで果物が食い違っていた。", "explanation": "ここは〈意見〉の意味。意見が食い違うという意味で、〈果物〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36825, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は庭で果物を育てるて、毎朝水をやる。", "corrected_sentence": "祖父は庭で果物を育てて、毎朝水をやる。", "error_description": "「育てる」は「育てて」と接続する。「育てるて」は誤った活用形で、「育てて」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36825, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭の果物を実る季節になった。", "corrected_sentence": "庭の果物が実る季節になった。", "error_description": "「実る」の主語は「が」で示す。「果物を実る」は誤りで、「果物が実る」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
