INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36826, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ひつようと する こと。", "primary_collocate": null, "pronunciation": "ようする", "ipa": "joːsɯɾɯ", "syllable_count": 4, "sentences": [{"text": "この工事には、約三か月の時間を要する。", "target_word": "要する", "complexity_tier": "T3", "furigana": "この工事[こうじ]には、約[やく]三[さん]か月[げつ]の時間[じかん]を要[よう]する。", "sentence_source": "generated"}, {"text": "傷が治るまでには、長い期間を要した。", "target_word": "要した", "complexity_tier": "T3", "furigana": "傷[きず]が治[なお]るまでには、長[なが]い期間[きかん]を要[よう]した。", "sentence_source": "generated"}, {"text": "山の道は危険なので、注意を要します。", "target_word": "要します", "complexity_tier": "T3", "furigana": "山[やま]の道[みち]は危険[きけん]なので、注意[ちゅうい]を要[よう]します。", "sentence_source": "generated"}, {"text": "新しい橋を作るには、多くの費用を要する。", "target_word": "要する", "complexity_tier": "T3", "furigana": "新[あたら]しい橋[はし]を作[つく]るには、多[おお]くの費用[ひよう]を要[よう]する。", "sentence_source": "generated"}, {"text": "事故の原因を調べるのに、五日を要しました。", "target_word": "要しました", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]を調[しら]べるのに、五日[いつか]を要[よう]しました。", "sentence_source": "generated"}, {"text": "この仕事は、特別な技術を要しない。", "target_word": "要しない", "complexity_tier": "T3", "furigana": "この仕事[しごと]は、特別[とくべつ]な技術[ぎじゅつ]を要[よう]しない。", "sentence_source": "generated"}, {"text": "一人で全部の資料を作るのは、多くの労力を要する。", "target_word": "要する", "complexity_tier": "T3", "furigana": "一人[ひとり]で全部[ぜんぶ]の資料[しりょう]を作[つく]るのは、多[おお]くの労力[ろうりょく]を要[よう]する。", "sentence_source": "generated"}, {"text": "この計算は複雑なので、答えを出すのに時間を要している。", "target_word": "要している", "complexity_tier": "T3", "furigana": "この計算[けいさん]は複雑[ふくざつ]なので、答[こた]えを出[だ]すのに時間[じかん]を要[よう]している。", "sentence_source": "generated"}, {"text": "引っ越しの準備に予想以上の日数を要して、疲れた。", "target_word": "要して", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの準備[じゅんび]に予想[よそう]以上[いじょう]の日数[にっすう]を要[よう]して、疲[つか]れた。", "sentence_source": "generated"}, {"text": "この絵を完成させるまでに、二年の月日を要した。", "target_word": "要した", "complexity_tier": "T3", "furigana": "この絵[え]を完成[かんせい]させるまでに、二年[にねん]の月日[つきひ]を要[よう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "要する", "label": "終止形"}, {"form": "要した", "label": "過去形"}, {"form": "要して", "label": "て形"}, {"form": "要しない", "label": "否定形"}, {"form": "要します", "label": "丁寧形"}], "register": "formal", "sense_fingerprint": "時間・費用・労力などをそのことのために必要とする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b06df7d-40b2-4106-9fa6-1559c7381280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36826, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要する", "is_correct": true, "explanation": "終止形（辞書形）。「〜を要する」で、時間が必要だという事実を述べる。"}, {"text": "要し", "is_correct": false, "explanation": "連用形。文を言い切れず、ここでは完結しない。"}, {"text": "要して", "is_correct": false, "explanation": "て形。言い切れないため、文末には入らない。"}, {"text": "要すれば", "is_correct": false, "explanation": "仮定形。「〜ば」が続かず、文の骨組みが合わない。"}], "explanations": {"要する": "終止形（辞書形）。「〜を要する」で、時間が必要だという事実を述べる。", "要し": "連用形。文を言い切れず、ここでは完結しない。", "要して": "て形。言い切れないため、文末には入らない。", "要すれば": "仮定形。「〜ば」が続かず、文の骨組みが合わない。"}, "sentence_index": 0, "correct_answer": "要する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋には、強い寒さを要する。", "explanation": "ここは〈感じる〉の意味（感覚を受ける）。要するは必要とする意味なので、感覚を表す用法とは合わない。"}, {"text": "彼は一日中ゲームに、時間を要した。", "explanation": "ここは〈費やす〉の意味。要するは必要になる・かかるの意味で、本人が意図して費やす場合には使えない。"}, {"text": "この写真は、大きな不安を要している。", "explanation": "ここは〈引き起こす〉の意味。要するは必要とする・かかるの意味で、感情を生み出す用法には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36826, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要する", "is_correct": true, "explanation": "終止形。「〜のは〜を要する」で、必要とする事実を述べる。"}, {"text": "要そう", "is_correct": false, "explanation": "意向形。事実を述べる文には合わず、推量の意味になる。"}, {"text": "要さ", "is_correct": false, "explanation": "未然形。単独で文を言い切れず、ここには入らない。"}, {"text": "要せ", "is_correct": false, "explanation": "命令形（文語）。文の意味が通らず、説明文には合わない。"}], "explanations": {"要する": "終止形。「〜のは〜を要する」で、必要とする事実を述べる。", "要そう": "意向形。事実を述べる文には合わず、推量の意味になる。", "要さ": "未然形。単独で文を言い切れず、ここには入らない。", "要せ": "命令形（文語）。文の意味が通らず、説明文には合わない。"}, "sentence_index": 6, "correct_answer": "要する"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一瞬の油断で、全財産を要した。", "explanation": "ここは〈失う〉の意味。要するは必要になる・かかるの意味で、損失には使えない。"}, {"text": "給料を一晩で要した。", "explanation": "ここは〈使い果たす〉の意味。要するは必要とする・かかるの意味で、使い切った内容には使えない。"}, {"text": "子どもは、新しいおもちゃを要した。", "explanation": "ここは〈欲しがる〉の意味（本人の希望）。要するは客観的に必要なことを表すので、この用法では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36826, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この作業には、十分な準備の時間で要する。", "corrected_sentence": "この作業には、十分な準備の時間を要する。", "error_description": "『要する』の目的語は『を』で示す。『時間で』は誤りで、正しくは『時間を』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "要した", "is_correct": true, "explanation": "過去形。治るまでに長い期間がかかったという過去の出来事を述べる。"}, {"text": "要して", "is_correct": false, "explanation": "て形。文を言い切れず、過去の出来事として終えられない。"}, {"text": "要さ", "is_correct": false, "explanation": "未然形。単独で文を終えられず、ここでは使えない。"}, {"text": "要せず", "is_correct": false, "explanation": "連用形（打ち消し）。文末に置けず、文が完結しない。"}], "correct_form": "要した", "base_form": "要する", "form_label": "過去形", "sentence_index": 1, "explanations": {"要した": "過去形。治るまでに長い期間がかかったという過去の出来事を述べる。", "要して": "て形。文を言い切れず、過去の出来事として終えられない。", "要さ": "未然形。単独で文を終えられず、ここでは使えない。", "要せず": "連用形（打ち消し）。文末に置けず、文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36826, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この修理には、数日の作業時間と要する。", "corrected_sentence": "この修理には、数日の作業時間を要する。", "error_description": "目的語は助詞『を』で示す。『時間と』は誤りで、正しくは『時間を』。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "要している", "is_correct": true, "explanation": "ている形。時間がかかっている状態を表し、今の状況を述べる文に合う。"}, {"text": "要しよう", "is_correct": false, "explanation": "意向形。「〜よう」は意志や推量を表し、今の状態を述べる文には合わない。"}, {"text": "要せよ", "is_correct": false, "explanation": "命令形（文語）。文末の命令にしかならず、状態を述べる文には合わない。"}, {"text": "要そう", "is_correct": false, "explanation": "意向形。推量や意志を表し、事実を述べる文には合わない。"}], "correct_form": "要している", "base_form": "要する", "form_label": "ている形", "sentence_index": 7, "explanations": {"要している": "ている形。時間がかかっている状態を表し、今の状況を述べる文に合う。", "要しよう": "意向形。「〜よう」は意志や推量を表し、今の状態を述べる文には合わない。", "要せよ": "命令形（文語）。文末の命令にしかならず、状態を述べる文には合わない。", "要そう": "意向形。推量や意志を表し、事実を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36827, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「提出を要します」で、必要とする対象（提出）を示す。"}, {"text": "で", "is_correct": false, "explanation": "「提出で要します」は成り立たず、手段の意味にもならない。"}, {"text": "へ", "is_correct": false, "explanation": "「提出へ要します」は方向を示すが、要するの対象にならない。"}, {"text": "と", "is_correct": false, "explanation": "「提出と要します」は並列の語で、ここでは成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「提出を要します」で、必要とする対象（提出）を示す。", "で": "「提出で要します」は成り立たず、手段の意味にもならない。", "へ": "「提出へ要します」は方向を示すが、要するの対象にならない。", "と": "「提出と要します」は並列の語で、ここでは成り立たない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36827, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「体力を要する」で、必要とする対象（体力）を示す。"}, {"text": "から", "is_correct": false, "explanation": "「体力から要する」は起点を示し、要するの対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "「体力より要する」は比較の語で、目的語を取れない。"}, {"text": "が", "is_correct": false, "explanation": "「体力が要する」は主語になり、「〜を要する」の形にならない。"}], "correct_answer": "を", "explanations": {"を": "「体力を要する」で、必要とする対象（体力）を示す。", "から": "「体力から要する」は起点を示し、要するの対象にならない。", "より": "「体力より要する」は比較の語で、目的語を取れない。", "が": "「体力が要する」は主語になり、「〜を要する」の形にならない。"}, "error_tags": {"から": "起点", "より": "比較", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36827, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "必要とする。求める。", "primary_collocate": null, "pronunciation": "ようする", "ipa": "joːsɯɾɯ", "syllable_count": 4, "sentences": [{"text": "この資格試験は、三年以上の経験を要する。", "target_word": "要する", "complexity_tier": "T3", "furigana": "この資格[しかく]試験[しけん]は、三年[さんねん]以上[いじょう]の経験[けいけん]を要[よう]する。", "sentence_source": "generated"}, {"text": "会員になるには、申込書の提出を要します。", "target_word": "要します", "complexity_tier": "T3", "furigana": "会員[かいいん]になるには、申込書[もうしこみしょ]の提出[ていしゅつ]を要[よう]します。", "sentence_source": "generated"}, {"text": "この役所の書類は、本人のサインを要する。", "target_word": "要する", "complexity_tier": "T3", "furigana": "この役所[やくしょ]の書類[しょるい]は、本人[ほんにん]のサインを要[よう]する。", "sentence_source": "generated"}, {"text": "急を要する用事ができたので、会議を早めに出た。", "target_word": "要する", "complexity_tier": "T3", "furigana": "急[きゅう]を要[よう]する用事[ようじ]ができたので、会議[かいぎ]を早[はや]めに出[で]た。", "sentence_source": "generated"}, {"text": "彼の病気は、一か月の入院を要する。", "target_word": "要する", "complexity_tier": "T3", "furigana": "彼[かれ]の病気[びょうき]は、一[いっ]か月[げつ]の入院[にゅういん]を要[よう]する。", "sentence_source": "generated"}, {"text": "大型の機械を動かすには、免許を要する。", "target_word": "要する", "complexity_tier": "T3", "furigana": "大型[おおがた]の機械[きかい]を動[うご]かすには、免許[めんきょ]を要[よう]する。", "sentence_source": "generated"}, {"text": "この部屋は、入る前に許可を要します。", "target_word": "要します", "complexity_tier": "T3", "furigana": "この部屋[へや]は、入[はい]る前[まえ]に許可[きょか]を要[よう]します。", "sentence_source": "generated"}, {"text": "仕事の中には、強い体力を要するものもある。", "target_word": "要する", "complexity_tier": "T3", "furigana": "仕事[しごと]の中[なか]には、強[つよ]い体力[たいりょく]を要[よう]するものもある。", "sentence_source": "generated"}, {"text": "海外へ行く場合は、ビザを要する国が多い。", "target_word": "要する", "complexity_tier": "T3", "furigana": "海外[かいがい]へ行[い]く場合[ばあい]は、ビザを要[よう]する国[くに]が多[おお]い。", "sentence_source": "generated"}, {"text": "この申し込みは、保護者の同意を要しません。", "target_word": "要しません", "complexity_tier": "T3", "furigana": "この申[もう]し込[こ]みは、保護者[ほごしゃ]の同意[どうい]を要[よう]しません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "要する", "label": "終止形"}, {"form": "要した", "label": "過去形"}, {"form": "要して", "label": "て形"}, {"form": "要しない", "label": "否定形"}, {"form": "要します", "label": "丁寧形"}], "register": "formal", "sense_fingerprint": "条件・資格・手続きなどをそのことに必要なものとして求める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b06df7d-40b2-4106-9fa6-1559c7381280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36827, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要する", "is_correct": true, "explanation": "終止形（辞書形）。「〜を要する」で、条件として経験を求める事実を述べる。"}, {"text": "要し", "is_correct": false, "explanation": "連用形。文を言い切れず、ここには入らない。"}, {"text": "要して", "is_correct": false, "explanation": "て形。言い切れず、文末に置けない。"}, {"text": "要せば", "is_correct": false, "explanation": "仮定形（文語）。「〜ば」が続かず、文の骨組みが合わない。"}], "explanations": {"要する": "終止形（辞書形）。「〜を要する」で、条件として経験を求める事実を述べる。", "要し": "連用形。文を言い切れず、ここには入らない。", "要して": "て形。言い切れず、文末に置けない。", "要せば": "仮定形（文語）。「〜ば」が続かず、文の骨組みが合わない。"}, "sentence_index": 0, "correct_answer": "要する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は新しいパソコンを要した。", "explanation": "ここは〈欲しがる〉の意味（本人の希望）。要するは必要なものを求める語で、ほしいという気持ちには使えない。"}, {"text": "この仕事は、危険を要する。", "explanation": "ここは〈伴う〉の意味。要するは必要とする意味なので、危険を伴うという内容には使えない。"}, {"text": "この失敗は、大きな混乱を要した。", "explanation": "ここは〈招く〉の意味。要するは必要とする意味で、混乱を引き起こす内容には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36827, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要します", "is_correct": true, "explanation": "丁寧形。「この部屋は〜を要します」で、丁寧に条件を述べる。"}, {"text": "要せず", "is_correct": false, "explanation": "連用形（打ち消し）。文末に置けず、文が完結しない。"}, {"text": "要そう", "is_correct": false, "explanation": "意向形。推量や意志を表し、事実を述べる文には合わない。"}, {"text": "要さ", "is_correct": false, "explanation": "未然形。単独では文を言い切れず、ここでは使えない。"}], "explanations": {"要します": "丁寧形。「この部屋は〜を要します」で、丁寧に条件を述べる。", "要せず": "連用形（打ち消し）。文末に置けず、文が完結しない。", "要そう": "意向形。推量や意志を表し、事実を述べる文には合わない。", "要さ": "未然形。単独では文を言い切れず、ここでは使えない。"}, "sentence_index": 6, "correct_answer": "要します"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この料金には、消費税を要します。", "explanation": "ここは〈含む〉の意味。要するは必要とする意味で、含まれているものには使えない。"}, {"text": "この言葉は、重要な意味を要する。", "explanation": "ここは〈持つ〉の意味。要するは必要とする意味で、意味を持つという内容には使えない。"}, {"text": "この景色は、大きな迫力を要した。", "explanation": "ここは〈備える〉の意味（特徴として具える）。要するは必要とする意味で、特徴を具える用法には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36827, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店で働くには、調理師の免許で要する。", "corrected_sentence": "この店で働くには、調理師の免許を要する。", "error_description": "『要する』の目的語は『を』で示す。『免許で』は誤りで、正しくは『免許を』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "要します", "is_correct": true, "explanation": "丁寧形。「会員になるには」に続けて、丁寧な口調で条件を述べる。"}, {"text": "要さ", "is_correct": false, "explanation": "未然形。単独で文を終えられず、ここでは使えない。"}, {"text": "要せず", "is_correct": false, "explanation": "連用形（打ち消し）。文末に置けず、文が完結しない。"}, {"text": "要して", "is_correct": false, "explanation": "て形。文を言い切れず、ここでは完結しない。"}], "correct_form": "要します", "base_form": "要する", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"要します": "丁寧形。「会員になるには」に続けて、丁寧な口調で条件を述べる。", "要さ": "未然形。単独で文を終えられず、ここでは使えない。", "要せず": "連用形（打ち消し）。文末に置けず、文が完結しない。", "要して": "て形。文を言い切れず、ここでは完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36827, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店に入るには、予約を要しです。", "corrected_sentence": "この店に入るには、予約を要します。", "error_description": "丁寧形は『要します』。『要しです』は連用形に『です』を続けた誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "要する", "is_correct": true, "explanation": "連体形。「体力を要するもの」と名詞を修飾する形。"}, {"text": "要す", "is_correct": false, "explanation": "文語の終止形。名詞を修飾する形にならず、ここでは使えない。"}, {"text": "要せ", "is_correct": false, "explanation": "文語の命令形。名詞を修飾できず、文の構造に合わない。"}, {"text": "要そう", "is_correct": false, "explanation": "意向形。名詞を修飾せず、「〜もの」に続かない。"}], "correct_form": "要する", "base_form": "要する", "form_label": "連体形", "sentence_index": 7, "explanations": {"要する": "連体形。「体力を要するもの」と名詞を修飾する形。", "要す": "文語の終止形。名詞を修飾する形にならず、ここでは使えない。", "要せ": "文語の命令形。名詞を修飾できず、文の構造に合わない。", "要そう": "意向形。名詞を修飾せず、「〜もの」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36829, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "黴菌を主語にして「入る」と続き、正しい。"}, {"text": "を", "is_correct": false, "explanation": "「入る」は目的語を取らないので、「を」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段の「で」は、主語の位置に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は、ここでは主語として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "黴菌を主語にして「入る」と続き、正しい。", "を": "「入る」は目的語を取らないので、「を」は不自然。", "で": "場所や手段の「で」は、主語の位置に合わない。", "へ": "方向の「へ」は、ここでは主語として成り立たない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36829, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "黴菌と心配が連体修飾でつながり、「黴菌の心配」として正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は名詞「心配」を直接修飾できず、「黴菌に心配は少ない」は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示し、名詞を直接修飾できないので、「黴菌から心配」は成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「黴菌を心配は少ない」は述語と組めず非文。"}], "correct_answer": "の", "explanations": {"の": "黴菌と心配が連体修飾でつながり、「黴菌の心配」として正しい。", "に": "「に」は名詞「心配」を直接修飾できず、「黴菌に心配は少ない」は意味が通らない。", "から": "「から」は起点を示し、名詞を直接修飾できないので、「黴菌から心配」は成り立たない。", "を": "「を」は目的語を示すが、「黴菌を心配は少ない」は述語と組めず非文。"}, "error_tags": {"の": "連体修飾", "に": "位置・相手", "から": "起点", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36829, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人に害を与える細菌などの微生物をまとめていう言葉。", "primary_collocate": null, "pronunciation": "かびきん", "ipa": "kabikʲiɴ", "syllable_count": 4, "sentences": [{"text": "黴菌という言葉は、体に悪い微生物をまとめて呼ぶときに使う。", "target_word": "黴菌", "complexity_tier": "T3", "furigana": "黴菌[かびきん]という言葉[ことば]は、体[からだ]に悪[わる]い微生物[びせいぶつ]をまとめて呼[よ]ぶときに使[つか]う。", "sentence_source": "generated"}, {"text": "黴菌が体に入ると、病気の原因になることがある。", "target_word": "黴菌", "complexity_tier": "T3", "furigana": "黴菌[かびきん]が体[からだ]に入[はい]ると、病気[びょうき]の原因[げんいん]になることがある。", "sentence_source": "generated"}, {"text": "熱いお湯で洗うと、まな板の黴菌を減らせる。", "target_word": "黴菌", "complexity_tier": "T3", "furigana": "熱[あつ]いお湯[ゆ]で洗[あら]うと、まな板[いた]の黴菌[かびきん]を減[へ]らせる。", "sentence_source": "generated"}, {"text": "傷を消毒するのは、黴菌が増えるのを防ぐためです。", "target_word": "黴菌", "complexity_tier": "T3", "furigana": "傷[きず]を消毒[しょうどく]するのは、黴菌[かびきん]が増[ふ]えるのを防[ふせ]ぐためです。", "sentence_source": "generated"}, {"text": "黴菌の中には、食べ物を腐らせるものもある。", "target_word": "黴菌", "complexity_tier": "T3", "furigana": "黴菌[かびきん]の中[なか]には、食[た]べ物[もの]を腐[くさ]らせるものもある。", "sentence_source": "generated"}, {"text": "昔の人は、黴菌のことをよく知らなかったので、病気が広がった。", "target_word": "黴菌", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、黴菌[かびきん]のことをよく知[し]らなかったので、病気[びょうき]が広[ひろ]がった。", "sentence_source": "generated"}, {"text": "医者は、黴菌を殺す薬を出した。", "target_word": "黴菌", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、黴菌[かびきん]を殺[ころ]す薬[くすり]を出[だ]した。", "sentence_source": "generated"}, {"text": "台所を清潔にしておけば、黴菌の心配は少ない。", "target_word": "黴菌", "complexity_tier": "T3", "furigana": "台所[だいどころ]を清潔[せいけつ]にしておけば、黴菌[かびきん]の心配[しんぱい]は少[すくな]い。", "sentence_source": "generated"}, {"text": "水が汚れていると、黴菌が増えて病気が出やすい。", "target_word": "黴菌", "complexity_tier": "T3", "furigana": "水[みず]が汚[よご]れていると、黴菌[かびきん]が増[ふ]えて病気[びょうき]が出[で]やすい。", "sentence_source": "generated"}, {"text": "汚れたタオルには黴菌がたくさんついている。", "target_word": "黴菌", "complexity_tier": "T3", "furigana": "汚[よご]れたタオルには黴菌[かびきん]がたくさんついている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "黴菌", "label": "基本形"}, {"form": "黴菌が", "label": "主語形"}, {"form": "黴菌を", "label": "目的語形"}, {"form": "黴菌の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "病気や食べ物の腐敗の原因になる、害のある細菌などの微生物の総称としての「黴菌」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b06b0e63-ab55-4198-b9e1-1c42010908cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36829, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黴菌", "is_correct": true, "explanation": "体に悪い微生物をまとめて呼ぶ語として、黴菌が入る文が成り立つ。"}, {"text": "食べ物", "is_correct": false, "explanation": "食べ物は微生物をまとめて呼ぶ語ではなく、文の意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "天気を微生物の呼び名として使うことはなく、文の意味が通らない。"}, {"text": "家具", "is_correct": false, "explanation": "家具は微生物を指さず、文の内容に合わない。"}], "explanations": {"黴菌": "体に悪い微生物をまとめて呼ぶ語として、黴菌が入る文が成り立つ。", "食べ物": "食べ物は微生物をまとめて呼ぶ語ではなく、文の意味が通らない。", "天気": "天気を微生物の呼び名として使うことはなく、文の意味が通らない。", "家具": "家具は微生物を指さず、文の内容に合わない。"}, "sentence_index": 0, "correct_answer": "黴菌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "黴菌は、細胞の中でしか増えない。", "explanation": "ここは〈ウイルス〉の性質。細胞の中でしか増えないのはウイルスで、黴菌は細胞の外でも増えるので合わない。"}, {"text": "パン作りでは、黴菌を使って生地を膨らませる。", "explanation": "ここは〈酵母〉の用法。生地を膨らませるのは酵母の働きで、害を与える黴菌を使うとは言わないので合わない。"}, {"text": "人の腸の中で、黴菌は卵を産んで増える。", "explanation": "ここは〈寄生虫〉の用法。卵を産んで増えるのは寄生虫の性質で、黴菌はこの使い方に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36829, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黴菌", "is_correct": true, "explanation": "殺す対象として黴菌を置くと、薬を出す文が成り立つ。"}, {"text": "絵", "is_correct": false, "explanation": "絵を殺す薬とは言わず、文の意味が通らない。"}, {"text": "歌", "is_correct": false, "explanation": "歌を殺す薬という言い方はなく、文脈に合わない。"}, {"text": "机", "is_correct": false, "explanation": "机を殺す薬は意味が通らず、医者の文脈に合わない。"}], "explanations": {"黴菌": "殺す対象として黴菌を置くと、薬を出す文が成り立つ。", "絵": "絵を殺す薬とは言わず、文の意味が通らない。", "歌": "歌を殺す薬という言い方はなく、文脈に合わない。", "机": "机を殺す薬は意味が通らず、医者の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "黴菌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "黴菌は、腸の調子を整える善玉菌だ。", "explanation": "ここは〈乳酸菌〉の用法。乳酸菌は善玉として働くが、人に害を与える黴菌を善玉とは言わないので合わない。"}, {"text": "汚れたお皿を、黴菌で洗った。", "explanation": "ここは〈洗剤〉の用法。汚れを落とすのは洗剤で、黴菌は汚れを落とすものではないので合わない。"}, {"text": "黴菌が、夏の夜に人の血を吸って腫れさせた。", "explanation": "ここは〈蚊〉の用法。血を吸って刺し跡を腫らせるのは蚊で、黴菌は血を吸う生き物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36829, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "黴菌が殺すために、熱いお湯で手を洗う。", "corrected_sentence": "黴菌を殺すために、熱いお湯で手を洗う。", "error_description": "「殺す」は他動詞なので、目的語の黴菌には「を」を使う。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36829, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "まな板の黴菌で、熱湯で消毒する。", "corrected_sentence": "まな板の黴菌を、熱湯で消毒する。", "error_description": "「消毒する」の対象は黴菌なので、「を」を使う。「で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
