INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36830, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "くさや　はっぱの　いろです。", "primary_collocate": null, "pronunciation": "みどり", "ipa": "midoɾi", "syllable_count": 3, "sentences": [{"text": "公園の木の葉は、春になると明るい緑になります。", "target_word": "緑", "complexity_tier": "T3", "furigana": "公園[こうえん]の木[き]の葉[は]は、春[はる]になると明[あか]るい緑[みどり]になります。", "sentence_source": "generated"}, {"text": "緑のペンで、ノートに絵をかきました。", "target_word": "緑", "complexity_tier": "T3", "furigana": "緑[みどり]のペンで、ノートに絵[え]をかきました。", "sentence_source": "generated"}, {"text": "私は緑のセーターが好きです。", "target_word": "緑", "complexity_tier": "T3", "furigana": "私[わたし]は緑[みどり]のセーターが好[す]きです。", "sentence_source": "generated"}, {"text": "雨上がりの道端は、草の緑が一段と鮮やかに見えます。", "target_word": "緑", "complexity_tier": "T3", "furigana": "雨上[あまあ]がりの道端[みちばた]は、草[くさ]の緑[みどり]が一段[いちだん]と鮮[あざ]やかに見[み]えます。", "sentence_source": "generated"}, {"text": "山の緑がとてもきれいで、写真をたくさんとりました。", "target_word": "緑", "complexity_tier": "T3", "furigana": "山[やま]の緑[みどり]がとてもきれいで、写真[しゃしん]をたくさんとりました。", "sentence_source": "generated"}, {"text": "夏は庭の緑が濃くなります。", "target_word": "緑", "complexity_tier": "T3", "furigana": "夏[なつ]は庭[にわ]の緑[みどり]が濃[こ]くなります。", "sentence_source": "generated"}, {"text": "弟は緑の帽子をかぶって学校へ行きました。", "target_word": "緑", "complexity_tier": "T3", "furigana": "弟[おとうと]は緑[みどり]の帽子[ぼうし]をかぶって学校[がっこう]へ行[い]きました。", "sentence_source": "generated"}, {"text": "青と黄色の絵の具をまぜると、緑になります。", "target_word": "緑", "complexity_tier": "T3", "furigana": "青[あお]と黄色[きいろ]の絵[え]の具[ぐ]をまぜると、緑[みどり]になります。", "sentence_source": "generated"}, {"text": "この町は緑が多いので、空気がおいしいです。", "target_word": "緑", "complexity_tier": "T3", "furigana": "この町[まち]は緑[みどり]が多[おお]いので、空気[くうき]がおいしいです。", "sentence_source": "generated"}, {"text": "緑のカーテンを白に替えたら、部屋が明るくなりました。", "target_word": "緑", "complexity_tier": "T3", "furigana": "緑[みどり]のカーテンを白[しろ]に替[か]えたら、部屋[へや]が明[あか]るくなりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "緑", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "草や葉の色を表す名詞の「緑」(みどり)。色名として使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: 4 words above tier T2 (max 3): 雨上がり (Zipf 3.17), 道端 (Zipf 3.47), 一段と (Zipf 3.18), 鮮やか (Zipf 3.69)','sentence 7 above tier T2: contains vocabulary far above tier T2: まぜる (Zipf 2.09)']::text[], '5f3ae7ef-de13-437b-8240-813bdede8e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36830, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "緑", "is_correct": true, "explanation": "ここは葉の色を表す〈緑〉。春の木の葉の色として自然に入る。"}, {"text": "黒", "is_correct": false, "explanation": "黒は暗い色を表すので、「明るい黒」とは言わない。ここには入らない。"}, {"text": "幹", "is_correct": false, "explanation": "幹は木の太い部分で色の名前ではないので、「明るい幹」は成り立たない。"}, {"text": "根", "is_correct": false, "explanation": "根は地中の部分で色を表さないので、ここには合わない。"}], "explanations": {"緑": "ここは葉の色を表す〈緑〉。春の木の葉の色として自然に入る。", "黒": "黒は暗い色を表すので、「明るい黒」とは言わない。ここには入らない。", "幹": "幹は木の太い部分で色の名前ではないので、「明るい幹」は成り立たない。", "根": "根は地中の部分で色を表さないので、ここには合わない。"}, "sentence_index": 0, "correct_answer": "緑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はまだ緑で、仕事は任せられません。", "explanation": "ここは〈未熟〉の意味。未熟な人は〈青い〉で表すので、〈緑〉は合わない。"}, {"text": "晴れた日の空は、どこまでも緑が広がっています。", "explanation": "ここは〈青〉の意味。空の色は青で表すのが普通なので、〈緑〉を使うのは合わない。"}, {"text": "紅葉の山が、緑に染まりました。", "explanation": "ここは〈赤〉の意味。紅葉の色は〈赤〉で言うので、〈緑〉では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36830, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "緑", "is_correct": true, "explanation": "ここは帽子の色を表す〈緑〉。「緑の帽子」と色で修飾する形が自然。"}, {"text": "葉", "is_correct": false, "explanation": "葉は植物の一部で、「葉の帽子」は色の説明にならないので、ここには入らない。"}, {"text": "花", "is_correct": false, "explanation": "花は色の名前ではないので、「花の帽子」とは言わない。"}, {"text": "枝", "is_correct": false, "explanation": "枝は木の部分で、「枝の帽子」は成り立たない。"}], "explanations": {"緑": "ここは帽子の色を表す〈緑〉。「緑の帽子」と色で修飾する形が自然。", "葉": "葉は植物の一部で、「葉の帽子」は色の説明にならないので、ここには入らない。", "花": "花は色の名前ではないので、「花の帽子」とは言わない。", "枝": "枝は木の部分で、「枝の帽子」は成り立たない。"}, "sentence_index": 6, "correct_answer": "緑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雪が積もって、一面が緑になりました。", "explanation": "ここは〈白〉の意味。雪の色は〈白〉で言うので、〈緑〉では合わない。"}, {"text": "夕焼けの空が、緑に染まりました。", "explanation": "ここは〈赤〉の意味。夕焼けの色は〈赤〉で言うので、〈緑〉では合わない。"}, {"text": "大きな緑が、強い風で倒れてしまいました。", "explanation": "ここは〈木〉の意味。倒れるのは木そのもので、色の〈緑〉では言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36830, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は緑を帽子をかぶって公園へ行きました。", "corrected_sentence": "妹は緑の帽子をかぶって公園へ行きました。", "error_description": "「緑」の後ろは「の」で「緑の帽子」と続ける。「を」にすると緑が目的語になり、「帽子を」と重なって不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36830, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨のあとで、木々の緑が重く見えました。", "corrected_sentence": "雨のあとで、木々の緑が濃く見えました。", "error_description": "緑の様子は「濃い」で表す。「重い」は色の濃さを表さないので、「緑が濃く見える」と直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
