INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36832, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「土」が主語になり、乾いた状態になる主体を示すので「が」。"}, {"text": "に", "is_correct": false, "explanation": "「土にかわいていた」は場所に乾くという意味にならず、状態の説明として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「土とかわいていた」は並列や相手を表すので、ここでは成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「土からかわいていた」は起点の意味になり、状態を表せない。"}], "correct_answer": "が", "explanations": {"が": "「土」が主語になり、乾いた状態になる主体を示すので「が」。", "に": "「土にかわいていた」は場所に乾くという意味にならず、状態の説明として成り立たない。", "と": "「土とかわいていた」は並列や相手を表すので、ここでは成り立たない。", "から": "「土からかわいていた」は起点の意味になり、状態を表せない。"}, "error_tags": {"に": "位置", "と": "相手・並列", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36832, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面の表面にあり、植物が育つもとになるものです。", "primary_collocate": null, "pronunciation": "つち", "ipa": "tsɯtɕi", "syllable_count": 2, "sentences": [{"text": "庭の土に、花のたねをまきました。", "target_word": "土", "complexity_tier": "T3", "furigana": "庭[にわ]の土[つち]に、花[はな]のたねをまきました。", "sentence_source": "generated"}, {"text": "雨がふって、土がやわらかくなりました。", "target_word": "土", "complexity_tier": "T3", "furigana": "雨[あめ]がふって、土[つち]がやわらかくなりました。", "sentence_source": "generated"}, {"text": "子どもたちは土をほって、小さな穴をつくりました。", "target_word": "土", "complexity_tier": "T3", "furigana": "子[こ]どもたちは土[つち]をほって、小[ちい]さな穴[あな]をつくりました。", "sentence_source": "generated"}, {"text": "植物が育つには、よい土が必要です。", "target_word": "土", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]が育[そだ]つには、よい土[つち]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "靴に土がついたので、玄関で落としました。", "target_word": "土", "complexity_tier": "T3", "furigana": "靴[くつ]に土[つち]がついたので、玄関[げんかん]で落[お]としました。", "sentence_source": "generated"}, {"text": "畑の土は黒くて、栄養がたくさんあります。", "target_word": "土", "complexity_tier": "T3", "furigana": "畑[はたけ]の土[つち]は黒[くろ]くて、栄養[えいよう]がたくさんあります。", "sentence_source": "generated"}, {"text": "土の中から、小さな虫が出てきました。", "target_word": "土", "complexity_tier": "T3", "furigana": "土[つち]の中[なか]から、小[ちい]さな虫[むし]が出[で]てきました。", "sentence_source": "generated"}, {"text": "鉢の土がかわいていたので、水をやりました。", "target_word": "土", "complexity_tier": "T3", "furigana": "鉢[はち]の土[つち]がかわいていたので、水[みず]をやりました。", "sentence_source": "generated"}, {"text": "雨の日は土のにおいが強くなります。", "target_word": "土", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は土[つち]のにおいが強[つよ]くなります。", "sentence_source": "generated"}, {"text": "犬が前足で土をほっています。", "target_word": "土", "complexity_tier": "T3", "furigana": "犬[いぬ]が前足[まえあし]で土[つち]をほっています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "土", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "地面や畑をつくる、植物が育つもとになる「土」(つち)。読みは「ど」ではない。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f3ae7ef-de13-437b-8240-813bdede8e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36832, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "土", "is_correct": true, "explanation": "ここは種をまく地面の〈土〉。「庭の土に種をまく」は自然な言い方。"}, {"text": "空", "is_correct": false, "explanation": "空には種をまけないので、庭の場所としては合わない。"}, {"text": "水", "is_correct": false, "explanation": "水に種をまくとは言わないので、ここには入らない。"}, {"text": "石", "is_correct": false, "explanation": "石には種をまけないので、ここには合わない。"}], "explanations": {"土": "ここは種をまく地面の〈土〉。「庭の土に種をまく」は自然な言い方。", "空": "空には種をまけないので、庭の場所としては合わない。", "水": "水に種をまくとは言わないので、ここには入らない。", "石": "石には種をまけないので、ここには合わない。"}, "sentence_index": 0, "correct_answer": "土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "薪を燃やすと、あとに土が残ります。", "explanation": "ここは〈灰〉の意味。燃やしたあとに残るのは〈灰〉で、〈土〉とは言わないので合わない。"}, {"text": "この土は駅から近くて、便利です。", "explanation": "ここは〈土地〉の意味。区画された場所を指すので、地面の土とは言わない。"}, {"text": "船がようやく土に着きました。", "explanation": "ここは〈陸〉の意味。船が着くのは陸地で、地面の土とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36832, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "土", "is_correct": true, "explanation": "ここは虫がいる地面の〈土〉。土の中から虫が出るのは自然。"}, {"text": "雲", "is_correct": false, "explanation": "雲の中から虫が出てくるとは言えないので、ここには合わない。"}, {"text": "風", "is_correct": false, "explanation": "風の中から虫が出てくるとは言えないので、ここには合わない。"}, {"text": "星", "is_correct": false, "explanation": "星の中から虫が出てくるとは言えないので、ここには合わない。"}], "explanations": {"土": "ここは虫がいる地面の〈土〉。土の中から虫が出るのは自然。", "雲": "雲の中から虫が出てくるとは言えないので、ここには合わない。", "風": "風の中から虫が出てくるとは言えないので、ここには合わない。", "星": "星の中から虫が出てくるとは言えないので、ここには合わない。"}, "sentence_index": 6, "correct_answer": "土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "土は太陽の周りを一年かけて回っています。", "explanation": "ここは〈地球〉の意味。惑星として太陽の周りを回るのは地球で、地面の土とは言わない。"}, {"text": "星がきらめく土は、雲ひとつなく澄んでいました。", "explanation": "ここは〈空〉の意味。雲ひとつなく澄むのは空で、地面の土には使わない。"}, {"text": "仕事で土のように疲れました。", "explanation": "ここは〈泥〉の意味。「泥のように疲れる」という慣用句で、土では言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36832, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "畑の土を、野菜の苗を植えました。", "corrected_sentence": "畑の土に、野菜の苗を植えました。", "error_description": "「土」の後の助詞は場所を表す「に」が正しい。「を」にすると土が植える対象のように読めて、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36832, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鍬で土を耕すました。", "corrected_sentence": "鍬で土を耕しました。", "error_description": "「耕す」は連用形の「耕し」に「ました」を続けて「耕しました」とする。「耕すました」は活用の形が誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36835, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「を」は混ぜる対象（絵の具）を示す格助詞で、「交ぜる」の直前に置く。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、混ぜる対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、混ぜる対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を表すので、ここでは対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「を」は混ぜる対象（絵の具）を示す格助詞で、「交ぜる」の直前に置く。", "が": "「が」は主語を示すので、混ぜる対象にはならない。", "へ": "「へ」は方向を表すので、混ぜる対象を示せない。", "より": "「より」は比較の基準を表すので、ここでは対象を示せない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分ける", "is_correct": true, "explanation": "〈交ぜる〉の対義語。混ざったものを別々にする意味の〈分ける〉。"}, {"text": "数える", "is_correct": false, "explanation": "数を確かめる動作で、交ぜるの対義語ではない。"}, {"text": "集める", "is_correct": false, "explanation": "まとめる動作で、交ぜるの対義語にはならない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "声を出す動作で、交ぜるの対義語ではない。"}], "correct_answer": "分ける", "explanations": {"分ける": "〈交ぜる〉の対義語。混ざったものを別々にする意味の〈分ける〉。", "数える": "数を確かめる動作で、交ぜるの対義語ではない。", "集める": "まとめる動作で、交ぜるの対義語にはならない。", "叫ぶ": "声を出す動作で、交ぜるの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36835, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「を」は混ぜる対象（牛乳とコーヒー）を示す格助詞で、「交ぜる」の直前に置く。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、混ぜる対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、ここでは対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「の」で名詞をつなぐ形は、ここでは混ぜる対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「を」は混ぜる対象（牛乳とコーヒー）を示す格助詞で、「交ぜる」の直前に置く。", "で": "「で」は場所や手段を表すので、混ぜる対象を示せない。", "から": "「から」は起点を表すので、ここでは対象を示せない。", "の": "「の」で名詞をつなぐ形は、ここでは混ぜる対象にならない。"}, "error_tags": {"で": "場所・手段", "から": "起点", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分ける", "is_correct": true, "explanation": "〈交ぜる〉の対義語。混ざったものを別々にする意味の〈分ける〉。"}, {"text": "運ぶ", "is_correct": false, "explanation": "場所を移す動作で、混ぜる動作の対義語ではない。"}, {"text": "眺める", "is_correct": false, "explanation": "見る動作で、交ぜるの対義語にはならない。"}, {"text": "磨く", "is_correct": false, "explanation": "表面をこする動作で、交ぜるの対義語ではない。"}], "correct_answer": "分ける", "explanations": {"分ける": "〈交ぜる〉の対義語。混ざったものを別々にする意味の〈分ける〉。", "運ぶ": "場所を移す動作で、混ぜる動作の対義語ではない。", "眺める": "見る動作で、交ぜるの対義語にはならない。", "磨く": "表面をこする動作で、交ぜるの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36835, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "いくつかのものを いっしょにして まざった じょうたいにすること。", "primary_collocate": null, "pronunciation": "まぜる", "ipa": "mazeɾɯ", "syllable_count": 3, "sentences": [{"text": "卵と砂糖を交ぜて、ケーキの生地を作ります。", "target_word": "交ぜて", "complexity_tier": "T3", "furigana": "卵[たまご]と砂糖[さとう]を交[ま]ぜて、ケーキの生地[きじ]を作[つく]ります。", "sentence_source": "generated"}, {"text": "青と黄色の絵の具を交ぜると、緑になります。", "target_word": "交ぜる", "complexity_tier": "T3", "furigana": "青[あお]と黄色[きいろ]の絵[え]の具[ぐ]を交[ま]ぜると、緑[みどり]になります。", "sentence_source": "generated"}, {"text": "サラダにドレッシングをかけて、よく交ぜてください。", "target_word": "交ぜて", "complexity_tier": "T3", "furigana": "サラダにドレッシングをかけて、よく交[ま]ぜてください。", "sentence_source": "generated"}, {"text": "母はなべのスープをスプーンで交ぜています。", "target_word": "交ぜて", "complexity_tier": "T3", "furigana": "母[はは]はなべのスープをスプーンで交[ま]ぜています。", "sentence_source": "generated"}, {"text": "粉と水を交ぜて、ねんどを作りました。", "target_word": "交ぜて", "complexity_tier": "T3", "furigana": "粉[こな]と水[みず]を交[ま]ぜて、ねんどを作[つく]りました。", "sentence_source": "generated"}, {"text": "納豆にしょうゆを入れて、箸で交ぜて食べます。", "target_word": "交ぜて", "complexity_tier": "T3", "furigana": "納豆[なっとう]にしょうゆを入[い]れて、箸[はし]で交[ま]ぜて食[た]べます。", "sentence_source": "generated"}, {"text": "土に肥料を交ぜてから、苗を植えました。", "target_word": "交ぜて", "complexity_tier": "T3", "furigana": "土[つち]に肥料[ひりょう]を交[ま]ぜてから、苗[なえ]を植[う]えました。", "sentence_source": "generated"}, {"text": "牛乳とコーヒーを交ぜると、やさしい味になります。", "target_word": "交ぜる", "complexity_tier": "T3", "furigana": "牛乳[ぎゅうにゅう]とコーヒーを交[ま]ぜると、やさしい味[あじ]になります。", "sentence_source": "generated"}, {"text": "先生はいろいろな色の砂を交ぜて、きれいな模様を作りました。", "target_word": "交ぜて", "complexity_tier": "T3", "furigana": "先生[せんせい]はいろいろな色[いろ]の砂[すな]を交[ま]ぜて、きれいな模様[もよう]を作[つく]りました。", "sentence_source": "generated"}, {"text": "ボウルの中で野菜とたれを交ぜます。", "target_word": "交ぜます", "complexity_tier": "T3", "furigana": "ボウルの中[なか]で野菜[やさい]とたれを交[ま]ぜます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "交ぜる", "label": "基本形"}, {"form": "交ぜます", "label": "ます形"}, {"form": "交ぜて", "label": "て形"}, {"form": "交ぜない", "label": "ない形"}, {"form": "交ぜた", "label": "た形"}], "register": "丁寧", "sense_fingerprint": "材料や色など複数のものを、かき回すなどして混ざった状態にする「交ぜる」。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f3ae7ef-de13-437b-8240-813bdede8e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36835, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交ぜて", "is_correct": true, "explanation": "ここは材料を一つにまとめる〈交ぜて〉。「卵と砂糖を交ぜて生地を作る」が自然。"}, {"text": "眺めて", "is_correct": false, "explanation": "眺めるは見る動作で、材料を混ぜる意味にならないので、ここには入らない。"}, {"text": "叫んで", "is_correct": false, "explanation": "叫ぶは声を出す動作で、材料を混ぜることにはならない。"}, {"text": "塗って", "is_correct": false, "explanation": "材料を塗るとは言わないので、ここには入らない。"}], "explanations": {"交ぜて": "ここは材料を一つにまとめる〈交ぜて〉。「卵と砂糖を交ぜて生地を作る」が自然。", "眺めて": "眺めるは見る動作で、材料を混ぜる意味にならないので、ここには入らない。", "叫んで": "叫ぶは声を出す動作で、材料を混ぜることにはならない。", "塗って": "材料を塗るとは言わないので、ここには入らない。"}, "sentence_index": 0, "correct_answer": "交ぜて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "玉ねぎを細かく交ぜて、フライパンで炒めました。", "explanation": "ここは〈刻む〉の意味。細かく切る動作で、混ぜる〈交ぜる〉は合わない。"}, {"text": "二本の道が駅の前で、交ぜています。", "explanation": "ここは〈交差する〉の意味。道が重なって交わる動きで、混ぜる〈交ぜる〉は使わない。"}, {"text": "床を交ぜて、ぴかぴかにしました。", "explanation": "ここは〈磨く〉の意味。表面をこすって光らせる動作で、〈交ぜる〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36835, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交ぜて", "is_correct": true, "explanation": "ここは肥料を土に混ぜ込む〈交ぜて〉。「土に肥料を交ぜてから」が自然。"}, {"text": "投げて", "is_correct": false, "explanation": "投げるは物を放る動作で、肥料を土に混ぜる意味にならない。"}, {"text": "踏んで", "is_correct": false, "explanation": "踏む動作で、肥料を混ぜることにはならないので、ここには合わない。"}, {"text": "掘って", "is_correct": false, "explanation": "掘る動作で、肥料を混ぜることにはならないので、ここには入らない。"}], "explanations": {"交ぜて": "ここは肥料を土に混ぜ込む〈交ぜて〉。「土に肥料を交ぜてから」が自然。", "投げて": "投げるは物を放る動作で、肥料を土に混ぜる意味にならない。", "踏んで": "踏む動作で、肥料を混ぜることにはならないので、ここには合わない。", "掘って": "掘る動作で、肥料を混ぜることにはならないので、ここには入らない。"}, "sentence_index": 6, "correct_answer": "交ぜて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "魚を紙で交ぜて、冷蔵庫に入れました。", "explanation": "ここは〈包む〉の意味。紙で覆う動作で、混ぜる〈交ぜる〉は合わない。"}, {"text": "ケーキを八等分に交ぜて、皆に配りました。", "explanation": "ここは〈切る〉の意味。八等分にする動作で、〈交ぜる〉は使わない。"}, {"text": "二人の剣士は刃を交ぜて、激しく戦いました。", "explanation": "ここは〈交える〉の意味。刃を向け合う意味で、混ぜる〈交ぜる〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36835, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小麦粉とバターが交ぜて、クッキーの生地を作りました。", "corrected_sentence": "小麦粉とバターを交ぜて、クッキーの生地を作りました。", "error_description": "小麦粉とバターは混ぜられる物なので「を」で示す。「が」にすると主語になり、混ぜる動作の対象として文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "交ぜる", "is_correct": true, "explanation": "基本形で、「交ぜると」の形で条件を表す。"}, {"text": "交ぜて", "is_correct": false, "explanation": "て形は「と」に続けられないので、条件を表す形にならない。"}, {"text": "交ぜない", "is_correct": false, "explanation": "否定形の「交ぜないと」は条件を表せるが、「緑になります」と続けると意味が逆になるので合わない。"}, {"text": "交ぜた", "is_correct": false, "explanation": "た形は完了を表すので、条件を表す「と」に続けられない。"}], "correct_form": "交ぜる", "base_form": "交ぜる", "form_label": "基本形", "sentence_index": 1, "explanations": {"交ぜる": "基本形で、「交ぜると」の形で条件を表す。", "交ぜて": "て形は「と」に続けられないので、条件を表す形にならない。", "交ぜない": "否定形の「交ぜないと」は条件を表せるが、「緑になります」と続けると意味が逆になるので合わない。", "交ぜた": "た形は完了を表すので、条件を表す「と」に続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36835, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鍋の中で野菜とだしを交ぜるました。", "corrected_sentence": "鍋の中で野菜とだしを交ぜました。", "error_description": "「交ぜました」が正しい。「交ぜるました」は「る」が余計で、ます形の活用になっていない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "交ぜる", "is_correct": true, "explanation": "基本形で、「交ぜると」の形で条件を表す。"}, {"text": "交ぜます", "is_correct": false, "explanation": "ます形は文を終える形で、「と」に続けて条件を表すことはできない。"}, {"text": "交ぜよう", "is_correct": false, "explanation": "意向形は意志を表すので、条件を表す文に合わない。"}, {"text": "交ぜれば", "is_correct": false, "explanation": "仮定形で、「と」と並べると文の形が合わない。"}], "correct_form": "交ぜる", "base_form": "交ぜる", "form_label": "基本形", "sentence_index": 7, "explanations": {"交ぜる": "基本形で、「交ぜると」の形で条件を表す。", "交ぜます": "ます形は文を終える形で、「と」に続けて条件を表すことはできない。", "交ぜよう": "意向形は意志を表すので、条件を表す文に合わない。", "交ぜれば": "仮定形で、「と」と並べると文の形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36836, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「菜園がある」の主語を示す「が」。存在を表す「あります」と合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「あります」は存在を表す自動詞なので、「菜園をあります」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ「の」。「菜園のあります」は文として成立しない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」。「菜園からあります」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「菜園がある」の主語を示す「が」。存在を表す「あります」と合う。", "を": "目的語の「を」。「あります」は存在を表す自動詞なので、「菜園をあります」は成り立たない。", "の": "名詞をつなぐ「の」。「菜園のあります」は文として成立しない。", "から": "起点を表す「から」。「菜園からあります」は意味が通らない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36836, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "動作の場所を示す「で」。「学校の菜園で育てた」と、育てた場所になる。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。菜園が育てる主体になり、「一年生が」と主語が重なって不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。比べる文脈がなく、文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。育てる動作の場所には使わない。"}], "correct_answer": "で", "explanations": {"で": "動作の場所を示す「で」。「学校の菜園で育てた」と、育てた場所になる。", "が": "主語の「が」。菜園が育てる主体になり、「一年生が」と主語が重なって不自然。", "より": "比較の「より」。比べる文脈がなく、文が成立しない。", "へ": "方向を示す「へ」。育てる動作の場所には使わない。"}, "error_tags": {"が": "主語", "より": "比較", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36836, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "やさいや花を育てるための、小さな畑のことです。", "primary_collocate": null, "pronunciation": "さいえん", "ipa": "saieɴ", "syllable_count": 4, "sentences": [{"text": "祖父は庭の菜園で、トマトを育てています。", "target_word": "菜園", "complexity_tier": "T3", "furigana": "祖父[そふ]は庭[にわ]の菜園[さいえん]で、トマトを育[そだ]てています。", "sentence_source": "generated"}, {"text": "私の家には小さな菜園があります。", "target_word": "菜園", "complexity_tier": "T3", "furigana": "私[わたし]の家[いえ]には小[ちい]さな菜園[さいえん]があります。", "sentence_source": "generated"}, {"text": "日曜日に、家族で菜園の草をぬきました。", "target_word": "菜園", "complexity_tier": "T3", "furigana": "日曜日[にちようび]に、家族[かぞく]で菜園[さいえん]の草[くさ]をぬきました。", "sentence_source": "generated"}, {"text": "菜園にはいろいろな野菜と花があります。", "target_word": "菜園", "complexity_tier": "T3", "furigana": "菜園[さいえん]にはいろいろな野菜[やさい]と花[はな]があります。", "sentence_source": "generated"}, {"text": "朝、菜園に水をやるのが私の仕事です。", "target_word": "菜園", "complexity_tier": "T3", "furigana": "朝[あさ]、菜園[さいえん]に水[みず]をやるのが私[わたし]の仕事[しごと]です。", "sentence_source": "generated"}, {"text": "菜園のきゅうりが大きくなったので、収穫しました。", "target_word": "菜園", "complexity_tier": "T3", "furigana": "菜園[さいえん]のきゅうりが大[おお]きくなったので、収穫[しゅうかく]しました。", "sentence_source": "generated"}, {"text": "雨が少なくて、菜園の野菜が元気がありません。", "target_word": "菜園", "complexity_tier": "T3", "furigana": "雨[あめ]が少[すく]なくて、菜園[さいえん]の野菜[やさい]が元気[げんき]がありません。", "sentence_source": "generated"}, {"text": "学校の菜園で、一年生がさつまいもを育てました。", "target_word": "菜園", "complexity_tier": "T3", "furigana": "学校[がっこう]の菜園[さいえん]で、一年生[いちねんせい]がさつまいもを育[そだ]てました。", "sentence_source": "generated"}, {"text": "菜園の土に肥料を入れて、苗を植えました。", "target_word": "菜園", "complexity_tier": "T3", "furigana": "菜園[さいえん]の土[つち]に肥料[ひりょう]を入[い]れて、苗[なえ]を植[う]えました。", "sentence_source": "generated"}, {"text": "夏休みは菜園の世話で、毎日いそがしかったです。", "target_word": "菜園", "complexity_tier": "T3", "furigana": "夏休[なつやす]みは菜園[さいえん]の世話[せわ]で、毎日[まいにち]いそがしかったです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "菜園", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "野菜や花を育てる小さな畑を指す名詞「菜園」。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T4: contains vocabulary far above tier T4: いそがしかっ (Zipf 1.1)']::text[], '5f3ae7ef-de13-437b-8240-813bdede8e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36836, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "菜園", "is_correct": true, "explanation": "野菜や花を育てる小さな畑で、「庭の○○でトマトを育てる」に入る。"}, {"text": "物置", "is_correct": false, "explanation": "物をしまっておく小屋で、トマトを育てる場所ではない。"}, {"text": "玄関", "is_correct": false, "explanation": "家の出入り口で、植物を育てる場所としては文が成り立たない。"}, {"text": "池", "is_correct": false, "explanation": "水をためた場所で、トマトを育てる場所としては意味が通らない。"}], "explanations": {"菜園": "野菜や花を育てる小さな畑で、「庭の○○でトマトを育てる」に入る。", "物置": "物をしまっておく小屋で、トマトを育てる場所ではない。", "玄関": "家の出入り口で、植物を育てる場所としては文が成り立たない。", "池": "水をためた場所で、トマトを育てる場所としては意味が通らない。"}, "sentence_index": 0, "correct_answer": "菜園"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "菜園では、りんごの木を植えて、毎年たくさん実を収穫する。", "explanation": "ここは〈果樹園〉の意味。菜園は野菜や花を育てる畑で、果樹を植えて実を取る場所の意味では使わない。"}, {"text": "菜園では牛を放して、毎日乳をしぼっている。", "explanation": "ここは〈牧場〉の意味。菜園は作物を育てる畑で、家畜を飼う場所の意味ではないので合わない。"}, {"text": "菜園では稲を植えて、秋に米を刈り取る。", "explanation": "ここは〈水田〉の意味。米は穀物で、菜園が育てる野菜や花の範囲には入らないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36836, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "菜園", "is_correct": true, "explanation": "野菜を育てる畑で、「雨が少なくて、○○の野菜が元気がない」に入る。"}, {"text": "教室", "is_correct": false, "explanation": "授業をする部屋で、野菜が育つ場所ではないので合わない。"}, {"text": "書斎", "is_correct": false, "explanation": "本を読んだり書いたりする部屋で、野菜の生育場所ではない。"}, {"text": "体育館", "is_correct": false, "explanation": "運動や行事に使う建物で、野菜を育てるところではない。"}], "explanations": {"菜園": "野菜を育てる畑で、「雨が少なくて、○○の野菜が元気がない」に入る。", "教室": "授業をする部屋で、野菜が育つ場所ではないので合わない。", "書斎": "本を読んだり書いたりする部屋で、野菜の生育場所ではない。", "体育館": "運動や行事に使う建物で、野菜を育てるところではない。"}, "sentence_index": 6, "correct_answer": "菜園"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "菜園で、週刊誌を買ってきた。", "explanation": "ここは〈売店〉の意味。菜園は作物を育てる畑で、物を売る店の意味では使わない。"}, {"text": "仕事のあと、菜園につかって疲れを取る。", "explanation": "ここは〈温泉〉の意味。菜園は湯につかる場所ではないので、この使い方は合わない。"}, {"text": "菜園で本を借りて、家で読んだ。", "explanation": "ここは〈図書館〉の意味。菜園は本を貸し出す場所ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36836, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末に、父と菜園を草をぬきました。", "corrected_sentence": "週末に、父と菜園の草をぬきました。", "error_description": "「菜園」と「草」の間は連体修飾の「の」が正しい。「を」にすると「菜園を」が目的語になり、「草を」と二重になって不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36836, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は裏の菜園が、きゅうりを作っています。", "corrected_sentence": "祖母は裏の菜園で、きゅうりを作っています。", "error_description": "きゅうりを作る場所を表す「で」が正しい。「が」にすると菜園が主語になり、作るのは祖母なので不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36838, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「授業を楽しんだ」の目的語を示す助詞。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、「授業が楽しんだ」は人が楽しむ文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示すが、楽しむの対象は表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、楽しむの対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「授業を楽しんだ」の目的語を示す助詞。", "が": "主語を示すため、「授業が楽しんだ」は人が楽しむ文として成り立たない。", "に": "相手や場所を示すが、楽しむの対象は表せない。", "へ": "方向を示すため、楽しむの対象にはならない。"}, "error_tags": {"が": "主語の誤り", "に": "相手・場所の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36838, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36838, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かをするのがうれしい、おもしろいと思うこと。", "primary_collocate": null, "pronunciation": "たのしむ", "ipa": "tanoɕimɯ", "syllable_count": 4, "sentences": [{"text": "子どもたちは雪の中で遊んで、冬を楽しんでいる。", "target_word": "楽しんで", "complexity_tier": "T3", "furigana": "子[こ]どもたちは雪[ゆき]の中[なか]で遊[あそ]んで、冬[ふゆ]を楽[たの]しんでいる。", "sentence_source": "generated"}, {"text": "先生の話がおもしろくて、みんな授業を楽しんだ。", "target_word": "楽しんだ", "complexity_tier": "T3", "furigana": "先生[せんせい]の話[はなし]がおもしろくて、みんな授業[じゅぎょう]を楽[たの]しんだ。", "sentence_source": "generated"}, {"text": "旅行では、地元の料理を楽しむつもりだ。", "target_word": "楽しむ", "complexity_tier": "T3", "furigana": "旅行[りょこう]では、地元[じもと]の料理[りょうり]を楽[たの]しむつもりだ。", "sentence_source": "generated"}, {"text": "負けてもいいから、試合を楽しんでほしい。", "target_word": "楽しんで", "complexity_tier": "T3", "furigana": "負[ま]けてもいいから、試合[しあい]を楽[たの]しんでほしい。", "sentence_source": "generated"}, {"text": "彼は音楽を聞きながら、散歩を楽しむ。", "target_word": "楽しむ", "complexity_tier": "T3", "furigana": "彼[かれ]は音楽[おんがく]を聞[き]きながら、散歩[さんぽ]を楽[たの]しむ。", "sentence_source": "generated"}, {"text": "難しい問題でも、考えることを楽しめる人は強い。", "target_word": "楽しめる", "complexity_tier": "T3", "furigana": "難[むずか]しい問題[もんだい]でも、考[かんが]えることを楽[たの]しめる人[ひと]は強[つよ]い。", "sentence_source": "generated"}, {"text": "祭りでは、花火や屋台を楽しんだ。", "target_word": "楽しんだ", "complexity_tier": "T3", "furigana": "祭[まつ]りでは、花火[はなび]や屋台[やたい]を楽[たの]しんだ。", "sentence_source": "generated"}, {"text": "勉強ばかりで、休みの日も何も楽しまなかった。", "target_word": "楽しまなかった", "complexity_tier": "T3", "furigana": "勉強[べんきょう]ばかりで、休[やす]みの日[ひ]も何[なに]も楽[たの]しまなかった。", "sentence_source": "generated"}, {"text": "初めてのスキーを楽しんだので、また来年も行きたい。", "target_word": "楽しんだ", "complexity_tier": "T3", "furigana": "初[はじ]めてのスキーを楽[たの]しんだので、また来年[らいねん]も行[い]きたい。", "sentence_source": "generated"}, {"text": "友だちと映画を楽しんだあと、カフェでお茶を飲んだ。", "target_word": "楽しんだ", "complexity_tier": "T3", "furigana": "友[とも]だちと映画[えいが]を楽[たの]しんだあと、カフェでお茶[ちゃ]を飲[の]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "楽しむ", "label": "終止形"}, {"form": "楽しみ", "label": "連用形"}, {"form": "楽しんで", "label": "て形"}, {"form": "楽しんだ", "label": "過去形"}, {"form": "楽しまない", "label": "否定形"}, {"form": "楽しめる", "label": "可能形"}], "register": "中立（普通体）", "sense_fingerprint": "ある活動や出来事をおもしろい・うれしいと感じて味わう", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e61b9b9-2b71-463a-b7c3-934bb8c70858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36838, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "楽しんで", "is_correct": true, "explanation": "「冬を楽しんでいる」の形で、て形が「いる」に続く。"}, {"text": "楽しみ", "is_correct": false, "explanation": "連用形で、「いる」に続けると文として成り立たない。"}, {"text": "楽しめ", "is_correct": false, "explanation": "命令形で、「冬を楽しめいる」は続かない。"}, {"text": "楽しんだ", "is_correct": false, "explanation": "過去形で、「楽しんだいる」の形は文法的に成り立たない。"}], "explanations": {"楽しんで": "「冬を楽しんでいる」の形で、て形が「いる」に続く。", "楽しみ": "連用形で、「いる」に続けると文として成り立たない。", "楽しめ": "命令形で、「冬を楽しめいる」は続かない。", "楽しんだ": "過去形で、「楽しんだいる」の形は文法的に成り立たない。"}, "sentence_index": 0, "correct_answer": "楽しんで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "合格の知らせを楽しんだ。", "explanation": "ここは〈喜ぶ〉の意味。楽しむは活動を味わう意味で、知らせそのものを楽しむとは言わない。"}, {"text": "ペットの死を楽しんで、一日中部屋にこもった。", "explanation": "ここは〈悲しむ〉の意味。楽しむは嬉しく過ごすことで、ペットの死を楽しむとは言わず、悲しむが合う。"}, {"text": "大事な書類を楽しんで、なくしてしまった。", "explanation": "ここは〈紛失〉の出来事を指す文。書類をなくす場面に楽しむは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36838, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "楽しんだ", "is_correct": true, "explanation": "過去形で、祭りでの出来事を述べる文に自然に収まる。"}, {"text": "楽しまず", "is_correct": false, "explanation": "連用形で、文を終えられない。"}, {"text": "楽しみながら", "is_correct": false, "explanation": "同時の動作を表す形で、文を終えられない。"}, {"text": "楽しみつつ", "is_correct": false, "explanation": "同時の動作を表す形で、文を終えられない。"}], "explanations": {"楽しんだ": "過去形で、祭りでの出来事を述べる文に自然に収まる。", "楽しまず": "連用形で、文を終えられない。", "楽しみながら": "同時の動作を表す形で、文を終えられない。", "楽しみつつ": "同時の動作を表す形で、文を終えられない。"}, "sentence_index": 6, "correct_answer": "楽しんだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "転職先を楽しんで、夜も眠れなかった。", "explanation": "ここは〈悩む〉の意味。転職先について不安になる様子は楽しむとは言わず、悩むが合う。"}, {"text": "手術の痛みを楽しんでいた。", "explanation": "ここは〈我慢〉の意味。痛みを楽しむとは言わず、我慢するという意味になる。"}, {"text": "会社の制度を楽しんで、ぎりぎりまで休んだ。", "explanation": "ここは〈利用〉の意味。制度を使う場面で楽しむとは言わず、利用するが合う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36838, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祭りでは、屋台の味を楽しみつもりだ。", "corrected_sentence": "祭りでは、屋台の味を楽しむつもりだ。", "error_description": "「つもり」の前は動詞の辞書形が必要。「楽しみ」は連用形なので誤りで、正しくは「楽しむつもり」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "楽しんだ", "is_correct": true, "explanation": "過去形で、「先生の話がおもしろくて」という出来事を振り返る文に合う。"}, {"text": "楽しまず", "is_correct": false, "explanation": "連用形（ず）で、文を終えられない。"}, {"text": "楽しんで", "is_correct": false, "explanation": "て形で、文を終えられない。"}, {"text": "楽しみ", "is_correct": false, "explanation": "連用形で、文の述語として終わらせられない。"}], "correct_form": "楽しんだ", "base_form": "楽しむ", "form_label": "過去形", "sentence_index": 1, "explanations": {"楽しんだ": "過去形で、「先生の話がおもしろくて」という出来事を振り返る文に合う。", "楽しまず": "連用形（ず）で、文を終えられない。", "楽しんで": "て形で、文を終えられない。", "楽しみ": "連用形で、文の述語として終わらせられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36838, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は夕方、庭で景色に楽しむ。", "corrected_sentence": "彼は夕方、庭で景色を楽しむ。", "error_description": "「楽しむ」の対象は「を」で示す。「に」を使うと対象が正しく示されない。正しくは「景色を楽しむ」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "楽しまなかった", "is_correct": true, "explanation": "否定の過去形で、何もしなかったという文脈に合う。"}, {"text": "楽しんだ", "is_correct": false, "explanation": "肯定の過去形で、「何も楽しまなかった」の否定の意味と合わない。"}, {"text": "楽しもう", "is_correct": false, "explanation": "意向形で、過去の出来事を表せない。"}, {"text": "楽しめ", "is_correct": false, "explanation": "命令形で、過去の出来事には合わない。"}], "correct_form": "楽しまなかった", "base_form": "楽しむ", "form_label": "否定過去形", "sentence_index": 7, "explanations": {"楽しまなかった": "否定の過去形で、何もしなかったという文脈に合う。", "楽しんだ": "肯定の過去形で、「何も楽しまなかった」の否定の意味と合わない。", "楽しもう": "意向形で、過去の出来事を表せない。", "楽しめ": "命令形で、過去の出来事には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
