INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36839, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "自分の好きなことやしたいことをして、気持ちよく過ごすこと。", "primary_collocate": null, "pronunciation": "たのしむ", "ipa": "tanoɕimɯ", "syllable_count": 4, "sentences": [{"text": "日曜日は、好きな本を読んで一人の時間を楽しむ。", "target_word": "楽しむ", "complexity_tier": "T3", "furigana": "日曜日[にちようび]は、好[す]きな本[ほん]を読[よ]んで一人[ひとり]の時間[じかん]を楽[たの]しむ。", "sentence_source": "generated"}, {"text": "定年のあと、祖父は釣りをして毎日を楽しんでいる。", "target_word": "楽しんで", "complexity_tier": "T3", "furigana": "定年[ていねん]のあと、祖父[そふ]は釣[つ]りをして毎日[まいにち]を楽[たの]しんでいる。", "sentence_source": "generated"}, {"text": "温泉に入って、のんびり休日を楽しんだ。", "target_word": "楽しんだ", "complexity_tier": "T3", "furigana": "温泉[おんせん]に入[はい]って、のんびり休日[きゅうじつ]を楽[たの]しんだ。", "sentence_source": "generated"}, {"text": "仕事を忘れて、週末は趣味を楽しむことにしている。", "target_word": "楽しむ", "complexity_tier": "T3", "furigana": "仕事[しごと]を忘[わす]れて、週末[しゅうまつ]は趣味[しゅみ]を楽[たの]しむことにしている。", "sentence_source": "generated"}, {"text": "彼女は夏の夜、ベランダで風を感じながら読書を楽しんでいた。", "target_word": "楽しんで", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は夏[なつ]の夜[よる]、ベランダで風[かぜ]を感[かん]じながら読書[どくしょ]を楽[たの]しんでいた。", "sentence_source": "generated"}, {"text": "忙しくても、自分の時間を楽しむ余裕がほしい。", "target_word": "楽しむ", "complexity_tier": "T3", "furigana": "忙[いそが]しくても、自分[じぶん]の時間[じかん]を楽[たの]しむ余裕[よゆう]がほしい。", "sentence_source": "generated"}, {"text": "休みの日は、料理を作ってワインを楽しむ。", "target_word": "楽しむ", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]は、料理[りょうり]を作[つく]ってワインを楽[たの]しむ。", "sentence_source": "generated"}, {"text": "海辺のホテルで、静かな朝を楽しんだ。", "target_word": "楽しんだ", "complexity_tier": "T3", "furigana": "海辺[うみべ]のホテルで、静[しず]かな朝[あさ]を楽[たの]しんだ。", "sentence_source": "generated"}, {"text": "退職した母は、旅行や習い事など、自由な生活を楽しんでいる。", "target_word": "楽しんで", "complexity_tier": "T3", "furigana": "退職[たいしょく]した母[はは]は、旅行[りょこう]や習[なら]い事[ごと]など、自由[じゆう]な生活[せいかつ]を楽[たの]しんでいる。", "sentence_source": "generated"}, {"text": "雨の日は家で映画を見て、のんびり楽しむのが好きだ。", "target_word": "楽しむ", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は家[いえ]で映画[えいが]を見[み]て、のんびり楽[たの]しむのが好[す]きだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "楽しむ", "label": "終止形"}, {"form": "楽しみ", "label": "連用形"}, {"form": "楽しんで", "label": "て形"}, {"form": "楽しんだ", "label": "過去形"}, {"form": "楽しまない", "label": "否定形"}, {"form": "楽しめる", "label": "可能形"}], "register": "中立（普通体）", "sense_fingerprint": "好きなことをして、ゆったり気持ちよく時間を過ごす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e61b9b9-2b71-463a-b7c3-934bb8c70858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36839, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "楽しむ", "is_correct": true, "explanation": "終止形で、一人の時間を楽しむという文を言い切れる。"}, {"text": "楽しみ", "is_correct": false, "explanation": "連用形で、文を終えられない。"}, {"text": "楽しまず", "is_correct": false, "explanation": "連用形で、文を終えられない。"}, {"text": "楽しんで", "is_correct": false, "explanation": "て形で、文を終えられない。"}], "explanations": {"楽しむ": "終止形で、一人の時間を楽しむという文を言い切れる。", "楽しみ": "連用形で、文を終えられない。", "楽しまず": "連用形で、文を終えられない。", "楽しんで": "て形で、文を終えられない。"}, "sentence_index": 0, "correct_answer": "楽しむ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先週の失敗を楽しんで、反省した。", "explanation": "失敗を楽しむとは言えず、〈楽しむ〉の意味にならない。"}, {"text": "別れを楽しむことにしている。", "explanation": "別れを楽しむとは言えず、〈楽しむ〉の意味にならない。"}, {"text": "上司の態度を楽しんで、怒った。", "explanation": "上司の態度を楽しむとは言えず、〈楽しむ〉の意味にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36839, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "楽しむ", "is_correct": true, "explanation": "終止形で、ワインを楽しむという文を言い切れる。"}, {"text": "楽しみながら", "is_correct": false, "explanation": "同時の動作を表す形で、文を終えられない。"}, {"text": "楽しみつつ", "is_correct": false, "explanation": "同時の動作を表す形で、文を終えられない。"}, {"text": "楽しんだり", "is_correct": false, "explanation": "例示の形で、文を終えられない。"}], "explanations": {"楽しむ": "終止形で、ワインを楽しむという文を言い切れる。", "楽しみながら": "同時の動作を表す形で、文を終えられない。", "楽しみつつ": "同時の動作を表す形で、文を終えられない。", "楽しんだり": "例示の形で、文を終えられない。"}, "sentence_index": 6, "correct_answer": "楽しむ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "隣の騒音を楽しんで、役所に訴えた。", "explanation": "騒音を楽しむとは言えず、〈楽しむ〉の意味にならない。"}, {"text": "財布の中身を楽しんで、全部使い切った。", "explanation": "財布の中身を楽しむとは言えず、〈楽しむ〉の意味にならない。"}, {"text": "部下の失敗を楽しんで、きつく叱った。", "explanation": "部下の失敗を楽しむとは言えず、〈楽しむ〉の意味にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36839, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "連休は、山で一人の時間に楽しもうと決めた。", "corrected_sentence": "連休は、山で一人の時間を楽しもうと決めた。", "error_description": "「楽しむ」の対象は「を」で示す。「に」を使うと、時間が楽しむ相手として誤って示される。正しくは「時間を楽しもう」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "楽しんで", "is_correct": true, "explanation": "て形で、「楽しんでいる」の形になり現在の様子を表す。"}, {"text": "楽しみ", "is_correct": false, "explanation": "連用形で、「楽しんでいる」の形を作れない。"}, {"text": "楽しまない", "is_correct": false, "explanation": "否定形で、毎日を楽しんでいるという肯定の文と合わない。"}, {"text": "楽しもう", "is_correct": false, "explanation": "意向形で、「楽しもういる」とは続かず、今の様子を表せない。"}], "correct_form": "楽しんで", "base_form": "楽しむ", "form_label": "て形", "sentence_index": 1, "explanations": {"楽しんで": "て形で、「楽しんでいる」の形になり現在の様子を表す。", "楽しみ": "連用形で、「楽しんでいる」の形を作れない。", "楽しまない": "否定形で、毎日を楽しんでいるという肯定の文と合わない。", "楽しもう": "意向形で、「楽しもういる」とは続かず、今の様子を表せない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36839, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は休日、カフェで音楽を楽しみ人だ。", "corrected_sentence": "彼女は休日、カフェで音楽を楽しむ人だ。", "error_description": "「人」を修飾する形は動詞の辞書形が必要。「楽しみ」は連用形なので誤りで、正しくは「楽しむ人」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "楽しんだ", "is_correct": true, "explanation": "過去形で、ホテルで朝を過ごした出来事を表す。"}, {"text": "楽しもう", "is_correct": false, "explanation": "意向形で、過去の出来事を表せない。"}, {"text": "楽しめ", "is_correct": false, "explanation": "命令形で、過去の出来事には合わない。"}, {"text": "楽しまれ", "is_correct": false, "explanation": "受身の連用形で、文を終えられず「楽しまれ。」とは言えない。"}], "correct_form": "楽しんだ", "base_form": "楽しむ", "form_label": "過去形", "sentence_index": 7, "explanations": {"楽しんだ": "過去形で、ホテルで朝を過ごした出来事を表す。", "楽しもう": "意向形で、過去の出来事を表せない。", "楽しめ": "命令形で、過去の出来事には合わない。", "楽しまれ": "受身の連用形で、文を終えられず「楽しまれ。」とは言えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36840, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "起点を示す「から」。「台所からいいにおいがする」の起点として合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。においがする文では目的語を取らないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。においが台所へ向かう意味になり、文脈に合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」。「台所といいにおい」の形では文が成り立たない。"}], "correct_answer": "から", "explanations": {"から": "起点を示す「から」。「台所からいいにおいがする」の起点として合う。", "を": "目的語の「を」。においがする文では目的語を取らないので合わない。", "へ": "方向を示す「へ」。においが台所へ向かう意味になり、文脈に合わない。", "と": "並列の「と」。「台所といいにおい」の形では文が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36840, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "方向を示す「へ」。「台所へ行った」の到着点として合う。"}, {"text": "で", "is_correct": false, "explanation": "場所の「で」。行く動作の場所にはならず、「台所で行った」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。「台所が行った」になり、行くのは人なので合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「台所の行った」の形にならない。"}], "correct_answer": "へ", "explanations": {"へ": "方向を示す「へ」。「台所へ行った」の到着点として合う。", "で": "場所の「で」。行く動作の場所にはならず、「台所で行った」は不自然。", "が": "主語の「が」。「台所が行った」になり、行くのは人なので合わない。", "の": "連体修飾の「の」。「台所の行った」の形にならない。"}, "error_tags": {"で": "場所", "が": "主語", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36840, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ごはんを作るへやのことです。", "primary_collocate": null, "pronunciation": "だいどころ", "ipa": "daidokoɾo", "syllable_count": 5, "sentences": [{"text": "母は朝早く台所で朝ごはんを作っている。", "target_word": "台所", "complexity_tier": "T3", "furigana": "母[はは]は朝[あさ]早[はや]く台所[だいどころ]で朝[あさ]ごはんを作[つく]っている。", "sentence_source": "generated"}, {"text": "台所からいいにおいがして、おなかがすいてきた。", "target_word": "台所", "complexity_tier": "T3", "furigana": "台所[だいどころ]からいいにおいがして、おなかがすいてきた。", "sentence_source": "generated"}, {"text": "新しい家は台所が広いので、家族みんなで料理ができる。", "target_word": "台所", "complexity_tier": "T3", "furigana": "新[あたら]しい家[いえ]は台所[だいどころ]が広[ひろ]いので、家族[かぞく]みんなで料理[りょうり]ができる。", "sentence_source": "generated"}, {"text": "夕食のあと、父は台所で皿を洗った。", "target_word": "台所", "complexity_tier": "T3", "furigana": "夕食[ゆうしょく]のあと、父[ちち]は台所[だいどころ]で皿[さら]を洗[あら]った。", "sentence_source": "generated"}, {"text": "台所の窓を開けると、庭の花が見える。", "target_word": "台所", "complexity_tier": "T3", "furigana": "台所[だいどころ]の窓[まど]を開[あ]けると、庭[にわ]の花[はな]が見[み]える。", "sentence_source": "generated"}, {"text": "姉は料理が好きで、一日の半分を台所で過ごす。", "target_word": "台所", "complexity_tier": "T3", "furigana": "姉[あね]は料理[りょうり]が好[す]きで、一日[いちにち]の半分[はんぶん]を台所[だいどころ]で過[す]ごす。", "sentence_source": "generated"}, {"text": "台所にいる母に「手伝おうか」と声をかけた。", "target_word": "台所", "complexity_tier": "T3", "furigana": "台所[だいどころ]にいる母[はは]に「手伝[てつだ]おうか」と声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "お湯をわかそうとして、台所へ行った。", "target_word": "台所", "complexity_tier": "T3", "furigana": "お湯[ゆ]をわかそうとして、台所[だいどころ]へ行[い]った。", "sentence_source": "generated"}, {"text": "台所が暑いので、小さい扇風機を置いた。", "target_word": "台所", "complexity_tier": "T3", "furigana": "台所[だいどころ]が暑[あつ]いので、小[ちい]さい扇風機[せんぷうき]を置[お]いた。", "sentence_source": "generated"}, {"text": "リビングは片づいているが、台所はまだ散らかっている。", "target_word": "台所", "complexity_tier": "T3", "furigana": "リビングは片[かた]づいているが、台所[だいどころ]はまだ散[ち]らかっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "台所", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "家の中で食事を作るための部屋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: 片づい (Zipf 1.86)']::text[], '5f3ae7ef-de13-437b-8240-813bdede8e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36840, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "台所", "is_correct": true, "explanation": "ごはんを作る部屋で、「○○で朝ごはんを作っている」に入る。"}, {"text": "浴室", "is_correct": false, "explanation": "体を洗う部屋で、朝ごはんを作る場所ではない。"}, {"text": "寝室", "is_correct": false, "explanation": "寝るための部屋で、料理をする場所ではない。"}, {"text": "玄関", "is_correct": false, "explanation": "家の出入り口で、朝ごはんを作る場所としては文が成り立たない。"}], "explanations": {"台所": "ごはんを作る部屋で、「○○で朝ごはんを作っている」に入る。", "浴室": "体を洗う部屋で、朝ごはんを作る場所ではない。", "寝室": "寝るための部屋で、料理をする場所ではない。", "玄関": "家の出入り口で、朝ごはんを作る場所としては文が成り立たない。"}, "sentence_index": 0, "correct_answer": "台所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台所で、歯をみがいた。", "explanation": "ここは〈洗面所〉の意味。台所は調理の部屋で、歯をみがく場所の意味では使わない。"}, {"text": "台所で、車を洗った。", "explanation": "ここは〈洗車場〉の意味。台所は車を洗う場所ではないので合わない。"}, {"text": "台所で、黒板を消した。", "explanation": "ここは〈教室〉の意味。台所は授業の場所ではなく、黒板を消す場所としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36840, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "台所", "is_correct": true, "explanation": "家で料理をする部屋で、「○○にいる母に声をかけた」の場所として合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、人がいる場所としては合わない。"}, {"text": "海", "is_correct": false, "explanation": "広い水域で、母がいる場所として文が成り立たない。"}, {"text": "病院", "is_correct": false, "explanation": "治療の施設で、手伝いを申し出る文脈に合わない。"}], "explanations": {"台所": "家で料理をする部屋で、「○○にいる母に声をかけた」の場所として合う。", "冷蔵庫": "食品を冷やす家電で、人がいる場所としては合わない。", "海": "広い水域で、母がいる場所として文が成り立たない。", "病院": "治療の施設で、手伝いを申し出る文脈に合わない。"}, "sentence_index": 6, "correct_answer": "台所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台所で、昼ごはんを注文した。", "explanation": "ここは〈食堂〉の意味。台所は家で料理をする部屋で、注文する場所ではない。"}, {"text": "台所で、ボウリングのピンを倒した。", "explanation": "ここは〈ボウリング場〉の意味。台所は食べ物を調理する部屋で、ピンを倒して遊ぶ場所の意味では使わないので合わない。"}, {"text": "台所で、本を借りた。", "explanation": "ここは〈図書館〉の意味。台所は本を貸し出す場所ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36840, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は夜、台所を皿を洗っています。", "corrected_sentence": "父は夜、台所で皿を洗っています。", "error_description": "皿を洗う場所を表す「で」が正しい。「を」にすると台所が目的語になり、「皿を」と二重になって不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36840, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は毎朝、台所がお茶をいれます。", "corrected_sentence": "祖母は毎朝、台所でお茶をいれます。", "error_description": "お茶をいれる場所を表す「で」が正しい。「が」にすると台所が主語になり、いれるのは祖母なので不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
