INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36842, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "野菜や果物の外側の部分です。食べないでむきます。", "primary_collocate": null, "pronunciation": "かわ", "ipa": "kawa", "syllable_count": 2, "sentences": [{"text": "りんごの皮をむいてから、小さく切る。", "target_word": "皮", "complexity_tier": "T3", "furigana": "りんごの皮[かわ]をむいてから、小[ちい]さく切[き]る。", "sentence_source": "generated"}, {"text": "バナナの皮はすべりやすいので、道に捨ててはいけない。", "target_word": "皮", "complexity_tier": "T3", "furigana": "バナナの皮[かわ]はすべりやすいので、道[みち]に捨[す]ててはいけない。", "sentence_source": "generated"}, {"text": "みかんの皮は、むいたあとゴミ箱に入れた。", "target_word": "皮", "complexity_tier": "T3", "furigana": "みかんの皮[かわ]は、むいたあとゴミ箱[ばこ]に入[い]れた。", "sentence_source": "generated"}, {"text": "じゃがいもの皮をむくのは、時間がかかる。", "target_word": "皮", "complexity_tier": "T3", "furigana": "じゃがいもの皮[かわ]をむくのは、時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "スイカの皮は固いので、食べずに捨てる。", "target_word": "皮", "complexity_tier": "T3", "furigana": "スイカの皮[かわ]は固[かた]いので、食[た]べずに捨[す]てる。", "sentence_source": "generated"}, {"text": "母は包丁で大根の皮を厚くむいた。", "target_word": "皮", "complexity_tier": "T3", "furigana": "母[はは]は包丁[ほうちょう]で大根[だいこん]の皮[かわ]を厚[あつ]くむいた。", "sentence_source": "generated"}, {"text": "柿の皮をむいて、干し柿を作る。", "target_word": "皮", "complexity_tier": "T3", "furigana": "柿[かき]の皮[かわ]をむいて、干[ほ]し柿[がき]を作[つく]る。", "sentence_source": "generated"}, {"text": "トマトの皮は、お湯につけるときれいにむける。", "target_word": "皮", "complexity_tier": "T3", "furigana": "トマトの皮[かわ]は、お湯[ゆ]につけるときれいにむける。", "sentence_source": "generated"}, {"text": "にんじんの皮は、ピーラーでうすくむくと楽だ。", "target_word": "皮", "complexity_tier": "T3", "furigana": "にんじんの皮[かわ]は、ピーラーでうすくむくと楽[らく]だ。", "sentence_source": "generated"}, {"text": "栗の皮は固いので、ナイフで切れ目を入れてからむく。", "target_word": "皮", "complexity_tier": "T3", "furigana": "栗[くり]の皮[かわ]は固[かた]いので、ナイフで切[き]れ目[め]を入[い]れてからむく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "皮", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "野菜や果物の食べずにむいて捨てる外側の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: むける (Zipf 2.15)','sentence 8 above tier T2: contains vocabulary far above tier T2: ピーラー (Zipf 2.13), うすく (Zipf 2.37)']::text[], '5f3ae7ef-de13-437b-8240-813bdede8e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36842, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "皮", "is_correct": true, "explanation": "「りんごの皮をむく」の皮。食べずにむいて捨てる外側の部分なので正解。"}, {"text": "種", "is_correct": false, "explanation": "種は果実の中心にあり、むいて取り除くものではないので合わない。"}, {"text": "葉", "is_correct": false, "explanation": "葉は枝についている部分で、りんごの外側をむく対象にならない。"}, {"text": "根", "is_correct": false, "explanation": "根は地中にある部分で、りんごの外側をむいて切る対象ではない。"}], "explanations": {"皮": "「りんごの皮をむく」の皮。食べずにむいて捨てる外側の部分なので正解。", "種": "種は果実の中心にあり、むいて取り除くものではないので合わない。", "葉": "葉は枝についている部分で、りんごの外側をむく対象にならない。", "根": "根は地中にある部分で、りんごの外側をむいて切る対象ではない。"}, "sentence_index": 0, "correct_answer": "皮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い太鼓の皮を張り替えて、音を良くした。", "explanation": "ここは〈太鼓の張り面〉の意味。太鼓に張った動物の皮を指すので、野菜や果物の外側という今回の語義とは合わない。"}, {"text": "貝の皮をはずしてから、鍋に入れる。", "explanation": "ここは〈殻〉の意味。貝の固い外側は殻と言い、皮とは言わないので合わない。"}, {"text": "寒い冬は皮のコートを着て出かける。", "explanation": "ここは〈なめし革〉の意味。動物の皮を加工した素材を指すので、野菜や果物の外側という今回の語義とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36842, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皮", "is_correct": true, "explanation": "「柿の皮をむく」の皮。食べずにむいて捨てる外側の部分なので正解。"}, {"text": "枝", "is_correct": false, "explanation": "枝は木の幹から伸びる部分で、柿の外側をむく対象にはならない。"}, {"text": "茎", "is_correct": false, "explanation": "茎は植物を支える部分で、柿の実をむく対象ではないので合わない。"}, {"text": "芽", "is_correct": false, "explanation": "芽は新しく出てくる部分で、むいて取り除く外側の層ではない。"}], "explanations": {"皮": "「柿の皮をむく」の皮。食べずにむいて捨てる外側の部分なので正解。", "枝": "枝は木の幹から伸びる部分で、柿の外側をむく対象にはならない。", "茎": "茎は植物を支える部分で、柿の実をむく対象ではないので合わない。", "芽": "芽は新しく出てくる部分で、むいて取り除く外側の層ではない。"}, "sentence_index": 6, "correct_answer": "皮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "煮詰めた牛乳の表面に皮が張った。", "explanation": "ここは〈膜〉の意味。液体の表面にできる薄い膜を指すので、野菜や果物の外側という今回の語義とは合わない。"}, {"text": "カメの皮は、とても硬くて割れにくい。", "explanation": "ここは〈甲羅〉の意味。カメの硬い外側は甲羅と言い、皮とは言わないので合わない。"}, {"text": "饅頭の皮を薄くのばして、あんを包む。", "explanation": "ここは〈包む生地〉の意味。饅頭や餃子の生地を指すので、野菜や果物の外側という今回の語義とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36842, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "みかんの皮を飲んでから、ゴミ箱に捨てた。", "corrected_sentence": "みかんの皮をむいてから、ゴミ箱に捨てた。", "error_description": "『皮』に対する動詞の誤り。皮は『むく』の対象で、『飲む』は合わない。正しくは『むいてから』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36842, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "柿の皮をむくてから、干し柿を作る。", "corrected_sentence": "柿の皮をむいてから、干し柿を作る。", "error_description": "『むく』の活用の誤り。て形は『むいて』になる。『むくてから』は活用形として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36843, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『皮』は『ぬぐ』の対象なので、目的語を示す『を』が正しい。"}, {"text": "に", "is_correct": false, "explanation": "『皮に』では『ぬぐ』の対象を示せず、この文には合わない。"}, {"text": "で", "is_correct": false, "explanation": "『皮で』は手段の意味になり、『ぬぐ』の対象としては不自然。"}, {"text": "と", "is_correct": false, "explanation": "『皮と』は並列や共同の相手を表すが、『ぬぐ』の対象としては成り立たない。"}], "correct_answer": "を", "explanations": {"を": "『皮』は『ぬぐ』の対象なので、目的語を示す『を』が正しい。", "に": "『皮に』では『ぬぐ』の対象を示せず、この文には合わない。", "で": "『皮で』は手段の意味になり、『ぬぐ』の対象としては不自然。", "と": "『皮と』は並列や共同の相手を表すが、『ぬぐ』の対象としては成り立たない。"}, "error_tags": {"に": "位置", "で": "手段", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36843, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『皮』が『厚い』の主語を示すので『が』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『皮を厚い』は形容詞『厚い』が目的語を取れないため不自然で、この文には合わない。"}, {"text": "に", "is_correct": false, "explanation": "『皮に厚い』では『厚い』の主語を示せず、文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "『皮で厚い』は手段の意味になり、主語と述語の関係が合わない。"}], "correct_answer": "が", "explanations": {"が": "『皮』が『厚い』の主語を示すので『が』が正しい。", "を": "『皮を厚い』は形容詞『厚い』が目的語を取れないため不自然で、この文には合わない。", "に": "『皮に厚い』では『厚い』の主語を示せず、文として成り立たない。", "で": "『皮で厚い』は手段の意味になり、主語と述語の関係が合わない。"}, "error_tags": {"を": "対象", "に": "位置", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36843, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "動物や植物の体をおおっている、外側の薄い部分。", "primary_collocate": null, "pronunciation": "かわ", "ipa": "kawa", "syllable_count": 2, "sentences": [{"text": "木の皮は、強い風や寒さから幹を守っている。", "target_word": "皮", "complexity_tier": "T3", "furigana": "木[き]の皮[かわ]は、強[つよ]い風[かぜ]や寒[さむ]さから幹[みき]を守[まも]っている。", "sentence_source": "generated"}, {"text": "へびは大きくなると、古い皮をぬいで新しくなる。", "target_word": "皮", "complexity_tier": "T3", "furigana": "へびは大[おお]きくなると、古[ふる]い皮[かわ]をぬいで新[あたら]しくなる。", "sentence_source": "generated"}, {"text": "日に焼けて、鼻の皮がむけてしまった。", "target_word": "皮", "complexity_tier": "T3", "furigana": "日[ひ]に焼[や]けて、鼻[はな]の皮[かわ]がむけてしまった。", "sentence_source": "generated"}, {"text": "動物の皮は、昔からかばんや靴の材料に使われてきた。", "target_word": "皮", "complexity_tier": "T3", "furigana": "動物[どうぶつ]の皮[かわ]は、昔[むかし]からかばんや靴[くつ]の材料[ざいりょう]に使[つか]われてきた。", "sentence_source": "generated"}, {"text": "シカは冬になると、木の皮を食べることがある。", "target_word": "皮", "complexity_tier": "T3", "furigana": "シカは冬[ふゆ]になると、木[き]の皮[かわ]を食[た]べることがある。", "sentence_source": "generated"}, {"text": "竹の皮で包んだおにぎりは、竹のいいにおいがする。", "target_word": "皮", "complexity_tier": "T3", "furigana": "竹[たけ]の皮[かわ]で包[つつ]んだおにぎりは、竹[たけ]のいいにおいがする。", "sentence_source": "generated"}, {"text": "カエルの皮はぬれていて、さわるとぬるぬるする。", "target_word": "皮", "complexity_tier": "T3", "furigana": "カエルの皮[かわ]はぬれていて、さわるとぬるぬるする。", "sentence_source": "generated"}, {"text": "手の皮が厚いのは、毎日重い荷物を運んでいるからだ。", "target_word": "皮", "complexity_tier": "T3", "furigana": "手[て]の皮[かわ]が厚[あつ]いのは、毎日[まいにち]重[おも]い荷物[にもつ]を運[はこ]んでいるからだ。", "sentence_source": "generated"}, {"text": "サクラの木から皮をはぐと、木が弱って枯れてしまう。", "target_word": "皮", "complexity_tier": "T3", "furigana": "サクラの木[き]から皮[かわ]をはぐと、木[き]が弱[よわ]って枯[か]れてしまう。", "sentence_source": "generated"}, {"text": "ゾウの皮は厚くて、しわがたくさんある。", "target_word": "皮", "complexity_tier": "T3", "furigana": "ゾウの皮[かわ]は厚[あつ]くて、しわがたくさんある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "皮", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "動物や植物の体の表面をおおう薄い外側の層", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f3ae7ef-de13-437b-8240-813bdede8e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36843, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "皮", "is_correct": true, "explanation": "木の表面をおおう外側の層を指し、幹を守る役目を持つ部分なので正解。"}, {"text": "花", "is_correct": false, "explanation": "花は咲いて実を結ぶ部分で、幹を風や寒さから守る役割はない。"}, {"text": "実", "is_correct": false, "explanation": "実は果実で、幹を寒さや風から守る役目を担わないので合わない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは形のあるものではなく、幹を守る部分として成り立たない。"}], "explanations": {"皮": "木の表面をおおう外側の層を指し、幹を守る役目を持つ部分なので正解。", "花": "花は咲いて実を結ぶ部分で、幹を風や寒さから守る役割はない。", "実": "実は果実で、幹を寒さや風から守る役目を担わないので合わない。", "香り": "香りは形のあるものではなく、幹を守る部分として成り立たない。"}, "sentence_index": 0, "correct_answer": "皮"}, "level_6": {"correct_sentence_index": 7, "wrong_sentences": [{"text": "子犬の皮がふさふさしていて、かわいい。", "explanation": "ここは〈毛〉の意味。ふさふさした毛並みは毛と言い、皮はその下の表面の層を指すので合わない。"}, {"text": "卵の皮が固くて、なかなか割れない。", "explanation": "ここは〈殻〉の意味。卵の固い外側は殻と言い、皮とは言わないので合わない。"}, {"text": "豆乳を温めると、表面にうすい皮ができる。", "explanation": "ここは〈膜〉の意味。液体の表面にできる薄い膜を指すので、動物や植物の体をおおう外側の部分という今回の語義とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36843, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皮", "is_correct": true, "explanation": "カエルの体の外側をおおう皮膚で、ぬれていてさわるとぬるぬるする部分なので正解。"}, {"text": "殻", "is_correct": false, "explanation": "殻はカメや貝などが持つ固い外側で、カエルには無く、ぬるぬるした表面にも合わない。"}, {"text": "羽", "is_correct": false, "explanation": "羽はカエルにはなく、ぬれてぬるぬるする表面を指す語ではない。"}, {"text": "毛", "is_correct": false, "explanation": "毛はカエルには生えておらず、ぬるぬるした体の表面を指す語ではない。"}], "explanations": {"皮": "カエルの体の外側をおおう皮膚で、ぬれていてさわるとぬるぬるする部分なので正解。", "殻": "殻はカメや貝などが持つ固い外側で、カエルには無く、ぬるぬるした表面にも合わない。", "羽": "羽はカエルにはなく、ぬれてぬるぬるする表面を指す語ではない。", "毛": "毛はカエルには生えておらず、ぬるぬるした体の表面を指す語ではない。"}, "sentence_index": 6, "correct_answer": "皮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "シカの皮は毎年生え変わる。", "explanation": "ここは〈角〉の意味。毎年生え変わるのは角で、皮が生え変わるものではないので合わない。"}, {"text": "カメの皮は、とても硬くて割れにくい。", "explanation": "ここは〈甲羅〉の意味。カメの硬い外側は甲羅と言い、皮とは言わないので合わない。"}, {"text": "餃子の皮を薄くのばして、具を包む。", "explanation": "ここは〈包む生地〉の意味。餃子や饅頭の生地を指すので、動物や植物の体をおおう外側の部分という今回の語義とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36843, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鼻の皮がむいて、ひりひりする。", "corrected_sentence": "鼻の皮がむけて、ひりひりする。", "error_description": "動詞の自動詞・他動詞の誤り。『皮がむける』は自動詞で、皮が主語の文では『むけて』が正しい。『むいて』は他動詞で合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36843, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ゾウの皮を厚くて、しわがたくさんある。", "corrected_sentence": "ゾウの皮が厚くて、しわがたくさんある。", "error_description": "助詞の誤り。『皮』は形容詞『厚い』の主語なので『が』が正しい。『を』では『厚くて』と結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
