INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36844, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "野菜のくずや食べ物の残りかす。", "primary_collocate": null, "pronunciation": "かす", "ipa": "kasɯ", "syllable_count": 2, "sentences": [{"text": "ジューサーにかけたあとの野菜の滓は、ふりかけにして食べられる。", "target_word": "滓", "complexity_tier": "T3", "furigana": "じゅーさーにかけたあとのやさいのかすは、ふりかけにしてたべられる。", "sentence_source": "generated"}, {"text": "にんじんをすりおろしたときに出た滓で、ハンバーグを作った。", "target_word": "滓", "complexity_tier": "T3", "furigana": "にんじんをすりおろしたときにでたかすで、はんばーぐをつくった。", "sentence_source": "generated"}, {"text": "大根おろしの滓は、水けをしぼってからみそ汁に入れる。", "target_word": "滓", "complexity_tier": "T3", "furigana": "だいこんおろしのかすは、みずけをしぼってからみそしるにいれる。", "sentence_source": "generated"}, {"text": "野菜を大量に下ごしらえすると、どうしても滓が多く出る。", "target_word": "滓", "complexity_tier": "T3", "furigana": "やさいをたいりょうにしたごしらえすると、どうしてもかすがおおくでる。", "sentence_source": "generated"}, {"text": "野菜の滓をそのまま捨てるのはもったいないので、堆肥にする。", "target_word": "滓", "complexity_tier": "T3", "furigana": "やさいのかすをそのますてるのはもったいないので、たいひにする。", "sentence_source": "generated"}, {"text": "ジュースを作ったあとに残った野菜の滓を、スープに加えた。", "target_word": "滓", "complexity_tier": "T3", "furigana": "じゅーすをつくったあとにのこったやさいのかすを、すーぷにくわえた。", "sentence_source": "generated"}, {"text": "野菜の滓をじっくり炒めると、香ばしくておいしい。", "target_word": "滓", "complexity_tier": "T3", "furigana": "やさいのかすをじっくりいためると、こうばしくておいしい。", "sentence_source": "generated"}, {"text": "ミキサーにかけた野菜の滓は、袋に入れて冷凍しておく。", "target_word": "滓", "complexity_tier": "T3", "furigana": "みきさーにかけたやさいのかすは、ふくろにいれてれいとうしておく。", "sentence_source": "generated"}, {"text": "野菜の滓が流しに残らないよう、三角コーナーに受けておく。", "target_word": "滓", "complexity_tier": "T3", "furigana": "やさいのかすがながしにのこらないよう、さんかくこーなーにうけておく。", "sentence_source": "generated"}, {"text": "家庭菜園では、野菜の滓を発酵させて肥料にしている。", "target_word": "滓", "complexity_tier": "T3", "furigana": "かていさいえんでは、やさいのかすをはっこうさせてひりょうにしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "滓", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "料理や食事のあとに出る野菜のくずや食べ物の残り", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f3ae7ef-de13-437b-8240-813bdede8e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36844, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "滓", "is_correct": true, "explanation": "野菜を下ごしらえしたあとに出る残りかすで、ふりかけにして食べられるので正解。"}, {"text": "汁", "is_correct": false, "explanation": "汁は液体で、乾かしてふりかけにできる固形の残りではないので合わない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは形のあるものではなく、ふりかけとして食べられる材料にならない。"}, {"text": "色", "is_correct": false, "explanation": "色は食材そのものではなく、ふりかけにする対象として成り立たない。"}], "explanations": {"滓": "野菜を下ごしらえしたあとに出る残りかすで、ふりかけにして食べられるので正解。", "汁": "汁は液体で、乾かしてふりかけにできる固形の残りではないので合わない。", "香り": "香りは形のあるものではなく、ふりかけとして食べられる材料にならない。", "色": "色は食材そのものではなく、ふりかけにする対象として成り立たない。"}, "sentence_index": 0, "correct_answer": "滓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ワインの瓶の底には、赤い滓がたまっている。", "explanation": "ここは〈澱〉の意味。ワインなどの底に沈む沈殿物を指すので、野菜のくずや食べ物の残りかすという今回の語義とは別なので合わない。"}, {"text": "彼は社会の滓と呼ばれ、誰からも相手にされなかった。", "explanation": "ここは〈人のくず〉の意味。人を卑しめて言う語で、野菜のくずや食べ物の残りかすという今回の語義とは合わない。"}, {"text": "卵の滓を集めて、庭にまく。", "explanation": "ここは〈殻〉の意味。卵の固い外側は殻と言い、滓とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36844, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滓", "is_correct": true, "explanation": "野菜の残りかすで、じっくり炒めて香ばしくできる材料なので正解。"}, {"text": "灰", "is_correct": false, "explanation": "灰は燃やしたあとに残るもので、野菜を炒めて食べる材料にはならない。"}, {"text": "泡", "is_correct": false, "explanation": "泡は液体の表面にできるもので、野菜を炒める材料ではないので合わない。"}, {"text": "露", "is_correct": false, "explanation": "露は空気中の水分が物に付いたもので、炒めて香ばしくする対象ではない。"}], "explanations": {"滓": "野菜の残りかすで、じっくり炒めて香ばしくできる材料なので正解。", "灰": "灰は燃やしたあとに残るもので、野菜を炒めて食べる材料にはならない。", "泡": "泡は液体の表面にできるもので、野菜を炒める材料ではないので合わない。", "露": "露は空気中の水分が物に付いたもので、炒めて香ばしくする対象ではない。"}, "sentence_index": 6, "correct_answer": "滓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "製鉄所の炉から、鉄の滓が流れ出した。", "explanation": "ここは〈鉱滓〉の意味。鉄の精錬で生じる金属の残りを指すので、野菜のくずや食べ物の残りかすという今回の語義とは合わない。"}, {"text": "湯を沸かした鍋の底に、白い滓がこびりついた。", "explanation": "ここは〈水垢〉の意味。水の成分が固まってつくものを指すので、野菜のくずや食べ物の残りかすという今回の語義とは合わない。"}, {"text": "桜の滓が、風に乗って散る。", "explanation": "ここは〈花びら〉の意味。風に乗って散るのは花びらで、野菜の残りかすを指す滓では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36844, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "野菜の滓に、ふりかけにして食べる人もいる。", "corrected_sentence": "野菜の滓を、ふりかけにして食べる人もいる。", "error_description": "助詞の誤り。『食べる』の対象を示すのは『を』。『に』では食べる対象にならず、文として誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36844, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "野菜の滓を炒めり、香ばしい香りを出した。", "corrected_sentence": "野菜の滓を炒めて、香ばしい香りを出した。", "error_description": "動詞の活用の誤り。『炒める』のて形は『炒めて』。『炒めり』は活用形として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36845, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『白い滓』が『残る』の主語を示すので『が』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『残る』は目的語を取らないので、『を』では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "『白い滓で残る』は手段の意味になり、『残る』の主語としては合わない。"}, {"text": "と", "is_correct": false, "explanation": "『と残る』は相手や並列を示すが、ここでは成り立たない。"}], "correct_answer": "が", "explanations": {"が": "『白い滓』が『残る』の主語を示すので『が』が正しい。", "を": "『残る』は目的語を取らないので、『を』では文が成り立たない。", "で": "『白い滓で残る』は手段の意味になり、『残る』の主語としては合わない。", "と": "『と残る』は相手や並列を示すが、ここでは成り立たない。"}, "error_tags": {"を": "対象", "で": "手段", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36845, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36845, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "液体をこしたあとに残る固体の部分。", "primary_collocate": null, "pronunciation": "かす", "ipa": "kasɯ", "syllable_count": 2, "sentences": [{"text": "コーヒーをいれたあと、フィルターに残った滓を捨てた。", "target_word": "滓", "complexity_tier": "T3", "furigana": "コーヒーをいれたあと、フィルターに残[のこ]った滓[かす]を捨[す]てた。", "sentence_source": "generated"}, {"text": "豆乳をこすと、布の中に白い滓が残る。", "target_word": "滓", "complexity_tier": "T3", "furigana": "豆乳[とうにゅう]をこすと、布[ぬの]の中[なか]に白[しろ]い滓[かす]が残[のこ]る。", "sentence_source": "generated"}, {"text": "ジュースをしぼったあとの滓も、ケーキに入れると使える。", "target_word": "滓", "complexity_tier": "T3", "furigana": "ジュースをしぼったあとの滓[かす]も、ケーキに入[い]れると使[つか]える。", "sentence_source": "generated"}, {"text": "お茶を飲み終わったら、急須の滓を捨てて洗う。", "target_word": "滓", "complexity_tier": "T3", "furigana": "お茶[ちゃ]を飲[の]み終[お]わったら、急須[きゅうす]の滓[かす]を捨[す]てて洗[あら]う。", "sentence_source": "generated"}, {"text": "油をしぼったあとの滓は、肥料や飼料に使われる。", "target_word": "滓", "complexity_tier": "T3", "furigana": "油[あぶら]をしぼったあとの滓[かす]は、肥料[ひりょう]や飼料[しりょう]に使[つか]われる。", "sentence_source": "generated"}, {"text": "茶こしにたまった滓を、そのままにするとカビが生える。", "target_word": "滓", "complexity_tier": "T3", "furigana": "茶[ちゃ]こしにたまった滓[かす]を、そのままにするとカビが生[は]える。", "sentence_source": "generated"}, {"text": "スープをこしたら、網の上に滓だけが残った。", "target_word": "滓", "complexity_tier": "T3", "furigana": "スープをこしたら、網[あみ]の上[うえ]に滓[かす]だけが残[のこ]った。", "sentence_source": "generated"}, {"text": "だしをこしたあとに残った滓を、炒めて佃煮にした。", "target_word": "滓", "complexity_tier": "T3", "furigana": "だしをこしたあとにのこったかすを、いためてつくだににした。", "sentence_source": "generated"}, {"text": "薬草を煮出したあと、滓を布でしぼってから捨てる。", "target_word": "滓", "complexity_tier": "T3", "furigana": "薬草[やくそう]を煮出[にだ]したあと、滓[かす]を布[ぬの]でしぼってから捨[す]てる。", "sentence_source": "generated"}, {"text": "古いお茶の滓が、カップの底にたまっていた。", "target_word": "滓", "complexity_tier": "T3", "furigana": "古[ふる]いお茶[ちゃ]の滓[かす]が、カップの底[そこ]にたまっていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "滓", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "液体をこしたりしぼったりしたあとに残る固体の残りかす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f3ae7ef-de13-437b-8240-813bdede8e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36845, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "滓", "is_correct": true, "explanation": "こしたあとにフィルターに残った固体の残りかすで、捨てるものなので正解。"}, {"text": "香り", "is_correct": false, "explanation": "香りは形のないもので、フィルターに残って捨てる対象ではないので合わない。"}, {"text": "色", "is_correct": false, "explanation": "色は物の性質で、フィルターに残って捨てる残りものにはならない。"}, {"text": "音", "is_correct": false, "explanation": "音は形のないもので、フィルターに残って捨てるものではないので合わない。"}], "explanations": {"滓": "こしたあとにフィルターに残った固体の残りかすで、捨てるものなので正解。", "香り": "香りは形のないもので、フィルターに残って捨てる対象ではないので合わない。", "色": "色は物の性質で、フィルターに残って捨てる残りものにはならない。", "音": "音は形のないもので、フィルターに残って捨てるものではないので合わない。"}, "sentence_index": 0, "correct_answer": "滓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "浴槽の縁に、白い滓がこびりついた。", "explanation": "ここは〈湯垢〉の意味。水の成分が固まったものを指すので、液体をこしたあとに残る固体の部分という今回の語義とは合わない。"}, {"text": "抹茶の滓をお湯で溶くと、とろりとする。", "explanation": "ここは〈粉〉の意味。抹茶のように粉状で溶かすものは粉と言い、こしたあとの残りかすの滓とは合わない。"}, {"text": "スイカの滓を、フォークで取り除く。", "explanation": "ここは〈種〉の意味。果実の中にある種は種と言い、液体をこしたあとの固体の残りとは別なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36845, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滓", "is_correct": true, "explanation": "こしたあとに網の上に残った固体の残りかすなので正解。"}, {"text": "光", "is_correct": false, "explanation": "光は形のないもので、網の上に残るものではないので合わない。"}, {"text": "影", "is_correct": false, "explanation": "影は光によってできるもので、網の上に残る固形物ではないので合わない。"}, {"text": "煙", "is_correct": false, "explanation": "煙は空中に広がるもので、網の上に固体として残るものではないので合わない。"}], "explanations": {"滓": "こしたあとに網の上に残った固体の残りかすなので正解。", "光": "光は形のないもので、網の上に残るものではないので合わない。", "影": "影は光によってできるもので、網の上に残る固形物ではないので合わない。", "煙": "煙は空中に広がるもので、網の上に固体として残るものではないので合わない。"}, "sentence_index": 6, "correct_answer": "滓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "溶かした鉄の表面に、黒い滓が浮いてきた。", "explanation": "ここは〈鉱滓〉の意味。金属を精錬する際に出る残りを指すので、液体をこしたあとに残る固体の部分という今回の語義とは合わない。"}, {"text": "ハサミで布を切ると、糸の滓が床に散らばる。", "explanation": "ここは〈屑〉の意味。切ったときに出る細かいくずは屑と言い、液体をこした残りの滓とは合わない。"}, {"text": "事故現場には、車の滓が散らばっていた。", "explanation": "ここは〈残骸〉の意味。壊れた機械などの残りは残骸と言い、こしたあとの残りかすの滓とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36845, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "茶こしにたまった滓を、ごみ箱に拾った。", "corrected_sentence": "茶こしにたまった滓を、ごみ箱に捨てた。", "error_description": "動詞の選択の誤り。滓をごみ箱に入れる文脈では『捨てる』が正しい。『拾う』はごみ箱へ入れる動作と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36845, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ドリップのあと、残った滓に捨てる。", "corrected_sentence": "ドリップのあと、残った滓を捨てる。", "error_description": "助詞の誤り。『捨てる』の対象を示すのは『を』。『に』では捨てる対象にならず、文として誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75956abe-2af0-445b-891b-4c0faa4c419b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36846, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。『コンポストを始めました』の『を』で、『始める』の対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "『コンポストが始めました』は主語にすると、『始める』の目的語が欠けて文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『コンポストに始めました』は帰着・対象の『に』になり、『始める』の対象として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "『コンポストへ始めました』は方向を示す『へ』で、『始める』の対象にならず不自然。"}], "correct_answer": "を", "explanations": {"を": "正解。『コンポストを始めました』の『を』で、『始める』の対象を示す。", "が": "『コンポストが始めました』は主語にすると、『始める』の目的語が欠けて文が成り立たない。", "に": "『コンポストに始めました』は帰着・対象の『に』になり、『始める』の対象として不自然。", "へ": "『コンポストへ始めました』は方向を示す『へ』で、『始める』の対象にならず不自然。"}, "error_tags": {"が": "主語", "に": "帰着・方向", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36846, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36846, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "生ごみを土に混ぜて、時間をかけてやわらかい土にすることを「コンポスト」と言います。", "primary_collocate": null, "pronunciation": "こんぽすと", "ipa": "kombosɯto", "syllable_count": 5, "sentences": [{"text": "生ごみをコンポストにすると、ごみが減ります。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "生[なま]ごみをコンポストにすると、ごみが減[へ]ります。", "sentence_source": "generated"}, {"text": "私は去年から、台所のごみでコンポストを始めました。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "私[わたし]は去年[きょねん]から、台所[だいどころ]のごみでコンポストを始[はじ]めました。", "sentence_source": "generated"}, {"text": "コンポストは時間がかかるので、毎日少しずつ混ぜます。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "コンポストは時間[じかん]がかかるので、毎日[まいにち]少[すこ]しずつ混[ま]ぜます。", "sentence_source": "generated"}, {"text": "落ち葉でコンポストをすれば、庭の土が元気になります。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "落[お]ち葉[ば]でコンポストをすれば、庭[にわ]の土[つち]が元気[げんき]になります。", "sentence_source": "generated"}, {"text": "野菜のくずは、毎日少しずつコンポストにしています。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "野菜[やさい]のくずは、毎日[まいにち]少[すこ]しずつコンポストにしています。", "sentence_source": "generated"}, {"text": "コンポストを続けたら、においが少なくなりました。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "コンポストを続[つづ]けたら、においが少[すく]なくなりました。", "sentence_source": "generated"}, {"text": "肉や魚はコンポストに向かないので、避けてください。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "肉[にく]や魚[さかな]はコンポストに向[む]かないので、避[さ]けてください。", "sentence_source": "generated"}, {"text": "市の講座で、家庭のコンポストのやり方を習いました。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "市[し]の講座[こうざ]で、家庭[かてい]のコンポストのやり方[かた]を習[なら]いました。", "sentence_source": "generated"}, {"text": "コンポストをすると、ごみを捨てる回数が減ります。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "コンポストをすると、ごみを捨[す]てる回数[かいすう]が減[へ]ります。", "sentence_source": "generated"}, {"text": "夏はコンポストが早く進むが、冬は時間がかかる。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "夏[なつ]はコンポストが早[はや]く進[すす]むが、冬[ふゆ]は時間[じかん]がかかる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コンポスト", "label": "基本形"}, {"form": "コンポストを", "label": "を格"}], "register": "標準（丁寧体・普通体）", "sense_fingerprint": "生ごみや落ち葉を土に混ぜて堆肥にする作業・過程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '729dc63f-8b18-4b3c-895a-efbae94aab11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36846, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コンポスト", "is_correct": true, "explanation": "正解。生ごみを土に混ぜて堆肥にする作業を指し、ごみが減るという文に合う。"}, {"text": "洗濯機", "is_correct": false, "explanation": "生ごみを洗濯機にするという作業は成り立たず、文が通らない。"}, {"text": "掃除機", "is_correct": false, "explanation": "掃除機は吸い取る道具で、生ごみを変える作業を表さない。"}, {"text": "扇風機", "is_correct": false, "explanation": "扇風機は風を送る機械で、生ごみを減らす作業とは関係がない。"}], "explanations": {"コンポスト": "正解。生ごみを土に混ぜて堆肥にする作業を指し、ごみが減るという文に合う。", "洗濯機": "生ごみを洗濯機にするという作業は成り立たず、文が通らない。", "掃除機": "掃除機は吸い取る道具で、生ごみを変える作業を表さない。", "扇風機": "扇風機は風を送る機械で、生ごみを減らす作業とは関係がない。"}, "sentence_index": 0, "correct_answer": "コンポスト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "買ってきた野菜を、コンポストして一週間保存した。", "explanation": "ここは〈保存〉の意味。コンポストは生ごみを土に変える作業で、食品を長持ちさせる方法としては使わない。"}, {"text": "洗剤が油汚れをコンポストして、お皿がきれいになった。", "explanation": "ここは〈分解〉の意味。コンポストは生ごみや落ち葉を堆肥にする作業で、油汚れを落とす話には使わない。"}, {"text": "パン生地をコンポストさせると、ふくらむ。", "explanation": "ここは〈発酵〉の意味。コンポストは生ごみなどを土に変える作業で、パン生地を膨らませる場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36846, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コンポスト", "is_correct": true, "explanation": "正解。肉や魚は分解に向かず避けるべき、という文脈に合う。"}, {"text": "本棚", "is_correct": false, "explanation": "本棚は物を並べる家具で、肉や魚の適性の話にはならない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は時刻を示す道具で、肉や魚の扱いとは関係がない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は花を生ける器で、分解に向くかどうかとは無関係。"}], "explanations": {"コンポスト": "正解。肉や魚は分解に向かず避けるべき、という文脈に合う。", "本棚": "本棚は物を並べる家具で、肉や魚の適性の話にはならない。", "時計": "時計は時刻を示す道具で、肉や魚の扱いとは関係がない。", "花瓶": "花瓶は花を生ける器で、分解に向くかどうかとは無関係。"}, "sentence_index": 6, "correct_answer": "コンポスト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "まな板を熱湯でコンポストして、きれいにする。", "explanation": "ここは〈殺菌〉の意味。コンポストは有機物を分解する作業で、菌を殺して清潔にする意味では使わない。"}, {"text": "大きなお鍋で、ご飯をコンポストして炊いた。", "explanation": "ここは〈炊飯〉の意味。コンポストは生ごみを分解して堆肥にする作業で、米を炊く調理には使わない。"}, {"text": "チーズをコンポストさせて、風味を深める。", "explanation": "ここは〈熟成〉の意味。コンポストは生ごみなどを堆肥にする過程で、チーズの風味を育てる場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36846, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末にまとめて、落ち葉をコンポストで入れます。", "corrected_sentence": "週末にまとめて、落ち葉をコンポストに入れます。", "error_description": "正しくは『に』（入れる先）。『で』は動作の場所や手段を表すので、『入れる』の行き先を示す『に』が必要。『コンポストで入れる』は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36846, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "コンポストが進めると、生ごみがやわらかい土になる。", "corrected_sentence": "コンポストが進むと、生ごみがやわらかい土になる。", "error_description": "『進む』は自動詞で『コンポストが進む』と主語にとる。『進める』は他動詞で目的語『を』を要するため、『コンポストが進める』は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36847, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。『このコンポストは』と主題を示し、『ふたを開けると』以下の説明に続く。"}, {"text": "を", "is_correct": false, "explanation": "『このコンポストを』では目的語になり、主題の文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すため、『このコンポストへ』は主題にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示し、『このコンポストと、ふたを開けると』では主題にならない。"}], "correct_answer": "は", "explanations": {"は": "正解。『このコンポストは』と主題を示し、『ふたを開けると』以下の説明に続く。", "を": "『このコンポストを』では目的語になり、主題の文として成り立たない。", "へ": "『へ』は方向を示すため、『このコンポストへ』は主題にならず不自然。", "と": "『と』は並列や相手を示し、『このコンポストと、ふたを開けると』では主題にならない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36847, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "正解。『コンポストから出して』と出どころ・起点を示す。"}, {"text": "を", "is_correct": false, "explanation": "『堆肥をコンポストを出して』と目的語の『を』が二つ重なり、不自然。"}, {"text": "に", "is_correct": false, "explanation": "『に』は到着点を示し、『コンポストに出す』では取り出す意味にならない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は所属を示すが、『コンポストの出して』では文が成り立たない。"}], "correct_answer": "から", "explanations": {"から": "正解。『コンポストから出して』と出どころ・起点を示す。", "を": "『堆肥をコンポストを出して』と目的語の『を』が二つ重なり、不自然。", "に": "『に』は到着点を示し、『コンポストに出す』では取り出す意味にならない。", "の": "『の』は所属を示すが、『コンポストの出して』では文が成り立たない。"}, "error_tags": {"を": "二重の目的語", "に": "到着点", "の": "所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36847, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生ごみや落ち葉を入れて、堆肥を作るための容器や置き場所。", "primary_collocate": null, "pronunciation": "こんぽすと", "ipa": "kombosɯto", "syllable_count": 5, "sentences": [{"text": "庭にコンポストを置いて、生ごみを入れています。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "庭[にわ]にコンポストを置[お]いて、生[なま]ごみを入[い]れています。", "sentence_source": "generated"}, {"text": "このコンポストは、ふたを開けると土のにおいがします。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "このコンポストは、ふたを開[あ]けると土[つち]のにおいがします。", "sentence_source": "generated"}, {"text": "落ち葉をコンポストに集めて、半年ほど待ちます。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "落[お]ち葉[ば]をコンポストに集[あつ]めて、半年[はんとし]ほど待[ま]ちます。", "sentence_source": "generated"}, {"text": "公園の隅にコンポストがあり、みんなで落ち葉を運んだ。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "公園[こうえん]の隅[すみ]にコンポストがあり、みんなで落[お]ち葉[ば]を運[はこ]んだ。", "sentence_source": "generated"}, {"text": "家庭用の小さなコンポストを、通販で買いました。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "家庭用[かていよう]の小[ちい]さなコンポストを、通販[つうはん]で買[か]いました。", "sentence_source": "generated"}, {"text": "コンポストの中では、微生物が生ごみを分解します。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "コンポストの中[なか]では、微生物[びせいぶつ]が生[なま]ごみを分解[ぶんかい]します。", "sentence_source": "generated"}, {"text": "雨が入ると、コンポストの中が水っぽくなります。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "雨[あめ]が入[はい]ると、コンポストの中[なか]が水[みず]っぽくなります。", "sentence_source": "generated"}, {"text": "完成した堆肥をコンポストから出して、畑にまいた。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "完成[かんせい]した堆肥[たいひ]をコンポストから出[だ]して、畑[はたけ]にまいた。", "sentence_source": "generated"}, {"text": "学校ではコンポストを使って、給食の残りを堆肥にしています。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "学校[がっこう]ではコンポストを使[つか]って、給食[きゅうしょく]の残[のこ]りを堆肥[たいひ]にしています。", "sentence_source": "generated"}, {"text": "生ごみをコンポストで分解すれば、肥料として使えます。", "target_word": "コンポスト", "complexity_tier": "T3", "furigana": "生[なま]ごみをコンポストで分解[ぶんかい]すれば、肥料[ひりょう]として使[つか]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コンポスト", "label": "基本形"}, {"form": "コンポストに", "label": "に格"}], "register": "標準（丁寧体・普通体）", "sense_fingerprint": "生ごみを入れて堆肥を作る庭先などの容器・置き場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '729dc63f-8b18-4b3c-895a-efbae94aab11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36847, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コンポスト", "is_correct": true, "explanation": "正解。生ごみを入れる容器として庭に置く文脈に合う。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は座るためのもので、生ごみを入れる場所としては成り立たない。"}, {"text": "自転車", "is_correct": false, "explanation": "自転車は乗り物で、生ごみを入れる場所にはならない。"}, {"text": "扇風機", "is_correct": false, "explanation": "扇風機は風を送る機械で、生ごみを入れる場所ではない。"}], "explanations": {"コンポスト": "正解。生ごみを入れる容器として庭に置く文脈に合う。", "椅子": "椅子は座るためのもので、生ごみを入れる場所としては成り立たない。", "自転車": "自転車は乗り物で、生ごみを入れる場所にはならない。", "扇風機": "扇風機は風を送る機械で、生ごみを入れる場所ではない。"}, "sentence_index": 0, "correct_answer": "コンポスト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "野菜をコンポストで煮て、スープにした。", "explanation": "ここは〈鍋〉の意味。コンポストは生ごみを堆肥にする容器や場所で、食材を煮る調理器具としては使わない。"}, {"text": "野菜はコンポストに入れて、一週間保存する。", "explanation": "ここは〈冷蔵庫〉の意味。コンポストは食品を保存するものではなく、生ごみを分解するためのものなので、保存には使わない。"}, {"text": "汚れた服をコンポストで洗った。", "explanation": "ここは〈洗濯機〉の意味。コンポストは衣類を洗う道具ではないので、洗う場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36847, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コンポスト", "is_correct": true, "explanation": "正解。容器の中という意味で、雨が入って中が水っぽくなる文脈に合う。"}, {"text": "写真", "is_correct": false, "explanation": "写真の中が水っぽくなるとは言えず、容器を指さない。"}, {"text": "時計", "is_correct": false, "explanation": "時計の中が水っぽくなるのは不自然で、容器を指さない。"}, {"text": "地図", "is_correct": false, "explanation": "地図の中という言い方は容器を指さず、水っぽくなる文脈に合わない。"}], "explanations": {"コンポスト": "正解。容器の中という意味で、雨が入って中が水っぽくなる文脈に合う。", "写真": "写真の中が水っぽくなるとは言えず、容器を指さない。", "時計": "時計の中が水っぽくなるのは不自然で、容器を指さない。", "地図": "地図の中という言い方は容器を指さず、水っぽくなる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "コンポスト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷たいご飯をコンポストで温めた。", "explanation": "ここは〈電子レンジ〉の意味。コンポストは加熱する器具ではなく、ご飯を温める場面には使わない。"}, {"text": "床のほこりをコンポストで吸い取った。", "explanation": "ここは〈掃除機〉の意味。コンポストはごみを吸う器具ではないので、ほこりを吸い取る場面には使わない。"}, {"text": "濡れた服をコンポストで乾かした。", "explanation": "ここは〈乾燥機〉の意味。コンポストは衣類を乾かす器具ではないので、乾かす場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36847, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ベランダのコンポストを、毎日生ごみを入れている。", "corrected_sentence": "ベランダのコンポストに、毎日生ごみを入れている。", "error_description": "正しくは『に』（入れる先）。『を』にすると『コンポストを』が入れる物の目的語になり、『生ごみを』と並んで不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36847, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭の隅に、コンポストが一つ置いてくる。", "corrected_sentence": "庭の隅に、コンポストが一つ置いてある。", "error_description": "『置いてある』は物の状態を表す。『置いてくる』は人が置いて戻るという動作で、コンポストを主語にすると意味が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36848, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "あげる動作の対象を示す「を」で正しい。"}, {"text": "に", "is_correct": false, "explanation": "「肥料にあげたら」は方向の「に」で、あげる対象として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「肥料があげたら」は、あげる動作の目的語にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「肥料とあげたら」は並列の「と」で、あげる対象として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "あげる動作の対象を示す「を」で正しい。", "に": "「肥料にあげたら」は方向の「に」で、あげる対象として成り立たない。", "が": "「肥料があげたら」は、あげる動作の目的語にならず不自然。", "と": "「肥料とあげたら」は並列の「と」で、あげる対象として成り立たない。"}, "error_tags": {"に": "方向", "が": "主格", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36848, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36848, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物が大きくなるために、土に混ぜる食べ物です。", "primary_collocate": null, "pronunciation": "ひりょう", "ipa": "çiɾʲoː", "syllable_count": 3, "sentences": [{"text": "トマトを大きく育てたくて、土に肥料を混ぜました。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "トマトを大[おお]きく育[そだ]てたくて、土[つち]に肥料[ひりょう]を混[ま]ぜました。", "sentence_source": "generated"}, {"text": "鉢の植物に肥料をあげたら、葉が元気になった。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "鉢[はち]の植物[しょくぶつ]に肥料[ひりょう]をあげたら、葉[は]が元気[げんき]になった。", "sentence_source": "generated"}, {"text": "肥料は、植物にとって食べ物のようなものです。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "肥料[ひりょう]は、植物[しょくぶつ]にとって食[た]べ物[もの]のようなものです。", "sentence_source": "generated"}, {"text": "おじいちゃんは毎年、畑に肥料をまいている。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "おじいちゃんは毎年[まいとし]、畑[はたけ]に肥料[ひりょう]をまいている。", "sentence_source": "generated"}, {"text": "肥料がないと、花があまり大きくならない。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "肥料[ひりょう]がないと、花[はな]があまり大[おお]きくならない。", "sentence_source": "generated"}, {"text": "生ごみを土に入れて、肥料を作ってみました。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "生[なま]ごみを土[つち]に入[い]れて、肥料[ひりょう]を作[つく]ってみました。", "sentence_source": "generated"}, {"text": "肥料のふくろに、使う量が書いてあります。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "肥料[ひりょう]のふくろに、使[つか]う量[りょう]が書[か]いてあります。", "sentence_source": "generated"}, {"text": "この肥料はにおいが強いので、庭で使うことにした。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "この肥料[ひりょう]はにおいが強[つよ]いので、庭[にわ]で使[つか]うことにした。", "sentence_source": "generated"}, {"text": "花の元気がないので、新しい肥料を買ってきた。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "花[はな]の元気[げんき]がないので、新[あたら]しい肥料[ひりょう]を買[か]ってきた。", "sentence_source": "generated"}, {"text": "理科の授業で、肥料をあげた草とあげない草を比べた。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、肥料[ひりょう]をあげた草[くさ]とあげない草[くさ]を比[くら]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "肥料", "label": "名詞(基本形)"}], "register": "neutral", "sense_fingerprint": "植物が大きく育つように土に混ぜる、植物の食べ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c171a401-7adc-4cc9-9573-2a4e0f6702de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36848, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接着剤", "is_correct": false, "explanation": "土に混ぜて植物を育てる材料ではなく、この文脈では不自然。"}, {"text": "電球", "is_correct": false, "explanation": "土に混ぜる物ではなく、植物を大きく育てる文脈には合わない。"}, {"text": "肥料", "is_correct": true, "explanation": "植物を大きく育てるために土に混ぜる食べ物を指すのは「肥料」。"}, {"text": "絵筆", "is_correct": false, "explanation": "土に混ぜる道具ではなく、この文脈では意味をなさない。"}], "explanations": {"接着剤": "土に混ぜて植物を育てる材料ではなく、この文脈では不自然。", "電球": "土に混ぜる物ではなく、植物を大きく育てる文脈には合わない。", "肥料": "植物を大きく育てるために土に混ぜる食べ物を指すのは「肥料」。", "絵筆": "土に混ぜる道具ではなく、この文脈では意味をなさない。"}, "sentence_index": 0, "correct_answer": "肥料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "虫を退治するために、畑に肥料をまいている。", "explanation": "ここは〈農薬〉の意味。肥料は栄養を与えるもので、虫を退治する働きはない。"}, {"text": "ストーブの燃料が切れたので、肥料を入れた。", "explanation": "ここは〈燃やして熱を得る材料〉の意味。肥料は植物用で、暖房の熱源としては使わない。"}, {"text": "ペットのうさぎに肥料をあげた。", "explanation": "ここは〈飼料〉の意味。肥料は植物の栄養で、動物の餌にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36848, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掃除機", "is_correct": false, "explanation": "ふくろに入れて使う物ではなく、使う量が書かれる文脈には合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "ふくろに入る物ではなく、使う量の表示とは結びつかない。"}, {"text": "電池", "is_correct": false, "explanation": "使う量を示すふくろという文脈では不自然。"}, {"text": "肥料", "is_correct": true, "explanation": "使う量が書かれたふくろの中身として自然なのは「肥料」。"}], "explanations": {"掃除機": "ふくろに入れて使う物ではなく、使う量が書かれる文脈には合わない。", "座布団": "ふくろに入る物ではなく、使う量の表示とは結びつかない。", "電池": "使う量を示すふくろという文脈では不自然。", "肥料": "使う量が書かれたふくろの中身として自然なのは「肥料」。"}, "sentence_index": 6, "correct_answer": "肥料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "避難袋に肥料を入れておく。", "explanation": "ここは〈食料〉の意味。肥料は植物用で、非常時に人が食べるための備えにはならない。"}, {"text": "洗濯機に肥料を入れて回した。", "explanation": "ここは〈洗剤〉の意味。肥料は植物用で、衣類の汚れを落とす用途には使わない。"}, {"text": "風邪をひいたので、肥料を飲んで寝た。", "explanation": "ここは〈薬〉の意味。肥料は植物の栄養で、体の病気を治す目的には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36848, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "花に肥料にあげると、よく咲くようになった。", "corrected_sentence": "花に肥料をあげると、よく咲くようになった。", "error_description": "「あげる」の対象は「を」で示す。「肥料に」だと方向の意味になり、あげる対象にならないので不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36848, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "花のために肥料にあげて、元気になった。", "corrected_sentence": "花のために肥料をあげて、元気になった。", "error_description": "「あげる」の対象は「を」で示す。「肥料に」だと方向の意味になり、あげる対象にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36849, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "まく動作の対象を示す「を」で正しい。"}, {"text": "に", "is_correct": false, "explanation": "「畑に肥料にまいたら」は「に」が重なって不自然。"}, {"text": "が", "is_correct": false, "explanation": "「肥料がまいたら」は、まくの目的語にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「肥料とまいたら」は並列の「と」で、まく対象として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "まく動作の対象を示す「を」で正しい。", "に": "「畑に肥料にまいたら」は「に」が重なって不自然。", "が": "「肥料がまいたら」は、まくの目的語にならず不自然。", "と": "「肥料とまいたら」は並列の「と」で、まく対象として成り立たない。"}, "error_tags": {"に": "場所（重複）", "が": "主格", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36849, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "埋める動作の対象を示す「を」で正しい。"}, {"text": "の", "is_correct": false, "explanation": "「肥料の埋めておく」は連体修飾のままで文が完結せず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「肥料へ埋めておく」は方向の「へ」で、埋める対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "「肥料より埋めておく」は比較の「より」で、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "埋める動作の対象を示す「を」で正しい。", "の": "「肥料の埋めておく」は連体修飾のままで文が完結せず、不自然。", "へ": "「肥料へ埋めておく」は方向の「へ」で、埋める対象にならない。", "より": "「肥料より埋めておく」は比較の「より」で、文が成り立たない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36849, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物の生長を助けるために土に与える、栄養分を含んだ物質のことです。", "primary_collocate": null, "pronunciation": "ひりょう", "ipa": "çiɾʲoː", "syllable_count": 3, "sentences": [{"text": "これは、作物の生育状況を細かく把握し、必要な水や肥料を的確に与える仕組みです。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "これは、作物[さくもつ]の生育状況[せいいくじょうきょう]を細[こま]かく把握[はあく]し、必要[ひつよう]な水[みず]や肥料[ひりょう]を的確[てきかく]に与[あた]える仕組[しく]みです。", "sentence_source": "mined"}, {"text": "畑に肥料をまいたら、野菜が大きく育った。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "畑[はたけ]に肥料[ひりょう]をまいたら、野菜[やさい]が大[おお]きく育[そだ]った。", "sentence_source": "generated"}, {"text": "肥料が足りないと、葉の色が薄くなることがあります。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "肥料[ひりょう]が足[た]りないと、葉[は]の色[いろ]が薄[うす]くなることがあります。", "sentence_source": "generated"}, {"text": "農家の人は、牛のふんから作った肥料を使っている。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]は、牛[うし]のふんから作[つく]った肥料[ひりょう]を使[つか]っている。", "sentence_source": "generated"}, {"text": "肥料をやりすぎると、かえって根が傷んでしまう。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "肥料[ひりょう]をやりすぎると、かえって根[ね]が傷[いた]んでしまう。", "sentence_source": "generated"}, {"text": "ホームセンターで花の肥料を買いました。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "ホームセンターで花[はな]の肥料[ひりょう]を買[か]いました。", "sentence_source": "generated"}, {"text": "この肥料は、雨で流れにくいように固めてあります。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "この肥料[ひりょう]は、雨[あめ]で流[なが]れにくいように固[かた]めてあります。", "sentence_source": "generated"}, {"text": "春になる前に、庭の木のまわりに肥料を埋めておく。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "春[はる]になる前[まえ]に、庭[にわ]の木[き]のまわりに肥料[ひりょう]を埋[う]めておく。", "sentence_source": "generated"}, {"text": "落ち葉を腐らせて、自然の肥料にします。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "落[お]ち葉[ば]を腐[くさ]らせて、自然[しぜん]の肥料[ひりょう]にします。", "sentence_source": "generated"}, {"text": "肥料の値段が上がり、農家の負担が増えている。", "target_word": "肥料", "complexity_tier": "T3", "furigana": "肥料[ひりょう]の値段[ねだん]が上[あ]がり、農家[のうか]の負担[ふたん]が増[ふ]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "肥料", "label": "名詞(基本形)"}], "register": "neutral", "sense_fingerprint": "植物の生長を助けるために土に与える栄養分を含んだ物質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c171a401-7adc-4cc9-9573-2a4e0f6702de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36849, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "照明", "is_correct": false, "explanation": "水や照明を植物に与えるとは言わず、栄養として成り立たない。"}, {"text": "肥料", "is_correct": true, "explanation": "作物の栄養として土に与える物を指すのは「肥料」。"}, {"text": "塗料", "is_correct": false, "explanation": "塗る材料で、植物に与える文脈には合わない。"}, {"text": "接着剤", "is_correct": false, "explanation": "くっつける材料で、植物に与える文脈では不自然。"}], "explanations": {"照明": "水や照明を植物に与えるとは言わず、栄養として成り立たない。", "肥料": "作物の栄養として土に与える物を指すのは「肥料」。", "塗料": "塗る材料で、植物に与える文脈には合わない。", "接着剤": "くっつける材料で、植物に与える文脈では不自然。"}, "sentence_index": 0, "correct_answer": "肥料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "害虫を防ぐために肥料をまいている。", "explanation": "ここは〈農薬〉の意味。肥料は植物の栄養で、害虫を防ぐ働きはない。"}, {"text": "牛に肥料をあげて、乳を取る。", "explanation": "ここは〈飼料〉の意味。肥料は植物用で、牛の餌にはならない。"}, {"text": "車に肥料を入れて出かけた。", "explanation": "ここは〈燃料〉の意味。肥料は植物の栄養で、車を動かす燃料とは別物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36849, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電池", "is_correct": false, "explanation": "雨で流れにくいように固めて使う物ではなく、この文脈に合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "固めて流れにくくする必要がなく、文脈に合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "雨で流れにくいように固めるものではなく、不自然。"}, {"text": "肥料", "is_correct": true, "explanation": "雨で流れにくいように固めて使う、粒状の肥料を指す。"}], "explanations": {"電池": "雨で流れにくいように固めて使う物ではなく、この文脈に合わない。", "教科書": "固めて流れにくくする必要がなく、文脈に合わない。", "座布団": "雨で流れにくいように固めるものではなく、不自然。", "肥料": "雨で流れにくいように固めて使う、粒状の肥料を指す。"}, "sentence_index": 6, "correct_answer": "肥料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "非常用の肥料を買っておいた。", "explanation": "ここは〈食料〉の意味。肥料は植物用で、非常時に人が食べるための備えにはならない。"}, {"text": "洗濯のために肥料を買った。", "explanation": "ここは〈洗剤〉の意味。肥料は植物用で、衣類を洗う目的には使わない。"}, {"text": "寒い夜、畑に肥料をまいて、霜よけにした。", "explanation": "ここは〈防寒シート〉の意味。肥料は植物の栄養で、霜から守る働きはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36849, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "農家は畑に肥料がまくと、野菜が大きく育つ。", "corrected_sentence": "農家は畑に肥料をまくと、野菜が大きく育つ。", "error_description": "「まく」の対象は「を」で示す。「肥料が」だと主語になってしまい、まくの目的語にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36849, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "畑に肥料に混ぜて、野菜が大きく育った。", "corrected_sentence": "畑に肥料を混ぜて、野菜が大きく育った。", "error_description": "「混ぜる」の対象は「を」で示す。「肥料に」だと方向の意味になり、混ぜる対象にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36850, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「毎日の取り組み」で、取り組みを説明する「の」になる。"}, {"text": "を", "is_correct": false, "explanation": "「毎日を取り組み」は文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「毎日が取り組み」では後ろの「を」とつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "「毎日へ取り組み」は方向の意味にならず不自然。"}], "correct_answer": "の", "explanations": {"の": "「毎日の取り組み」で、取り組みを説明する「の」になる。", "を": "「毎日を取り組み」は文として成り立たない。", "が": "「毎日が取り組み」では後ろの「を」とつながらない。", "へ": "「毎日へ取り組み」は方向の意味にならず不自然。"}, "error_tags": {"を": "object", "が": "subject", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
