INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36850, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを始めて、がんばって続けること。", "primary_collocate": null, "pronunciation": "とりくみ", "ipa": "torikɯmi", "syllable_count": 4, "sentences": [{"text": "取り組みが大切だ。", "target_word": "取り組み", "complexity_tier": "T1", "furigana": "取[と]り組[く]みが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "毎日の取り組みを続けます。", "target_word": "取り組み", "complexity_tier": "T2", "furigana": "毎日[まいにち]の取[と]り組[く]みを続[つづ]けます。", "sentence_source": "generated"}, {"text": "彼の取り組みはすばらしいです。", "target_word": "取り組み", "complexity_tier": "T2", "furigana": "彼[かれ]の取[と]り組[く]みはすばらしいです。", "sentence_source": "generated"}, {"text": "勉強への取り組みを変えてみた。", "target_word": "取り組み", "complexity_tier": "T3", "furigana": "勉強[べんきょう]への取[と]り組[く]みを変[か]えてみた。", "sentence_source": "generated"}, {"text": "小さな取り組みでも、続ければ力になる。", "target_word": "取り組み", "complexity_tier": "T3", "furigana": "小[ちい]さな取[と]り組[く]みでも、続[つづ]ければ力[ちから]になる。", "sentence_source": "generated"}, {"text": "運動の取り組みは、まだ三日目です。", "target_word": "取り組み", "complexity_tier": "T3", "furigana": "運動[うんどう]の取[と]り組[く]みは、まだ三日目[みっかめ]です。", "sentence_source": "generated"}, {"text": "毎朝走るという取り組みを、一年間続けてきた。", "target_word": "取り組み", "complexity_tier": "T4", "furigana": "毎朝[まいあさ]走[はし]るという取[と]り組[く]みを、一年間[いちねんかん]続[つづ]けてきた。", "sentence_source": "generated"}, {"text": "彼女の真剣な取り組みを見て、私もやる気が出た。", "target_word": "取り組み", "complexity_tier": "T4", "furigana": "彼女[かのじょ]の真剣[しんけん]な取[と]り組[く]みを見[み]て、私[わたし]もやる気[き]が出[で]た。", "sentence_source": "generated"}, {"text": "新しいことへの取り組みは、最初は苦しくても、続けるうちに楽しくなる。", "target_word": "取り組み", "complexity_tier": "T5", "furigana": "新[あたら]しいことへの取[と]り組[く]みは、最初[さいしょ]は苦[くる]しくても、続[つづ]けるうちに楽[たの]しくなる。", "sentence_source": "generated"}, {"text": "先生は、生徒一人ひとりの取り組みを丁寧に見て、声をかけてくれる。", "target_word": "取り組み", "complexity_tier": "T5", "furigana": "先生[せんせい]は、生徒[せいと]一人[ひとり]ひとりの取[と]り組[く]みを丁寧[ていねい]に見[み]て、声[こえ]をかけてくれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り組む", "label": "派生"}, {"form": "取組", "label": "派生"}, {"form": "取り組み方", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 始めてがんばって続けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aab15603-a3e6-49a6-923d-02d2cfa720e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36850, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り組み", "is_correct": true, "explanation": "「がんばって続けること」の意味で、「大切だ」に自然につながる。"}, {"text": "遅刻", "is_correct": false, "explanation": "形は合うが、遅刻が大切だという意味が合わない。"}, {"text": "寝坊", "is_correct": false, "explanation": "形は合うが、寝坊が大切だという意味が合わない。"}, {"text": "居眠り", "is_correct": false, "explanation": "形は合うが、居眠りが大切だという意味が合わない。"}], "explanations": {"取り組み": "「がんばって続けること」の意味で、「大切だ」に自然につながる。", "遅刻": "形は合うが、遅刻が大切だという意味が合わない。", "寝坊": "形は合うが、寝坊が大切だという意味が合わない。", "居眠り": "形は合うが、居眠りが大切だという意味が合わない。"}, "sentence_index": 0, "correct_answer": "取り組み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は取り組みを冷蔵庫に入れて冷やした。", "explanation": "取り組みは行為のことで、物ではないので冷蔵庫に入れられない。"}, {"text": "この取り組みは三メートルもある。", "explanation": "取り組みは長さを測れる物ではないので、「三メートル」と合わない。"}, {"text": "朝ごはんに取り組みを食べてから出かけた。", "explanation": "取り組みは食べ物ではないので、「食べる」と使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36850, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り組み", "is_correct": true, "explanation": "「毎朝走る」ことを続ける行為として自然に合う。"}, {"text": "失敗", "is_correct": false, "explanation": "形は合うが、毎朝走ることを失敗と呼ぶ意味が合わない。"}, {"text": "言い訳", "is_correct": false, "explanation": "形は合うが、走ることと言い訳では意味が合わない。"}, {"text": "勘違い", "is_correct": false, "explanation": "形は合うが、一年間続ける行為として意味が合わない。"}], "explanations": {"取り組み": "「毎朝走る」ことを続ける行為として自然に合う。", "失敗": "形は合うが、毎朝走ることを失敗と呼ぶ意味が合わない。", "言い訳": "形は合うが、走ることと言い訳では意味が合わない。", "勘違い": "形は合うが、一年間続ける行為として意味が合わない。"}, "sentence_index": 6, "correct_answer": "取り組み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "取り組みが重くて、持ち上げることができなかった。", "explanation": "取り組みは行為で、重さのある物ではないので持ち上げられない。"}, {"text": "昨日、取り組みを買いに駅前の店へ行った。", "explanation": "取り組みは商品ではないので、店で買えない。"}, {"text": "取り組みは雨のように空から降ってきた。", "explanation": "取り組みは自然現象ではなく、人が続ける行為なので降ってこない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36850, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は彼の取り組みを食べて、ほめてくれた。", "corrected_sentence": "先生は彼の取り組みを見て、ほめてくれた。", "error_description": "取り組みは食べられないので、「食べて」は「見て」にするのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36850, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は新しい取り組みを飲んで、毎日がんばっている。", "corrected_sentence": "兄は新しい取り組みを始めて、毎日がんばっている。", "error_description": "取り組みは飲むものではないので、「飲んで」ではなく「始めて」にするのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36851, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「町の新しい取り組み」で、取り組みの主体を示す。"}, {"text": "を", "is_correct": false, "explanation": "「町を新しい取り組み」は名詞をつなぐ形として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「町へ新しい取り組み」は名詞をつなぐ形として成り立たない。"}, {"text": "ので", "is_correct": false, "explanation": "「町ので新しい取り組み」は文法的に成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「町の新しい取り組み」で、取り組みの主体を示す。", "を": "「町を新しい取り組み」は名詞をつなぐ形として成り立たない。", "へ": "「町へ新しい取り組み」は名詞をつなぐ形として成り立たない。", "ので": "「町ので新しい取り組み」は文法的に成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "ので": "conjunction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36851, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「取り組みの成果」で、取り組みと成果の関係を示す。"}, {"text": "を", "is_correct": false, "explanation": "「取り組みを成果は」は名詞をつなぐ形として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「取り組みへ成果は」は名詞をつなぐ形として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「取り組みが成果は」は「が」と「は」が重なり、文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「取り組みの成果」で、取り組みと成果の関係を示す。", "を": "「取り組みを成果は」は名詞をつなぐ形として成り立たない。", "へ": "「取り組みへ成果は」は名詞をつなぐ形として成り立たない。", "が": "「取り組みが成果は」は「が」と「は」が重なり、文として成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "が": "subject"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36851, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある目的のために、積極的に行動を起こしたり、努力したりすること。", "primary_collocate": null, "pronunciation": "とりくみ", "ipa": "torikɯmi", "syllable_count": 4, "sentences": [{"text": "この取り組みは、単なる植物の栽培を超え、環境再生と社会的結束の醸成を同時に企図する点に特徴がある。", "target_word": "取り組み", "complexity_tier": "T6", "furigana": "この取[と]り組[く]みは、単[たん]なる植物[しょくぶつ]の栽培[さいばい]を超[こ]え、環境[かんきょう]再生[さいせい]と社会的[しゃかいてき]結束[けっそく]の醸成[じょうせい]を同時[どうじ]に企図[きと]する点[てん]に特徴[とくちょう]がある。", "sentence_source": "mined"}, {"text": "これは町の新しい取り組みです。", "target_word": "取り組み", "complexity_tier": "T2", "furigana": "これは町[まち]の新[あたら]しい取[と]り組[く]みです。", "sentence_source": "generated"}, {"text": "学校の取り組みが注目されている。", "target_word": "取り組み", "complexity_tier": "T3", "furigana": "学校[がっこう]の取[と]り組[く]みが注目[ちゅうもく]されている。", "sentence_source": "generated"}, {"text": "環境を守る取り組みを続けている。", "target_word": "取り組み", "complexity_tier": "T3", "furigana": "環境[かんきょう]を守[まも]る取[と]り組[く]みを続[つづ]けている。", "sentence_source": "generated"}, {"text": "会社はごみを減らす取り組みを始めた。", "target_word": "取り組み", "complexity_tier": "T3", "furigana": "会社[かいしゃ]はごみを減[へ]らす取[と]り組[く]みを始[はじ]めた。", "sentence_source": "generated"}, {"text": "この取り組みのおかげで、利用者が増えた。", "target_word": "取り組み", "complexity_tier": "T3", "furigana": "この取[と]り組[く]みのおかげで、利用者[りようしゃ]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "地域全体での取り組みが必要だと考える。", "target_word": "取り組み", "complexity_tier": "T4", "furigana": "地域[ちいき]全体[ぜんたい]での取[と]り組[く]みが必要[ひつよう]だと考[かんが]える。", "sentence_source": "generated"}, {"text": "取り組みの成果は、来年はっきりするだろう。", "target_word": "取り組み", "complexity_tier": "T4", "furigana": "取[と]り組[く]みの成果[せいか]は、来年[らいねん]はっきりするだろう。", "sentence_source": "generated"}, {"text": "教育の格差をなくす取り組みには、市民の協力も欠かせない。", "target_word": "取り組み", "complexity_tier": "T5", "furigana": "教育[きょういく]の格差[かくさ]をなくす取[と]り組[く]みには、市民[しみん]の協力[きょうりょく]も欠[か]かせない。", "sentence_source": "generated"}, {"text": "多くの企業が脱炭素に向けた取り組みを強化し、投資を増やしている。", "target_word": "取り組み", "complexity_tier": "T5", "furigana": "多[おお]くの企業[きぎょう]が脱炭素[だつたんそ]に向[む]けた取[と]り組[く]みを強化[きょうか]し、投資[とうし]を増[ふ]やしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り組む", "label": "派生"}, {"form": "取組", "label": "派生"}, {"form": "取り組み方", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 目的のために積極的に努力すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aab15603-a3e6-49a6-923d-02d2cfa720e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36851, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り組み", "is_correct": true, "explanation": "「この取り組み」で、目的のための活動を指し、後の説明に合う。"}, {"text": "靴", "is_correct": false, "explanation": "形は合うが、靴が環境再生を企図するでは意味が合わない。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、机が社会的結束を企図するでは意味が合わない。"}, {"text": "切手", "is_correct": false, "explanation": "形は合うが、切手が環境再生を企図するでは意味が合わない。"}], "explanations": {"取り組み": "「この取り組み」で、目的のための活動を指し、後の説明に合う。", "靴": "形は合うが、靴が環境再生を企図するでは意味が合わない。", "机": "形は合うが、机が社会的結束を企図するでは意味が合わない。", "切手": "形は合うが、切手が環境再生を企図するでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "取り組み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日、駅で友達と取り組みを食べた。", "explanation": "「取り組み」は努力や活動を表す語で、食べ物ではないため食べられない。"}, {"text": "私は取り組みを玄関で脱いだ。", "explanation": "「取り組み」は物ではなく、脱ぐことはできない。"}, {"text": "取り組みが雨で濡れたので、傘をさした。", "explanation": "「取り組み」は抽象的な活動で、雨に濡れる物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36851, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り組み", "is_correct": true, "explanation": "「全体での取り組みが必要」で、協力して行う活動の意味になる。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが、地域全体での辞書が必要だと考えるでは意味が合わない。"}, {"text": "果物", "is_correct": false, "explanation": "形は合うが、地域全体での果物が必要だと考えるでは意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、地域全体での天気が必要だと考えるでは意味が合わない。"}], "explanations": {"取り組み": "「全体での取り組みが必要」で、協力して行う活動の意味になる。", "辞書": "形は合うが、地域全体での辞書が必要だと考えるでは意味が合わない。", "果物": "形は合うが、地域全体での果物が必要だと考えるでは意味が合わない。", "天気": "形は合うが、地域全体での天気が必要だと考えるでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "取り組み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟は取り組みを飲んで、風邪を治した。", "explanation": "「取り組み」は活動を表す語で、薬のように飲むことはできない。"}, {"text": "公園で大きな取り組みが鳴いている。", "explanation": "「取り組み」は動物ではなく、鳴くことはない。"}, {"text": "私は新しい取り組みを着て出かけた。", "explanation": "「取り組み」は服ではなく、着ることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
