INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36852, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「使用量を削減する」の目的語を示す助詞。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示すため、削減の対象は表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、削減の対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示すため、削減の対象は表せない。"}], "correct_answer": "を", "explanations": {"を": "「使用量を削減する」の目的語を示す助詞。", "に": "相手や場所を示すため、削減の対象は表せない。", "へ": "方向を示すため、削減の対象にはならない。", "と": "並列を示すため、削減の対象は表せない。"}, "error_tags": {"に": "相手・場所の誤り", "へ": "方向の誤り", "と": "並列の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "増加", "is_correct": true, "explanation": "量や数が増える意味で、削減の対義語として辞書に並ぶ。"}, {"text": "拡大", "is_correct": false, "explanation": "規模を広げる意味で、量を減らす削減とは対義関係にならない。"}, {"text": "維持", "is_correct": false, "explanation": "現状を保つ意味で、削減の対義語ではない。"}, {"text": "節約", "is_correct": false, "explanation": "無駄を省く意味で、削減の類義に近く、対義語ではない。"}], "correct_answer": "増加", "explanations": {"増加": "量や数が増える意味で、削減の対義語として辞書に並ぶ。", "拡大": "規模を広げる意味で、量を減らす削減とは対義関係にならない。", "維持": "現状を保つ意味で、削減の対義語ではない。", "節約": "無駄を省く意味で、削減の類義に近く、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36852, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「残業時間の削減」の形で、残業時間が削減の対象になる名詞の連なり。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示し、残業時間を削減の対象として表せない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すため、名詞を結ぶ形にはならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すため、削減の対象を表せない。"}], "correct_answer": "の", "explanations": {"の": "「残業時間の削減」の形で、残業時間が削減の対象になる名詞の連なり。", "で": "手段や場所を示し、残業時間を削減の対象として表せない。", "より": "比較を示すため、名詞を結ぶ形にはならない。", "から": "起点を示すため、削減の対象を表せない。"}, "error_tags": {"で": "手段・場所の誤り", "より": "比較の誤り", "から": "起点の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "増加", "is_correct": true, "explanation": "量や数が増える意味で、削減の対義語として辞書に並ぶ。"}, {"text": "上昇", "is_correct": false, "explanation": "数値が上がる意味で、削減の対義語としては登録されない。"}, {"text": "停止", "is_correct": false, "explanation": "動きを止める意味で、量の増減とは対義関係にない。"}, {"text": "放置", "is_correct": false, "explanation": "そのままにする意味で、削減の対義語ではない。"}], "correct_answer": "増加", "explanations": {"増加": "量や数が増える意味で、削減の対義語として辞書に並ぶ。", "上昇": "数値が上がる意味で、削減の対義語としては登録されない。", "停止": "動きを止める意味で、量の増減とは対義関係にない。", "放置": "そのままにする意味で、削減の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36852, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "「削減」は、物の量や数を少なくすることです。", "primary_collocate": null, "pronunciation": "さくげん", "ipa": "sakɯɡeɴ", "syllable_count": 4, "sentences": [{"text": "会社は無駄な費用の削減に力を入れている。", "target_word": "削減", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は無駄[むだ]な費用[ひよう]の削減[さくげん]に力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "電気の使用量を削減するため、使わない部屋の電気を消す。", "target_word": "削減", "complexity_tier": "T3", "furigana": "電気[でんき]の使用量[しようりょう]を削減[さくげん]するため、使[つか]わない部屋[へや]の電気[でんき]を消[け]す。", "sentence_source": "generated"}, {"text": "市は来年度の予算を一割削減すると発表した。", "target_word": "削減", "complexity_tier": "T3", "furigana": "市[し]は来年度[らいねんど]の予算[よさん]を一割[いちわり]削減[さくげん]すると発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "ごみの削減は、家庭でできる小さな工夫から始まる。", "target_word": "削減", "complexity_tier": "T3", "furigana": "ごみの削減[さくげん]は、家庭[かてい]でできる小[ちい]さな工夫[くふう]から始[はじ]まる。", "sentence_source": "generated"}, {"text": "人数の削減で、一人あたりの仕事が増えてしまった。", "target_word": "削減", "complexity_tier": "T3", "furigana": "人数[にんずう]の削減[さくげん]で、一人[ひとり]あたりの仕事[しごと]が増[ふ]えてしまった。", "sentence_source": "generated"}, {"text": "紙の使用を削減するために、会議の資料を画面で見ることにした。", "target_word": "削減", "complexity_tier": "T3", "furigana": "紙[かみ]の使用[しよう]を削減[さくげん]するために、会議[かいぎ]の資料[しりょう]を画面[がめん]で見[み]ることにした。", "sentence_source": "generated"}, {"text": "費用が足りないので、旅行の日数を削減した。", "target_word": "削減", "complexity_tier": "T3", "furigana": "費用[ひよう]が足[た]りないので、旅行[りょこう]の日数[にっすう]を削減[さくげん]した。", "sentence_source": "generated"}, {"text": "残業時間の削減は、社員の健康を守ることにもつながる。", "target_word": "削減", "complexity_tier": "T3", "furigana": "残業時間[ざんぎょうじかん]の削減[さくげん]は、社員[しゃいん]の健康[けんこう]を守[まも]ることにもつながる。", "sentence_source": "generated"}, {"text": "工場は二酸化炭素の排出を削減する新しい機械を入れた。", "target_word": "削減", "complexity_tier": "T3", "furigana": "工場[こうじょう]は二酸化炭素[にさんかたんそ]の排出[はいしゅつ]を削減[さくげん]する新[あたら]しい機械[きかい]を入[い]れた。", "sentence_source": "generated"}, {"text": "食費の削減のため、外食の回数を減らした。", "target_word": "削減", "complexity_tier": "T3", "furigana": "食費[しょくひ]の削減[さくげん]のため、外食[がいしょく]の回数[かいすう]を減[へ]らした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "削減", "label": "基本形"}, {"form": "削減する", "label": "終止形（サ変）"}, {"form": "削減した", "label": "過去形"}, {"form": "削減して", "label": "て形"}], "register": "やや硬い（普通体）", "sense_fingerprint": "費用・量・人数などを計画的に減らすこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e61b9b9-2b71-463a-b7c3-934bb8c70858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36852, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "削減", "is_correct": true, "explanation": "量や費用を減らす意味で、「無駄な費用の削減に力を入れている」に合う。"}, {"text": "発表", "is_correct": false, "explanation": "公にする意味で、費用を対象に力を入れる文脈には合わない。"}, {"text": "排出", "is_correct": false, "explanation": "外へ出す意味で、無駄な費用には使わない。"}, {"text": "利用", "is_correct": false, "explanation": "使う意味で、無駄な費用を減らす取り組みとは合わない。"}], "explanations": {"削減": "量や費用を減らす意味で、「無駄な費用の削減に力を入れている」に合う。", "発表": "公にする意味で、費用を対象に力を入れる文脈には合わない。", "排出": "外へ出す意味で、無駄な費用には使わない。", "利用": "使う意味で、無駄な費用を減らす取り組みとは合わない。"}, "sentence_index": 0, "correct_answer": "削減"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ライバル店ができて、客が削減した。", "explanation": "削減は人が意図して量を減らす語で、客が自然に減る場面には使えない。"}, {"text": "町に新しい店が削減した。", "explanation": "新しく現れる店は増える方向の出来事で、量を減らす削減とは言えない。"}, {"text": "新しい車を削減して、すぐに買った。", "explanation": "買うことは量を減らす行為ではなく、削減とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36852, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "削減", "is_correct": true, "explanation": "減らす意味で、費用が足りないので日数を減らしたという文脈に合う。"}, {"text": "撮影", "is_correct": false, "explanation": "写真や映像を撮る意味で、旅行の日数には使わない。"}, {"text": "翻訳", "is_correct": false, "explanation": "言語を別の言語に変える意味で、日数とは合わない。"}, {"text": "修理", "is_correct": false, "explanation": "壊れたものを直す意味で、日数には使わない。"}], "explanations": {"削減": "減らす意味で、費用が足りないので日数を減らしたという文脈に合う。", "撮影": "写真や映像を撮る意味で、旅行の日数には使わない。", "翻訳": "言語を別の言語に変える意味で、日数とは合わない。", "修理": "壊れたものを直す意味で、日数には使わない。"}, "sentence_index": 6, "correct_answer": "削減"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨年の大会で、チームは優勝を削減した。", "explanation": "優勝は数を減らす対象ではなく、削減とは言えない。"}, {"text": "鉛筆を削減して、先を尖らせた。", "explanation": "鉛筆の先を削ることは量を減らす意味ではなく、削減とは言えない。"}, {"text": "彼は笑顔を削減して、仕事に集中した。", "explanation": "笑顔は数えられる量ではなく、削減の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36852, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "食費に削減するため、毎週の買い物を見直した。", "corrected_sentence": "食費を削減するため、毎週の買い物を見直した。", "error_description": "「削減する」の対象は「を」で示す。「に」を使うと、食費が削減の相手として誤って示される。正しくは「食費を削減する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36852, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場は排出量を削減しので、古い機械を止めた。", "corrected_sentence": "工場は排出量を削減したので、古い機械を止めた。", "error_description": "「削減」の過去形は「削減した」。「削減し」は接続の形が不完全で、「ので」に続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36853, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36853, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「無理な削減は」で、削減について述べる話題（主題）を示す。"}, {"text": "の", "is_correct": false, "explanation": "「削減の」は名詞を修飾する形で、ここでは文の主題を作れず、文が途中で切れる。"}, {"text": "を", "is_correct": false, "explanation": "「削減を」は目的語になるが、ここには動詞がなく文が途中で切れる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並べる働きだが、「無理な削減と」では文が途中で切れて意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "「無理な削減は」で、削減について述べる話題（主題）を示す。", "の": "「削減の」は名詞を修飾する形で、ここでは文の主題を作れず、文が途中で切れる。", "を": "「削減を」は目的語になるが、ここには動詞がなく文が途中で切れる。", "と": "「と」は並べる働きだが、「無理な削減と」では文が途中で切れて意味が通らない。"}, "error_tags": {"の": "連体修飾", "を": "動詞がなく文が途中で切れる", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36853, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "「削減」とは、数量や程度を減らして、少なくすることです。", "primary_collocate": null, "pronunciation": "さくげん", "ipa": "sakɯɡeɴ", "syllable_count": 4, "sentences": [{"text": "農薬の削減を進めた結果、川の水がきれいになった。", "target_word": "削減", "complexity_tier": "T3", "furigana": "農薬[のうやく]の削減[さくげん]を進[すす]めた結果[けっか]、川[かわ]の水[みず]がきれいになった。", "sentence_source": "generated"}, {"text": "会社の赤字が続き、社員の給料の削減が決まった。", "target_word": "削減", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の赤字[あかじ]が続[つづ]き、社員[しゃいん]の給料[きゅうりょう]の削減[さくげん]が決[き]まった。", "sentence_source": "generated"}, {"text": "町は水道料金の値上げを避けるため、事業の削減を進めている。", "target_word": "削減", "complexity_tier": "T3", "furigana": "町[まち]は水道料金[すいどうりょうきん]の値上[ねあ]げを避[さ]けるため、事業[じぎょう]の削減[さくげん]を進[すす]めている。", "sentence_source": "generated"}, {"text": "工事の費用を削減する代わりに、使う材料を安いものに変えた。", "target_word": "削減", "complexity_tier": "T3", "furigana": "工事[こうじ]の費用[ひよう]を削減[さくげん]する代[か]わりに、使[つか]う材料[ざいりょう]を安[やす]いものに変[か]えた。", "sentence_source": "generated"}, {"text": "授業の時間の削減には、反対する先生も多い。", "target_word": "削減", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]の時間[じかん]の削減[さくげん]には、反対[はんたい]する先生[せんせい]も多[おお]い。", "sentence_source": "generated"}, {"text": "家計の支出を削減しようと、まず携帯電話のプランを見直した。", "target_word": "削減", "complexity_tier": "T3", "furigana": "家計[かけい]の支出[ししゅつ]を削減[さくげん]しようと、まず携帯電話[けいたいでんわ]のプランを見直[みなお]した。", "sentence_source": "generated"}, {"text": "会社は経費を二割削減する方針を出し、社内では不安の声が上がっている。", "target_word": "削減", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は経費[けいひ]を二割[にわり]削減[さくげん]する方針[ほうしん]を出[だ]し、社内[しゃない]では不安[ふあん]の声[こえ]が上[あ]がっている。", "sentence_source": "generated"}, {"text": "無理な削減は、サービスの質を下げる原因になる。", "target_word": "削減", "complexity_tier": "T3", "furigana": "無理[むり]な削減[さくげん]は、サービスの質[しつ]を下[さ]げる原因[げんいん]になる。", "sentence_source": "generated"}, {"text": "石油の使用を削減するため、国は電気自動車を増やしている。", "target_word": "削減", "complexity_tier": "T3", "furigana": "石油[せきゆ]の使用[しよう]を削減[さくげん]するため、国[くに]は電気自動車[でんきじどうしゃ]を増[ふ]やしている。", "sentence_source": "generated"}, {"text": "糖分の削減を目指して、毎朝の砂糖入りコーヒーをやめた。", "target_word": "削減", "complexity_tier": "T3", "furigana": "糖分[とうぶん]の削減[さくげん]を目指[めざ]して、毎朝[まいあさ]の砂糖[さとう]入[い]りコーヒーをやめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "削減", "label": "基本形"}, {"form": "削減する", "label": "終止形（サ変）"}, {"form": "削減した", "label": "過去形"}, {"form": "削減して", "label": "て形"}], "register": "やや硬い（普通体）", "sense_fingerprint": "数量や程度（給料・使用・人員など）を減らして少なくすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e61b9b9-2b71-463a-b7c3-934bb8c70858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36853, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "削減", "is_correct": true, "explanation": "「農薬の削減を進めた」は農薬を減らす意味になり、川がきれいになったという結果につながる。"}, {"text": "増加", "is_correct": false, "explanation": "農薬を増やしても川の水はきれいにならないので、結果の文と矛盾する。"}, {"text": "輸入", "is_correct": false, "explanation": "農薬を輸入することは川をきれいにする行為ではなく、結果の文とつながらない。"}, {"text": "製造", "is_correct": false, "explanation": "農薬を製造しても川はきれいにならず、結果の文と矛盾する。"}], "explanations": {"削減": "「農薬の削減を進めた」は農薬を減らす意味になり、川がきれいになったという結果につながる。", "増加": "農薬を増やしても川の水はきれいにならないので、結果の文と矛盾する。", "輸入": "農薬を輸入することは川をきれいにする行為ではなく、結果の文とつながらない。", "製造": "農薬を製造しても川はきれいにならず、結果の文と矛盾する。"}, "sentence_index": 0, "correct_answer": "削減"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "約束を削減した。", "explanation": "約束は量を減らす対象ではなく、削減とは言えない。"}, {"text": "夢を削減した。", "explanation": "夢は数や量を減らす対象ではなく、削減とは言えない。"}, {"text": "木の表面を削減して、平らにした。", "explanation": "木の表面を薄くする作業は、量を減らす削減とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36853, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "削減", "is_correct": true, "explanation": "「経費を二割削減する方針」は経費を減らす意味になり、文脈に合う。"}, {"text": "解約", "is_correct": false, "explanation": "「経費を解約する」とは言わず、契約を断つ意味になるので経費には合わない。"}, {"text": "納品", "is_correct": false, "explanation": "「経費を納品する」という使い方はなく、品物を届ける意味で文と合わない。"}, {"text": "放棄", "is_correct": false, "explanation": "「経費を放棄する」とは言わず、権利などを捨てる意味で文と合わない。"}], "explanations": {"削減": "「経費を二割削減する方針」は経費を減らす意味になり、文脈に合う。", "解約": "「経費を解約する」とは言わず、契約を断つ意味になるので経費には合わない。", "納品": "「経費を納品する」という使い方はなく、品物を届ける意味で文と合わない。", "放棄": "「経費を放棄する」とは言わず、権利などを捨てる意味で文と合わない。"}, "sentence_index": 6, "correct_answer": "削減"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "息を削減した。", "explanation": "息は数や量で減らせるものではなく、削減とは言えない。"}, {"text": "町の人口が削減している。", "explanation": "人口が自然に減る変化は、削減ではなく減少で表す。"}, {"text": "ろうそくの火を削減した。", "explanation": "火を消すことは量を減らす意味ではなく、削減とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36853, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町は事業費の削減に進めて、財源を確保した。", "corrected_sentence": "町は事業費の削減を進めて、財源を確保した。", "error_description": "誤りは「削減に進める」の助詞。正しくは「削減を進める」で、「進める」は「削減」を目的語に取るので「を」が必要。「に」にすると不自然な文になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36853, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "予算が削減するため、祭りは中止になった。", "corrected_sentence": "予算が削減されたため、祭りは中止になった。", "error_description": "誤りは「削減する」の形。予算は削減される側なので受身の「削減された」が必要。能動形の「削減する」では意味が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
