INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36854, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "みんなのために、役に立つことをする。", "primary_collocate": null, "pronunciation": "こうけん", "ipa": "koːkeɴ", "syllable_count": 4, "sentences": [{"text": "彼はボランティア活動で地域に貢献しています。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "彼[かれ]はボランティア活動[かつどう]で地域[ちいき]に貢献[こうけん]しています。", "sentence_source": "generated"}, {"text": "私は将来、医者になって社会に貢献したいです。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "私[わたし]は将来[しょらい]、医者[いしゃ]になって社会[しゃかい]に貢献[こうけん]したいです。", "sentence_source": "generated"}, {"text": "長年、町の発展に貢献した田中さんが表彰されました。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "長年[ながねん]、町[まち]の発展[はってん]に貢献[こうけん]した田中[たなか]さんが表彰[ひょうしょう]されました。", "sentence_source": "generated"}, {"text": "小さな親切でも、みんなのために貢献できると思います。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "小[ちい]さな親切[しんせつ]でも、みんなのために貢献[こうけん]できると思[おも]います。", "sentence_source": "generated"}, {"text": "環境を守る活動に貢献したくて、毎週ごみ拾いに参加しています。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "環境[かんきょう]を守[まも]る活動[かつどう]に貢献[こうけん]したくて、毎週[まいしゅう]ごみ拾[ひろ]いに参加[さんか]しています。", "sentence_source": "generated"}, {"text": "彼女は新しい薬を開発して、多くの患者さんの命を救うことに貢献しました。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は新[あたら]しい薬[くすり]を開発[かいはつ]して、多[おお]くの患者[かんじゃ]さんの命[いのち]を救[すく]うことに貢献[こうけん]しました。", "sentence_source": "generated"}, {"text": "学生のうちから社会に貢献する経験を積むことは大切です。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "学生[がくせい]のうちから社会[しゃかい]に貢献[こうけん]する経験[けいけん]を積[つ]むことは大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "大きな貢献ではなくても、自分にできることから始めましょう。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "大[おお]きな貢献[こうけん]ではなくても、自分[じぶん]にできることから始[はじ]めましょう。", "sentence_source": "generated"}, {"text": "先生は教育に生涯を捧げ、地域の子どもたちのために貢献しました。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "先生[せんせい]は教育[きょういく]に生涯[しょうがい]を捧[ささ]げ、地域[ちいき]の子[こ]どもたちのために貢献[こうけん]しました。", "sentence_source": "generated"}, {"text": "この発明は人々の暮らしを便利にし、社会に大きく貢献しました。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "この発明[はつめい]は人々[ひとびと]の暮[く]らしを便利[べんり]にし、社会[しゃかい]に大[おお]きく貢献[こうけん]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "貢献する", "label": "辞書形"}, {"form": "貢献した", "label": "過去形"}, {"form": "貢献して", "label": "て形"}, {"form": "貢献している", "label": "継続形"}, {"form": "貢献しない", "label": "否定形"}, {"form": "貢献できる", "label": "可能形"}, {"form": "貢献したい", "label": "願望形"}], "register": "neutral", "sense_fingerprint": "社会や周りの人々のために役に立つ行いをすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e600720-6c23-4799-8dcf-cf155a991805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36854, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "貢献", "is_correct": true, "explanation": "「地域に」に続き、役立つ働きを表す語。文の意味に合う。"}, {"text": "解散", "is_correct": false, "explanation": "「解散」は団体をまとめて終わらせる意味で、地域への働きという文脈には合わない。"}, {"text": "放棄", "is_correct": false, "explanation": "「放棄」は権利や役目を捨てる意味で、地域のために役立つ文脈には合わない。"}, {"text": "中断", "is_correct": false, "explanation": "「中断」は途中でやめる意味で、役立つ働きを表す文には合わない。"}], "explanations": {"貢献": "「地域に」に続き、役立つ働きを表す語。文の意味に合う。", "解散": "「解散」は団体をまとめて終わらせる意味で、地域への働きという文脈には合わない。", "放棄": "「放棄」は権利や役目を捨てる意味で、地域のために役立つ文脈には合わない。", "中断": "「中断」は途中でやめる意味で、役立つ働きを表す文には合わない。"}, "sentence_index": 0, "correct_answer": "貢献"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家臣は殿様に名刀を貢献した。", "explanation": "ここは〈献上〉の意味。貢献は社会や目的への役立ちを指すので、目上の人に物を差し出す場面には使わない。"}, {"text": "彼は恋人に高価な服を貢献した。", "explanation": "ここは〈貢ぐ〉の意味。貢献は役に立つ働きを指すので、相手に金品を使い続ける場面には合わない。"}, {"text": "彼は地元の病院に現金を貢献した。", "explanation": "ここは〈寄付〉の意味。貢献は働きや役立ちを指す語で、金銭を施設に渡す行為そのものには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36854, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "貢献", "is_correct": true, "explanation": "「社会に」に続き、役立つ働きを表す語。文の意味に合う。"}, {"text": "修理", "is_correct": false, "explanation": "「修理」は壊れたものを直す意味で、社会への働きという文脈には合わない。"}, {"text": "出勤", "is_correct": false, "explanation": "「出勤」は職場に出ることで、「社会に」と続けて経験を積むという文には合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩」は気晴らしに歩くことで、社会に対する働きという文脈には合わない。"}], "explanations": {"貢献": "「社会に」に続き、役立つ働きを表す語。文の意味に合う。", "修理": "「修理」は壊れたものを直す意味で、社会への働きという文脈には合わない。", "出勤": "「出勤」は職場に出ることで、「社会に」と続けて経験を積むという文には合わない。", "散歩": "「散歩」は気晴らしに歩くことで、社会に対する働きという文脈には合わない。"}, "sentence_index": 6, "correct_answer": "貢献"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "業者は毎週、店に野菜を貢献している。", "explanation": "ここは〈納入〉の意味。品物を決まった先に届ける語で、貢献は役立つ働きを指すので合わない。"}, {"text": "町の人々は市立図書館に絵本を貢献した。", "explanation": "ここは〈寄贈〉の意味。物を施設に贈る語で、貢献はその物品の提供には使わない。"}, {"text": "店は無料で試食を貢献した。", "explanation": "ここは〈提供〉の意味。客に品を出す場面には、貢献という語は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36854, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は長年、会社を貢献しました。", "corrected_sentence": "祖父は長年、会社に貢献しました。", "error_description": "「貢献」は対象に「に」を付ける語。「を」は誤りで、正しくは「会社に貢献しました」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36854, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は会社に貢献さませんでした。", "corrected_sentence": "私は会社に貢献しませんでした。", "error_description": "「貢献する」の否定過去は「貢献しませんでした」。「さ」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36855, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「プロジェクトに貢献」の「に」。貢献の対象を示す助詞。"}, {"text": "を", "is_correct": false, "explanation": "「貢献」は「に」で対象を示すので、「を」は誤り。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示し、「プロジェクトと貢献」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、動詞「貢献しています」の前には続かない。"}], "correct_answer": "に", "explanations": {"に": "「プロジェクトに貢献」の「に」。貢献の対象を示す助詞。", "を": "「貢献」は「に」で対象を示すので、「を」は誤り。", "と": "「と」は相手や並列を示し、「プロジェクトと貢献」は意味が通らない。", "の": "「の」は名詞をつなぐ助詞で、動詞「貢献しています」の前には続かない。"}, "error_tags": {"を": "対象の助詞ではない", "と": "並列の助詞で合わない", "の": "名詞連結で動詞に続かない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
