INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36855, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "共同の目的のために、自分の力や物を差し出すこと。", "primary_collocate": null, "pronunciation": "こうけん", "ipa": "koːkeɴ", "syllable_count": 4, "sentences": [{"text": "彼は優勝という目標のために、チームに大きく貢献しました。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "彼[かれ]は優勝[ゆうしょう]という目標[もくひょう]のために、チームに大[おお]きく貢献[こうけん]しました。", "sentence_source": "generated"}, {"text": "社員は自分の得意な分野でプロジェクトに貢献しています。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "社員[しゃいん]は自分[じぶん]の得意[とくい]な分野[ぶんや]でプロジェクトに貢献[こうけん]しています。", "sentence_source": "generated"}, {"text": "村の祭りを成功させるため、住民は資金や時間を出して貢献しました。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "村[むら]の祭[まつ]りを成功[せいこう]させるため、住民[じゅうみん]は資金[しきん]や時間[じかん]を出[だ]して貢献[こうけん]しました。", "sentence_source": "generated"}, {"text": "新入社員の彼女も、アイデアを出して会議に貢献しました。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "新入社員[しんにゅうしゃいん]の彼女[かのじょ]も、アイデアを出[だ]して会議[かいぎ]に貢献[こうけん]しました。", "sentence_source": "generated"}, {"text": "試合に出られなくても、声援でチームに貢献する選手もいます。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "試合[しあい]に出[で]られなくても、声援[せいえん]でチームに貢献[こうけん]する選手[せんしゅ]もいます。", "sentence_source": "generated"}, {"text": "研究所の完成には、多くの寄付者の貢献がありました。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "研究所[けんきゅうじょ]の完成[かんせい]には、多[おお]くの寄付者[きふしゃ]の貢献[こうけん]がありました。", "sentence_source": "generated"}, {"text": "彼の貢献のおかげで、計画は予定より早く終わりました。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "彼[かれ]の貢献[こうけん]のおかげで、計画[けいかく]は予定[よてい]より早[はや]く終[お]わりました。", "sentence_source": "generated"}, {"text": "みんなで文化祭を作るため、私も道具を持ってきて貢献しました。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "みんなで文化祭[ぶんかさい]を作[つく]るため、私[わたし]も道具[どうぐ]を持[も]ってきて貢献[こうけん]しました。", "sentence_source": "generated"}, {"text": "山小屋の修理に、登山者たちが材料と労力で貢献しました。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "山小屋[やまごや]の修理[しゅうり]に、登山者[とざんしゃ]たちが材料[ざいりょう]と労力[ろうりょく]で貢献[こうけん]しました。", "sentence_source": "generated"}, {"text": "今度のイベントに貢献したい人は、事務室に申し込んでください。", "target_word": "貢献", "complexity_tier": "T3", "furigana": "今度[こんど]のイベントに貢献[こうけん]したい人[ひと]は、事務室[じむしつ]に申[もう]し込[こ]んでください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "貢献する", "label": "辞書形"}, {"form": "貢献した", "label": "過去形"}, {"form": "貢献して", "label": "て形"}, {"form": "貢献している", "label": "継続形"}, {"form": "貢献しない", "label": "否定形"}, {"form": "貢献できる", "label": "可能形"}, {"form": "貢献したい", "label": "願望形"}], "register": "neutral", "sense_fingerprint": "チームや計画などの共通の目的のために、自分の力・時間・資金などを出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e600720-6c23-4799-8dcf-cf155a991805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36855, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "貢献", "is_correct": true, "explanation": "「チームに大きく」に続き、役立つ働きを表す語。文の意味に合う。"}, {"text": "欠場", "is_correct": false, "explanation": "「欠場」は試合に出ないことで、「チームに大きく」という働きの文脈には合わない。"}, {"text": "解雇", "is_correct": false, "explanation": "「解雇」は雇用を打ち切る意味で、チームへの働きを表す文には合わない。"}, {"text": "放棄", "is_correct": false, "explanation": "「放棄」は権利や役目を捨てる意味で、チームのために力を出す文脈には合わない。"}], "explanations": {"貢献": "「チームに大きく」に続き、役立つ働きを表す語。文の意味に合う。", "欠場": "「欠場」は試合に出ないことで、「チームに大きく」という働きの文脈には合わない。", "解雇": "「解雇」は雇用を打ち切る意味で、チームへの働きを表す文には合わない。", "放棄": "「放棄」は権利や役目を捨てる意味で、チームのために力を出す文脈には合わない。"}, "sentence_index": 0, "correct_answer": "貢献"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会長は選手に優勝旗を貢献した。", "explanation": "ここは〈贈呈〉の意味。儀礼として品や賞を渡す語で、貢献は役立つ働きを指すので、物を手渡す場面には合わない。"}, {"text": "戦時中、国は村の鉄や鍋を貢献させた。", "explanation": "ここは〈供出〉の意味。国が強制的に物を出させる語で、貢献は自分の意思で力や物を差し出すことなので合わない。"}, {"text": "家臣は城主に名産品を貢献した。", "explanation": "ここは〈献上〉の意味。身分の高い人に品を差し出す場面には、貢献は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36855, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "貢献", "is_correct": true, "explanation": "「彼の」の後に「のおかげで」と続く名詞で、役立ちを表す。文の意味に合う。"}, {"text": "気温", "is_correct": false, "explanation": "「気温」は空気の温度で、人の働きを表す文脈には合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "「辞書」は言葉を調べる本で、計画の進行を表す文には合わない。"}, {"text": "外国", "is_correct": false, "explanation": "「外国」は国の意味で、「彼の」に続けて計画の早期終了を表す文には合わない。"}], "explanations": {"貢献": "「彼の」の後に「のおかげで」と続く名詞で、役立ちを表す。文の意味に合う。", "気温": "「気温」は空気の温度で、人の働きを表す文脈には合わない。", "辞書": "「辞書」は言葉を調べる本で、計画の進行を表す文には合わない。", "外国": "「外国」は国の意味で、「彼の」に続けて計画の早期終了を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "貢献"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場は毎月、大手メーカーに部品を貢献した。", "explanation": "ここは〈納入〉の意味。決まった先へ品物を届ける語で、貢献は役立つ働きを指すので合わない。"}, {"text": "彼は夜の店の女性にお金を貢献していた。", "explanation": "ここは〈貢ぐ〉の意味。相手に金品を続けて使う場面で、貢献の意味とは合わない。"}, {"text": "ホテルは客に無料の朝食を貢献した。", "explanation": "ここは〈提供〉の意味。客に品を出す場面には、貢献は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36855, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は会議に大きな貢献を買いました。", "corrected_sentence": "彼は会議に大きな貢献を果たしました。", "error_description": "「貢献」は「買う」ものではなく、「果たす」と組む。「買いました」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36855, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は班の仕事を貢献しました。", "corrected_sentence": "私は班の仕事に貢献しました。", "error_description": "「貢献」は対象に「に」を付ける語。「を」は誤りで、正しくは「班の仕事に貢献しました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36856, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「食べ残しを見ています」の「を」。動詞「見る」の目的語を示す助詞。"}, {"text": "に", "is_correct": false, "explanation": "「見ています」は「を」で目的語を取るので、「に」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、「食べ残しの見ています」は文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示し、「食べ残しで見ています」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「食べ残しを見ています」の「を」。動詞「見る」の目的語を示す助詞。", "に": "「見ています」は「を」で目的語を取るので、「に」は不自然。", "の": "「の」は名詞をつなぐ助詞で、「食べ残しの見ています」は文が成り立たない。", "で": "「で」は手段や場所を示し、「食べ残しで見ています」は意味が通らない。"}, "error_tags": {"に": "目的語の助詞ではない", "の": "名詞連結で動詞に続かない", "で": "手段・場所の助詞で合わない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36856, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「食べ残しを紙でふき取ります」の「を」。動詞の目的語を示す助詞。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示し、「食べ残しと紙でふき取る」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう先を示し、「食べ残しへふき取る」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を示し、ここではふき取る対象を取れない。"}], "correct_answer": "を", "explanations": {"を": "「食べ残しを紙でふき取ります」の「を」。動詞の目的語を示す助詞。", "と": "「と」は並列を示し、「食べ残しと紙でふき取る」は意味が通らない。", "へ": "「へ」は向かう先を示し、「食べ残しへふき取る」は不自然。", "より": "「より」は比較や起点を示し、ここではふき取る対象を取れない。"}, "error_tags": {"と": "並列の助詞で合わない", "へ": "方向の助詞で合わない", "より": "比較の助詞で合わない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36856, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "食べ物で、お皿にまだのこっているもの。", "primary_collocate": null, "pronunciation": "たべのこし", "ipa": "tabenokoɕi", "syllable_count": 5, "sentences": [{"text": "食事のあと、お皿には魚の食べ残しがありました。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "食事[しょくじ]のあと、お皿[さら]には魚[さかな]の食[た]べ残[のこ]しがありました。", "sentence_source": "generated"}, {"text": "弟のお皿の食べ残しを、犬が見ています。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "弟[おとうと]のお皿[さら]の食[た]べ残[のこ]しを、犬[いぬ]が見[み]ています。", "sentence_source": "generated"}, {"text": "食べ残しをそのままにすると、においが出るので、すぐに片づけました。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "食[た]べ残[のこ]しをそのままにすると、においが出[で]るので、すぐに片[かた]づけました。", "sentence_source": "generated"}, {"text": "店員さんは、テーブルの食べ残しをお盆にのせて運びました。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "店員[てんいん]さんは、テーブルの食[た]べ残[のこ]しをお盆[ぼん]にのせて運[はこ]びました。", "sentence_source": "generated"}, {"text": "子どもの食べ残しが多いので、量を少なくしました。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "子[こ]どもの食[た]べ残[のこ]しが多[おお]いので、量[りょう]を少[すく]なくしました。", "sentence_source": "generated"}, {"text": "皿の食べ残しにハエが止まっていたので、追い払いました。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "皿[さら]の食[た]べ残[のこ]しにハエが止[と]まっていたので、追[お]い払[はら]いました。", "sentence_source": "generated"}, {"text": "兄はいつも野菜の食べ残しを皿の端に集めます。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "兄[あに]はいつも野菜[やさい]の食[た]べ残[のこ]しを皿[さら]の端[はし]に集[あつ]めます。", "sentence_source": "generated"}, {"text": "洗う前に、お皿の食べ残しを紙でふき取ります。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "洗[あら]う前[まえ]に、お皿[さら]の食[た]べ残[のこ]しを紙[かみ]でふき取[と]ります。", "sentence_source": "generated"}, {"text": "食べ残しがついたままの皿は、水につけておくと洗いやすいです。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "食[た]べ残[のこ]しがついたままの皿[さら]は、水[みず]につけておくと洗[あら]いやすいです。", "sentence_source": "generated"}, {"text": "給食の時間が終わると、みんなのトレーに食べ残しがないか先生が見て回ります。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "給食[きゅうしょく]の時間[じかん]が終[お]わると、みんなのトレーに食[た]べ残[のこ]しがないか先生[せんせい]が見[み]て回[まわ]ります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食べ残し", "label": "基本形"}, {"form": "食べ残しの", "label": "連体形（の）"}, {"form": "食べ残しが", "label": "主語形（が）"}, {"form": "食べ残しを", "label": "目的語形（を）"}], "register": "neutral", "sense_fingerprint": "食事のあと、お皿の上にまだ残っている食べ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: 追い払い (Zipf 2.39)','sentence 7 above tier T2: contains vocabulary far above tier T2: ふき取り (Zipf 1.93)']::text[], '2e600720-6c23-4799-8dcf-cf155a991805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36856, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食べ残し", "is_correct": true, "explanation": "「お皿に残った魚」という文脈に合う。食事のあと皿に残った食べ物のこと。"}, {"text": "値段", "is_correct": false, "explanation": "「値段」は商品の価格で、お皿の上の食べ物という文脈には合わない。"}, {"text": "体重", "is_correct": false, "explanation": "「体重」は人や動物の重さで、お皿に残った魚という文には合わない。"}, {"text": "出勤簿", "is_correct": false, "explanation": "「出勤簿」は勤務の記録帳で、食事のあとの皿の上には合わない。"}], "explanations": {"食べ残し": "「お皿に残った魚」という文脈に合う。食事のあと皿に残った食べ物のこと。", "値段": "「値段」は商品の価格で、お皿の上の食べ物という文脈には合わない。", "体重": "「体重」は人や動物の重さで、お皿に残った魚という文には合わない。", "出勤簿": "「出勤簿」は勤務の記録帳で、食事のあとの皿の上には合わない。"}, "sentence_index": 0, "correct_answer": "食べ残し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事故現場には車の食べ残しが散らばっていた。", "explanation": "ここは〈残骸〉の意味。食べ残しは食事で残った食品に限るので、壊れた車の破片には使わない。"}, {"text": "引き出しの食べ残しを整理した。", "explanation": "ここは〈残り物〉の意味。食べ残しは食べ物に限るので、物品の余りには使わない。"}, {"text": "財布の食べ残しを数えた。", "explanation": "ここは〈残金〉の意味。食べ残しは食べ物なので、お金の残りには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36856, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食べ残し", "is_correct": true, "explanation": "「野菜の」に続き、皿の端に集める対象として文の意味に合う。"}, {"text": "電池", "is_correct": false, "explanation": "「電池」は電気を蓄える部品で、野菜の後に続けて皿に集める文には合わない。"}, {"text": "空き缶", "is_correct": false, "explanation": "「空き缶」は飲み終わった容器で、野菜と組み合わさって皿に集める文には合わない。"}, {"text": "定規", "is_correct": false, "explanation": "「定規」は線を引く道具で、食事のあとの皿の端という文脈には合わない。"}], "explanations": {"食べ残し": "「野菜の」に続き、皿の端に集める対象として文の意味に合う。", "電池": "「電池」は電気を蓄える部品で、野菜の後に続けて皿に集める文には合わない。", "空き缶": "「空き缶」は飲み終わった容器で、野菜と組み合わさって皿に集める文には合わない。", "定規": "「定規」は線を引く道具で、食事のあとの皿の端という文脈には合わない。"}, "sentence_index": 6, "correct_answer": "食べ残し"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合の食べ残しは五分しかなかった。", "explanation": "ここは〈残り時間〉の意味。食べ残しは食事で残った食品のことなので、試合の時間には使わない。"}, {"text": "布の食べ残しで小物を作った。", "explanation": "ここは〈余り〉の意味。食べ残しは食品の残りに限るので、布の切れ端には使わない。"}, {"text": "交番に食べ残しを届けた。", "explanation": "ここは〈落とし物〉の意味。食べ残しは食事で残った食品で、拾った持ち物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36856, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "食べ残しに片づけました。", "corrected_sentence": "食べ残しを片づけました。", "error_description": "「片づける」は対象に「を」を付ける。「に」は誤りで、正しくは「食べ残しを片づけました」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36856, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "食べ残しを作りました。", "corrected_sentence": "食べ残しを捨てました。", "error_description": "「食べ残し」は「捨てる」などと組む。「作る」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36857, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「食べ残しが出やすい」の「が」。「出る」の主語を示す助詞。"}, {"text": "を", "is_correct": false, "explanation": "「出る」は自動詞なので「を」は付かず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「食べ残しに出やすい」は対象の意味になり、文の意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示し、「食べ残しと出やすい」は文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「食べ残しが出やすい」の「が」。「出る」の主語を示す助詞。", "を": "「出る」は自動詞なので「を」は付かず、文が成り立たない。", "に": "「食べ残しに出やすい」は対象の意味になり、文の意味が通らない。", "と": "「と」は並列を示し、「食べ残しと出やすい」は文が成り立たない。"}, "error_tags": {"を": "自動詞に付かない", "に": "対象を示さない", "と": "並列の助詞で合わない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36857, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「食べ残しを冷蔵庫に入れて」の「を」。「入れる」の目的語を示す助詞。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示し、「食べ残しが入れて」は目的語にならず文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示し、「食べ残しで冷蔵庫に入れて」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「食べ残しへ入れて」は入れる対象として不自然。"}], "correct_answer": "を", "explanations": {"を": "「食べ残しを冷蔵庫に入れて」の「を」。「入れる」の目的語を示す助詞。", "が": "「が」は主語を示し、「食べ残しが入れて」は目的語にならず文が成り立たない。", "で": "「で」は手段を示し、「食べ残しで冷蔵庫に入れて」は意味が通らない。", "へ": "「へ」は方向を示し、「食べ残しへ入れて」は入れる対象として不自然。"}, "error_tags": {"が": "主語の助詞で合わない", "で": "手段の助詞で合わない", "へ": "方向の助詞で合わない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36857, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "食事のときに、食べきれずに残った料理や食品。", "primary_collocate": null, "pronunciation": "たべのこし", "ipa": "tabenokoɕi", "syllable_count": 5, "sentences": [{"text": "このレストランでは、食べ残しを持ち帰る袋を用意しています。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "このレストランでは、食[た]べ残[のこ]しを持[も]ち帰[かえ]る袋[ふくろ]を用意[ようい]しています。", "sentence_source": "generated"}, {"text": "宴会では食べ残しが出やすいので、料理は少なめに注文しました。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "宴会[えんかい]では食[た]べ残[のこ]しが出[で]やすいので、料理[りょうり]は少[すく]なめに注文[ちゅうもん]しました。", "sentence_source": "generated"}, {"text": "食べ残しを減らすために、小盛りを選べる店が増えています。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "食[た]べ残[のこ]しを減[へ]らすために、小盛[こもり]りを選[えら]べる店[みせ]が増[ふ]えています。", "sentence_source": "generated"}, {"text": "食べ残しは食品ロスの大きな原因の一つです。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "食[た]べ残[のこ]しは食品[しょくひん]ロスの大[おお]きな原因[げんいん]の一[ひと]つです。", "sentence_source": "generated"}, {"text": "学校の給食では、食べ残しの量を毎日記録しています。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "学校[がっこう]の給食[きゅうしょく]では、食[た]べ残[のこ]しの量[りょう]を毎日[まいにち]記録[きろく]しています。", "sentence_source": "generated"}, {"text": "食べ残しが出ないように、自分が食べられる量だけ取りましょう。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "食[た]べ残[のこ]しが出[で]ないように、自分[じぶん]が食[た]べられる量[りょう]だけ取[と]りましょう。", "sentence_source": "generated"}, {"text": "ホテルのバイキングでは、食べ残しをすると追加料金をとる所もあります。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "ホテルのバイキングでは、食[た]べ残[のこ]しをすると追加[ついか]料金[りょうきん]を取[と]る所[ところ]もあります。", "sentence_source": "generated"}, {"text": "私は食べ残しを冷蔵庫に入れて、次の日の昼ごはんにしました。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "私[わたし]は食[た]べ残[のこ]しを冷蔵庫[れいぞうこ]に入[い]れて、次[つぎ]の日[ひ]の昼[ひる]ごはんにしました。", "sentence_source": "generated"}, {"text": "食べ残しの多い日は、店の人も悲しい気持ちになります。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "食[た]べ残[のこ]しの多[おお]い日[ひ]は、店[みせ]の人[ひと]も悲[かな]しい気持[きも]ちになります。", "sentence_source": "generated"}, {"text": "食べ残しをごみにしないで、動物の餌に使う農家もあります。", "target_word": "食べ残し", "complexity_tier": "T3", "furigana": "食[た]べ残[のこ]しをごみにしないで、動物[どうぶつ]の餌[えさ]に使[つか]う農家[のうか]もあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食べ残し", "label": "基本形"}, {"form": "食べ残しの", "label": "連体形（の）"}, {"form": "食べ残しが", "label": "主語形（が）"}, {"form": "食べ残しを", "label": "目的語形（を）"}], "register": "neutral", "sense_fingerprint": "食事で食べきれなかった料理や食品（量や廃棄の話題で使われる）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e600720-6c23-4799-8dcf-cf155a991805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36857, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食べ残し", "is_correct": true, "explanation": "「持ち帰る袋」の対象として、食事で残った料理という文脈に合う。"}, {"text": "洗剤", "is_correct": false, "explanation": "「洗剤」は洗い物に使う品で、持ち帰る袋の対象には合わない。"}, {"text": "切符", "is_correct": false, "explanation": "「切符」は乗り物などに使う券で、レストランで持ち帰る対象には合わない。"}, {"text": "体温計", "is_correct": false, "explanation": "「体温計」は体温を測る器具で、持ち帰る袋の対象という文には合わない。"}], "explanations": {"食べ残し": "「持ち帰る袋」の対象として、食事で残った料理という文脈に合う。", "洗剤": "「洗剤」は洗い物に使う品で、持ち帰る袋の対象には合わない。", "切符": "「切符」は乗り物などに使う券で、レストランで持ち帰る対象には合わない。", "体温計": "「体温計」は体温を測る器具で、持ち帰る袋の対象という文には合わない。"}, "sentence_index": 0, "correct_answer": "食べ残し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "倉庫の食べ残しを数えて、帳簿に書いた。", "explanation": "ここは〈在庫〉の意味。食べ残しは食事で残った料理のことで、店の商品の数には使わない。"}, {"text": "ガラスの食べ残しで手を切った。", "explanation": "ここは〈破片〉の意味。食べ残しは食品なので、割れたガラスには使わない。"}, {"text": "ページの食べ残しにメモを書いた。", "explanation": "ここは〈余白〉の意味。食べ残しは食べ物に限るので、紙の空いた部分には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36857, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食べ残し", "is_correct": true, "explanation": "「をすると追加料金」の対象として、食事で残した料理という文脈に合う。"}, {"text": "盗難", "is_correct": false, "explanation": "「盗難」は物を盗まれることで、「をすると追加料金」という文の対象には合わない。"}, {"text": "造船", "is_correct": false, "explanation": "「造船」は船を造ることで、バイキングの追加料金の文脈には合わない。"}, {"text": "失恋", "is_correct": false, "explanation": "「失恋」は恋が終わることで、料金の対象としては文が成り立たない。"}], "explanations": {"食べ残し": "「をすると追加料金」の対象として、食事で残した料理という文脈に合う。", "盗難": "「盗難」は物を盗まれることで、「をすると追加料金」という文の対象には合わない。", "造船": "「造船」は船を造ることで、バイキングの追加料金の文脈には合わない。", "失恋": "「失恋」は恋が終わることで、料金の対象としては文が成り立たない。"}, "sentence_index": 6, "correct_answer": "食べ残し"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友人から長い食べ残しが届いた。", "explanation": "ここは〈手紙〉の意味。食べ残しは食事で残った料理で、郵便物には使わない。"}, {"text": "契約書に食べ残しを押した。", "explanation": "ここは〈印鑑〉の意味。食べ残しは食品なので、契約書に押す物には使わない。"}, {"text": "来年の食べ残しを決めた。", "explanation": "ここは〈予算〉の意味。食べ残しは食事の残りで、来年の計画の金額には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36857, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "食べ残しを少なくなるように、量を決めましょう。", "corrected_sentence": "食べ残しが少なくなるように、量を決めましょう。", "error_description": "「少なくなる」は主語に「が」を付ける。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36857, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "食べ残しの長い宴会は、店も大変です。", "corrected_sentence": "食べ残しの多い宴会は、店も大変です。", "error_description": "「食べ残し」は量を表す「多い」と組む。「長い」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36858, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「生塵が早く腐る」の主語を示す助詞で、文の意味に合う。"}, {"text": "を", "is_correct": false, "explanation": "「腐る」は目的語をとらない自動詞なので、「生塵を腐る」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「生塵に早く腐る」は、腐る場所や相手を示す語法として不自然。"}, {"text": "と", "is_correct": false, "explanation": "相手・並列の「と」。「生塵と早く腐る」は文として成り立たず不自然。"}], "correct_answer": "が", "explanations": {"が": "「生塵が早く腐る」の主語を示す助詞で、文の意味に合う。", "を": "「腐る」は目的語をとらない自動詞なので、「生塵を腐る」は成り立たない。", "に": "「生塵に早く腐る」は、腐る場所や相手を示す語法として不自然。", "と": "相手・並列の「と」。「生塵と早く腐る」は文として成り立たず不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "位置・相手", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36858, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「生塵を小さな袋にまとめる」で、まとめられる対象を示す目的語の助詞。"}, {"text": "が", "is_correct": false, "explanation": "「生塵が袋にまとめる」は、まとめる動作の主語として不自然で、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す助詞で、「生塵で袋にまとめる」は不自然な文になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「生塵へ袋にまとめる」は動作の対象として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「生塵を小さな袋にまとめる」で、まとめられる対象を示す目的語の助詞。", "が": "「生塵が袋にまとめる」は、まとめる動作の主語として不自然で、文が成り立たない。", "で": "手段を示す助詞で、「生塵で袋にまとめる」は不自然な文になる。", "へ": "方向を示す助詞で、「生塵へ袋にまとめる」は動作の対象として成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "で": "手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36858, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ごみや食べ物の残りで、いらなくなったもののことです。", "primary_collocate": null, "pronunciation": "なまごみ", "ipa": "namaɡomi", "syllable_count": 4, "sentences": [{"text": "台所の生塵は、においが出る前に袋に入れて捨てます。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "台所[だいどころ]の生塵[なまごみ]は、においが出[で]る前[まえ]に袋[ふくろ]に入[い]れて捨[す]てます。", "sentence_source": "generated"}, {"text": "夏は生塵が早く腐るので、毎日出すようにしています。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "夏[なつ]は生塵[なまごみ]が早[はや]く腐[くさ]るので、毎日[まいにち]出[だ]すようにしています。", "sentence_source": "generated"}, {"text": "生塵の日は、火曜日と金曜日です。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "生塵[なまごみ]の日[ひ]は、火曜日[かようび]と金曜日[きんようび]です。", "sentence_source": "generated"}, {"text": "野菜の皮や魚の骨は、生塵として捨てます。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "野菜[やさい]の皮[かわ]や魚[さかな]の骨[ほね]は、生塵[なまごみ]として捨[す]てます。", "sentence_source": "generated"}, {"text": "生塵は水気を切ってから出すと、においが少なくなります。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "生塵[なまごみ]は水気[みずけ]を切[き]ってから出[だ]すと、においが少[すく]なくなります。", "sentence_source": "generated"}, {"text": "袋の口が開いていたので、カラスが生塵をあさっていました。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "袋[ふくろ]の口[くち]が開[あ]いていたので、カラスが生塵[なまごみ]をあさっていました。", "sentence_source": "generated"}, {"text": "生塵のにおいが部屋に広がって、窓を開けました。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "生塵[なまごみ]のにおいが部屋[へや]に広[ひろ]がって、窓[まど]を開[あ]けました。", "sentence_source": "generated"}, {"text": "食事のあと、母は生塵を小さな袋にまとめました。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "食事[しょくじ]のあと、母[はは]は生塵[なまごみ]を小[ちい]さな袋[ふくろ]にまとめました。", "sentence_source": "generated"}, {"text": "旅行に行く前に、冷蔵庫の古い食べ物を生塵として出しました。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "旅行[りょこう]に行[い]く前[まえ]に、冷蔵庫[れいぞうこ]の古[ふる]い食[た]べ物[もの]を生塵[なまごみ]として出[だ]しました。", "sentence_source": "generated"}, {"text": "生塵はほかのごみと分けて、決まった袋に入れてください。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "生塵[なまごみ]はほかのごみと分[わ]けて、決[き]まった袋[ふくろ]に入[い]れてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生塵", "label": "基本形"}, {"form": "生塵の", "label": "連体形（の）"}, {"form": "生塵が", "label": "主語形（が）"}, {"form": "生塵を", "label": "目的語形（を）"}], "register": "neutral", "sense_fingerprint": "台所などで出る、水気があって腐りやすい食べ物のごみ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e600720-6c23-4799-8dcf-cf155a991805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36858, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生塵", "is_correct": true, "explanation": "台所から出る水気のある生ごみを指し、においが出る前に袋に入れて捨てる話の主語として自然に入る。"}, {"text": "蛇口", "is_correct": false, "explanation": "台所の設備で、袋に入れて捨てるものではないため、文の主語として成り立たない。"}, {"text": "換気扇", "is_correct": false, "explanation": "台所に付いている設備で、ごみとして捨てることはないので、この空欄には入らない。"}, {"text": "食器棚", "is_correct": false, "explanation": "家具であり、においを出して袋に入れて捨てる対象ではないため、この文には合わない。"}], "explanations": {"生塵": "台所から出る水気のある生ごみを指し、においが出る前に袋に入れて捨てる話の主語として自然に入る。", "蛇口": "台所の設備で、袋に入れて捨てるものではないため、文の主語として成り立たない。", "換気扇": "台所に付いている設備で、ごみとして捨てることはないので、この空欄には入らない。", "食器棚": "家具であり、においを出して袋に入れて捨てる対象ではないため、この文には合わない。"}, "sentence_index": 0, "correct_answer": "生塵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "猫のえさを、生塵として店で買いました。", "explanation": "ここは〈ペットフード〉の意味。えさは買って与える食べ物で、捨てるごみではないので、生塵とは合わない。"}, {"text": "窓のさんに積もった生塵を、はたきで払いました。", "explanation": "ここは〈埃〉の意味。生塵は食べ物のくずを指すので、積もったちりに使うのは誤り。"}, {"text": "この料理は、生塵で味を整えました。", "explanation": "ここは〈調味料〉の意味。生塵は捨てるごみを指し、味付けに使う語ではないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36858, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生塵", "is_correct": true, "explanation": "台所から出る生ごみを指し、においが部屋に広がるという文の主語として自然に入る。"}, {"text": "時計", "is_correct": false, "explanation": "においを出さない道具で、「時計のにおい」は成り立たず、この空欄には入らない。"}, {"text": "天気", "is_correct": false, "explanation": "においの発生源にならない概念で、「天気のにおいが部屋に広がる」は不自然。"}, {"text": "木曜日", "is_correct": false, "explanation": "曜日を表す名詞で、においを出す物ではないため、この文には合わない。"}], "explanations": {"生塵": "台所から出る生ごみを指し、においが部屋に広がるという文の主語として自然に入る。", "時計": "においを出さない道具で、「時計のにおい」は成り立たず、この空欄には入らない。", "天気": "においの発生源にならない概念で、「天気のにおいが部屋に広がる」は不自然。", "木曜日": "曜日を表す名詞で、においを出す物ではないため、この文には合わない。"}, "sentence_index": 6, "correct_answer": "生塵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母の日に、感謝の気持ちを込めて生塵を贈りました。", "explanation": "ここは〈贈り物〉の意味。贈り物は人に渡して喜ばれるものだが、生塵は捨てる不要物なので、贈る対象にはならない。"}, {"text": "市場で新鮮な生塵を見つけて、うれしくなりました。", "explanation": "ここは〈生鮮食品〉の意味。生鮮食品は新鮮さを喜ぶものだが、生塵は捨てるごみなので、新鮮さを評価する語とは合わない。"}, {"text": "庭に生えた生塵を、一本ずつ抜きました。", "explanation": "ここは〈雑草〉の意味。雑草は庭に生えて抜く植物だが、生塵は食べ物のごみなので、生えるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36858, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏は生塵を早く腐るので、こまめに出すようにしています。", "corrected_sentence": "夏は生塵が早く腐るので、こまめに出すようにしています。", "error_description": "「腐る」は生塵が主語になる動きなので、主語を示す「が」が正しい。「を」にすると目的語のように読まれ、不自然な文になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36858, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "生塵をにおいが台所に広がって、窓をすぐ開けました。", "corrected_sentence": "生塵のにおいが台所に広がって、窓をすぐ開けました。", "error_description": "「生塵のにおい」の「の」を「を」に変えると、生塵が目的語になってしまい、においとの修飾関係が崩れる。正しくは「の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36859, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「家庭から出る生塵の約半分」で、生塵の一部を修飾する連体修飾の「の」。"}, {"text": "を", "is_correct": false, "explanation": "「生塵を約半分は」は、目的語を示すはずの位置に入るが文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「生塵に約半分は」は、位置や相手を示す形として不自然で、修飾の関係が作れない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す助詞で、「生塵で約半分は」は文の構造が崩れる。"}], "correct_answer": "の", "explanations": {"の": "「家庭から出る生塵の約半分」で、生塵の一部を修飾する連体修飾の「の」。", "を": "「生塵を約半分は」は、目的語を示すはずの位置に入るが文が成り立たない。", "に": "「生塵に約半分は」は、位置や相手を示す形として不自然で、修飾の関係が作れない。", "で": "手段や場所を示す助詞で、「生塵で約半分は」は文の構造が崩れる。"}, "error_tags": {"の": "連体修飾", "を": "目的語", "に": "位置", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36859, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36859, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "家庭や飲食店などから出る、食べ物のくずや調理くずなどの不要になった有機物の総称。", "primary_collocate": null, "pronunciation": "なまごみ", "ipa": "namaɡomi", "syllable_count": 4, "sentences": [{"text": "飲食店では、毎日たくさんの生塵が出ます。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "飲食店[いんしょくてん]では、毎日[まいにち]たくさんの生塵[なまごみ]が出[で]ます。", "sentence_source": "generated"}, {"text": "家庭から出る生塵の約半分は、水分だといわれています。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "家庭[かてい]から出[で]る生塵[なまごみ]の約[やく]半分[はんぶん]は、水分[すいぶん]だといわれています。", "sentence_source": "generated"}, {"text": "市は、生塵を集めて堆肥にする取り組みを始めました。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "市[し]は、生塵[なまごみ]を集[あつ]めて堆肥[たいひ]にする取[と]り組[く]みを始[はじ]めました。", "sentence_source": "generated"}, {"text": "調理くずや食べ残しなど、食べ物に関わるごみをまとめて生塵といいます。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "調理[ちょうり]くずや食[た]べ残[のこ]しなど、食[た]べ物[もの]に関[かか]わるごみをまとめて生塵[なまごみ]といいます。", "sentence_source": "generated"}, {"text": "生塵を減らすために、野菜は皮ごと使う家庭が増えています。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "生塵[なまごみ]を減[へ]らすために、野菜[やさい]は皮[かわ]ごと使[つか]う家庭[かてい]が増[ふ]えています。", "sentence_source": "generated"}, {"text": "生塵は水分が多くて燃えにくいため、処理に費用がかかります。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "生塵[なまごみ]は水分[すいぶん]が多[おお]くて燃[も]えにくいため、処理[しょり]に費用[ひよう]がかかります。", "sentence_source": "generated"}, {"text": "給食センターでは、出た生塵を機械で肥料に変えています。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "給食[きゅうしょく]センターでは、出[で]た生塵[なまごみ]を機械[きかい]で肥料[ひりょう]に変[か]えています。", "sentence_source": "generated"}, {"text": "庭に穴を掘って、家庭の生塵を土に返す人もいます。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "庭[にわ]に穴[あな]を掘[ほ]って、家庭[かてい]の生塵[なまごみ]を土[つち]に返[かえ]す人[ひと]もいます。", "sentence_source": "generated"}, {"text": "生塵の量は、家庭の食生活によって大きく変わります。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "生塵[なまごみ]の量[りょう]は、家庭[かてい]の食生活[しょくせいかつ]によって大[おお]きく変[か]わります。", "sentence_source": "generated"}, {"text": "スーパーの裏では、売れ残った野菜などの生塵が毎日集められます。", "target_word": "生塵", "complexity_tier": "T3", "furigana": "スーパーの裏[うら]では、売[う]れ残[のこ]った野菜[やさい]などの生塵[なまごみ]が毎日[まいにち]集[あつ]められます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生塵", "label": "基本形"}, {"form": "生塵の", "label": "連体形（の）"}, {"form": "生塵が", "label": "主語形（が）"}, {"form": "生塵を", "label": "目的語形（を）"}], "register": "neutral", "sense_fingerprint": "家庭・飲食店・店などから出る食品くずや調理くずなど、不要になった有機物ごみの総称（処理や量の話題で使われる）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e600720-6c23-4799-8dcf-cf155a991805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36859, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生塵", "is_correct": true, "explanation": "飲食店から出る食べ物くずなどの有機物ごみを指し、「毎日たくさん出る」という文に自然に合う。"}, {"text": "天気", "is_correct": false, "explanation": "ごみのように出るものではなく、「天気が出ます」は意味が成り立たない。"}, {"text": "英語", "is_correct": false, "explanation": "学習科目であり、飲食店から出るものではないので、この空欄には入らない。"}, {"text": "時計", "is_correct": false, "explanation": "飲食店で毎日たくさん出る物ではなく、「時計が出ます」は不自然。"}], "explanations": {"生塵": "飲食店から出る食べ物くずなどの有機物ごみを指し、「毎日たくさん出る」という文に自然に合う。", "天気": "ごみのように出るものではなく、「天気が出ます」は意味が成り立たない。", "英語": "学習科目であり、飲食店から出るものではないので、この空欄には入らない。", "時計": "飲食店で毎日たくさん出る物ではなく、「時計が出ます」は不自然。"}, "sentence_index": 0, "correct_answer": "生塵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場で出る金属くずや油なども、まとめて生塵といいます。", "explanation": "ここは〈産業廃棄物〉の意味。金属くずや油は有機物の食べ物くずではないので、生塵には当たらない。"}, {"text": "古い布団を、生塵として干しました。", "explanation": "ここは〈寝具〉の意味。布団は干して使うもので、捨てるごみではないので、生塵とは合わない。"}, {"text": "夕食の生塵を買いに、スーパーへ行きました。", "explanation": "ここは〈食材〉の意味。食材は料理に使うために買うものだが、生塵は捨てるものなので、買う対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36859, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生塵", "is_correct": true, "explanation": "給食センターで出た食べ物のくずを指し、機械で肥料に変えるという文の目的語として自然に入る。"}, {"text": "宿題", "is_correct": false, "explanation": "学校の課題で、機械で肥料に変える対象にはならないので、この文には合わない。"}, {"text": "天井", "is_correct": false, "explanation": "建物の一部で、出た物を肥料に変える対象にはならず、文として成り立たない。"}, {"text": "算数", "is_correct": false, "explanation": "教科の名前で、肥料に変えられる物ではないため、この空欄には入らない。"}], "explanations": {"生塵": "給食センターで出た食べ物のくずを指し、機械で肥料に変えるという文の目的語として自然に入る。", "宿題": "学校の課題で、機械で肥料に変える対象にはならないので、この文には合わない。", "天井": "建物の一部で、出た物を肥料に変える対象にはならず、文として成り立たない。", "算数": "教科の名前で、肥料に変えられる物ではないため、この空欄には入らない。"}, "sentence_index": 6, "correct_answer": "生塵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝市で新鮮な生塵を見つけて、うれしくなりました。", "explanation": "ここは〈生鮮食品〉の意味。生鮮食品は新鮮さを喜ぶ食品だが、生塵は捨てるごみなので、新鮮さを評価する語とは合わない。"}, {"text": "古い新聞紙を、生塵として束ねて出しました。", "explanation": "ここは〈古紙〉の意味。新聞紙は食べ物のくずではないので、生塵とは言わない。"}, {"text": "台所の水は、生塵として川に流れます。", "explanation": "ここは〈生活排水〉の意味。排水は液体の水なので、固形の食べ物くずを指す生塵とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36859, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ホテルの厨房では、毎日たくさんの生塵を出ます。", "corrected_sentence": "ホテルの厨房では、毎日たくさんの生塵が出ます。", "error_description": "「出る」は自動詞なので、生塵は主語となり「が」を使う。「を」にすると他動詞のように読まれ、不自然な文になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36859, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その店は生塵が毎日ごみ置き場に出します。", "corrected_sentence": "その店は生塵を毎日ごみ置き場に出します。", "error_description": "「出す」は他動詞で、出されるものを「を」で示す。生塵を主語の「が」で示すと、店が出すという関係が崩れて不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36860, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「かばんの中を見ても」で、見る対象を示す目的語の「を」。"}, {"text": "が", "is_correct": false, "explanation": "「かばんの中が見ても」は、見る動作の主語として成り立たず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「かばんの中に見ても」は、見る動作の場所として不自然で、文の意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す「と」で、「かばんの中と見ても」は文の構造が崩れる。"}], "correct_answer": "を", "explanations": {"を": "「かばんの中を見ても」で、見る対象を示す目的語の「を」。", "が": "「かばんの中が見ても」は、見る動作の主語として成り立たず不自然。", "に": "「かばんの中に見ても」は、見る動作の場所として不自然で、文の意味が通らない。", "と": "相手や並列を示す「と」で、「かばんの中と見ても」は文の構造が崩れる。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "位置", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36860, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「中が赤くて甘い」で、赤くて甘いという状態の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「中を赤くて甘い」は、状態を表す文の目的語として成り立たず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「中に赤くて甘い」は、場所を示す形として状態の説明にならず不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」だが、「中の赤くて甘いです」は文の述語が成り立たず不自然。"}], "correct_answer": "が", "explanations": {"が": "「中が赤くて甘い」で、赤くて甘いという状態の主語を示す「が」。", "を": "「中を赤くて甘い」は、状態を表す文の目的語として成り立たず不自然。", "に": "「中に赤くて甘い」は、場所を示す形として状態の説明にならず不自然。", "の": "連体修飾の「の」だが、「中の赤くて甘いです」は文の述語が成り立たず不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "位置", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36860, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "何かの内側や真ん中。", "primary_collocate": null, "pronunciation": "なか", "ipa": "naka", "syllable_count": 2, "sentences": [{"text": "箱の中に、古い写真が入っていました。", "target_word": "中", "complexity_tier": "T3", "furigana": "箱(はこ)の中(なか)に、古(ふる)い写真(しゃしん)が入(はい)っていました。", "sentence_source": "generated"}, {"text": "かばんの中を見ても、財布が見つかりません。", "target_word": "中", "complexity_tier": "T3", "furigana": "かばんの中(なか)を見(み)ても、財布(さいふ)が見(み)つかりません。", "sentence_source": "generated"}, {"text": "外は寒いので、家の中で本を読んでいます。", "target_word": "中", "complexity_tier": "T3", "furigana": "外(そと)は寒(さむ)いので、家(いえ)の中(なか)で本(ほん)を読(よ)んでいます。", "sentence_source": "generated"}, {"text": "部屋の中は暗くて、何も見えませんでした。", "target_word": "中", "complexity_tier": "T3", "furigana": "部屋(へや)の中(なか)は暗(くら)くて、何(なに)も見(み)えませんでした。", "sentence_source": "generated"}, {"text": "冷蔵庫の中にケーキがあるので、食べてもいいですよ。", "target_word": "中", "complexity_tier": "T3", "furigana": "冷蔵庫(れいぞうこ)の中(なか)にケーキがあるので、食(た)べてもいいですよ。", "sentence_source": "generated"}, {"text": "池の中で、大きな魚が泳いでいます。", "target_word": "中", "complexity_tier": "T3", "furigana": "池(いけ)の中(なか)で、大(おお)きな魚(さかな)が泳(およ)いでいます。", "sentence_source": "generated"}, {"text": "雨がやまないので、店の中で少し待ちました。", "target_word": "中", "complexity_tier": "T3", "furigana": "雨(あめ)がやまないので、店(みせ)の中(なか)で少(すこ)し待(ま)ちました。", "sentence_source": "generated"}, {"text": "この果物は、中が赤くて甘いです。", "target_word": "中", "complexity_tier": "T3", "furigana": "この果物(くだもの)は、中(なか)が赤(あか)くて甘(あま)いです。", "sentence_source": "generated"}, {"text": "先生は教室の中に入って、窓を開けました。", "target_word": "中", "complexity_tier": "T3", "furigana": "先生(せんせい)は教室(きょうしつ)の中(なか)に入(はい)って、窓(まど)を開(あ)けました。", "sentence_source": "generated"}, {"text": "森の中は静かで、鳥の声だけが聞こえました。", "target_word": "中", "complexity_tier": "T3", "furigana": "森(もり)の中(なか)は静(しず)かで、鳥(とり)の声(こえ)だけが聞(き)こえました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "中", "label": "基本形"}], "register": "丁寧な日常語", "sense_fingerprint": "物や場所の内側、内部（なかと読む）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e600720-6c23-4799-8dcf-cf155a991805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36860, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中", "is_correct": true, "explanation": "「箱の中」で、箱の内側を指す。古い写真が入っていたという文に合う。"}, {"text": "外", "is_correct": false, "explanation": "内側の反対の意味で、「箱の外に入っていた」は内容が矛盾するため、この空欄には入らない。"}, {"text": "色", "is_correct": false, "explanation": "箱の色を表す名詞で、写真が入っている場所を示せないので、この文には合わない。"}, {"text": "名前", "is_correct": false, "explanation": "箱に付けられた呼び名で、写真が入る場所にはならないため、この文は成り立たない。"}], "explanations": {"中": "「箱の中」で、箱の内側を指す。古い写真が入っていたという文に合う。", "外": "内側の反対の意味で、「箱の外に入っていた」は内容が矛盾するため、この空欄には入らない。", "色": "箱の色を表す名詞で、写真が入っている場所を示せないので、この文には合わない。", "名前": "箱に付けられた呼び名で、写真が入る場所にはならないため、この文は成り立たない。"}, "sentence_index": 0, "correct_answer": "中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人の中に、小さな椅子が一つあります。", "explanation": "ここは〈間〉の意味。二人のあいだは人の内側ではないので、「二人の中」とは言わない。"}, {"text": "一週間の中で、三日雨が降りました。", "explanation": "ここは〈期間の範囲〉の意味。一週間の中で三日は期間内の数を指すので、内側の意味とは違い誤り。"}, {"text": "三人の中から、代表を一人選びました。", "explanation": "ここは〈選択の範囲〉の意味。三人の中から一人を選ぶのは集まりの範囲を指すので、内側の意味とは違い誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36860, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中", "is_correct": true, "explanation": "「店の中」で、店の内側を指す。雨を避けて店の中で待ったという文に合う。"}, {"text": "形", "is_correct": false, "explanation": "店の外観を表す名詞で、待つ場所を示せないため、この文には合わない。"}, {"text": "値段", "is_correct": false, "explanation": "商品の価格を表す語で、場所を示す役割を果たせないので、この空欄には入らない。"}, {"text": "寿命", "is_correct": false, "explanation": "物の使える期間を表す語で、待つ場所にはならないため、この文は成り立たない。"}], "explanations": {"中": "「店の中」で、店の内側を指す。雨を避けて店の中で待ったという文に合う。", "形": "店の外観を表す名詞で、待つ場所を示せないため、この文には合わない。", "値段": "商品の価格を表す語で、場所を示す役割を果たせないので、この空欄には入らない。", "寿命": "物の使える期間を表す語で、待つ場所にはならないため、この文は成り立たない。"}, "sentence_index": 6, "correct_answer": "中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "テストの中で、一問だけ間違えました。", "explanation": "ここは〈範囲〉の意味。テストの中で一問は範囲内の数を指すので、内側の意味とは違い誤り。"}, {"text": "ドアの中を押して、家に入りました。", "explanation": "ここは〈表面〉の意味。ドアは面を押すもので、中を押すとは言わないので誤り。"}, {"text": "話の中で、彼が急に笑いました。", "explanation": "ここは〈途中〉の意味。話の中で、は話の最中を指し、内側の意味とは違うので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36860, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冷蔵庫の中を牛乳が入っています。", "corrected_sentence": "冷蔵庫の中に牛乳が入っています。", "error_description": "「入る」の場所は「に」で示す。「を」は目的語を示すので、場所を表すここでは使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36860, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は部屋の中を、本を読んでいます。", "corrected_sentence": "妹は部屋の中で、本を読んでいます。", "error_description": "「読む」の場所は「で」で示す。「を」にすると中が目的語になり、読む場所を表す意味が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36862, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「地面に」で、絵をかく場所を示す。"}, {"text": "が", "is_correct": false, "explanation": "「地面が」は主語になるが、絵をかく場所を示す文には合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を表すので、場所を示す文には使えない。"}, {"text": "を", "is_correct": false, "explanation": "「地面を」の後に「絵を」が続き、目的語が二つになって不自然。"}], "correct_answer": "に", "explanations": {"に": "「地面に」で、絵をかく場所を示す。", "が": "「地面が」は主語になるが、絵をかく場所を示す文には合わない。", "より": "「より」は比較の基準を表すので、場所を示す文には使えない。", "を": "「地面を」の後に「絵を」が続き、目的語が二つになって不自然。"}, "error_tags": {"が": "主語", "より": "比較", "を": "目的語の重なり"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36862, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「地面に」で、置く場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「地面を置く」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、置く場所を表せない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐが、「地面の置く」では動詞につながらない。"}], "correct_answer": "に", "explanations": {"に": "「地面に」で、置く場所を示す。", "を": "「を」は目的語を示すが、「地面を置く」は成り立たない。", "と": "「と」は並列や相手を示すが、置く場所を表せない。", "の": "「の」は名詞をつなぐが、「地面の置く」では動詞につながらない。"}, "error_tags": {"を": "目的語", "と": "並列", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36862, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "じめんは、わたしたちが立っている下の、土のところです。", "primary_collocate": null, "pronunciation": "じめん", "ipa": "dʑimeɴ", "syllable_count": 3, "sentences": [{"text": "雨がやんだあとも、地面はまだぬれていた。", "target_word": "地面", "complexity_tier": "T3", "furigana": "雨[あめ]がやんだあとも、地面[じめん]はまだぬれていた。", "sentence_source": "generated"}, {"text": "子どもは地面に木の枝で絵をかいて遊んでいる。", "target_word": "地面", "complexity_tier": "T3", "furigana": "子[こ]どもは地面[じめん]に木[き]の枝[えだ]で絵[え]をかいて遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "地震で、地面が大きくゆれた。", "target_word": "地面", "complexity_tier": "T3", "furigana": "地震[じしん]で、地面[じめん]が大[おお]きくゆれた。", "sentence_source": "generated"}, {"text": "鳥が地面におりて、小さな虫を探している。", "target_word": "地面", "complexity_tier": "T3", "furigana": "鳥[とり]が地面[じめん]におりて、小[ちい]さな虫[むし]を探[さが]している。", "sentence_source": "generated"}, {"text": "地面が固いので、スコップで穴をほるのが大変だ。", "target_word": "地面", "complexity_tier": "T3", "furigana": "地面[じめん]が固[かた]いので、スコップで穴[あな]をほるのが大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "落ち葉が地面いっぱいに広がっている。", "target_word": "地面", "complexity_tier": "T3", "furigana": "落[お]ち葉[ば]が地面[じめん]いっぱいに広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "冬の朝は、地面が凍って歩きにくい。", "target_word": "地面", "complexity_tier": "T3", "furigana": "冬[ふゆ]の朝[あさ]は、地面[じめん]が凍[こお]って歩[ある]きにくい。", "sentence_source": "generated"}, {"text": "荷物を地面に置くと、よごれてしまう。", "target_word": "地面", "complexity_tier": "T3", "furigana": "荷物[にもつ]を地面[じめん]に置[お]くと、よごれてしまう。", "sentence_source": "generated"}, {"text": "木の根は、地面の下に深く広がっている。", "target_word": "地面", "complexity_tier": "T3", "furigana": "木[き]の根[ね]は、地面[じめん]の下[した]に深[ふか]く広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "転んだ子どもが、地面にすわって泣いていた。", "target_word": "地面", "complexity_tier": "T3", "furigana": "転[ころ]んだ子[こ]どもが、地面[じめん]にすわって泣[な]いていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地面", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "外で立っている足の下にある、土の表面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e61b9b9-2b71-463a-b7c3-934bb8c70858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36862, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地面", "is_correct": true, "explanation": "雨がやんだあと足もとの地面がぬれているという文脈に合う。"}, {"text": "空", "is_correct": false, "explanation": "空は雨でぬれる場所ではないので、「空はまだぬれていた」は文脈に合わない。"}, {"text": "太陽", "is_correct": false, "explanation": "太陽はぬれるものではないので、文が通らない。"}, {"text": "月", "is_correct": false, "explanation": "月は地上のぬれた場所ではなく、文脈に合わない。"}], "explanations": {"地面": "雨がやんだあと足もとの地面がぬれているという文脈に合う。", "空": "空は雨でぬれる場所ではないので、「空はまだぬれていた」は文脈に合わない。", "太陽": "太陽はぬれるものではないので、文が通らない。", "月": "月は地上のぬれた場所ではなく、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "地面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社の経営地面が弱い。", "explanation": "地面は足の下の土を指し、会社の基盤の意味にはならない。"}, {"text": "旅行の前に地面で道を確認した。", "explanation": "地面では道順は確認できず、地図の代わりにはならない。"}, {"text": "地面を見上げると、星が光っていた。", "explanation": "地面は足の下にあり、見上げて星を見る対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36862, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地面", "is_correct": true, "explanation": "冬の朝、足もとの地面が凍って歩きにくいという文脈に合う。"}, {"text": "星", "is_correct": false, "explanation": "星は凍って歩きにくくなるものではないので、文が通らない。"}, {"text": "花", "is_correct": false, "explanation": "花が凍っても歩きにくさにはつながらず、文脈に合わない。"}, {"text": "煙", "is_correct": false, "explanation": "煙は凍って歩きにくくなるものではないので、文が通らない。"}], "explanations": {"地面": "冬の朝、足もとの地面が凍って歩きにくいという文脈に合う。", "星": "星は凍って歩きにくくなるものではないので、文が通らない。", "花": "花が凍っても歩きにくさにはつながらず、文脈に合わない。", "煙": "煙は凍って歩きにくくなるものではないので、文が通らない。"}, "sentence_index": 6, "correct_answer": "地面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地面は太陽のまわりを回っている。", "explanation": "地面は足もとの土を指し、惑星全体は表せない。"}, {"text": "湖の地面に波が立った。", "explanation": "波が立つのは水面で、陸の表面を指す地面とは言わない。"}, {"text": "地面の雪をおろした。", "explanation": "雪をおろすのは屋根で、地面の雪をおろすとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36862, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもは地面を座って、絵本を読んでいる。", "corrected_sentence": "子どもは地面に座って、絵本を読んでいる。", "error_description": "誤りは「地面」に続く助詞。「座る」は場所に「に」を取るので、「を」ではなく「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36862, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "日差しで地面を熱くなり、犬が歩けなくなった。", "corrected_sentence": "日差しで地面が熱くなり、犬が歩けなくなった。", "error_description": "誤りは「地面を」の助詞。「熱くなる」は変化する主体に「が」を取るので、「地面が熱くなり」が正しく、「を」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36863, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「地面が」で、でこぼこしている主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「地面をでこぼこしている」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すが、「地面とでこぼこしている」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「地面へでこぼこしている」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「地面が」で、でこぼこしている主語を示す。", "を": "「を」は目的語を示すが、「地面をでこぼこしている」は成り立たない。", "と": "「と」は並列を示すが、「地面とでこぼこしている」は文が成り立たない。", "へ": "「へ」は方向を示すが、「地面へでこぼこしている」は意味が通らない。"}, "error_tags": {"を": "目的語", "と": "並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36863, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「地面の上」で、上にあるという位置を示す。"}, {"text": "に", "is_correct": false, "explanation": "「地面に上に」は助詞が重なって位置関係を表せず、不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "「地面で上に」は場所を表す働きと「上」の組み合わせが合わず、意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「地面が上に線を引いて」では地面が線を引く主語になり意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「地面の上」で、上にあるという位置を示す。", "に": "「地面に上に」は助詞が重なって位置関係を表せず、不自然になる。", "で": "「地面で上に」は場所を表す働きと「上」の組み合わせが合わず、意味が通らない。", "が": "「が」は主語を示すが、「地面が上に線を引いて」では地面が線を引く主語になり意味が通らない。"}, "error_tags": {"に": "帰着", "で": "場所", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36863, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面とは、わたしたちが歩いたり、立ったりする、足の下にある土や固いところのことです。", "primary_collocate": null, "pronunciation": "じめん", "ipa": "dʑimeɴ", "syllable_count": 3, "sentences": [{"text": "公園の地面はやわらかくて、走っても足が痛くならない。", "target_word": "地面", "complexity_tier": "T3", "furigana": "公園[こうえん]の地面[じめん]はやわらかくて、走[はし]っても足[あし]が痛[いた]くならない。", "sentence_source": "generated"}, {"text": "地面がでこぼこしているので、自転車は押して歩く。", "target_word": "地面", "complexity_tier": "T3", "furigana": "地面[じめん]がでこぼこしているので、自転車[じてんしゃ]は押[お]して歩[ある]く。", "sentence_source": "generated"}, {"text": "夏の昼は、地面が熱くて、はだしでは歩けない。", "target_word": "地面", "complexity_tier": "T3", "furigana": "夏[なつ]の昼[ひる]は、地面[じめん]が熱[あつ]くて、はだしでは歩[ある]けない。", "sentence_source": "generated"}, {"text": "飛行機が着陸して、ようやく地面に足がついた。", "target_word": "地面", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]が着陸[ちゃくりく]して、ようやく地面[じめん]に足[あし]がついた。", "sentence_source": "generated"}, {"text": "地面に水をまくと、ほこりが立たなくなる。", "target_word": "地面", "complexity_tier": "T3", "furigana": "地面[じめん]に水[みず]をまくと、ほこりが立[た]たなくなる。", "sentence_source": "generated"}, {"text": "雪が積もり、地面が真っ白になった。", "target_word": "地面", "complexity_tier": "T3", "furigana": "雪[ゆき]が積[つ]もり、地面[じめん]が真[ま]っ白[しろ]になった。", "sentence_source": "generated"}, {"text": "ボールが地面にはねて、遠くまで転がった。", "target_word": "地面", "complexity_tier": "T3", "furigana": "ボールが地面[じめん]にはねて、遠[とお]くまで転[ころ]がった。", "sentence_source": "generated"}, {"text": "地面の上に線を引いて、かけっこのゴールにした。", "target_word": "地面", "complexity_tier": "T3", "furigana": "地面[じめん]の上[うえ]に線[せん]を引[ひ]いて、かけっこのゴールにした。", "sentence_source": "generated"}, {"text": "地面にあいた小さな穴から、アリが出てくる。", "target_word": "地面", "complexity_tier": "T3", "furigana": "地面[じめん]にあいた小[ちい]さな穴[あな]から、アリが出[で]てくる。", "sentence_source": "generated"}, {"text": "工事の人が、地面をならして平らにしている。", "target_word": "地面", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]が、地面[じめん]をならして平[たい]らにしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地面", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "人が歩いたり立ったりする、足の下の土や固い面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e61b9b9-2b71-463a-b7c3-934bb8c70858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36863, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地面", "is_correct": true, "explanation": "やわらかい地面なので走っても足が痛くならないという文脈に合う。"}, {"text": "池", "is_correct": false, "explanation": "池は走る場所ではなく、やわらかくて足が痛くならないという説明に合わない。"}, {"text": "遊具", "is_correct": false, "explanation": "遊具は走る場所ではなく、「公園の遊具はやわらかくて」は文が通らない。"}, {"text": "木", "is_correct": false, "explanation": "木は走れる場所ではないので、「公園の木はやわらかくて」は文脈に合わない。"}], "explanations": {"地面": "やわらかい地面なので走っても足が痛くならないという文脈に合う。", "池": "池は走る場所ではなく、やわらかくて足が痛くならないという説明に合わない。", "遊具": "遊具は走る場所ではなく、「公園の遊具はやわらかくて」は文が通らない。", "木": "木は走れる場所ではないので、「公園の木はやわらかくて」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "地面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部屋の地面にワックスをかけた。", "explanation": "ここは〈床〉の意味。地面は外の土の表面で、部屋の中の床は床と言う。"}, {"text": "池の地面に葉が浮いている。", "explanation": "ここは〈水面〉の意味。葉が浮いているのは水の表面で、地面は陸の表面を指す。"}, {"text": "地面からランプがつるされている。", "explanation": "ここは〈天井〉の意味。ランプをつるすのは天井で、地面からは下げられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36863, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地面", "is_correct": true, "explanation": "ボールが地面にはねて遠くまで転がったという文脈に合う。"}, {"text": "空", "is_correct": false, "explanation": "ボールが空にはねることはなく、文が通らない。"}, {"text": "雲", "is_correct": false, "explanation": "ボールが雲にはねることはなく、文脈に合わない。"}, {"text": "星", "is_correct": false, "explanation": "ボールが星にはねるという場面はなく、文が通らない。"}], "explanations": {"地面": "ボールが地面にはねて遠くまで転がったという文脈に合う。", "空": "ボールが空にはねることはなく、文が通らない。", "雲": "ボールが雲にはねることはなく、文脈に合わない。", "星": "ボールが星にはねるという場面はなく、文が通らない。"}, "sentence_index": 6, "correct_answer": "地面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地面の上に船が浮かんでいる。", "explanation": "ここは〈海〉の意味。船が浮かぶのは海で、地面の上に船は浮かばないので合わない。"}, {"text": "地面に月が浮かんでいる。", "explanation": "ここは〈空〉の意味。月は空に浮かぶもので、地面に浮かぶことはない。"}, {"text": "地面は太陽のまわりを回っている。", "explanation": "ここは〈地球〉の意味。地面は足もとの土で、太陽のまわりを回るのは地球全体なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36863, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもが地面を寝転んで、空を見上げている。", "corrected_sentence": "子どもが地面に寝転んで、空を見上げている。", "error_description": "誤りは「地面」に続く助詞。「寝転ぶ」は場所に「に」を取るので、「を」ではなく「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36863, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨がやんで、地面が縮んで歩きやすくなった。", "corrected_sentence": "雨がやんで、地面が乾いて歩きやすくなった。", "error_description": "誤りは「縮んで」。「縮む」は地面には使わず、地面の水分がなくなる様子は「乾く」で表すので、正しくは「乾いて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36864, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗い", "is_correct": true, "explanation": "「細かい」（粒が小さい）の対義語。粗いは粒が大きく目が粗い様子を表す。"}, {"text": "太い", "is_correct": false, "explanation": "太いは太さを表す語で、粒の細かさの対義語ではない。"}, {"text": "重い", "is_correct": false, "explanation": "重いは重さを表し、粒の大小の対義語にならない。"}, {"text": "高い", "is_correct": false, "explanation": "高いは高さや値段を表し、粒の細かさとは対にならない。"}], "correct_answer": "粗い", "explanations": {"粗い": "「細かい」（粒が小さい）の対義語。粗いは粒が大きく目が粗い様子を表す。", "太い": "太いは太さを表す語で、粒の細かさの対義語ではない。", "重い": "重いは重さを表し、粒の大小の対義語にならない。", "高い": "高いは高さや値段を表し、粒の細かさとは対にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
