INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36864, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "とても小さいこと。", "primary_collocate": null, "pronunciation": "こまかい", "ipa": "komakai", "syllable_count": 4, "sentences": [{"text": "野菜を細かく刻んで、スープに入れます。", "target_word": "細かく", "complexity_tier": "T3", "furigana": "野菜[やさい]を細[こま]かく刻[きざ]んで、スープに入[い]れます。", "sentence_source": "generated"}, {"text": "床に細かいガラスの破片が散らばっていた。", "target_word": "細かい", "complexity_tier": "T3", "furigana": "床[ゆか]に細[こま]かいガラスの破片[はへん]が散[ち]らばっていた。", "sentence_source": "generated"}, {"text": "細かい砂が靴の中に入って、歩きにくい。", "target_word": "細かい", "complexity_tier": "T3", "furigana": "細[こま]かい砂[すな]が靴[くつ]の中[なか]に入[はい]って、歩[ある]きにくい。", "sentence_source": "generated"}, {"text": "パンを細かくちぎって、鳥にあげた。", "target_word": "細かく", "complexity_tier": "T3", "furigana": "パンを細[こま]かくちぎって、鳥[とり]にあげた。", "sentence_source": "generated"}, {"text": "細かい雨が一日中降り続いている。", "target_word": "細かい", "complexity_tier": "T3", "furigana": "細[こま]かい雨[あめ]が一日中[いちにちじゅう]降[ふ]り続[つづ]いている。", "sentence_source": "generated"}, {"text": "紙を細かく破って、ごみ箱に捨てた。", "target_word": "細かく", "complexity_tier": "T3", "furigana": "紙[かみ]を細[こま]かく破[やぶ]って、ごみ箱[ばこ]に捨[す]てた。", "sentence_source": "generated"}, {"text": "細かい文字が多くて、説明書が読みにくい。", "target_word": "細かい", "complexity_tier": "T3", "furigana": "細[こま]かい文字[もじ]が多[おお]くて、説明書[せつめいしょ]が読[よ]みにくい。", "sentence_source": "generated"}, {"text": "細かい粉を水に溶かして、ゆっくりかき混ぜる。", "target_word": "細かい", "complexity_tier": "T3", "furigana": "細[こま]かい粉[こな]を水[みず]に溶[と]かして、ゆっくりかき混[ま]ぜる。", "sentence_source": "generated"}, {"text": "氷を細かく砕いて、ジュースに入れた。", "target_word": "細かく", "complexity_tier": "T3", "furigana": "氷[こおり]を細[こま]かく砕[くだ]いて、ジュースに入[い]れた。", "sentence_source": "generated"}, {"text": "粒が細かい砂糖は、すぐに溶けるので便利です。", "target_word": "細かい", "complexity_tier": "T3", "furigana": "粒[つぶ]が細[こま]かい砂糖[さとう]は、すぐに溶[と]けるので便利[べんり]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "細かい", "label": "終止形"}, {"form": "細かく", "label": "連用形"}, {"form": "細かくて", "label": "て形"}, {"form": "細かかった", "label": "過去形"}, {"form": "細かくない", "label": "否定形"}, {"form": "細かければ", "label": "仮定形"}], "register": "標準（中立）", "sense_fingerprint": "粒や破片などが非常に小さい、細かい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33db208a-4ad2-4e69-a0ee-68818b305fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36864, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "細かく", "is_correct": true, "explanation": "副詞。「刻んで」を修飾し、小さく切る様子を表して文が成り立つ。"}, {"text": "細かさ", "is_correct": false, "explanation": "名詞。程度を表す名詞で、「刻んで」に直接続けると文が成り立たない。"}, {"text": "細部", "is_correct": false, "explanation": "名詞。部分そのものを指すので、動詞「刻んで」を修飾する形になっていない。"}, {"text": "形状", "is_correct": false, "explanation": "名詞。形の様子を指すので、野菜を刻む動作とは合わない。"}], "explanations": {"細かく": "副詞。「刻んで」を修飾し、小さく切る様子を表して文が成り立つ。", "細かさ": "名詞。程度を表す名詞で、「刻んで」に直接続けると文が成り立たない。", "細部": "名詞。部分そのものを指すので、動詞「刻んで」を修飾する形になっていない。", "形状": "名詞。形の様子を指すので、野菜を刻む動作とは合わない。"}, "sentence_index": 0, "correct_answer": "細かく"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は細かい腕をして、重いものも軽々と持ち上げる。", "explanation": "ここは〈太い〉の意味。細かいは小ささを指すので、腕の太さには使わない。"}, {"text": "彼女は手足が細かくて、モデルのようだ。", "explanation": "ここは〈細い〉の意味。細かいは粒や注意の小ささを指すので、人の体の細さには使わない。"}, {"text": "大声で細かく叫んで、みんなが驚いた。", "explanation": "ここは〈大きく〉の意味。細かくは小片や細部に関わる副詞で、声を大きくする意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36864, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "細かい", "is_correct": true, "explanation": "連体形。後ろの「文字」を修飾して、文字が小さいことを表し文が成り立つ。"}, {"text": "精緻", "is_correct": false, "explanation": "名詞・形容動詞語幹。「精緻文字」と直接続けられず、文が成り立たない。"}, {"text": "細密", "is_correct": false, "explanation": "名詞・形容動詞語幹。「細密な」の形が必要で、ここでは文が続かない。"}, {"text": "細線", "is_correct": false, "explanation": "名詞で細い線を指す。文字の小ささを表す文脈に合わない。"}], "explanations": {"細かい": "連体形。後ろの「文字」を修飾して、文字が小さいことを表し文が成り立つ。", "精緻": "名詞・形容動詞語幹。「精緻文字」と直接続けられず、文が成り立たない。", "細密": "名詞・形容動詞語幹。「細密な」の形が必要で、ここでは文が続かない。", "細線": "名詞で細い線を指す。文字の小ささを表す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "細かい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その紙は細かくて、向こうが透けて見える。", "explanation": "ここは〈薄い〉の意味。細かいは粒の小ささを指すので、紙の薄さには使わない。"}, {"text": "彼女は細かい声で歌うので、客席の一番後ろまで響く。", "explanation": "ここは〈大きい〉の意味。細かいは小ささを表すので、声の力強さには使わない。"}, {"text": "彼は細かく急いで、電車に乗り遅れた。", "explanation": "ここは〈速く〉の意味。細かくは小ささや細部に関わり、速さは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36864, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ごまを細かい刻んで、サラダにふりかけた。", "corrected_sentence": "ごまを細かく刻んで、サラダにふりかけた。", "error_description": "動詞「刻んで」を修飾するので連用形「細かく」が正しい。連体形「細かい」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "細かい", "is_correct": true, "explanation": "連体形。後ろの「ガラスの破片」を修飾し、細かい破片という意味になる。"}, {"text": "細かく", "is_correct": false, "explanation": "連用形。名詞を直接修飾できず、「細かくガラス」は成り立たない。"}, {"text": "細かくて", "is_correct": false, "explanation": "て形。名詞を修飾できず、ここでは文が続かない。"}, {"text": "細かければ", "is_correct": false, "explanation": "仮定形。節になるため、名詞「ガラスの破片」を修飾できない。"}], "correct_form": "細かい", "base_form": "細かい", "form_label": "連体形", "sentence_index": 1, "explanations": {"細かい": "連体形。後ろの「ガラスの破片」を修飾し、細かい破片という意味になる。", "細かく": "連用形。名詞を直接修飾できず、「細かくガラス」は成り立たない。", "細かくて": "て形。名詞を修飾できず、ここでは文が続かない。", "細かければ": "仮定形。節になるため、名詞「ガラスの破片」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36864, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "粉を細かいすりつぶして、水に溶かした。", "corrected_sentence": "粉を細かくすりつぶして、水に溶かした。", "error_description": "動詞「すりつぶす」を修飾するので連用形「細かく」が正しい。連体形「細かい」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "細かい", "is_correct": true, "explanation": "連体形。後ろの「粉」を修飾して「細かい粉」となり、文の意味に合う。"}, {"text": "細かさ", "is_correct": false, "explanation": "名詞。程度を表す名詞で、「粉」に直接続けると「細かさ粉」となり文が成り立たない。"}, {"text": "細かくても", "is_correct": false, "explanation": "〜ても形。名詞「粉」を修飾できず、「細かくても粉を」は文が続かない。"}, {"text": "細かかろう", "is_correct": false, "explanation": "推量形。名詞「粉」を修飾できず、「細かかろう粉を」は成り立たない。"}], "correct_form": "細かい", "base_form": "細かい", "form_label": "連体形", "sentence_index": 7, "explanations": {"細かい": "連体形。後ろの「粉」を修飾して「細かい粉」となり、文の意味に合う。", "細かさ": "名詞。程度を表す名詞で、「粉」に直接続けると「細かさ粉」となり文が成り立たない。", "細かくても": "〜ても形。名詞「粉」を修飾できず、「細かくても粉を」は文が続かない。", "細かかろう": "推量形。名詞「粉」を修飾できず、「細かかろう粉を」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36865, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大まか", "is_correct": true, "explanation": "「細かい」（注意が行き届く）の対義語。大まかは細部を気にしない様子を表す。"}, {"text": "太い", "is_correct": false, "explanation": "太い・細いは太さの対で、注意の行き届きの対義語ではない。"}, {"text": "広い", "is_correct": false, "explanation": "広いは面積の広さを指し、注意の細やかさとは関係ない。"}, {"text": "高い", "is_correct": false, "explanation": "高いは高さや値段を表し、対義語にならない。"}], "correct_answer": "大まか", "explanations": {"大まか": "「細かい」（注意が行き届く）の対義語。大まかは細部を気にしない様子を表す。", "太い": "太い・細いは太さの対で、注意の行き届きの対義語ではない。", "広い": "広いは面積の広さを指し、注意の細やかさとは関係ない。", "高い": "高いは高さや値段を表し、対義語にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36865, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大まか", "is_correct": true, "explanation": "「細かい」（注意が行き届く）の対義語。大まかは細部を気にしない様子を表す。"}, {"text": "厚い", "is_correct": false, "explanation": "厚いは厚さを表す語で、注意の細かさの対義語ではない。"}, {"text": "重い", "is_correct": false, "explanation": "重いは重さを表す語で、対義語にならない。"}, {"text": "深い", "is_correct": false, "explanation": "深いは奥行きや理解の深さを表し、注意の行き届きとは対にならない。"}], "correct_answer": "大まか", "explanations": {"大まか": "「細かい」（注意が行き届く）の対義語。大まかは細部を気にしない様子を表す。", "厚い": "厚いは厚さを表す語で、注意の細かさの対義語ではない。", "重い": "重いは重さを表す語で、対義語にならない。", "深い": "深いは奥行きや理解の深さを表し、注意の行き届きとは対にならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36865, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "細かく分かれている様子。または、詳しいところまで注意が行き届いていること。", "primary_collocate": null, "pronunciation": "こまかい", "ipa": "komakai", "syllable_count": 4, "sentences": [{"text": "これは、作物の生育状況を細かく把握し、必要な水や肥料を的確に与える仕組みです。", "target_word": "細かく", "complexity_tier": "T3", "furigana": "これは、作物[さくもつ]の生育[せいいく]状況[じょうきょう]を細[こま]かく把握[はあく]し、必要[ひつよう]な水[みず]や肥料[ひりょう]を的確[てきかく]に与[あた]える仕組[しく]みです。", "sentence_source": "mined"}, {"text": "先生は作文の細かい間違いまで、丁寧に直してくれた。", "target_word": "細かい", "complexity_tier": "T3", "furigana": "先生[せんせい]は作文[さくぶん]の細[こま]かい間違[まちが]いまで、丁寧[ていねい]に直[なお]してくれた。", "sentence_source": "generated"}, {"text": "契約書の細かい条件を、もう一度確認しましょう。", "target_word": "細かい", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]の細[こま]かい条件[じょうけん]を、もう一度[いちど]確認[かくにん]しましょう。", "sentence_source": "generated"}, {"text": "彼は細かいところに気がつく人なので、秘書に向いている。", "target_word": "細かい", "complexity_tier": "T3", "furigana": "彼[かれ]は細[こま]かいところに気[き]がつく人[ひと]なので、秘書[ひしょ]に向[む]いている。", "sentence_source": "generated"}, {"text": "説明が細かくて、初心者でもすぐに理解できました。", "target_word": "細かくて", "complexity_tier": "T3", "furigana": "説明[せつめい]が細[こま]かくて、初心者[しょしんしゃ]でもすぐに理解[りかい]できました。", "sentence_source": "generated"}, {"text": "予定を細かく決めすぎると、旅行が窮屈になる。", "target_word": "細かく", "complexity_tier": "T3", "furigana": "予定[よてい]を細[こま]かく決[き]めすぎると、旅行[りょこう]が窮屈[きゅうくつ]になる。", "sentence_source": "generated"}, {"text": "地図には、町の道が細かく描かれている。", "target_word": "細かく", "complexity_tier": "T3", "furigana": "地図[ちず]には、町[まち]の道[みち]が細[こま]かく描[えが]かれている。", "sentence_source": "generated"}, {"text": "細かい話は後にして、まず全体の方針を決めよう。", "target_word": "細かい", "complexity_tier": "T3", "furigana": "細[こま]かい話[はなし]は後[あと]にして、まず全体[ぜんたい]の方針[ほうしん]を決[き]めよう。", "sentence_source": "generated"}, {"text": "姉は家計簿を細かくつけて、毎月の支出を確認している。", "target_word": "細かく", "complexity_tier": "T3", "furigana": "姉[あね]は家計簿[かけいぼ]を細[こま]かくつけて、毎月[まいつき]の支出[ししゅつ]を確認[かくにん]している。", "sentence_source": "generated"}, {"text": "作業を細かく分ければ、みんなで手分けしやすい。", "target_word": "細かく", "complexity_tier": "T3", "furigana": "作業[さぎょう]を細[こま]かく分[わ]ければ、みんなで手分[てわ]けしやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "細かい", "label": "終止形"}, {"form": "細かく", "label": "連用形"}, {"form": "細かくて", "label": "て形"}, {"form": "細かかった", "label": "過去形"}, {"form": "細かくない", "label": "否定形"}, {"form": "細かければ", "label": "仮定形"}], "register": "標準（中立）", "sense_fingerprint": "詳細まで行き届いている、細部に及ぶ、細かい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33db208a-4ad2-4e69-a0ee-68818b305fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36865, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "細かく", "is_correct": true, "explanation": "副詞。「把握し」を修飾して、細部まで行き届いて把握する様子を表し、文が成り立つ。"}, {"text": "細かさ", "is_correct": false, "explanation": "名詞。「細かさ」は程度を表す名詞で、「把握し」の直前に置くと文が続かない。"}, {"text": "細部", "is_correct": false, "explanation": "名詞。細かい部分そのものを指すため、動詞「把握し」を修飾する形になっていない。"}, {"text": "形状", "is_correct": false, "explanation": "名詞。形の様子を指すので、生育状況を把握する文脈に合わない。"}], "explanations": {"細かく": "副詞。「把握し」を修飾して、細部まで行き届いて把握する様子を表し、文が成り立つ。", "細かさ": "名詞。「細かさ」は程度を表す名詞で、「把握し」の直前に置くと文が続かない。", "細部": "名詞。細かい部分そのものを指すため、動詞「把握し」を修飾する形になっていない。", "形状": "名詞。形の様子を指すので、生育状況を把握する文脈に合わない。"}, "sentence_index": 0, "correct_answer": "細かく"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は細かい声で話すので、教室の隅まで聞こえない。", "explanation": "ここは〈小さい〉の意味。細かいは細部への注意や粒の小ささを指すので、声の小ささには使わない。"}, {"text": "彼女はウエストが細かくて、モデルのようだ。", "explanation": "ここは〈細い〉の意味。細かいは細部への注意や粒の小ささを指すので、体の細さには使わない。"}, {"text": "大声で細かく叫んで、みんなが驚いた。", "explanation": "ここは〈大きく〉の意味。細かくは細部や小片に関わる副詞で、声を大きくする意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36865, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "細かく", "is_correct": true, "explanation": "副詞。「描かれている」を修飾して、細部まで丁寧に描かれた様子を表す。"}, {"text": "細密", "is_correct": false, "explanation": "名詞・形容動詞語幹。「道が細密描かれ」と続けられず、文が成り立たない。"}, {"text": "精緻", "is_correct": false, "explanation": "名詞・形容動詞語幹。副詞形「精緻に」が必要で、ここでは文が続かない。"}, {"text": "細線", "is_correct": false, "explanation": "名詞で細い線を指す。道を描く様子を表す語順になっていない。"}], "explanations": {"細かく": "副詞。「描かれている」を修飾して、細部まで丁寧に描かれた様子を表す。", "細密": "名詞・形容動詞語幹。「道が細密描かれ」と続けられず、文が成り立たない。", "精緻": "名詞・形容動詞語幹。副詞形「精緻に」が必要で、ここでは文が続かない。", "細線": "名詞で細い線を指す。道を描く様子を表す語順になっていない。"}, "sentence_index": 6, "correct_answer": "細かく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その店は細かい部屋で、四人座ると窮屈だ。", "explanation": "ここは〈狭い〉の意味。細かいは細部への注意や細分化を指すので、部屋の広さには使わない。"}, {"text": "その冬は細かい寒さが町を覆い、人々は外に出られなかった。", "explanation": "ここは〈厳しい〉の意味。細かいは細部や小ささを指すので、寒さの強さには使わない。"}, {"text": "その店は細かい明かりで、夜も店内がとても暗い。", "explanation": "ここは〈暗い〉の意味。細かいは細部や小ささを表し、明るさの程度には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36865, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は説明書の細かく部分まで読んで、ミスに気がついた。", "corrected_sentence": "彼は説明書の細かい部分まで読んで、ミスに気がついた。", "error_description": "名詞「部分」を修飾する位置に連用形「細かく」が入っている。連体形「細かい」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "細かい", "is_correct": true, "explanation": "連体形。後ろの「間違い」を修飾して「細かい間違い」となり、文の意味に合う。"}, {"text": "細かく", "is_correct": false, "explanation": "連用形。名詞「間違い」を直接修飾できず、「細かく間違い」は成り立たない。"}, {"text": "細かくて", "is_correct": false, "explanation": "て形。名詞を修飾できず、ここでは文が続かない。"}, {"text": "細かければ", "is_correct": false, "explanation": "仮定形。節になるため、名詞「間違い」を修飾できない。"}], "correct_form": "細かい", "base_form": "細かい", "form_label": "連体形", "sentence_index": 1, "explanations": {"細かい": "連体形。後ろの「間違い」を修飾して「細かい間違い」となり、文の意味に合う。", "細かく": "連用形。名詞「間違い」を直接修飾できず、「細かく間違い」は成り立たない。", "細かくて": "て形。名詞を修飾できず、ここでは文が続かない。", "細かければ": "仮定形。節になるため、名詞「間違い」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36865, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この作業は細かいを分けるのが大変だ。", "corrected_sentence": "この作業は細かく分けるのが大変だ。", "error_description": "動詞「分ける」を修飾するので連用形「細かく」が入る。「細かいを」は形容詞のあとに名詞がなく誤り。「細かく分ける」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "細かい", "is_correct": true, "explanation": "連体形。後ろの「話」を修飾して「細かい話」となり、文の意味に合う。"}, {"text": "細かさ", "is_correct": false, "explanation": "名詞。程度を表す名詞で、「話」に直接続けると「細かさ話」となり文が成り立たない。"}, {"text": "細かくても", "is_correct": false, "explanation": "〜ても形。名詞「話」を修飾できず、「細かくても話は」は文が続かない。"}, {"text": "細かかろう", "is_correct": false, "explanation": "推量形。名詞「話」を修飾できず、「細かかろう話は」は成り立たない。"}], "correct_form": "細かい", "base_form": "細かい", "form_label": "連体形", "sentence_index": 7, "explanations": {"細かい": "連体形。後ろの「話」を修飾して「細かい話」となり、文の意味に合う。", "細かさ": "名詞。程度を表す名詞で、「話」に直接続けると「細かさ話」となり文が成り立たない。", "細かくても": "〜ても形。名詞「話」を修飾できず、「細かくても話は」は文が続かない。", "細かかろう": "推量形。名詞「話」を修飾できず、「細かかろう話は」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
