INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36866, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いきているもの。人やどうぶつや虫など、自分でうごくもの。", "primary_collocate": null, "pronunciation": "いきもの", "ipa": "ikimono", "syllable_count": 4, "sentences": [{"text": "池の中には、いろいろな生き物がすんでいます。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "池[いけ]の中[なか]には、いろいろな生[い]き物[もの]がすんでいます。", "sentence_source": "generated"}, {"text": "動物園には、大きい生き物も小さい生き物もいます。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]には、大[おお]きい生[い]き物[もの]も小[ちい]さい生[い]き物[もの]もいます。", "sentence_source": "generated"}, {"text": "夜の森では、目に見えない生き物の声がたくさん聞こえる。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "夜[よる]の森[もり]では、目[め]に見[み]えない生[い]き物[もの]の声[こえ]がたくさん聞[き]こえる。", "sentence_source": "generated"}, {"text": "私は小さいころから、虫や魚などの生き物が大好きでした。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "私[わたし]は小[ちい]さいころから、虫[むし]や魚[さかな]などの生[い]き物[もの]が大好[だいす]きでした。", "sentence_source": "generated"}, {"text": "動かない石と違って、生き物は自分で動くことができる。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "動[うご]かない石[いし]と違[ちが]って、生[い]き物[もの]は自分[じぶん]で動[うご]くことができる。", "sentence_source": "generated"}, {"text": "海に行ったとき、砂浜で見つけた生き物を図鑑で調べた。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "海[うみ]に行[い]ったとき、砂浜[すなはま]で見[み]つけた生[い]き物[もの]を図鑑[ずかん]で調[しら]べた。", "sentence_source": "generated"}, {"text": "弟は生き物が好きなので、休みの日は川へ魚を取りに行く。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "弟[おとうと]は生[い]き物[もの]が好[す]きなので、休[やす]みの日[ひ]は川[かわ]へ魚[さかな]を取[と]りに行[い]く。", "sentence_source": "generated"}, {"text": "あの白くて小さい生き物は何ですか。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "あの白[しろ]くて小[ちい]さい生[い]き物[もの]は何[なん]ですか。", "sentence_source": "generated"}, {"text": "公園の池に、見たことのない生き物がいたので、写真を撮りました。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "公園[こうえん]の池[いけ]に、見[み]たことのない生[い]き物[もの]がいたので、写真[しゃしん]を撮[と]りました。", "sentence_source": "generated"}, {"text": "犬や猫のような生き物を飼うときは、最後まで世話をしなければならない。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "犬[いぬ]や猫[ねこ]のような生[い]き物[もの]を飼[か]うときは、最後[さいご]まで世話[せわ]をしなければならない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生き物", "label": "基本形"}], "register": "中立", "sense_fingerprint": "自分で動く、人・動物・虫などの命あるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T3: contains vocabulary far above tier T3: 夜の森 (Zipf 1.81)']::text[], '61ff364e-4b2f-4e6b-b85e-ab8916606415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36866, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生き物", "is_correct": true, "explanation": "池にすむ、命あるものを指す。空欄に入って文が成り立つ。"}, {"text": "時計", "is_correct": false, "explanation": "池の中にすむものではない。「いろいろな時計がすんでいます」は意味が通らない。"}, {"text": "本棚", "is_correct": false, "explanation": "家具で、池の中で生活するものではない。文に合わない。"}, {"text": "消しゴム", "is_correct": false, "explanation": "池の中で生活するものではない。文に合わない。"}], "explanations": {"生き物": "池にすむ、命あるものを指す。空欄に入って文が成り立つ。", "時計": "池の中にすむものではない。「いろいろな時計がすんでいます」は意味が通らない。", "本棚": "家具で、池の中で生活するものではない。文に合わない。", "消しゴム": "池の中で生活するものではない。文に合わない。"}, "sentence_index": 0, "correct_answer": "生き物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この植物は生き物がとても強く、乾燥にも耐える。", "explanation": "ここは〈生命力〉の意味。植物の生きる力の強さは「生命力が強い」と言い、生き物とは言わない。"}, {"text": "事故の後、彼は生き物を取り留めた。", "explanation": "ここは〈命〉の意味。「命を取り留める」は命が助かることを言うので、生き物は合わない。"}, {"text": "冷蔵庫には、刺身などの生き物を入れておく。", "explanation": "ここは〈生もの〉の意味。刺身など、なまの食品を指すので、生き物は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36866, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生き物", "is_correct": true, "explanation": "命あるものを指し、「弟は___が好き」の空欄に入る。"}, {"text": "宿題", "is_correct": false, "explanation": "好きな対象としては不自然で、次の「休みの日は川へ魚を取りに行く」とつながらない。"}, {"text": "掃除機", "is_correct": false, "explanation": "好きな対象としては不自然で、文の流れに合わない。"}, {"text": "地震", "is_correct": false, "explanation": "好むものではなく、文の流れに合わない。"}], "explanations": {"生き物": "命あるものを指し、「弟は___が好き」の空欄に入る。", "宿題": "好きな対象としては不自然で、次の「休みの日は川へ魚を取りに行く」とつながらない。", "掃除機": "好きな対象としては不自然で、文の流れに合わない。", "地震": "好むものではなく、文の流れに合わない。"}, "sentence_index": 6, "correct_answer": "生き物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼にとって、家族との時間こそが生き物だ。", "explanation": "ここは〈生きがい〉の意味。心の支えになる大切なものは「生きがい」と言い、生き物とは言わない。"}, {"text": "この電池は、生き物が長い。", "explanation": "ここは〈寿命〉の意味。電池の寿命は期間の話で、生き物とは言わない。"}, {"text": "彼は仕事を辞めて、これからの生き物をゼロから組み立て直した。", "explanation": "ここは〈生き方〉の意味。これからの暮らし方を組み立て直すことは「生き方」と言い、生き物とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36866, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の林では、小さな生き物を鳴き声がよく聞こえる。", "corrected_sentence": "夜の林では、小さな生き物の鳴き声がよく聞こえる。", "error_description": "「生き物の」の「の」が「を」になっている。「生き物の鳴き声」と所属を表す「の」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36866, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "うちには、生き物が好きの弟が一人いる。", "corrected_sentence": "うちには、生き物が好きな弟が一人いる。", "error_description": "「好き」は連体形「好きな」で名詞を修飾する。「好きの」は誤りで、「生き物が好きな弟」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36867, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「生き物」が「動いていた」の主語になるので、「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞だが、「動いていた」は目的語を取らないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "行き先や相手を示す。「動いていた」の主語を表すには合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は後に名詞がないと文が終わらず、「動いていた」の前には置けない。"}], "correct_answer": "が", "explanations": {"が": "「生き物」が「動いていた」の主語になるので、「が」が正しい。", "を": "目的語を示す助詞だが、「動いていた」は目的語を取らないので合わない。", "に": "行き先や相手を示す。「動いていた」の主語を表すには合わない。", "の": "連体修飾の「の」は後に名詞がないと文が終わらず、「動いていた」の前には置けない。"}, "error_tags": {"を": "object", "に": "dative_or_location", "の": "attributive_no_head"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36867, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「生き物の種類」と所属を表す「の」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、「生き物が種類」は文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、「生き物を種類」は文に合わない。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を示す助詞で、「生き物に種類」は文に合わない。"}], "correct_answer": "の", "explanations": {"の": "「生き物の種類」と所属を表す「の」が正しい。", "が": "主語を示す助詞で、「生き物が種類」は文として成り立たない。", "を": "目的語を示す助詞で、「生き物を種類」は文に合わない。", "に": "場所や相手を示す助詞で、「生き物に種類」は文に合わない。"}, "error_tags": {"が": "subject", "を": "object", "に": "dative_or_location"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36867, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "命を持って生きているもの。人間や動物、植物、微生物などを含む。", "primary_collocate": null, "pronunciation": "いきもの", "ipa": "ikimono", "syllable_count": 4, "sentences": [{"text": "地球には、動物も植物も微生物も、たくさんの生き物がいる。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "地球[ちきゅう]には、動物[どうぶつ]も植物[しょくぶつ]も微生物[びせいぶつ]も、たくさんの生[い]き物[もの]がいる。", "sentence_source": "generated"}, {"text": "顕微鏡で水を見ると、目に見えない小さな生き物が動いていた。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "顕微鏡[けんびきょう]で水[みず]を見[み]ると、目[め]に見[み]えない小[ちい]さな生[い]き物[もの]が動[うご]いていた。", "sentence_source": "generated"}, {"text": "木や草も、命を持っている大切な生き物です。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "木[き]や草[くさ]も、命[いのち]を持[も]っている大切[たいせつ]な生[い]き物[もの]です。", "sentence_source": "generated"}, {"text": "川の水がきれいになると、いろいろな生き物が戻ってきた。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]がきれいになると、いろいろな生[い]き物[もの]が戻[もど]ってきた。", "sentence_source": "generated"}, {"text": "生き物は、水と空気と光がなければ生きていけない。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "生[い]き物[もの]は、水[みず]と空気[くうき]と光[ひかり]がなければ生[い]きていけない。", "sentence_source": "generated"}, {"text": "土の中には、微生物のような小さな生き物がたくさんいる。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "土[つち]の中[なか]には、微生物[びせいぶつ]のような小[ちい]さな生[い]き物[もの]がたくさんいる。", "sentence_source": "generated"}, {"text": "理科の授業で、生き物の命の大切さについて学んだ。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、生[い]き物[もの]の命[いのち]の大切[たいせつ]さについて学[まな]んだ。", "sentence_source": "generated"}, {"text": "環境が変わると、そこに住む生き物の種類も変わってしまう。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "環境[かんきょう]が変[か]わると、そこに住[す]む生[い]き物[もの]の種類[しゅるい]も変[か]わってしまう。", "sentence_source": "generated"}, {"text": "人間も、自然の中で生きている生き物の一つだ。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "人間[にんげん]も、自然[しぜん]の中[なか]で生[い]きている生[い]き物[もの]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "火星に生き物がいるかどうかを、科学者たちは調べている。", "target_word": "生き物", "complexity_tier": "T3", "furigana": "火星[かせい]に生[い]き物[もの]がいるかどうかを、科学者[かがくしゃ]たちは調[しら]べている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生き物", "label": "基本形"}], "register": "中立", "sense_fingerprint": "人間・動物・植物・微生物を含む、命あるもの全体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ff364e-4b2f-4e6b-b85e-ab8916606415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36867, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生き物", "is_correct": true, "explanation": "動物や植物などの命あるものを指し、「たくさんの___がいる」に入る。"}, {"text": "機械", "is_correct": false, "explanation": "命がないので「いる」とは言わない。文に合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "命がないので「いる」とは言わない。文に合わない。"}, {"text": "石", "is_correct": false, "explanation": "命がないので、動物や植物と並べて「いる」とは言わない。"}], "explanations": {"生き物": "動物や植物などの命あるものを指し、「たくさんの___がいる」に入る。", "機械": "命がないので「いる」とは言わない。文に合わない。", "教科書": "命がないので「いる」とは言わない。文に合わない。", "石": "命がないので、動物や植物と並べて「いる」とは言わない。"}, "sentence_index": 0, "correct_answer": "生き物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この木は雪の中でも生き物が強く、春にまた芽を出す。", "explanation": "ここは〈生命力〉の意味。生きる力の強さは「生命力が強い」と言い、生き物とは言わない。"}, {"text": "事故の後、父は生き物を取り留めた。", "explanation": "ここは〈命〉の意味。「命を取り留める」は命が助かることを言うので、生き物は合わない。"}, {"text": "夏は、刺身などの生き物が傷みやすい。", "explanation": "ここは〈生もの〉の意味。刺身など、なまの食品を指すので、生き物は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36867, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生き物", "is_correct": true, "explanation": "命あるものを指し、「理科の授業で、___の命の大切さ」に入って意味が通る。"}, {"text": "掃除機", "is_correct": false, "explanation": "電気で動く家電で、命がないので「命の大切さ」の対象にはならない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、命がないので「命の大切さ」の対象にはならない。"}, {"text": "自転車", "is_correct": false, "explanation": "人が乗る乗り物で、命がないので「命の大切さ」の対象にはならない。"}], "explanations": {"生き物": "命あるものを指し、「理科の授業で、___の命の大切さ」に入って意味が通る。", "掃除機": "電気で動く家電で、命がないので「命の大切さ」の対象にはならない。", "冷蔵庫": "食品を冷やす家電で、命がないので「命の大切さ」の対象にはならない。", "自転車": "人が乗る乗り物で、命がないので「命の大切さ」の対象にはならない。"}, "sentence_index": 6, "correct_answer": "生き物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼にとって、絵を描くことが生き物だ。", "explanation": "ここは〈生きがい〉の意味。「絵を描くことが生きがいだ」は価値の話で、生き物とは言わない。"}, {"text": "この電球は生き物が長い。", "explanation": "ここは〈寿命〉の意味。電球の寿命は期間の話で、生き物は合わない。"}, {"text": "彼は家族と話し合い、これからの生き物を一から組み直すことにした。", "explanation": "ここは〈生き方〉の意味。これからの暮らし方を組み直すことは「生き方」と言い、生き物とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36867, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この池には、珍しい生き物を卵が見つかった。", "corrected_sentence": "この池には、珍しい生き物の卵が見つかった。", "error_description": "「生き物の卵」と所属を表す「の」が必要。「を」は誤りで、「の」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36867, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "森の中で、珍しい生き物を見つかった。", "corrected_sentence": "森の中で、珍しい生き物が見つかった。", "error_description": "「見つかる」の主語には「が」を使う。「を」は誤りで、「生き物が見つかった」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36868, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「菌」が主語となり、「食べて土に変えてくれる」動作の主体を示す。"}, {"text": "に", "is_correct": false, "explanation": "「菌に食べて」では菌が相手になり、食べる主体を示せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は行き先を示す。「菌へ食べて」は方向の文にならず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる文の形。「菌より食べて」は比較の文にならず不自然。"}], "correct_answer": "が", "explanations": {"が": "「菌」が主語となり、「食べて土に変えてくれる」動作の主体を示す。", "に": "「菌に食べて」では菌が相手になり、食べる主体を示せず不自然。", "へ": "「へ」は行き先を示す。「菌へ食べて」は方向の文にならず不自然。", "より": "「より」は比べる文の形。「菌より食べて」は比較の文にならず不自然。"}, "error_tags": {"に": "相手", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36868, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36868, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "とても小さな生き物で、目には見えないけれど、食べ物を土に変えるはたらきをするものです。", "primary_collocate": null, "pronunciation": "きん", "ipa": "kʲiɴ", "syllable_count": 2, "sentences": [{"text": "菌は目に見えないほど小さな生き物だ。", "target_word": "菌", "complexity_tier": "T3", "furigana": "菌[きん]は目[め]に見[み]えないほど小[ちい]さな生[い]き物[もの]だ。", "sentence_source": "generated"}, {"text": "生ごみを土に埋めておくと、菌が食べて土に変えてくれる。", "target_word": "菌", "complexity_tier": "T3", "furigana": "生[なま]ごみを土[つち]に埋[う]めておくと、菌[きん]が食[た]べて土[つち]に変[か]えてくれる。", "sentence_source": "generated"}, {"text": "落ち葉がなくなるのは、菌が少しずつ食べているからだ。", "target_word": "菌", "complexity_tier": "T3", "furigana": "落[お]ち葉[ば]がなくなるのは、菌[きん]が少[すこ]しずつ食[た]べているからだ。", "sentence_source": "generated"}, {"text": "菌のおかげで、くさったものがやがて土にもどる。", "target_word": "菌", "complexity_tier": "T3", "furigana": "菌[きん]のおかげで、くさったものがやがて土[つち]にもどる。", "sentence_source": "generated"}, {"text": "顕微鏡を使うと、小さな菌の形が見える。", "target_word": "菌", "complexity_tier": "T3", "furigana": "顕微鏡[けんびきょう]を使[つか]うと、小[ちい]さな菌[きん]の形[かたち]が見[み]える。", "sentence_source": "generated"}, {"text": "畑の土には、たくさんの菌がすんでいる。", "target_word": "菌", "complexity_tier": "T3", "furigana": "畑[はたけ]の土[つち]には、たくさんの菌[きん]がすんでいる。", "sentence_source": "generated"}, {"text": "菌がはたらいてくれるので、庭の土はいつもふかふかだ。", "target_word": "菌", "complexity_tier": "T3", "furigana": "菌[きん]がはたらいてくれるので、庭[にわ]の土[つち]はいつもふかふかだ。", "sentence_source": "generated"}, {"text": "先生は「菌は土を元気にする大切な生き物です」と話した。", "target_word": "菌", "complexity_tier": "T3", "furigana": "先生[せんせい]は「菌[きん]は土[つち]を元気[げんき]にする大切[たいせつ]な生[い]き物[もの]です」と話[はな]した。", "sentence_source": "generated"}, {"text": "パンを置きっぱなしにすると、菌が増えて緑色になった。", "target_word": "菌", "complexity_tier": "T3", "furigana": "パンを置[お]きっぱなしにすると、菌[きん]が増[ふ]えて緑色[みどりいろ]になった。", "sentence_source": "generated"}, {"text": "菌が働かなければ、枯れた草や木はずっと地面に残ってしまう。", "target_word": "菌", "complexity_tier": "T3", "furigana": "菌[きん]が働[はたら]かなければ、枯[か]れた草[くさ]や木[き]はずっと地面[じめん]に残[のこ]ってしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "菌", "label": "基本形"}], "register": "plain", "sense_fingerprint": "目に見えないほど小さく、食べ物や落ち葉を土に変える生き物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5d03ae9-b159-42d0-9195-de0f63374e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36868, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "菌", "is_correct": true, "explanation": "目に見えないほど小さな生き物を指す「菌」が主語になり、文の意味が成り立つ。"}, {"text": "木", "is_correct": false, "explanation": "木は目に見えないほど小さな生き物ではないので、文の主語として成り立たない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は生き物ではないので、「目に見えないほど小さな生き物だ」の主語にならない。"}, {"text": "砂", "is_correct": false, "explanation": "砂は小さくても生き物ではないので、「生き物だ」と言える主語にならない。"}], "explanations": {"菌": "目に見えないほど小さな生き物を指す「菌」が主語になり、文の意味が成り立つ。", "木": "木は目に見えないほど小さな生き物ではないので、文の主語として成り立たない。", "紙": "紙は生き物ではないので、「目に見えないほど小さな生き物だ」の主語にならない。", "砂": "砂は小さくても生き物ではないので、「生き物だ」と言える主語にならない。"}, "sentence_index": 0, "correct_answer": "菌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この新しい菌は、ボタンを押すと動く。", "explanation": "ここは〈機械〉の意味。「動く」は機械や装置に使う語で、菌には使わない。"}, {"text": "夜、窓の外で菌がやかましく鳴いた。", "explanation": "ここは〈虫〉の意味。鳴くのは虫や鳥で、菌は鳴かないので合わない。"}, {"text": "菌を三台買った。", "explanation": "ここは菌を〈機械〉として数えている。台は機械を数える助数詞で、菌は機械ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36868, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "菌", "is_correct": true, "explanation": "土の中で枯れた草や木を分解して働く生き物を指し、「働きやすい」の主語になる。"}, {"text": "石", "is_correct": false, "explanation": "石は働く生き物ではないので、「石がはたらいてくれる」は意味が通らない。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は生き物ではないので、「鉄がはたらいてくれる」という文は成り立たない。"}, {"text": "塩", "is_correct": false, "explanation": "塩は土を分解して働くものではないので、「塩がはたらいてくれる」は不自然。"}], "explanations": {"菌": "土の中で枯れた草や木を分解して働く生き物を指し、「働きやすい」の主語になる。", "石": "石は働く生き物ではないので、「石がはたらいてくれる」は意味が通らない。", "鉄": "鉄は生き物ではないので、「鉄がはたらいてくれる」という文は成り立たない。", "塩": "塩は土を分解して働くものではないので、「塩がはたらいてくれる」は不自然。"}, "sentence_index": 6, "correct_answer": "菌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寝る前に菌を磨いた。", "explanation": "ここは菌を〈歯や床〉のように磨く対象として扱っている。菌は磨く物ではないので、ここでは合わない。"}, {"text": "この菌から芽が出た。", "explanation": "ここは菌を〈植物の種〉として扱っている。菌からは芽が出ないので、ここでは合わない。"}, {"text": "先生は菌の答案を採点した。", "explanation": "ここは菌を〈答案〉のように扱っている。答案は採点される書類で、菌は答案ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36868, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "生ごみが土に変わるのは、菌を生ごみをゆっくり分解するからだ。", "corrected_sentence": "生ごみが土に変わるのは、菌が生ごみをゆっくり分解するからだ。", "error_description": "分解する主語の「菌」には「が」を使う。「菌を」は目的語の形で、「生ごみを」と目的語が重なり文が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36868, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "枯れ葉が土になるのは、菌を枯れ葉をゆっくり分解するからだ。", "corrected_sentence": "枯れ葉が土になるのは、菌が枯れ葉をゆっくり分解するからだ。", "error_description": "分解する主語の「菌」には「が」を使う。「菌を」は目的語の形で、「枯れ葉を」と目的語が重なり文が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
