INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36869, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「菌」が主語となり、「増える」動作の主体を示す。"}, {"text": "の", "is_correct": false, "explanation": "「ご飯に菌の増えて」では名詞の続きにならず、動詞「増えて」につながらない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる文の形。「ご飯より菌が増えて」は比較の意味が立たず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「菌と増えて」は共に増えるという意味にならず、「〜と増える」の形として不自然。"}], "correct_answer": "が", "explanations": {"が": "「菌」が主語となり、「増える」動作の主体を示す。", "の": "「ご飯に菌の増えて」では名詞の続きにならず、動詞「増えて」につながらない。", "より": "「より」は比べる文の形。「ご飯より菌が増えて」は比較の意味が立たず不自然。", "と": "「菌と増えて」は共に増えるという意味にならず、「〜と増える」の形として不自然。"}, "error_tags": {"の": "連体", "より": "比較", "と": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36869, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "微生物の一種で、特に有機物を分解する働きを持つ生物。発酵や腐敗に関わる。", "primary_collocate": null, "pronunciation": "きん", "ipa": "kʲiɴ", "syllable_count": 2, "sentences": [{"text": "ヨーグルトは、乳酸を作る菌が牛乳を発酵させて作られる。", "target_word": "菌", "complexity_tier": "T3", "furigana": "ヨーグルトは、乳酸[にゅうさん]を作[つく]る菌[きん]が牛乳[ぎゅうにゅう]を発酵[はっこう]させて作[つく]られる。", "sentence_source": "generated"}, {"text": "パンがふくらむのは、酵母という菌が糖を分解して気体を出すからだ。", "target_word": "菌", "complexity_tier": "T3", "furigana": "パンがふくらむのは、酵母[こうぼ]という菌[きん]が糖[とう]を分解[ぶんかい]して気体[きたい]を出[だ]すからだ。", "sentence_source": "generated"}, {"text": "落ち葉は土の中の菌によって分解され、やがて栄養になる。", "target_word": "菌", "complexity_tier": "T3", "furigana": "落[お]ち葉[ば]は土[つち]の中[なか]の菌[きん]によって分解[ぶんかい]され、やがて栄養[えいよう]になる。", "sentence_source": "generated"}, {"text": "食べ物が腐るのは、空気中の菌が増えて有機物を分解するためだ。", "target_word": "菌", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]が腐[くさ]るのは、空気中[くうきちゅう]の菌[きん]が増[ふ]えて有機物[ゆうきぶつ]を分解[ぶんかい]するためだ。", "sentence_source": "generated"}, {"text": "納豆は、蒸した大豆に菌を加えて発酵させて作る。", "target_word": "菌", "complexity_tier": "T3", "furigana": "納豆[なっとう]は、蒸[む]した大豆[だいず]に菌[きん]を加[くわ]えて発酵[はっこう]させて作[つく]る。", "sentence_source": "generated"}, {"text": "チーズの熟成には、いろいろな菌が重要な役割を果たしている。", "target_word": "菌", "complexity_tier": "T3", "furigana": "チーズの熟成[じゅくせい]には、いろいろな菌[きん]が重要[じゅうよう]な役割[やくわり]を果[は]たしている。", "sentence_source": "generated"}, {"text": "堆肥を作るときは、菌が働きやすいように水分と空気を調節する。", "target_word": "菌", "complexity_tier": "T3", "furigana": "堆肥[たいひ]を作[つく]るときは、菌[きん]が働[はたら]きやすいように水分[すいぶん]と空気[くうき]を調節[ちょうせつ]する。", "sentence_source": "generated"}, {"text": "冷蔵庫に入れ忘れたご飯に菌が増えて、においがおかしくなった。", "target_word": "菌", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]に入[い]れ忘[わす]れたご飯[はん]に菌[きん]が増[ふ]えて、においがおかしくなった。", "sentence_source": "generated"}, {"text": "味噌の味は、熟成のあいだに働く菌の種類によって変わる。", "target_word": "菌", "complexity_tier": "T3", "furigana": "味噌[みそ]の味[あじ]は、熟成[じゅくせい]のあいだに働[はたら]く菌[きん]の種類[しゅるい]によって変[か]わる。", "sentence_source": "generated"}, {"text": "森の地面が落ち葉で埋まらないのは、菌が少しずつ葉を分解しているからだ。", "target_word": "菌", "complexity_tier": "T3", "furigana": "森[もり]の地面[じめん]が落[お]ち葉[ば]で埋[う]まらないのは、菌[きん]が少[すこ]しずつ葉[は]を分解[ぶんかい]しているからだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "菌", "label": "基本形"}], "register": "plain", "sense_fingerprint": "有機物を分解し発酵や腐敗に関わる微生物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5d03ae9-b159-42d0-9195-de0f63374e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36869, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "菌", "is_correct": true, "explanation": "乳酸を作る微生物を指す「菌」が主語になり、牛乳を発酵させる文として成り立つ。"}, {"text": "水", "is_correct": false, "explanation": "水は微生物ではなく、牛乳を発酵させる主語にはならない。"}, {"text": "石", "is_correct": false, "explanation": "石は生き物ではないので、牛乳を発酵させる主語として成り立たない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は発酵させる働きを持たず、この文の主語として合わない。"}], "explanations": {"菌": "乳酸を作る微生物を指す「菌」が主語になり、牛乳を発酵させる文として成り立つ。", "水": "水は微生物ではなく、牛乳を発酵させる主語にはならない。", "石": "石は生き物ではないので、牛乳を発酵させる主語として成り立たない。", "紙": "紙は発酵させる働きを持たず、この文の主語として合わない。"}, "sentence_index": 0, "correct_answer": "菌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭の菌がきれいに咲いた。", "explanation": "ここは〈花〉の意味。「咲く」は花に使う動詞で、菌には「生える・増える」を使うので合わない。"}, {"text": "パソコンが菌に感染して、画面が固まった。", "explanation": "ここは〈コンピュータウイルス〉の意味。「菌」は生き物なので、パソコンには感染しない。ウイルスと取り違えた使い方。"}, {"text": "けがをすると、体の菌が傷口をふさいで治していく。", "explanation": "ここは〈細胞〉の意味。傷口をふさいで治すのは体の細胞の働きで、菌がするわけではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36869, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "菌", "is_correct": true, "explanation": "堆肥の中で有機物を分解して働く微生物を指し、「働きやすい」の主語になる。"}, {"text": "塩", "is_correct": false, "explanation": "塩は微生物ではないので、「塩が働きやすい」とは言えない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は働く生き物ではないので、「鍋が働きやすいように水分と空気を調節する」は成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は働く生き物ではないので、「窓が働きやすいように水分と空気を調節する」は意味が通らない。"}], "explanations": {"菌": "堆肥の中で有機物を分解して働く微生物を指し、「働きやすい」の主語になる。", "塩": "塩は微生物ではないので、「塩が働きやすい」とは言えない。", "鍋": "鍋は働く生き物ではないので、「鍋が働きやすいように水分と空気を調節する」は成り立たない。", "窓": "窓は働く生き物ではないので、「窓が働きやすいように水分と空気を調節する」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "菌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "シダは菌で増える。", "explanation": "ここは〈胞子〉の意味。シダは胞子で増えるので、菌で増えるとは言わない。"}, {"text": "子どもが菌を積み上げて遊んだ。", "explanation": "ここは菌を〈積み木〉のように重ねられる固い物として扱っている。菌は積み上げて遊ぶ物ではないので、ここでは合わない。"}, {"text": "試合で菌を蹴ってゴールを決めた。", "explanation": "ここは菌を〈ボール〉のように蹴って動かす物として扱っている。菌は蹴ってゴールに入れる物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36869, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ヨーグルトが酸っぱくなるのは、菌を乳糖を分解して酸を作るからだ。", "corrected_sentence": "ヨーグルトが酸っぱくなるのは、菌が乳糖を分解して酸を作るからだ。", "error_description": "「菌」は分解する主語なので「が」が正しい。「菌を」は目的語の形で、「乳糖を」と目的語が二つ重なり文が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36869, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ぬか漬けが酸っぱくなるのは、ぬか床の菌を野菜の糖を分解するからだ。", "corrected_sentence": "ぬか漬けが酸っぱくなるのは、ぬか床の菌が野菜の糖を分解するからだ。", "error_description": "分解する主語の「菌」には「が」を使う。「菌を」は目的語の形で、「野菜の糖を」と目的語が重なり文が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36871, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "硬い", "is_correct": true, "explanation": "押して形が変わりにくい性質を表し、軟らかいの対義語。"}, {"text": "大きい", "is_correct": false, "explanation": "大きさの形容で、やわらかさの対義語ではない。"}, {"text": "明るい", "is_correct": false, "explanation": "光や色の形容で、やわらかさの対義語ではない。"}, {"text": "速い", "is_correct": false, "explanation": "速さの形容で、やわらかさの対義語ではない。"}], "correct_answer": "硬い", "explanations": {"硬い": "押して形が変わりにくい性質を表し、軟らかいの対義語。", "大きい": "大きさの形容で、やわらかさの対義語ではない。", "明るい": "光や色の形容で、やわらかさの対義語ではない。", "速い": "速さの形容で、やわらかさの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36871, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "硬い", "is_correct": true, "explanation": "押して形が変わりにくい性質を表し、軟らかいの対義語。"}, {"text": "重い", "is_correct": false, "explanation": "重さの形容で、やわらかさの対義語ではない。"}, {"text": "白い", "is_correct": false, "explanation": "色の形容で、やわらかさの対義語ではない。"}, {"text": "長い", "is_correct": false, "explanation": "長さの形容で、やわらかさの対義語ではない。"}], "correct_answer": "硬い", "explanations": {"硬い": "押して形が変わりにくい性質を表し、軟らかいの対義語。", "重い": "重さの形容で、やわらかさの対義語ではない。", "白い": "色の形容で、やわらかさの対義語ではない。", "長い": "長さの形容で、やわらかさの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36871, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "指で押すと簡単に形が変わる様子。物理的に柔らかく、弾力があること。", "primary_collocate": null, "pronunciation": "やわらかい", "ipa": "jawaɾakai", "syllable_count": 5, "sentences": [{"text": "このパンは軟らかくて、指で押すとすぐへこむ。", "target_word": "軟らかくて", "complexity_tier": "T3", "furigana": "このパンは軟[やわ]らかくて、指[ゆび]で押[お]すとすぐへこむ。", "sentence_source": "generated"}, {"text": "軟らかいスポンジは、強く握ると小さくなる。", "target_word": "軟らかい", "complexity_tier": "T3", "furigana": "軟[やわ]らかいスポンジは、強[つよ]く握[にぎ]ると小[ちい]さくなる。", "sentence_source": "generated"}, {"text": "新しいマットレスは軟らかすぎて、朝起きると腰が痛くなった。", "target_word": "軟らかすぎて", "complexity_tier": "T3", "furigana": "新[あたら]しいマットレスは軟[やわ]らかすぎて、朝[あさ]起[お]きると腰[こし]が痛[いた]くなった。", "sentence_source": "generated"}, {"text": "赤ちゃんのほおは軟らかく、指で触ると少しへこむ。", "target_word": "軟らかく", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんのほおは軟[やわ]らかく、指[ゆび]で触[さわ]ると少[すこ]しへこむ。", "sentence_source": "generated"}, {"text": "このボールは軟らかいので、ぶつかってもあまり痛くない。", "target_word": "軟らかい", "complexity_tier": "T3", "furigana": "このボールは軟[やわ]らかいので、ぶつかってもあまり痛[いた]くない。", "sentence_source": "generated"}, {"text": "焼きたてのパンは軟らかく、手でちぎるのが簡単だ。", "target_word": "軟らかく", "complexity_tier": "T3", "furigana": "焼[や]きたてのパンは軟[やわ]らかく、手[て]でちぎるのが簡単[かんたん]だ。", "sentence_source": "generated"}, {"text": "軟らかい消しゴムはよく消えるけれど、すぐに減ってしまう。", "target_word": "軟らかい", "complexity_tier": "T3", "furigana": "軟[やわ]らかい消[け]しゴムはよく消[き]えるけれど、すぐに減[へ]ってしまう。", "sentence_source": "generated"}, {"text": "熟した桃は軟らかいので、袋に入れてそっと運んだ。", "target_word": "軟らかい", "complexity_tier": "T3", "furigana": "熟[じゅく]した桃[もも]は軟[やわ]らかいので、袋[ふくろ]に入[い]れてそっと運[はこ]んだ。", "sentence_source": "generated"}, {"text": "軟らかいクッションに座ると、体が沈んで楽になる。", "target_word": "軟らかい", "complexity_tier": "T3", "furigana": "軟[やわ]らかいクッションに座[すわ]ると、体[からだ]が沈[しず]んで楽[らく]になる。", "sentence_source": "generated"}, {"text": "この靴は底が軟らかいから、長く歩いても足が疲れにくい。", "target_word": "軟らかい", "complexity_tier": "T3", "furigana": "この靴[くつ]は底[そこ]が軟[やわ]らかいから、長[なが]く歩[ある]いても足[あし]が疲[つか]れにくい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "軟らかい", "label": "終止形"}, {"form": "軟らかく", "label": "連用形"}, {"form": "軟らかくない", "label": "否定形"}, {"form": "軟らかかった", "label": "過去形"}, {"form": "軟らかければ", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "押すと簡単に形が変わる、物理的な柔らかさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ff364e-4b2f-4e6b-b85e-ab8916606415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36871, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "軟らかくて", "is_correct": true, "explanation": "指で押すとへこむ性質を表し、「このパンは___、指で押すと」に入る。"}, {"text": "明るくて", "is_correct": false, "explanation": "色や光の形容で、押すとへこむ性質の説明にならない。"}, {"text": "速くて", "is_correct": false, "explanation": "速さの形容で、押すとへこむ性質の説明にならない。"}, {"text": "甘くて", "is_correct": false, "explanation": "味の形容で、押すとへこむ性質の説明にならない。"}], "explanations": {"軟らかくて": "指で押すとへこむ性質を表し、「このパンは___、指で押すと」に入る。", "明るくて": "色や光の形容で、押すとへこむ性質の説明にならない。", "速くて": "速さの形容で、押すとへこむ性質の説明にならない。", "甘くて": "味の形容で、押すとへこむ性質の説明にならない。"}, "sentence_index": 0, "correct_answer": "軟らかくて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この大理石の床は軟らかく、鏡のように光っている。", "explanation": "ここは〈滑らか〉の意味。表面がなめらかに光る様子は「滑らか」と言い、軟らかいとは言わない。"}, {"text": "このお風呂のお湯は軟らかく、入るとやけどしそうなほど熱い。", "explanation": "ここは〈熱い〉の意味。温度の高さは「熱い」と言い、軟らかいとは言わない。"}, {"text": "このガラス細工は軟らかく、少しぶつけただけで割れてしまった。", "explanation": "ここは〈脆い〉の意味。壊れやすい様子は「脆い」と言い、軟らかいとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36871, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "軟らかい", "is_correct": true, "explanation": "「___消しゴム」として、よく消えるけれど減るという性質を表す。"}, {"text": "明るい", "is_correct": false, "explanation": "色や光の形容で、消しゴムの性質の説明にならない。"}, {"text": "速い", "is_correct": false, "explanation": "速さの形容で、消しゴムの性質の説明にならない。"}, {"text": "甘い", "is_correct": false, "explanation": "味の形容で、消しゴムの性質の説明にならない。"}], "explanations": {"軟らかい": "「___消しゴム」として、よく消えるけれど減るという性質を表す。", "明るい": "色や光の形容で、消しゴムの性質の説明にならない。", "速い": "速さの形容で、消しゴムの性質の説明にならない。", "甘い": "味の形容で、消しゴムの性質の説明にならない。"}, "sentence_index": 6, "correct_answer": "軟らかい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この鉄の板は軟らかく、ハンマーで叩いても少しも形が変わらない。", "explanation": "ここは〈堅い〉の意味。変形しにくい硬さは「堅い」と言い、軟らかいとは言わない。"}, {"text": "彼は軟らかい意志で、一度決めた計画をすぐに投げ出した。", "explanation": "ここは〈軟弱〉の意味。意志の弱さは「軟弱」と言い、軟らかいとは言わない。"}, {"text": "この椅子は軟らかいので、何年使っても壊れない頑丈さがある。", "explanation": "ここは〈頑丈〉の意味。丈夫で壊れにくい様子は「頑丈」と言い、軟らかいとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36871, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この枕は軟らかいで、寝ると首が沈む。", "corrected_sentence": "この枕は軟らかくて、寝ると首が沈む。", "error_description": "「で」の前は連用形「軟らかくて」。「軟らかいで」は誤りで、「軟らかくて」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "軟らかい", "is_correct": true, "explanation": "「軟らかいスポンジ」と名詞を修飾する連体形で、正しい。"}, {"text": "軟らかく", "is_correct": false, "explanation": "連用形で、名詞を修飾できない。"}, {"text": "軟らかくて", "is_correct": false, "explanation": "て形で、名詞「スポンジ」を直接修飾できない。"}, {"text": "軟らかければ", "is_correct": false, "explanation": "仮定形で、名詞「スポンジ」を直接修飾できない。"}], "correct_form": "軟らかい", "base_form": "軟らかい", "form_label": "連体形", "sentence_index": 1, "explanations": {"軟らかい": "「軟らかいスポンジ」と名詞を修飾する連体形で、正しい。", "軟らかく": "連用形で、名詞を修飾できない。", "軟らかくて": "て形で、名詞「スポンジ」を直接修飾できない。", "軟らかければ": "仮定形で、名詞「スポンジ」を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36871, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "熟した柿は軟らかくので、皮をむくと指が沈んだ。", "corrected_sentence": "熟した柿は軟らかいので、皮をむくと指が沈んだ。", "error_description": "「ので」の前は終止形「軟らかい」。「軟らかく」は誤りで、「軟らかいので」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "軟らかい", "is_correct": true, "explanation": "「軟らかいので」と続く終止形で、正しい。"}, {"text": "軟らかすぎて", "is_correct": false, "explanation": "て形で、理由を表す「ので」の前には置けない。"}, {"text": "軟らかさ", "is_correct": false, "explanation": "名詞で、「軟らかさので」と活用形として続かない。"}, {"text": "軟らかかったら", "is_correct": false, "explanation": "仮定形で、理由を表す「ので」の前には置けない。"}], "correct_form": "軟らかい", "base_form": "軟らかい", "form_label": "終止形", "sentence_index": 7, "explanations": {"軟らかい": "「軟らかいので」と続く終止形で、正しい。", "軟らかすぎて": "て形で、理由を表す「ので」の前には置けない。", "軟らかさ": "名詞で、「軟らかさので」と活用形として続かない。", "軟らかかったら": "仮定形で、理由を表す「ので」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
