INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36872, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "生き物や食べ物にいいものを作るための、自然の材料でできたものです。", "primary_collocate": null, "pronunciation": "ゆうき", "ipa": "jɯːki", "syllable_count": 3, "sentences": [{"text": "この農園は、化学の肥料を使わず、有機の肥料だけで野菜を育てている。", "target_word": "有機", "complexity_tier": "T3", "furigana": "この農園[のうえん]は、化学[かがく]の肥料[ひりょう]を使[つか]わず、有機[ゆうき]の肥料[ひりょう]だけで野菜[やさい]を育[そだ]てている。", "sentence_source": "generated"}, {"text": "有機の野菜は形が不ぞろいだが、味が濃いと言われる。", "target_word": "有機", "complexity_tier": "T3", "furigana": "有機[ゆうき]の野菜[やさい]は形[かたち]が不[ふ]ぞろいだが、味[あじ]が濃[こ]いと言[い]われる。", "sentence_source": "generated"}, {"text": "この八百屋は、有機の野菜だけを売っている。", "target_word": "有機", "complexity_tier": "T3", "furigana": "この八百屋[やおや]は、有機[ゆうき]の野菜[やさい]だけを売[う]っている。", "sentence_source": "generated"}, {"text": "有機にこだわる店は、材料の産地をはっきり書いている。", "target_word": "有機", "complexity_tier": "T3", "furigana": "有機[ゆうき]にこだわる店[みせ]は、材料[ざいりょう]の産地[さんち]をはっきり書[か]いている。", "sentence_source": "generated"}, {"text": "子どもに食べさせるなら、有機の食べ物のほうが安心だ。", "target_word": "有機", "complexity_tier": "T3", "furigana": "子[こ]どもに食[た]べさせるなら、有機[ゆうき]の食[た]べ物[もの]のほうが安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "この店のコーヒーは有機なので、少し値段が高い。", "target_word": "有機", "complexity_tier": "T3", "furigana": "この店[みせ]のコーヒーは有機[ゆうき]なので、少[すこ]し値段[ねだん]が高[たか]い。", "sentence_source": "generated"}, {"text": "有機のお米は、ふつうのお米より育てるのに手間がかかる。", "target_word": "有機", "complexity_tier": "T3", "furigana": "有機[ゆうき]のお米[こめ]は、ふつうのお米[こめ]より育[そだ]てるのに手間[てま]がかかる。", "sentence_source": "generated"}, {"text": "土をよくするため、落ち葉で有機の肥料を作った。", "target_word": "有機", "complexity_tier": "T3", "furigana": "土[つち]をよくするため、落[お]ち葉[ば]で有機[ゆうき]の肥料[ひりょう]を作[つく]った。", "sentence_source": "generated"}, {"text": "有機の畑では、虫を取るのも手作業が多い。", "target_word": "有機", "complexity_tier": "T3", "furigana": "有機[ゆうき]の畑[はたけ]では、虫[むし]を取[と]るのも手作業[てさぎょう]が多[おお]い。", "sentence_source": "generated"}, {"text": "お土産に、有機の茶葉で作られたお茶を買った。", "target_word": "有機", "complexity_tier": "T3", "furigana": "お土産[みやげ]に、有機[ゆうき]の茶葉[ちゃば]で作[つく]られたお茶[おちゃ]を買[か]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "有機", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "化学の薬品を使わず、自然の材料で作られた（農産物・肥料など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: 不ぞろい (Zipf 1.4)']::text[], '4e61b9b9-2b71-463a-b7c3-934bb8c70858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36872, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有機", "is_correct": true, "explanation": "化学の薬品を使わず、自然の材料で作る肥料という文脈に合う。"}, {"text": "農薬", "is_correct": false, "explanation": "「農薬の肥料」は成り立たず、化学の薬品を使わない肥料という文脈に合わない。"}, {"text": "石油", "is_correct": false, "explanation": "石油は肥料の材料にならず、自然の材料ではないので文が通らない。"}, {"text": "機械", "is_correct": false, "explanation": "機械は肥料にならず、文脈に合わない。"}], "explanations": {"有機": "化学の薬品を使わず、自然の材料で作る肥料という文脈に合う。", "農薬": "「農薬の肥料」は成り立たず、化学の薬品を使わない肥料という文脈に合わない。", "石油": "石油は肥料の材料にならず、自然の材料ではないので文が通らない。", "機械": "機械は肥料にならず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "有機"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼らの関係は有機の結びつきで、互いに支え合っている。", "explanation": "ここは〈有機的〉（部分が互いにつながって全体をなす）の意味。有機は材料や農産物に使う語で、人間関係の結びつきには有機的を使う。"}, {"text": "この店は有機の契約で、農家から野菜を仕入れている。", "explanation": "ここは〈有期〉（期限つき）の意味。有機は材料の性質を表す語で、期限のある契約には有期を使う。"}, {"text": "彼は有機の立場で交渉を進めた。", "explanation": "有機は材料や農産物に使う語で、立場の強さには使わない。（有利は「ゆうり」で、同音ではない）"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36872, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有機", "is_correct": true, "explanation": "有機の米は手間がかかるという文脈の主語として合う。"}, {"text": "電気", "is_correct": false, "explanation": "「電気のお米」は存在せず、食べ物の文脈に合わない。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は食べ物ではなく、「鉄のお米」は文脈に合わない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は食べ物ではなく、「紙のお米」は文脈に合わない。"}], "explanations": {"有機": "有機の米は手間がかかるという文脈の主語として合う。", "電気": "「電気のお米」は存在せず、食べ物の文脈に合わない。", "鉄": "鉄は食べ物ではなく、「鉄のお米」は文脈に合わない。", "紙": "紙は食べ物ではなく、「紙のお米」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "有機"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏のボーナスで有機保険に入った。", "explanation": "ここは〈有期〉（期限つき）の保険の意味。正しくは有期保険で、有機は保険には使わない。"}, {"text": "店員さんが有機の声で話しかけてきた。", "explanation": "有機は材料の性質を表す語で、声の様子には使わない。"}, {"text": "台風の日、有機の供給が止まった。", "explanation": "有機は食べ物や材料に使う語で、供給される物には使わない。停電で止まるのは電気。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36872, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "有機で野菜は、土作りに時間がかかる。", "corrected_sentence": "有機の野菜は、土作りに時間がかかる。", "error_description": "誤りは「有機で」。「有機」は名詞なので、野菜につなぐには「の」が必要。「で」は手段・場所を表し、名詞を直接つなげない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36872, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "有機に肥料をまいたら、土がふかふかになった。", "corrected_sentence": "有機の肥料をまいたら、土がふかふかになった。", "error_description": "誤りは「有機に」の助詞。「有機」は名詞なので、「の」で肥料につなぐ必要がある。「に」では名詞同士の関係が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36874, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「勉強する」の対象を示す「を」。化学を勉強する、が自然。"}, {"text": "が", "is_correct": false, "explanation": "「化学が勉強して」では、勉強の対象を示せず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を表し、勉強の対象にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表し、ここでは勉強の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「勉強する」の対象を示す「を」。化学を勉強する、が自然。", "が": "「化学が勉強して」では、勉強の対象を示せず不自然。", "に": "「に」は方向や相手を表し、勉強の対象にはならない。", "で": "「で」は手段や場所を表し、ここでは勉強の対象を示せない。"}, "error_tags": {"が": "主語（対象のずれ）", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36874, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「得意だ」の対象を示す「が」。化学が得意だ、が自然。"}, {"text": "を", "is_correct": false, "explanation": "「化学を得意だ」は目的語を取る形になり、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表し、「得意だ」の対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「得意だ」の対象を示せない。"}], "correct_answer": "が", "explanations": {"が": "「得意だ」の対象を示す「が」。化学が得意だ、が自然。", "を": "「化学を得意だ」は目的語を取る形になり、不自然。", "と": "「と」は並列や相手を表し、「得意だ」の対象にはならない。", "へ": "「へ」は方向を表し、「得意だ」の対象を示せない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36874, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物質の成り立ちや性質・変化を、実験などによって調べる学問。", "primary_collocate": null, "pronunciation": "かがく", "ipa": "kaɡaku", "syllable_count": 3, "sentences": [{"text": "化学の授業で、水と塩を使った実験をした。", "target_word": "化学", "complexity_tier": "T3", "furigana": "化学[かがく]の授業[じゅぎょう]で、水[みず]と塩[しお]を使[つか]った実験[じっけん]をした。", "sentence_source": "generated"}, {"text": "姉は大学で化学を勉強して、薬を作る会社に入った。", "target_word": "化学", "complexity_tier": "T3", "furigana": "姉[あね]は大学[だいがく]で化学[かがく]を勉強[べんきょう]して、薬[くすり]を作[つく]る会社[かいしゃ]に入[はい]った。", "sentence_source": "generated"}, {"text": "化学が好きになったのは、色が変わる実験を見たからだ。", "target_word": "化学", "complexity_tier": "T3", "furigana": "化学[かがく]が好[す]きになったのは、色[いろ]が変[か]わる実験[じっけん]を見[み]たからだ。", "sentence_source": "generated"}, {"text": "化学の先生は、物の性質について分かりやすく説明してくれた。", "target_word": "化学", "complexity_tier": "T3", "furigana": "化学[かがく]の先生[せんせい]は、物[もの]の性質[せいしつ]について分[わ]かりやすく説明[せつめい]してくれた。", "sentence_source": "generated"}, {"text": "化学では、すべての物が小さな粒でできていると考える。", "target_word": "化学", "complexity_tier": "T3", "furigana": "化学[かがく]では、すべての物[もの]が小[ちい]さな粒[つぶ]でできていると考える。", "sentence_source": "generated"}, {"text": "洗剤を混ぜると危ない理由は、化学を学ぶと分かる。", "target_word": "化学", "complexity_tier": "T3", "furigana": "洗剤[せんざい]を混[ま]ぜると危[あぶ]ない理由[りゆう]は、化学[かがく]を学[まな]ぶと分[わ]かる。", "sentence_source": "generated"}, {"text": "化学の教科書には、元素の表がのっている。", "target_word": "化学", "complexity_tier": "T3", "furigana": "化学[かがく]の教科書[きょうかしょ]には、元素[げんそ]の表[ひょう]がのっている。", "sentence_source": "generated"}, {"text": "兄は化学が得意だが、歴史はあまり好きではない。", "target_word": "化学", "complexity_tier": "T3", "furigana": "兄[あに]は化学[かがく]が得意[とくい]だが、歴史[れきし]はあまり好[す]きではない。", "sentence_source": "generated"}, {"text": "薬品を使う化学の実験では、必ずめがねをかけてください。", "target_word": "化学", "complexity_tier": "T3", "furigana": "薬品[やくひん]を使[つか]う化学[かがく]の実験[じっけん]では、必[かなら]ずめがねをかけてください。", "sentence_source": "generated"}, {"text": "料理の味が変わる理由も、化学を使って説明できる。", "target_word": "化学", "complexity_tier": "T3", "furigana": "料理[りょうり]の味[あじ]が変[か]わる理由[りゆう]も、化学[かがく]を使[つか]って説明[せつめい]できる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "化学", "label": "基本形"}], "register": "中立", "sense_fingerprint": "物質の成り立ちや性質・変化を調べる学問（化学）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ff364e-4b2f-4e6b-b85e-ab8916606415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36874, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "化学", "is_correct": true, "explanation": "「化学の授業」で水と塩を使った実験をした、という文に合う。"}, {"text": "体育", "is_correct": false, "explanation": "体育の授業で水と塩を使った実験をすることはなく、文に合わない。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽の授業で水と塩を使った実験をすることはなく、文に合わない。"}, {"text": "書道", "is_correct": false, "explanation": "書道の授業で水と塩を使った実験をすることはなく、文に合わない。"}], "explanations": {"化学": "「化学の授業」で水と塩を使った実験をした、という文に合う。", "体育": "体育の授業で水と塩を使った実験をすることはなく、文に合わない。", "音楽": "音楽の授業で水と塩を使った実験をすることはなく、文に合わない。", "書道": "書道の授業で水と塩を使った実験をすることはなく、文に合わない。"}, "sentence_index": 0, "correct_answer": "化学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この化学は強い酸性なので、手袋をして扱う。", "explanation": "ここは〈薬品〉の意味。化学は学問の名前で、薬品のような物質そのものは指さないので合わない。"}, {"text": "このジュースは化学が果物だけでできている。", "explanation": "ここは〈成分〉の意味。化学は学問の名前なので、飲み物の中身（成分）には使わないので合わない。"}, {"text": "ボールが坂を転がる速さは、化学の公式で計算できる。", "explanation": "ここは〈物理〉の意味。ボールの運動の計算は物理で扱うもので、化学は物質の性質や変化を調べる学問なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36874, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "化学", "is_correct": true, "explanation": "元素の表がのっているのは化学の教科書なので、文に合う。"}, {"text": "国語", "is_correct": false, "explanation": "国語の教科書に元素の表が載ることは考えにくく、文に合わない。"}, {"text": "道徳", "is_correct": false, "explanation": "道徳の教科書に元素の表が載ることはなく、文に合わない。"}, {"text": "美術", "is_correct": false, "explanation": "美術の教科書に元素の表が載ることはなく、文に合わない。"}], "explanations": {"化学": "元素の表がのっているのは化学の教科書なので、文に合う。", "国語": "国語の教科書に元素の表が載ることは考えにくく、文に合わない。", "道徳": "道徳の教科書に元素の表が載ることはなく、文に合わない。", "美術": "美術の教科書に元素の表が載ることはなく、文に合わない。"}, "sentence_index": 6, "correct_answer": "化学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "化学は、これ以上分けられない基本の物質だ。", "explanation": "ここは〈元素〉の意味。化学は学問の名前で、基本の物質そのものは指さないので合わない。"}, {"text": "化学は、原子が集まってできた小さな粒だ。", "explanation": "ここは〈分子〉の意味。化学は物質を調べる学問で、小さな粒そのものは指さないので合わない。"}, {"text": "この職人は化学が確かで、どの器も同じ形に仕上がる。", "explanation": "ここは〈技術〉の意味。腕前や作り方を指す技術とは違い、化学は学問の名前なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36874, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉は大学で化学が勉強している。", "corrected_sentence": "姉は大学で化学を勉強している。", "error_description": "「化学を勉強している」が正しい。「勉強する」は対象に「を」を付けるので、「化学が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36874, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は化学を作っている。", "corrected_sentence": "兄は化学を教えている。", "error_description": "「化学を教えている」が正しい。「作る」は物や料理などを生み出す動詞で、学問の化学には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36876, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「植物は」と主題を示し、文の主語として自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「植物を」だと目的語になり、「水をたくさん必要とします」と続かず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「植物で」は手段や場所の意味になり、ここでは文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「植物へ」は方向を表すが、「必要とします」の主語にはならない。"}], "correct_answer": "は", "explanations": {"は": "正解。「植物は」と主題を示し、文の主語として自然につながる。", "を": "「植物を」だと目的語になり、「水をたくさん必要とします」と続かず不自然。", "で": "「植物で」は手段や場所の意味になり、ここでは文が成り立たない。", "へ": "「植物へ」は方向を表すが、「必要とします」の主語にはならない。"}, "error_tags": {"を": "object", "で": "means", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36876, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「植物の種」と修飾の「の」でつながり、自然。"}, {"text": "を", "is_correct": false, "explanation": "「植物を種」では目的語になり、名詞同士の関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「植物へ種」は方向を表すが、種を修飾する形にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「植物より種」は比較の意味になり、ここでは文が不自然。"}], "correct_answer": "の", "explanations": {"の": "正解。「植物の種」と修飾の「の」でつながり、自然。", "を": "「植物を種」では目的語になり、名詞同士の関係が成り立たない。", "へ": "「植物へ種」は方向を表すが、種を修飾する形にはならない。", "より": "「植物より種」は比較の意味になり、ここでは文が不自然。"}, "error_tags": {"を": "object", "へ": "direction", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36876, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生きているもののうち、自分で動かないもの。", "primary_collocate": null, "pronunciation": "しょくぶつ", "ipa": "ɕokɯbɯtsɯ", "syllable_count": 4, "sentences": [{"text": "庭にはいろいろな植物が育っています。", "target_word": "植物", "complexity_tier": "T3", "furigana": "庭[にわ]にはいろいろな植物[しょくぶつ]が育[そだ]っています。", "sentence_source": "generated"}, {"text": "この植物は水をたくさん必要とします。", "target_word": "植物", "complexity_tier": "T3", "furigana": "この植物[しょくぶつ]は水[みず]をたくさん必要[ひつよう]とします。", "sentence_source": "generated"}, {"text": "植物は光を受けて大きくなります。", "target_word": "植物", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]は光[ひかり]を受[う]けて大[おお]きくなります。", "sentence_source": "generated"}, {"text": "部屋に植物を置くと、気持ちが落ち着きます。", "target_word": "植物", "complexity_tier": "T3", "furigana": "部屋[へや]に植物[しょくぶつ]を置[お]くと、気持[きも]ちが落[お]ち着[つ]きます。", "sentence_source": "generated"}, {"text": "動物とちがって、植物は自分で歩いて移動できません。", "target_word": "植物", "complexity_tier": "T3", "furigana": "動物[どうぶつ]とちがって、植物[しょくぶつ]は自分[じぶん]で歩[ある]いて移動[いどう]できません。", "sentence_source": "generated"}, {"text": "山に登って、珍しい植物を写真に撮りました。", "target_word": "植物", "complexity_tier": "T3", "furigana": "山[やま]に登[のぼ]って、珍[めずら]しい植物[しょくぶつ]を写真[しゃしん]に撮[と]りました。", "sentence_source": "generated"}, {"text": "夏は暑いので、毎朝植物に水をやります。", "target_word": "植物", "complexity_tier": "T3", "furigana": "夏[なつ]は暑[あつ]いので、毎朝[まいあさ]植物[しょくぶつ]に水[みず]をやります。", "sentence_source": "generated"}, {"text": "植物の種を春にまいて、秋に花を見ました。", "target_word": "植物", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]の種[たね]を春[はる]にまいて、秋[あき]に花[はな]を見[み]ました。", "sentence_source": "generated"}, {"text": "理科の授業で、植物の葉のつくりを調べました。", "target_word": "植物", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、植物[しょくぶつ]の葉[は]のつくりを調[しら]べました。", "sentence_source": "generated"}, {"text": "冬は寒さに弱い植物を家の中に入れます。", "target_word": "植物", "complexity_tier": "T3", "furigana": "冬[ふゆ]は寒[さむ]さに弱[よわ]い植物[しょくぶつ]を家[いえ]の中[なか]に入[い]れます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "植物", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "plant: a living thing that does not move by itself, such as a tree, grass or flower", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ccc050-8e2e-4945-adb4-0419425842d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36876, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "植物", "is_correct": true, "explanation": "「育つ」は生きている植物に使える。庭で育つものとして自然で、正解。"}, {"text": "建物", "is_correct": false, "explanation": "建物は育つものではない。生き物ではないので「育っています」に合わない。"}, {"text": "乗り物", "is_correct": false, "explanation": "乗り物は成長するものではないので、「育っています」は不自然。"}, {"text": "荷物", "is_correct": false, "explanation": "荷物は育たない。「育つ」は生きものの成長に使う。"}], "explanations": {"植物": "「育つ」は生きている植物に使える。庭で育つものとして自然で、正解。", "建物": "建物は育つものではない。生き物ではないので「育っています」に合わない。", "乗り物": "乗り物は成長するものではないので、「育っています」は不自然。", "荷物": "荷物は育たない。「育つ」は生きものの成長に使う。"}, "sentence_index": 0, "correct_answer": "植物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕食のサラダに使うレタスを、スーパーで植物として買いました。", "explanation": "ここは〈野菜〉の意味。食材を指すときは野菜と言い、植物は生物の分類なので買い物の品名には合わない。"}, {"text": "夏の夜、庭の植物がうるさいほど鳴いています。", "explanation": "ここは〈虫〉の意味。植物は鳴かないので、鳴く生き物の話には植物は使えない。"}, {"text": "花瓶に一輪の植物を挿しました。", "explanation": "ここは〈花〉の意味。一輪は花を数える言い方で、植物を一輪と数えることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36876, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "植物", "is_correct": true, "explanation": "正解。毎朝水をやる対象は、水を必要とする植物。"}, {"text": "食器", "is_correct": false, "explanation": "食器に水をやることはない。水やりの対象ではない。"}, {"text": "家具", "is_correct": false, "explanation": "家具に水をやるとは言わない。水やりの対象にならない。"}, {"text": "布団", "is_correct": false, "explanation": "布団に水をやるのは不自然。水やりの対象ではない。"}], "explanations": {"植物": "正解。毎朝水をやる対象は、水を必要とする植物。", "食器": "食器に水をやることはない。水やりの対象ではない。", "家具": "家具に水をやるとは言わない。水やりの対象にならない。", "布団": "布団に水をやるのは不自然。水やりの対象ではない。"}, "sentence_index": 6, "correct_answer": "植物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもたちは、公園で植物と一緒に走り回りました。", "explanation": "ここは〈動物〉の意味。植物は自分で動かないので、一緒に走り回る生き物の話には合わない。"}, {"text": "夕方になると、家族の植物が私の帰りを待っていてくれます。", "explanation": "ここは〈家族〉の意味。植物は人ではないので、家族の代わりには使えない。"}, {"text": "ペットの植物と一緒に、毎晩散歩に出かけます。", "explanation": "ここは〈ペット〉（飼う動物）の意味。動かない植物は散歩に連れて行けないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36876, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎朝、植物を水を与えます。", "corrected_sentence": "毎朝、植物に水を与えます。", "error_description": "「与える」の相手は「に」で示す。「植物を」は誤りで、「植物に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36876, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の終わりに、植物を苗を庭に植えました。", "corrected_sentence": "夏の終わりに、植物の苗を庭に植えました。", "error_description": "「植物の苗」の「の」が正しい。「植物を苗」と書くと植物が目的語になり、意味が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
