INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36878, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "人やもののことを、傷つけない感じだ。", "primary_collocate": null, "pronunciation": "やさしい", "ipa": "jasaɕiː", "syllable_count": 4, "sentences": [{"text": "この石けんは赤ちゃんの肌に優しいので、毎日安心して使えます。", "target_word": "優しい", "complexity_tier": "T3", "furigana": "この石[せっ]けんは赤[あか]ちゃんの肌[はだ]に優[やさ]しいので、毎日[まいにち]安心[あんしん]して使[つか]えます。", "sentence_source": "generated"}, {"text": "環境に優しい紙のストローが、最近はいろいろな店で使われています。", "target_word": "優しい", "complexity_tier": "T3", "furigana": "環境[かんきょう]に優[やさ]しい紙[かみ]のストローが、最近[さいきん]はいろいろな店[みせ]で使[つか]われています。", "sentence_source": "generated"}, {"text": "胃が弱っているので、今日は体に優しいおかゆを食べました。", "target_word": "優しい", "complexity_tier": "T3", "furigana": "胃[い]が弱[よわ]っているので、今日[きょう]は体[からだ]に優[やさ]しいおかゆを食[た]べました。", "sentence_source": "generated"}, {"text": "目に優しいライトだから、夜に本を読んでも疲れません。", "target_word": "優しい", "complexity_tier": "T3", "furigana": "目[め]に優[やさ]しいライトだから、夜[よる]に本[ほん]を読[よ]んでも疲[つか]れません。", "sentence_source": "generated"}, {"text": "耳に優しい小さな音のピアノ曲で、子どもはすぐに眠りました。", "target_word": "優しい", "complexity_tier": "T3", "furigana": "耳[みみ]に優[やさ]しい小[ちい]さな音[おと]のピアノ曲[きょく]で、子[こ]どもはすぐに眠[ねむ]りました。", "sentence_source": "generated"}, {"text": "彼は割れやすい皿を優しく洗って、棚に戻した。", "target_word": "優しく", "complexity_tier": "T3", "furigana": "彼[かれ]は割[わ]れやすい皿[さら]を優[やさ]しく洗[あら]って、棚[たな]に戻[もど]した。", "sentence_source": "generated"}, {"text": "母は赤ちゃんを優しく抱いて、ゆっくり歩きました。", "target_word": "優しく", "complexity_tier": "T3", "furigana": "母[はは]は赤[あか]ちゃんを優[やさ]しく抱[だ]いて、ゆっくり歩[ある]きました。", "sentence_source": "generated"}, {"text": "このブラシは毛がやわらかく、髪に優しいので、切れ毛が減りました。", "target_word": "優しい", "complexity_tier": "T3", "furigana": "このブラシは毛[け]がやわらかく、髪[かみ]に優[やさ]しいので、切[き]れ毛[げ]が減[へ]りました。", "sentence_source": "generated"}, {"text": "優しい味のスープなので、病気の時でも飲みやすいです。", "target_word": "優しい", "complexity_tier": "T3", "furigana": "優[やさ]しい味[あじ]のスープなので、病気[びょうき]の時[とき]でも飲[の]みやすいです。", "sentence_source": "generated"}, {"text": "地球に優しい生活をしたいから、できるだけ電気を節約しています。", "target_word": "優しい", "complexity_tier": "T3", "furigana": "地球[ちきゅう]に優[やさ]しい生活[せいかつ]をしたいから、できるだけ電気[でんき]を節約[せつやく]しています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "優しい", "label": "終止形"}, {"form": "優しく", "label": "連用形"}, {"form": "優しかった", "label": "過去形"}, {"form": "優しくない", "label": "否定形"}, {"form": "優しければ", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "肌・体・環境などを傷つけない、刺激の少ないやわらかな感じ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1150120c-165e-4f2c-8c6f-3d4fb6877a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36878, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "優しい", "is_correct": true, "explanation": "「肌に優しい」の形で、刺激が少なく傷つけないという意味が通る。"}, {"text": "眠い", "is_correct": false, "explanation": "「肌に眠いので」は意味をなさない。眠い（ねむい）は眠気を表す。"}, {"text": "寂しい", "is_correct": false, "explanation": "「肌に寂しいので」は成立しない。寂しい（さびしい）は心の状態を表す。"}, {"text": "忙しい", "is_correct": false, "explanation": "「肌に忙しいので」は意味をなさない。忙しい（いそがしい）は時間に余裕がないことを表す。"}], "explanations": {"優しい": "「肌に優しい」の形で、刺激が少なく傷つけないという意味が通る。", "眠い": "「肌に眠いので」は意味をなさない。眠い（ねむい）は眠気を表す。", "寂しい": "「肌に寂しいので」は成立しない。寂しい（さびしい）は心の状態を表す。", "忙しい": "「肌に忙しいので」は意味をなさない。忙しい（いそがしい）は時間に余裕がないことを表す。"}, "sentence_index": 0, "correct_answer": "優しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱は持つと優しいので、子どもでも片手で運べる。", "explanation": "ここは〈軽い〉の意味。重さが少ないことは「軽い」で表し、「優しい」は人や物を傷つけない性質に使うので合わない。"}, {"text": "この鞄は優しいので、重い荷物を入れても壊れない。", "explanation": "ここは〈丈夫〉の意味。ものの頑丈さは「丈夫」で表すので、「優しい」は合わない。"}, {"text": "このホテルの部屋は優しくて、どこも埃がない。", "explanation": "ここは〈清潔〉の意味。埃がなく清らかな様子は「清潔」で表し、「優しい」は部屋の清潔さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36878, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "優しく", "is_correct": true, "explanation": "「優しく抱いて」は動作の仕方を表す連用形で、穏やかに抱く意味が通る。"}, {"text": "遅く", "is_correct": false, "explanation": "「遅く抱いて」は動作の時間を表し、赤ちゃんを抱く文脈に合わない。"}, {"text": "暗く", "is_correct": false, "explanation": "「暗く抱いて」は意味をなさない。暗い（くらい）は明るさを表す。"}, {"text": "遠く", "is_correct": false, "explanation": "「遠く抱いて」は距離を表し、抱くという動作と結びつかない。"}], "explanations": {"優しく": "「優しく抱いて」は動作の仕方を表す連用形で、穏やかに抱く意味が通る。", "遅く": "「遅く抱いて」は動作の時間を表し、赤ちゃんを抱く文脈に合わない。", "暗く": "「暗く抱いて」は意味をなさない。暗い（くらい）は明るさを表す。", "遠く": "「遠く抱いて」は距離を表し、抱くという動作と結びつかない。"}, "sentence_index": 6, "correct_answer": "優しく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この包丁は優しくて、どんな硬い肉もすぐ切れる。", "explanation": "ここは〈鋭い〉の意味。切れ味の鋭さは「鋭い」で表し、「優しい」は害を与えない性質に使うので合わない。"}, {"text": "この殺虫剤は優しくて、家の中の害虫をすぐ退治する。", "explanation": "ここは〈強力〉の意味。効き目の強さは「強力」で表し、「優しい」は害を与えない性質に使うので、害虫を退治する場面には合わない。"}, {"text": "この店の厨房は優しくて、床も調理台もいつもぴかぴかだ。", "explanation": "ここは〈清潔〉の意味。ぴかぴかで清らかな状態は「清潔」で表し、「優しい」は厨房の清潔さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36878, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この乳液は敏感な肌を優しいので、冬の乾燥した時期にぴったりです。", "corrected_sentence": "この乳液は敏感な肌に優しいので、冬の乾燥した時期にぴったりです。", "error_description": "「優しい」は「～に優しい」の形で助詞「に」をとる。「肌を優しい」の「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "優しい", "is_correct": true, "explanation": "「紙のストロー」を修飾する連体形で、文の形として正しい。"}, {"text": "優しく", "is_correct": false, "explanation": "連用形は名詞を直接修飾できず、「優しく紙のストロー」は成り立たない。"}, {"text": "優しくて", "is_correct": false, "explanation": "て形は名詞に直接続かず、「優しくて紙のストロー」は成り立たない。"}, {"text": "優しければ", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、「優しければ紙のストロー」は成り立たない。"}], "correct_form": "優しい", "base_form": "優しい", "form_label": "連体形", "sentence_index": 1, "explanations": {"優しい": "「紙のストロー」を修飾する連体形で、文の形として正しい。", "優しく": "連用形は名詞を直接修飾できず、「優しく紙のストロー」は成り立たない。", "優しくて": "て形は名詞に直接続かず、「優しくて紙のストロー」は成り立たない。", "優しければ": "仮定形は名詞を修飾できず、「優しければ紙のストロー」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36878, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このシャンプーは頭皮に優しいて、毎日使っても髪が傷みません。", "corrected_sentence": "このシャンプーは頭皮に優しくて、毎日使っても髪が傷みません。", "error_description": "形容詞のて形は「優しくて」（「く」が必要）。「優しいて」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "優しい", "is_correct": true, "explanation": "「髪に優しいので」の「ので」の前に置く終止形で、理由の文として正しい。"}, {"text": "優しさ", "is_correct": false, "explanation": "名詞形の「優しさ」は「ので」の前に置くと文が成り立たず、終止形ではない。"}, {"text": "優しそう", "is_correct": false, "explanation": "様態の「優しそう」は「ので」の前に直接続かず、「優しそうなので」のように「な」が必要になる。"}, {"text": "優しげ", "is_correct": false, "explanation": "形容動詞の語幹「優しげ」は「ので」の前に「な」を介する必要があり、そのままでは成り立たない。"}], "correct_form": "優しい", "base_form": "優しい", "form_label": "終止形", "sentence_index": 7, "explanations": {"優しい": "「髪に優しいので」の「ので」の前に置く終止形で、理由の文として正しい。", "優しさ": "名詞形の「優しさ」は「ので」の前に置くと文が成り立たず、終止形ではない。", "優しそう": "様態の「優しそう」は「ので」の前に直接続かず、「優しそうなので」のように「な」が必要になる。", "優しげ": "形容動詞の語幹「優しげ」は「ので」の前に「な」を介する必要があり、そのままでは成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36879, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "厳しい", "is_correct": true, "explanation": "人柄の「優しい」の対義語。厳格で甘さがない人柄を表し、この文脈の先生の性格と対になる。"}, {"text": "眠い", "is_correct": false, "explanation": "眠気を表す語で、人柄の対義語ではない。"}, {"text": "細かい", "is_correct": false, "explanation": "細部へのこだわりを表し、人柄の「優しい」とは対義にならない。"}, {"text": "重い", "is_correct": false, "explanation": "負担や責任の大きさを表し、人柄の対義語ではない。"}], "correct_answer": "厳しい", "explanations": {"厳しい": "人柄の「優しい」の対義語。厳格で甘さがない人柄を表し、この文脈の先生の性格と対になる。", "眠い": "眠気を表す語で、人柄の対義語ではない。", "細かい": "細部へのこだわりを表し、人柄の「優しい」とは対義にならない。", "重い": "負担や責任の大きさを表し、人柄の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36879, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "厳しい", "is_correct": true, "explanation": "人柄の「優しい」の対義語。厳格で甘さがない人柄を表し、対になる評価である。"}, {"text": "薄い", "is_correct": false, "explanation": "濃さや厚みを表し、人柄の対義語ではない。"}, {"text": "広い", "is_correct": false, "explanation": "空間や心の広さを表し、人柄の対義語にはならない。"}, {"text": "早い", "is_correct": false, "explanation": "速さや時期を表し、人柄の対義語ではない。"}], "correct_answer": "厳しい", "explanations": {"厳しい": "人柄の「優しい」の対義語。厳格で甘さがない人柄を表し、対になる評価である。", "薄い": "濃さや厚みを表し、人柄の対義語ではない。", "広い": "空間や心の広さを表し、人柄の対義語にはならない。", "早い": "速さや時期を表し、人柄の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36879, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "人や物に対して、穏やかで親切な様子。害を与えず、優しく接するさま。", "primary_collocate": null, "pronunciation": "やさしい", "ipa": "jasaɕiː", "syllable_count": 4, "sentences": [{"text": "田中さんは困っている人を見ると、いつも優しい声で話しかけます。", "target_word": "優しい", "complexity_tier": "T3", "furigana": "田中[たなか]さんは困[こま]っている人[ひと]を見[み]ると、いつも優[やさ]しい声[こえ]で話[はな]しかけます。", "sentence_source": "generated"}, {"text": "私の祖母は優しい人で、怒ったところを見たことがありません。", "target_word": "優しい", "complexity_tier": "T3", "furigana": "私[わたし]の祖母[そぼ]は優[やさ]しい人[ひと]で、怒[おこ]ったところを見[み]たことがありません。", "sentence_source": "generated"}, {"text": "新しい学校で不安だったが、隣の席の子が優しく教えてくれた。", "target_word": "優しく", "complexity_tier": "T3", "furigana": "新[あたら]しい学校[がっこう]で不安[ふあん]だったが、隣[となり]の席[せき]の子[こ]が優[やさ]しく教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "優しい先生のおかげで、クラスの雰囲気はいつも明るいです。", "target_word": "優しい", "complexity_tier": "T3", "furigana": "優[やさ]しい先生[せんせい]のおかげで、クラスの雰囲気[ふんいき]はいつも明[あか]るいです。", "sentence_source": "generated"}, {"text": "彼は優しいので、友だちの失敗を笑ったりしません。", "target_word": "優しい", "complexity_tier": "T3", "furigana": "彼[かれ]は優[やさ]しいので、友[とも]だちの失敗[しっぱい]を笑[わら]ったりしません。", "sentence_source": "generated"}, {"text": "泣いている妹に、姉は優しく声をかけました。", "target_word": "優しく", "complexity_tier": "T3", "furigana": "泣[な]いている妹[いもうと]に、姉[あね]は優[やさ]しく声[こえ]をかけました。", "sentence_source": "generated"}, {"text": "父は厳しいが、本当は優しい人だと私は知っています。", "target_word": "優しい", "complexity_tier": "T3", "furigana": "父[ちち]は厳[きび]しいが、本当[ほんとう]は優[やさ]しい人[ひと]だと私[わたし]は知[し]っています。", "sentence_source": "generated"}, {"text": "小さい頃は、近所の優しいおじさんがよくお菓子をくれた。", "target_word": "優しい", "complexity_tier": "T3", "furigana": "小[ちい]さい頃[ころ]は、近所[きんじょ]の優[やさ]しいおじさんがよくお菓子[かし]をくれた。", "sentence_source": "generated"}, {"text": "動物にも優しい彼女は、道で見つけた子犬を家に連れて帰った。", "target_word": "優しい", "complexity_tier": "T3", "furigana": "動物[どうぶつ]にも優[やさ]しい彼女[かのじょ]は、道[みち]で見[み]つけた子犬[こいぬ]を家[いえ]に連[つ]れて帰[かえ]った。", "sentence_source": "generated"}, {"text": "優しい言葉をかけてもらって、私は少し元気になりました。", "target_word": "優しい", "complexity_tier": "T3", "furigana": "優[やさ]しい言葉[ことば]をかけてもらって、私[わたし]は少[すこ]し元気[げんき]になりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "優しい", "label": "終止形"}, {"form": "優しく", "label": "連用形"}, {"form": "優しかった", "label": "過去形"}, {"form": "優しくない", "label": "否定形"}, {"form": "優しければ", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "人柄や態度が穏やかで親切なこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1150120c-165e-4f2c-8c6f-3d4fb6877a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36879, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "優しい", "is_correct": true, "explanation": "「優しい声」は穏やかで親切な話し方を表し、文脈に合う。"}, {"text": "赤い", "is_correct": false, "explanation": "「赤い声」は意味をなさない。赤い（あかい）は色を表す。"}, {"text": "暑い", "is_correct": false, "explanation": "「暑い声」は成立しない。暑い（あつい）は気温を表す。"}, {"text": "狭い", "is_correct": false, "explanation": "「狭い声」は意味をなさない。狭い（せまい）は空間の小ささを表す。"}], "explanations": {"優しい": "「優しい声」は穏やかで親切な話し方を表し、文脈に合う。", "赤い": "「赤い声」は意味をなさない。赤い（あかい）は色を表す。", "暑い": "「暑い声」は成立しない。暑い（あつい）は気温を表す。", "狭い": "「狭い声」は意味をなさない。狭い（せまい）は空間の小ささを表す。"}, "sentence_index": 0, "correct_answer": "優しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は皿洗いが優しくて、いつも一番早く終わる。", "explanation": "ここは〈手際がいい〉の意味。手早く仕事をこなす様子は「手際がいい」で表し、「優しい」は人柄や接し方に使うので合わない。"}, {"text": "彼女は仕事が優しくて、どんな難題もすぐ解決する。", "explanation": "ここは〈有能〉の意味。仕事の能力の高さは「有能」や「優秀」で表し、人柄の「優しい」は合わない。"}, {"text": "校長先生は規則に優しくて、遅刻を絶対に許さない。", "explanation": "ここは〈厳格〉の意味。規則を厳しく守らせる態度は「厳格」で表し、「優しい」は規則には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36879, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "優しい", "is_correct": true, "explanation": "「本当は優しい人」と対比の文脈に合う人柄の表現で、文が成り立つ。"}, {"text": "暑い", "is_correct": false, "explanation": "「本当は暑い人」は気温の意味になり、人柄の評価にならない。"}, {"text": "白い", "is_correct": false, "explanation": "「本当は白い人」は肌や色を表し、人柄の評価として意味が通らない。"}, {"text": "短い", "is_correct": false, "explanation": "「短い人」は性格の評価にならず、意味が通らない。"}], "explanations": {"優しい": "「本当は優しい人」と対比の文脈に合う人柄の表現で、文が成り立つ。", "暑い": "「本当は暑い人」は気温の意味になり、人柄の評価にならない。", "白い": "「本当は白い人」は肌や色を表し、人柄の評価として意味が通らない。", "短い": "「短い人」は性格の評価にならず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "優しい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は手先が優しくて、複雑な模型もすぐ組み立てる。", "explanation": "ここは〈器用〉の意味。手先の巧みさは「器用」で表し、「優しい」は人柄に使うので合わない。"}, {"text": "消防士は優しく炎の中へ飛び込んだ。", "explanation": "ここは〈勇敢〉の意味。危険を恐れない勇気は「勇敢」で表し、「優しく飛び込む」は意味がずれる。"}, {"text": "彼は優しく宿題を放り出して、ゲームばかりしていた。", "explanation": "ここは〈怠ける〉の意味。やる気なく投げ出す様子は「怠ける」で表し、「優しく」では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36879, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "あの先生は生徒に優しいて、質問を何度でも受けてくれる。", "corrected_sentence": "あの先生は生徒に優しくて、質問を何度でも受けてくれる。", "error_description": "形容詞のて形は「優しくて」。「優しいて」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "優しい", "is_correct": true, "explanation": "「優しい人」と名詞を修飾する連体形で、人柄の説明として正しい。"}, {"text": "優しく", "is_correct": false, "explanation": "連用形は名詞を直接修飾できず、「優しく人」は成り立たない。"}, {"text": "優しければ", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、「優しければ人」は成り立たない。"}, {"text": "優しくて", "is_correct": false, "explanation": "て形は名詞に続かず、「優しくて人」は成り立たない。"}], "correct_form": "優しい", "base_form": "優しい", "form_label": "連体形", "sentence_index": 1, "explanations": {"優しい": "「優しい人」と名詞を修飾する連体形で、人柄の説明として正しい。", "優しく": "連用形は名詞を直接修飾できず、「優しく人」は成り立たない。", "優しければ": "仮定形は名詞を修飾できず、「優しければ人」は成り立たない。", "優しくて": "て形は名詞に続かず、「優しくて人」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36879, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "森さんは困っている人を優しくて、いつも手を貸してくれる。", "corrected_sentence": "森さんは困っている人に優しくて、いつも手を貸してくれる。", "error_description": "「優しい」は「～に優しい」で相手を表す助詞「に」をとる。「人を優しくて」の「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "優しい", "is_correct": true, "explanation": "「近所のおじさん」を修飾する連体形で、文の形として正しい。"}, {"text": "優しさ", "is_correct": false, "explanation": "名詞形の「優しさ」は名詞「おじさん」を直接修飾できず、連体形ではない。"}, {"text": "優しそう", "is_correct": false, "explanation": "様態の「優しそう」は名詞に直接続かず、「優しそうなおじさん」のように「な」が必要になる。"}, {"text": "優しかろう", "is_correct": false, "explanation": "推量の「優しかろう」は名詞を直接修飾できず、「優しかろうおじさん」は成り立たない。"}], "correct_form": "優しい", "base_form": "優しい", "form_label": "連体形", "sentence_index": 7, "explanations": {"優しい": "「近所のおじさん」を修飾する連体形で、文の形として正しい。", "優しさ": "名詞形の「優しさ」は名詞「おじさん」を直接修飾できず、連体形ではない。", "優しそう": "様態の「優しそう」は名詞に直接続かず、「優しそうなおじさん」のように「な」が必要になる。", "優しかろう": "推量の「優しかろう」は名詞を直接修飾できず、「優しかろうおじさん」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36880, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「入れる」の場所を示す「に」。下の段が野菜を入れる場所になる。"}, {"text": "が", "is_correct": false, "explanation": "「段が野菜を入れた」では段が動作主になり、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「段を野菜を入れた」は段を目的語にしてしまい、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「段と野菜」は並列になり、入れる場所を示せない。"}], "correct_answer": "に", "explanations": {"に": "「入れる」の場所を示す「に」。下の段が野菜を入れる場所になる。", "が": "「段が野菜を入れた」では段が動作主になり、文が成り立たない。", "を": "「段を野菜を入れた」は段を目的語にしてしまい、不自然。", "と": "「段と野菜」は並列になり、入れる場所を示せない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36880, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36880, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "棚や階段などで、上下に重なった一つ一つの平らな区切り。その数を数える言葉でもある。", "primary_collocate": null, "pronunciation": "だん", "ipa": "daɴ", "syllable_count": 2, "sentences": [{"text": "この本棚は五段あって、上の段には辞書を置いている。", "target_word": "段", "complexity_tier": "T3", "furigana": "この本棚[ほんだな]は五段[ごだん]あって、上[うえ]の段[だん]には辞書[じしょ]を置[お]いている。", "sentence_source": "generated"}, {"text": "冷蔵庫の一番下の段に、野菜を入れた。", "target_word": "段", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]の一番下[いちばんした]の段[だん]に、野菜[やさい]を入[い]れた。", "sentence_source": "generated"}, {"text": "新しいコップは、棚の上から二つ目の段に並べた。", "target_word": "段", "complexity_tier": "T3", "furigana": "新[あたら]しいコップは、棚[たな]の上[うえ]から二[ふた]つ目[め]の段[だん]に並[なら]べた。", "sentence_source": "generated"}, {"text": "私は箱の一番上の段から、古い本を取り出した。", "target_word": "段", "complexity_tier": "T3", "furigana": "私[わたし]は箱[はこ]の一番上[いちばんうえ]の段[だん]から、古[ふる]い本[ほん]を取[と]り出[だ]した。", "sentence_source": "generated"}, {"text": "この棚の段には、まだ何も置いていない。", "target_word": "段", "complexity_tier": "T3", "furigana": "この棚[たな]の段[だん]には、まだ何[なに]も置[お]いていない。", "sentence_source": "generated"}, {"text": "上の段のお皿は小さく、下の段のお皿は大きい。", "target_word": "段", "complexity_tier": "T3", "furigana": "上[うえ]の段[だん]のお皿[さら]は小[ちい]さく、下[した]の段[だん]のお皿[さら]は大[おお]きい。", "sentence_source": "generated"}, {"text": "この棚は段の間が狭いので、大きい箱は入らない。", "target_word": "段", "complexity_tier": "T3", "furigana": "この棚[たな]は段[だん]の間[あいだ]が狭[せま]いので、大[おお]きい箱[はこ]は入[はい]らない。", "sentence_source": "generated"}, {"text": "田んぼが山の斜面に、何段も重なって見える。", "target_word": "段", "complexity_tier": "T3", "furigana": "田[た]んぼが山[やま]の斜面[しゃめん]に、何段[なんだん]も重[かさ]なって見[み]える。", "sentence_source": "generated"}, {"text": "棚の段を低くすると、子どもでも本が取りやすい。", "target_word": "段", "complexity_tier": "T3", "furigana": "棚[たな]の段[だん]を低[ひく]くすると、子[こ]どもでも本[ほん]が取[と]りやすい。", "sentence_source": "generated"}, {"text": "引き出しは三段あり、一番下の段に冬の服をしまっている。", "target_word": "段", "complexity_tier": "T3", "furigana": "引[ひ]き出[だ]しは三段[さんだん]あり、一番下[いちばんした]の段[だん]に冬[ふゆ]の服[ふく]をしまっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "基本形"}], "register": "中立", "sense_fingerprint": "棚などの上下に重なった一つ一つの平らな場所・その数え方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ff364e-4b2f-4e6b-b85e-ab8916606415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36880, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "段", "is_correct": true, "explanation": "本棚の上下に重なった一つ一つの区切りを指し、「上の段」に合う。"}, {"text": "足", "is_correct": false, "explanation": "「上の足」では、辞書を置く場所として意味が通らない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は本棚の区切りではなく、辞書を置く場所として不自然。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は本棚の一区切りとは言えず、文に合わない。"}], "explanations": {"段": "本棚の上下に重なった一つ一つの区切りを指し、「上の段」に合う。", "足": "「上の足」では、辞書を置く場所として意味が通らない。", "窓": "窓は本棚の区切りではなく、辞書を置く場所として不自然。", "鍵": "鍵は本棚の一区切りとは言えず、文に合わない。"}, "sentence_index": 0, "correct_answer": "段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この映画は三段見た。", "explanation": "ここは〈回数〉の意味。見た回数は「回」で数え、段は棚などの区切りを数える言葉なので合わない。"}, {"text": "この建物は五段まであって、上の段には会議室がある。", "explanation": "ここは〈階〉の意味。建物の階は「階」を使い、棚などの一区切りの「段」とは合わない。"}, {"text": "この部屋は三段暑い。", "explanation": "ここは〈度〉の意味。暑さの程度は「度」で数え、段は棚などの区切りを数える言葉なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36880, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "段", "is_correct": true, "explanation": "「段の間」は棚の区切りの間隔を指し、棚の話として合う。"}, {"text": "指", "is_correct": false, "explanation": "指の間が狭いという話では、棚に大きい箱が入らない理由にならない。"}, {"text": "傘", "is_correct": false, "explanation": "傘の間が狭いという話では、棚の大きさの説明にならない。"}, {"text": "耳", "is_correct": false, "explanation": "耳の間が狭いという話は、棚と箱の関係として成り立たない。"}], "explanations": {"段": "「段の間」は棚の区切りの間隔を指し、棚の話として合う。", "指": "指の間が狭いという話では、棚に大きい箱が入らない理由にならない。", "傘": "傘の間が狭いという話では、棚の大きさの説明にならない。", "耳": "耳の間が狭いという話は、棚と箱の関係として成り立たない。"}, "sentence_index": 6, "correct_answer": "段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水を三段飲んだ。", "explanation": "ここは〈杯〉の意味。飲み物の量は「杯」で数え、段は棚などの区切りを数える言葉なので合わない。"}, {"text": "この時代は、身分の段がはっきり分かれていた。", "explanation": "ここは〈階級〉の意味。身分の上下は「階級」で、棚などの一区切りの「段」とは合わない。"}, {"text": "料理の段を考えてから、台所に立つ。", "explanation": "ここは〈段取り〉の意味。手順の計画は「段取り」という熟語で、段だけでは手順の意味を持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36880, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "棚の段を本を置きました。", "corrected_sentence": "棚の段に本を置きました。", "error_description": "「段に置く」が正しい。「置く」の場所は「に」で示す。「段を」と言うと段を目的語にしてしまい、不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36880, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "棚の段を数えると、五人ある。", "corrected_sentence": "棚の段を数えると、五段ある。", "error_description": "「五段」が正しい。棚の段を数える助数詞は「段」。「人」は人を数える助数詞なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36881, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「置く」の場所を示す「に」。一番上の段が辞書の置き場所になる。"}, {"text": "と", "is_correct": false, "explanation": "「段と辞書を置きました」は並列になり、置き場所を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「段が辞書を置きました」では段が動作主になり、不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を表し、置く場所は示せない。"}], "correct_answer": "に", "explanations": {"に": "「置く」の場所を示す「に」。一番上の段が辞書の置き場所になる。", "と": "「段と辞書を置きました」は並列になり、置き場所を示せない。", "が": "「段が辞書を置きました」では段が動作主になり、不自然。", "より": "「より」は比較や起点を表し、置く場所は示せない。"}, "error_tags": {"と": "並列", "より": "比較・起点", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36881, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「二段になっている」の「に」。段の数で状態が決まることを表す。"}, {"text": "が", "is_correct": false, "explanation": "「二段がなっている」は主語と述語が成り立たず、不自然。"}, {"text": "を", "is_correct": false, "explanation": "「二段をなっている」は目的語を取れず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「二段でなっている」は手段や場所を表す「で」で、状態は表せない。"}], "correct_answer": "に", "explanations": {"に": "「二段になっている」の「に」。段の数で状態が決まることを表す。", "が": "「二段がなっている」は主語と述語が成り立たず、不自然。", "を": "「二段をなっている」は目的語を取れず、不自然。", "で": "「二段でなっている」は手段や場所を表す「で」で、状態は表せない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36881, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "棚・箱・ケーキなどの上下に重なった一つ一つの区切り。その数を数える単位でもある。", "primary_collocate": null, "pronunciation": "だん", "ipa": "daɴ", "syllable_count": 2, "sentences": [{"text": "この棚は三段あって、本がたくさん入ります。", "target_word": "段", "complexity_tier": "T3", "furigana": "この棚[たな]は三[さん]段[だん]あって、本[ほん]がたくさん入[はい]ります。", "sentence_source": "generated"}, {"text": "本棚の一番上の段に辞書を置きました。", "target_word": "段", "complexity_tier": "T3", "furigana": "本棚[ほんだな]の一番[いちばん]上[うえ]の段[だん]に辞書[じしょ]を置[お]きました。", "sentence_source": "generated"}, {"text": "弟の本棚は、上の段が空いています。", "target_word": "段", "complexity_tier": "T3", "furigana": "弟[おとうと]の本棚[ほんだな]は、上[うえ]の段[だん]が空[あ]いています。", "sentence_source": "generated"}, {"text": "ケーキを三段に重ねて、お祝いの席に出しました。", "target_word": "段", "complexity_tier": "T3", "furigana": "ケーキを三[さん]段[だん]に重[かさ]ねて、お祝[いわ]いの席[せき]に出[だ]しました。", "sentence_source": "generated"}, {"text": "箱の下の段には、冬の服が入っています。", "target_word": "段", "complexity_tier": "T3", "furigana": "箱[はこ]の下[した]の段[だん]には、冬[ふゆ]の服[ふく]が入[はい]っています。", "sentence_source": "generated"}, {"text": "一段ずつゆっくり上がって、やっと上に着きました。", "target_word": "段", "complexity_tier": "T3", "furigana": "一[いち]段[だん]ずつゆっくり上[あ]がって、やっと上[うえ]に着[つ]きました。", "sentence_source": "generated"}, {"text": "先生は、棚の上の段に今日の資料を置きました。", "target_word": "段", "complexity_tier": "T3", "furigana": "先生[せんせい]は、棚[たな]の上[うえ]の段[だん]に今日[きょう]の資料[しりょう]を置[お]きました。", "sentence_source": "generated"}, {"text": "このお弁当は二段になっていて、下の段にご飯が入っています。", "target_word": "段", "complexity_tier": "T3", "furigana": "このお弁当[べんとう]は二[に]段[だん]になっていて、下[した]の段[だん]にご飯[はん]が入[はい]っています。", "sentence_source": "generated"}, {"text": "冷蔵庫の一番下の段に、野菜を入れてください。", "target_word": "段", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]の一番[いちばん]下[した]の段[だん]に、野菜[やさい]を入[い]れてください。", "sentence_source": "generated"}, {"text": "本棚の上の段と下の段に、本を分けて入れました。", "target_word": "段", "complexity_tier": "T3", "furigana": "本棚[ほんだな]の上[うえ]の段[だん]と下[した]の段[だん]に、本[ほん]を分[わ]けて入[い]れました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "基本形"}, {"form": "段に", "label": "助詞つき形"}], "register": "丁寧", "sense_fingerprint": "棚・箱・ケーキなどの上下に重なった一つ一つの区切り。数える単位にもなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ff364e-4b2f-4e6b-b85e-ab8916606415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36881, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "段", "is_correct": true, "explanation": "棚の層の数を表す数え方で、「三段あって」に合う。"}, {"text": "人", "is_correct": false, "explanation": "棚の数を数えるのに人の助数詞は使えず、「三人あって」は文に合わない。"}, {"text": "匹", "is_correct": false, "explanation": "匹は動物を数える助数詞で、棚には合わない。"}, {"text": "冊", "is_correct": false, "explanation": "冊は本を数える助数詞で、棚の数には使えない。"}], "explanations": {"段": "棚の層の数を表す数え方で、「三段あって」に合う。", "人": "棚の数を数えるのに人の助数詞は使えず、「三人あって」は文に合わない。", "匹": "匹は動物を数える助数詞で、棚には合わない。", "冊": "冊は本を数える助数詞で、棚の数には使えない。"}, "sentence_index": 0, "correct_answer": "段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この歌は三段聞いた。", "explanation": "ここは〈回数〉の意味。聞いた回数は「回」で数え、段は棚などの区切りを数える言葉なので合わない。"}, {"text": "この計画は三つの段に分かれています。", "explanation": "ここは〈段階〉の意味。順を追った時期や過程は「段階」を使い、棚の区切りの「段」とは合わない。"}, {"text": "体育館には、生徒が三段いた。", "explanation": "ここは〈人〉を数える言葉の意味。人の数は「人」で数え、段は棚などの区切りを数える言葉なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36881, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "段", "is_correct": true, "explanation": "棚の上の区切りを指す段で、資料を置く場所として合う。"}, {"text": "声", "is_correct": false, "explanation": "棚の上の声に資料を置くのは意味が通らない。"}, {"text": "音", "is_correct": false, "explanation": "棚の上の音に資料を置くのは意味が通らない。"}, {"text": "雲", "is_correct": false, "explanation": "棚の上の雲に資料を置くのは意味が通らない。"}], "explanations": {"段": "棚の上の区切りを指す段で、資料を置く場所として合う。", "声": "棚の上の声に資料を置くのは意味が通らない。", "音": "棚の上の音に資料を置くのは意味が通らない。", "雲": "棚の上の雲に資料を置くのは意味が通らない。"}, "sentence_index": 6, "correct_answer": "段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この本棚は五階あって、上の階に辞書がある。", "explanation": "ここは〈階〉の意味。棚の上下の区切りは「段」で、「階」は建物の床の区切りなので合わない。"}, {"text": "この時代は、身分の段がはっきり分かれていた。", "explanation": "ここは〈階級〉の意味。身分の上下は「階級」で、棚の区切りの段とは合わない。"}, {"text": "料理の段を考えてから、台所に立つ。", "explanation": "ここは〈段取り〉の意味。手順の計画は「段取り」という熟語で、段だけでは手順の意味を持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36881, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "棚の上の段が本を置きました。", "corrected_sentence": "棚の上の段に本を置きました。", "error_description": "「段に」の「に」が正しい。「段が」だと段が主語になり、段が本を置くことになって不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36881, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上の段を本を取りました。", "corrected_sentence": "上の段から本を取りました。", "error_description": "「段から」が正しい。「から」は起点を示す。「段を」と言うと段を目的語にしてしまい、不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36882, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ボールを投げて」の『を』。投げる対象がボールなので、直後にこの助詞が入る。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語を示す。「ボールが投げて」はボールが投げる主体になり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は方向や対象を示す。「ボールに投げて」は投げる対象として不自然。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や共同を示す。「ボールと投げて」は動作の対象を表せず成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「ボールを投げて」の『を』。投げる対象がボールなので、直後にこの助詞が入る。", "が": "『が』は主語を示す。「ボールが投げて」はボールが投げる主体になり、文が成り立たない。", "に": "『に』は方向や対象を示す。「ボールに投げて」は投げる対象として不自然。", "と": "『と』は並列や共同を示す。「ボールと投げて」は動作の対象を表せず成り立たない。"}, "error_tags": {"が": "主語を示す", "に": "方向・対象を示す", "と": "並列を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36882, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「青いボールを三つ」の『を』。ボールを数える対象になるので、直後にこの助詞が入る。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示す。「青いボールで三つ、かごの中に入れた」は数える対象を表せない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示す。「青いボールより三つ」は比べる文脈がなく、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示す。「青いボールへ三つ」は数える対象として不自然で、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「青いボールを三つ」の『を』。ボールを数える対象になるので、直後にこの助詞が入る。", "で": "『で』は手段や場所を示す。「青いボールで三つ、かごの中に入れた」は数える対象を表せない。", "より": "『より』は比較を示す。「青いボールより三つ」は比べる文脈がなく、意味が通らない。", "へ": "『へ』は方向を示す。「青いボールへ三つ」は数える対象として不自然で、文が成り立たない。"}, "error_tags": {"で": "手段を示す", "より": "比較を示す", "へ": "方向を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36882, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "まるい たま。", "primary_collocate": null, "pronunciation": "ぼーる", "ipa": "boːɾɯ", "syllable_count": 3, "sentences": [{"text": "赤くて丸いボールが、坂をころころ転がっていった。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "赤[あか]くて丸[まる]いボールが、坂[さか]をころころ転[ころ]がっていった。", "sentence_source": "generated"}, {"text": "子どもが公園で、小さなボールを投げて遊んでいる。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "子[こ]どもが公園[こうえん]で、小[ちい]さなボールを投[な]げて遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "犬はゴムのボールが大好きで、毎日くわえて走る。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "犬[いぬ]はゴムのボールが大好[だいす]きで、毎日[まいにち]くわえて走[はし]る。", "sentence_source": "generated"}, {"text": "ボールに空気を入れると、丸くふくらんだ。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "ボールに空気[くうき]を入[い]れると、丸[まる]くふくらんだ。", "sentence_source": "generated"}, {"text": "棚の下に入ったボールを、長い棒で取り出した。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "棚[たな]の下[した]に入[はい]ったボールを、長[なが]い棒[ぼう]で取[と]り出[だ]した。", "sentence_source": "generated"}, {"text": "赤ちゃんは、やわらかいボールを手でさわって笑った。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは、やわらかいボールを手[て]でさわって笑[わら]った。", "sentence_source": "generated"}, {"text": "ボールが窓に当たって、ガラスが割れてしまった。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "ボールが窓[まど]に当[あ]たって、ガラスが割[わ]れてしまった。", "sentence_source": "generated"}, {"text": "青いボールを三つ、かごの中に入れた。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "青[あお]いボールを三[みっ]つ、かごの中[なか]に入[い]れた。", "sentence_source": "generated"}, {"text": "水の上に浮かぶボールが、風でゆっくり動いている。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "水[みず]の上[うえ]に浮[う]かぶボールが、風[かぜ]でゆっくり動[うご]いている。", "sentence_source": "generated"}, {"text": "猫は転がるボールを見つけて、すぐに追いかけた。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "猫[ねこ]は転[ころ]がるボールを見[み]つけて、すぐに追[お]いかけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ボール", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ゴムなどでできた丸い形のもの。転がしたり投げたりして遊ぶ丸いたま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: ふくらん (Zipf 2.47)']::text[], '304dfb6b-ca54-46db-b588-035b48c78535') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36882, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ボール", "is_correct": true, "explanation": "「赤くて丸いボールが坂を転がる」は自然で、この文の意味に合う。"}, {"text": "手紙", "is_correct": false, "explanation": "「赤くて丸い手紙が坂をころころ転がっていった」は不自然。手紙は転がって移動する物ではない。"}, {"text": "窓", "is_correct": false, "explanation": "「赤くて丸い窓が坂をころころ転がっていった」は成り立たない。窓は据え付けられた物で転がらない。"}, {"text": "駅", "is_correct": false, "explanation": "「赤くて丸い駅が坂をころころ転がっていった」は意味が通らない。駅は建物で、転がる物ではない。"}], "explanations": {"ボール": "「赤くて丸いボールが坂を転がる」は自然で、この文の意味に合う。", "手紙": "「赤くて丸い手紙が坂をころころ転がっていった」は不自然。手紙は転がって移動する物ではない。", "窓": "「赤くて丸い窓が坂をころころ転がっていった」は成り立たない。窓は据え付けられた物で転がらない。", "駅": "「赤くて丸い駅が坂をころころ転がっていった」は意味が通らない。駅は建物で、転がる物ではない。"}, "sentence_index": 0, "correct_answer": "ボール"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "選手たちは、試合のためにボールに集まった。", "explanation": "ここは〈球場〉の意味。ボールは球そのものを指すので、試合が行われる会場を表す場合は〈球場〉を使う。"}, {"text": "ボールに乗って、大空を旅した。", "explanation": "ここは〈気球〉の意味。ボールは遊びの球を指すので、人が乗る乗り物を表す場合は〈気球〉を使う。"}, {"text": "ボールで的を撃った。", "explanation": "ここは〈弾〉の意味。ボールは遊びの球を指すので、撃ち出す弾丸を表す場合は〈弾〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36882, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ボール", "is_correct": true, "explanation": "「ボールが窓に当たって、ガラスが割れた」は自然で、この文の意味に合う。"}, {"text": "花びら", "is_correct": false, "explanation": "「花びらが窓に当たって、ガラスが割れてしまった」は成り立たない。花びらは軽く、ガラスを割る力はない。"}, {"text": "綿毛", "is_correct": false, "explanation": "「綿毛が窓に当たって、ガラスが割れてしまった」は不自然。綿毛は軽く柔らかく、ガラスを割る力はない。"}, {"text": "霧", "is_correct": false, "explanation": "「霧が窓に当たって、ガラスが割れてしまった」は意味が通らない。霧は形がなく、ガラスを割る力はない。"}], "explanations": {"ボール": "「ボールが窓に当たって、ガラスが割れた」は自然で、この文の意味に合う。", "花びら": "「花びらが窓に当たって、ガラスが割れてしまった」は成り立たない。花びらは軽く、ガラスを割る力はない。", "綿毛": "「綿毛が窓に当たって、ガラスが割れてしまった」は不自然。綿毛は軽く柔らかく、ガラスを割る力はない。", "霧": "「霧が窓に当たって、ガラスが割れてしまった」は意味が通らない。霧は形がなく、ガラスを割る力はない。"}, "sentence_index": 6, "correct_answer": "ボール"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "猫はボールにくるまって、冬の夜を過ごした。", "explanation": "ここは〈ふとん〉の意味。ボールは遊びの球を指すので、体を包む寝具を表す場合は〈ふとん〉を使う。"}, {"text": "猫は、ボールを三つ倒した。", "explanation": "ここは〈ピン〉の意味。ボールは投げる球を指すので、倒される的を表す場合は〈ピン〉を使う。"}, {"text": "猫は驚いて、ボールを大きく見開いた。", "explanation": "ここは〈目玉〉の意味。ボールは遊び道具の球を指すので、目の玉を表す場合は〈目玉〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36882, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "犬がボールに追いかけて、庭を走った。", "corrected_sentence": "犬がボールを追いかけて、庭を走った。", "error_description": "「追いかける」は目的語に「を」を取る。「ボールに」は誤りで、正しくは「ボールを追いかけて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36882, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日、公園でボールを読んで遊んだ。", "corrected_sentence": "昨日、公園でボールを蹴って遊んだ。", "error_description": "「ボールを〜」は蹴る・投げるなど球を扱う動作と組む。「読んで」は組み合わせが誤りで、正しくは「蹴って」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36883, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ボールを使って練習」の『を』。使う対象がボールなので、直後にこの助詞が入る。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語を示す。「ボールが使って練習した」は能動の動詞と合わず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示す。「ボールへ使って練習」は使う対象を表せず成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐ。「ボールの使って練習」は動詞の目的語を示せず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「ボールを使って練習」の『を』。使う対象がボールなので、直後にこの助詞が入る。", "が": "『が』は主語を示す。「ボールが使って練習した」は能動の動詞と合わず不自然。", "へ": "『へ』は方向を示す。「ボールへ使って練習」は使う対象を表せず成り立たない。", "の": "『の』は名詞をつなぐ。「ボールの使って練習」は動詞の目的語を示せず、文が成り立たない。"}, "error_tags": {"が": "主語を示す", "へ": "方向を示す", "の": "連体修飾を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36883, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「サッカーのボールは、バレーのボールより」の『は』。ボールを主題として取り上げるので、直後にこの助詞が入る。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示す。「サッカーのボールで、バレーのボールより大きい」は文の主題を表せない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は方向や対象を示す。「サッカーのボールに、バレーのボールより大きい」は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示す。「サッカーのボールから、バレーのボールより大きい」は比較の文として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「サッカーのボールは、バレーのボールより」の『は』。ボールを主題として取り上げるので、直後にこの助詞が入る。", "で": "『で』は手段や場所を示す。「サッカーのボールで、バレーのボールより大きい」は文の主題を表せない。", "に": "『に』は方向や対象を示す。「サッカーのボールに、バレーのボールより大きい」は意味が通らない。", "から": "『から』は起点を示す。「サッカーのボールから、バレーのボールより大きい」は比較の文として成り立たない。"}, "error_tags": {"で": "手段を示す", "に": "方向・対象を示す", "から": "起点を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36883, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "球。また、それを使う遊びや競技の道具。", "primary_collocate": null, "pronunciation": "ぼーる", "ipa": "boːɾɯ", "syllable_count": 3, "sentences": [{"text": "彼はゴール前でボールを受けて、すばやくシュートした。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "彼[かれ]はゴール前[まえ]でボールを受[う]けて、すばやくシュートした。", "sentence_source": "generated"}, {"text": "試合の前に、みんなでボールを使って練習した。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "試合[しあい]の前[まえ]に、みんなでボールを使[つか]って練習[れんしゅう]した。", "sentence_source": "generated"}, {"text": "野球では、ピッチャーが投げたボールをバッターが打つ。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "野球[やきゅう]では、ピッチャーが投[な]げたボールをバッターが打[う]つ。", "sentence_source": "generated"}, {"text": "強い風のせいで、ボールがまっすぐ飛ばなかった。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]のせいで、ボールがまっすぐ飛[と]ばなかった。", "sentence_source": "generated"}, {"text": "体育の時間に、先生がバスケットのボールを配った。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "体育[たいいく]の時間[じかん]に、先生[せんせい]がバスケットのボールを配[くば]った。", "sentence_source": "generated"}, {"text": "彼女はボールから目をはなさずに、レシーブをした。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はボールから目[め]をはなさずに、レシーブをした。", "sentence_source": "generated"}, {"text": "試合中、ボールがコートの外に出て、審判が笛を吹いた。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "試合中[しあいちゅう]、ボールがコートの外[そと]に出[で]て、審判[しんぱん]が笛[ふえ]を吹[ふ]いた。", "sentence_source": "generated"}, {"text": "サッカーのボールは、バレーのボールより少し大きい。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "サッカーのボールは、バレーのボールより少[すこ]し大[おお]きい。", "sentence_source": "generated"}, {"text": "空気が足りなくて、ボールがよくはずまない。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "空気[くうき]が足[た]りなくて、ボールがよくはずまない。", "sentence_source": "generated"}, {"text": "部活の後、後輩がボールを倉庫にかたづけた。", "target_word": "ボール", "complexity_tier": "T3", "furigana": "部活[ぶかつ]の後[あと]、後輩[こうはい]がボールを倉庫[そうこ]にかたづけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ボール", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "サッカー・野球・バスケットなどの球技で使う競技用の球", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: はなさ (Zipf 2.22)','sentence 9 above tier T2: contains vocabulary far above tier T2: かたづけ (Zipf 2.38)']::text[], '304dfb6b-ca54-46db-b588-035b48c78535') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36883, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ボール", "is_correct": true, "explanation": "「ゴール前でボールを受けて」はサッカーなどで球を受ける意味で、この文に合う。"}, {"text": "眠気", "is_correct": false, "explanation": "「ゴール前で眠気を受けて」は意味が通らない。眠気は受け取る対象ではない。"}, {"text": "腕時計", "is_correct": false, "explanation": "「ゴール前で腕時計を受けて、シュートした」は文脈に合わず不自然。"}, {"text": "花粉", "is_correct": false, "explanation": "「ゴール前で花粉を受けて」は成り立たない。シュートの動作とも結びつかない。"}], "explanations": {"ボール": "「ゴール前でボールを受けて」はサッカーなどで球を受ける意味で、この文に合う。", "眠気": "「ゴール前で眠気を受けて」は意味が通らない。眠気は受け取る対象ではない。", "腕時計": "「ゴール前で腕時計を受けて、シュートした」は文脈に合わず不自然。", "花粉": "「ゴール前で花粉を受けて」は成り立たない。シュートの動作とも結びつかない。"}, "sentence_index": 0, "correct_answer": "ボール"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "アイスホッケーの選手が、氷上でボールを打った。", "explanation": "ここは〈パック〉の意味。アイスホッケーでは平たい円盤のパックを使うので、球のボールとは言わない。"}, {"text": "陸上の選手が、砲丸投げでボールを投げた。", "explanation": "ここは〈砲丸〉の意味。砲丸投げでは重い金属の球の砲丸を投げるので、ボールとは言わない。"}, {"text": "その棋士は、囲碁のボールを盤に置いた。", "explanation": "ここは〈石〉の意味。囲碁では石を盤に置くので、ボールとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36883, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ボール", "is_correct": true, "explanation": "「ボールがコートの外に出て」はボールが外へ出た場面を表し、この文に合う。"}, {"text": "天井", "is_correct": false, "explanation": "「天井がコートの外に出て」は成り立たない。天井は建物の部位で、コートの外に出る物ではない。"}, {"text": "照明", "is_correct": false, "explanation": "「照明がコートの外に出て」は文脈に合わず不自然。照明は設置された物で移動しない。"}, {"text": "窓ガラス", "is_correct": false, "explanation": "「窓ガラスがコートの外に出て」は意味が通らない。窓ガラスは建物の一部で、試合の場面には合わない。"}], "explanations": {"ボール": "「ボールがコートの外に出て」はボールが外へ出た場面を表し、この文に合う。", "天井": "「天井がコートの外に出て」は成り立たない。天井は建物の部位で、コートの外に出る物ではない。", "照明": "「照明がコートの外に出て」は文脈に合わず不自然。照明は設置された物で移動しない。", "窓ガラス": "「窓ガラスがコートの外に出て」は意味が通らない。窓ガラスは建物の一部で、試合の場面には合わない。"}, "sentence_index": 6, "correct_answer": "ボール"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "リレーの走者は、ボールを次の走者に渡した。", "explanation": "ここは〈バトン〉の意味。リレーでは棒状のバトンを次の走者に渡すので、ボールとは言わない。"}, {"text": "バドミントンの選手が、ボールを高く打ち上げた。", "explanation": "ここは〈シャトル〉の意味。バドミントンでは羽根のシャトルを使うので、ボールとは言わない。"}, {"text": "選手は、槍投げの練習でボールを遠くへ投げた。", "explanation": "ここは〈槍〉の意味。槍投げでは槍を投げるので、ボールとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36883, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "選手はゴールに向けてボールに蹴った。", "corrected_sentence": "選手はゴールに向けてボールを蹴った。", "error_description": "「蹴る」は目的語に「を」を取る。「ボールに」は誤りで、正しくは「ボールを蹴った」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36883, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨でボールが濡れされて、重くなった。", "corrected_sentence": "雨でボールが濡れて、重くなった。", "error_description": "「濡れる」は自動詞で、「〜される」の受身形は作れない。「濡れされて」は誤りで、正しくは「濡れて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36884, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「この箱におもちゃが入っている」で、入っている場所を示す「に」。"}, {"text": "が", "is_correct": false, "explanation": "「この箱がおもちゃが入っている」は、主語が二つ重なり不自然な文になる。"}, {"text": "を", "is_correct": false, "explanation": "「この箱をおもちゃが入っている」は、目的語として文の構造が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「箱からは」では、おもちゃが箱から出ていく意味になり、入っている状態と合わない。"}], "correct_answer": "に", "explanations": {"に": "「この箱におもちゃが入っている」で、入っている場所を示す「に」。", "が": "「この箱がおもちゃが入っている」は、主語が二つ重なり不自然な文になる。", "を": "「この箱をおもちゃが入っている」は、目的語として文の構造が成り立たない。", "から": "起点の「から」。「箱からは」では、おもちゃが箱から出ていく意味になり、入っている状態と合わない。"}, "error_tags": {"に": "位置", "が": "主語", "を": "目的語", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36884, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「箱の蓋」で、蓋が箱の部分であることを示す連体修飾の「の」。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」で、「箱へ蓋が閉まらない」は文の意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」で、「箱より蓋が閉まらない」は意味が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」で、「箱から蓋が閉まらない」は蓋の状態の説明にならない。"}], "correct_answer": "の", "explanations": {"の": "「箱の蓋」で、蓋が箱の部分であることを示す連体修飾の「の」。", "へ": "方向を示す「へ」で、「箱へ蓋が閉まらない」は文の意味が通らない。", "より": "比較を示す「より」で、「箱より蓋が閉まらない」は意味が成り立たない。", "から": "起点を示す「から」で、「箱から蓋が閉まらない」は蓋の状態の説明にならない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36884, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものを入れるための、四角い入れ物。", "primary_collocate": null, "pronunciation": "はこ", "ipa": "hako", "syllable_count": 2, "sentences": [{"text": "机の上に小さな箱が置いてあります。", "target_word": "箱", "complexity_tier": "T3", "furigana": "机(つくえ)の上(うえ)に小(ちい)さな箱(はこ)が置(お)いてあります。", "sentence_source": "generated"}, {"text": "この箱にはおもちゃがたくさん入っています。", "target_word": "箱", "complexity_tier": "T3", "furigana": "この箱(はこ)にはおもちゃがたくさん入(はい)っています。", "sentence_source": "generated"}, {"text": "箱を開けると、中に指輪が入っていました。", "target_word": "箱", "complexity_tier": "T3", "furigana": "箱(はこ)を開(あ)けると、中(なか)に指輪(ゆびわ)が入(はい)っていました。", "sentence_source": "generated"}, {"text": "引っ越しの前に、本を箱に詰めました。", "target_word": "箱", "complexity_tier": "T3", "furigana": "引(ひ)っ越(こ)しの前(まえ)に、本(ほん)を箱(はこ)に詰(つ)めました。", "sentence_source": "generated"}, {"text": "重い箱を一人で運ぶのは大変です。", "target_word": "箱", "complexity_tier": "T3", "furigana": "重(おも)い箱(はこ)を一人(ひとり)で運(はこ)ぶのは大変(たいへん)です。", "sentence_source": "generated"}, {"text": "誕生日に、赤い箱に入ったプレゼントをもらいました。", "target_word": "箱", "complexity_tier": "T3", "furigana": "誕生日(たんじょうび)に、赤(あか)い箱(はこ)に入(はい)ったプレゼントをもらいました。", "sentence_source": "generated"}, {"text": "空いた箱は、ごみの日に出してください。", "target_word": "箱", "complexity_tier": "T3", "furigana": "空(あ)いた箱(はこ)は、ごみの日(ひ)に出(だ)してください。", "sentence_source": "generated"}, {"text": "箱の蓋が閉まらないので、荷物を少し減らしました。", "target_word": "箱", "complexity_tier": "T3", "furigana": "箱(はこ)の蓋(ふた)が閉(し)まらないので、荷物(にもつ)を少(すこ)し減(へ)らしました。", "sentence_source": "generated"}, {"text": "友達にお菓子の箱を渡しました。", "target_word": "箱", "complexity_tier": "T3", "furigana": "友達(ともだち)にお菓子(かし)の箱(はこ)を渡(わた)しました。", "sentence_source": "generated"}, {"text": "猫が箱の中に入って、じっとしています。", "target_word": "箱", "complexity_tier": "T3", "furigana": "猫(ねこ)が箱(はこ)の中(なか)に入(はい)って、じっとしています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "箱", "label": "基本形"}], "register": "丁寧な日常語", "sense_fingerprint": "物を入れる四角い入れ物（容器としての箱）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e600720-6c23-4799-8dcf-cf155a991805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36884, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "箱", "is_correct": true, "explanation": "四角い入れ物で、机の上に置いてあるという文の主語として自然に入る。"}, {"text": "歌", "is_correct": false, "explanation": "耳で聞くもので、机の上に置いてあるものではないため、この文には合わない。"}, {"text": "雲", "is_correct": false, "explanation": "空にあるもので、机の上に置く物ではないので、この空欄には入らない。"}, {"text": "天気", "is_correct": false, "explanation": "状態を表す語で、机の上に置いてある物ではないため、文として成り立たない。"}], "explanations": {"箱": "四角い入れ物で、机の上に置いてあるという文の主語として自然に入る。", "歌": "耳で聞くもので、机の上に置いてあるものではないため、この文には合わない。", "雲": "空にあるもので、机の上に置く物ではないので、この空欄には入らない。", "天気": "状態を表す語で、机の上に置いてある物ではないため、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "箱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "魚を箱で切りました。", "explanation": "ここは〈まな板〉の意味。魚を切るのはまな板の上で、箱では切れないので誤り。"}, {"text": "プレゼントを、箱で包みました。", "explanation": "ここは〈包装紙〉の意味。プレゼントを包むのは包装紙で、箱では包まないので不自然。"}, {"text": "スープを箱でかき混ぜました。", "explanation": "ここは〈鍋〉の意味。スープをかき混ぜるのは鍋やおたまで、箱ではかき混ぜられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36884, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "箱", "is_correct": true, "explanation": "空になった入れ物を指し、ごみの日に出すという文の主語として自然に入る。"}, {"text": "星", "is_correct": false, "explanation": "夜空に見えるもので、ごみの日に出す物ではないため、この文には合わない。"}, {"text": "夢", "is_correct": false, "explanation": "抽象的なもので、ごみとして出す対象にはならず、文として成り立たない。"}, {"text": "旗", "is_correct": false, "explanation": "掲げるための布で、空いた状態になってごみとして出す物ではないので、この空欄には入らない。"}], "explanations": {"箱": "空になった入れ物を指し、ごみの日に出すという文の主語として自然に入る。", "星": "夜空に見えるもので、ごみの日に出す物ではないため、この文には合わない。", "夢": "抽象的なもので、ごみとして出す対象にはならず、文として成り立たない。", "旗": "掲げるための布で、空いた状態になってごみとして出す物ではないので、この空欄には入らない。"}, "sentence_index": 6, "correct_answer": "箱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ワイシャツを箱に吊るしました。", "explanation": "ここは〈ハンガー〉の意味。ワイシャツを吊るすのはハンガーで、箱には吊るせないので誤り。"}, {"text": "ごはんを箱で口に運びました。", "explanation": "ここは〈箸〉の意味。ごはんを口に運ぶのは箸で、箱では運べないので誤り。"}, {"text": "おにぎりを箱で握りました。", "explanation": "ここは〈手〉の意味。おにぎりは手で握るもので、箱を使って握ることはできないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36884, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "箱が、古いおもちゃを入れました。", "corrected_sentence": "箱に、古いおもちゃを入れました。", "error_description": "「入れる」の場所は「に」で示す。「が」にすると箱が主語になり、箱が入れたという意味になって不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36884, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "引っ越しの荷物は、箱で入れておきました。", "corrected_sentence": "引っ越しの荷物は、箱に入れておきました。", "error_description": "「入れる」の場所は「に」で示す。「で」にすると手段の意味になり、箱で入れるという不自然な文になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36885, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「箱に入っている」の「に」。入っている場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すので、「箱の中にある」という場所の関係にならない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、ここでは箱が主語になる文の形にならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示すため、「箱の」の後に「は」が続く文は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「箱に入っている」の「に」。入っている場所を示す。", "を": "「を」は動作の対象を示すので、「箱の中にある」という場所の関係にならない。", "が": "「が」は主語を示すが、ここでは箱が主語になる文の形にならない。", "の": "「の」は所属や修飾を示すため、「箱の」の後に「は」が続く文は成り立たない。"}, "error_tags": {"を": "対象を示す", "が": "主語を示す", "の": "所属・修飾を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36885, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「箱を積み上げる」の「を」。積み上げる対象を示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示すので、箱を積み上げる対象を表せない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、箱が積み上げる主体になってしまい、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示すので、積み上げる動作の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「箱を積み上げる」の「を」。積み上げる対象を示す。", "と": "「と」は並列や共同を示すので、箱を積み上げる対象を表せない。", "が": "「が」は主語を示すので、箱が積み上げる主体になってしまい、文が成り立たない。", "の": "「の」は所属や修飾を示すので、積み上げる動作の対象にはならない。"}, "error_tags": {"と": "並列を示す", "の": "所属・修飾を示す", "が": "主語を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36885, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物を入れておくための、主に四角い形をした入れ物。段ボールや木、プラスチックなどで作られます。", "primary_collocate": null, "pronunciation": "はこ", "ipa": "hako", "syllable_count": 2, "sentences": [{"text": "段ボールの箱に、冬の服をしまいました。", "target_word": "箱", "complexity_tier": "T3", "furigana": "段(だん)ボールの箱(はこ)に、冬(ふゆ)の服(ふく)をしまいました。", "sentence_source": "generated"}, {"text": "木の箱には、祖父の道具が入っています。", "target_word": "箱", "complexity_tier": "T3", "furigana": "木(き)の箱(はこ)には、祖父(そふ)の道具(どうぐ)が入(はい)っています。", "sentence_source": "generated"}, {"text": "プラスチックの箱は軽くて、洗うのも簡単です。", "target_word": "箱", "complexity_tier": "T3", "furigana": "プラスチックの箱(はこ)は軽(かる)くて、洗(あら)うのも簡単(かんたん)です。", "sentence_source": "generated"}, {"text": "届いた箱が大きかったので、玄関で開けました。", "target_word": "箱", "complexity_tier": "T3", "furigana": "届(とど)いた箱(はこ)が大(おお)きかったので、玄関(げんかん)で開(あ)けました。", "sentence_source": "generated"}, {"text": "箱の底が破れたため、新しい箱に入れ替えました。", "target_word": "箱", "complexity_tier": "T3", "furigana": "箱(はこ)の底(そこ)が破(やぶ)れたため、新(あたら)しい箱(はこ)に入(い)れ替(か)えました。", "sentence_source": "generated"}, {"text": "店員さんは、ケーキを白い箱に丁寧に入れてくれました。", "target_word": "箱", "complexity_tier": "T3", "furigana": "店員(てんいん)さんは、ケーキを白(しろ)い箱(はこ)に丁寧(ていねい)に入(い)れてくれました。", "sentence_source": "generated"}, {"text": "工具を箱に入れておけば、なくしません。", "target_word": "箱", "complexity_tier": "T3", "furigana": "工具(こうぐ)を箱(はこ)に入(い)れておけば、なくしません。", "sentence_source": "generated"}, {"text": "箱を積み上げすぎて、倒れてしまいました。", "target_word": "箱", "complexity_tier": "T3", "furigana": "箱(はこ)を積(つ)み上(あ)げすぎて、倒(たお)れてしまいました。", "sentence_source": "generated"}, {"text": "空の箱を二つ重ねて、棚の代わりに使っています。", "target_word": "箱", "complexity_tier": "T3", "furigana": "空(から)の箱(はこ)を二(ふた)つ重(かさ)ねて、棚(たな)の代(か)わりに使(つか)っています。", "sentence_source": "generated"}, {"text": "弟は大きな箱を机にして、絵を描きました。", "target_word": "箱", "complexity_tier": "T3", "furigana": "弟(おとうと)は大(おお)きな箱(はこ)を机(つくえ)にして、絵(え)を描(か)きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "箱", "label": "基本形"}], "register": "丁寧な日常語", "sense_fingerprint": "段ボール・木・プラスチック製の、物を保管・運搬する四角い入れ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e600720-6c23-4799-8dcf-cf155a991805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36885, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "箱", "is_correct": true, "explanation": "「段ボールの箱に冬の服をしまう」が成り立つ。空欄に入るのは入れ物の箱だけ。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵には服をしまえない。「段ボールの鍵に服をしまう」は意味が通らない。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は物を入れる器ではないので、服をしまう先にはならない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は服を収納する物ではなく、「時計に服をしまう」は成り立たない。"}], "explanations": {"箱": "「段ボールの箱に冬の服をしまう」が成り立つ。空欄に入るのは入れ物の箱だけ。", "鍵": "鍵には服をしまえない。「段ボールの鍵に服をしまう」は意味が通らない。", "椅子": "椅子は物を入れる器ではないので、服をしまう先にはならない。", "時計": "時計は服を収納する物ではなく、「時計に服をしまう」は成り立たない。"}, "sentence_index": 0, "correct_answer": "箱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "麺を箱に上げて、水で締めた。", "explanation": "ここは〈ざる〉の意味。湯切りして水で締めるのはざるで、箱では水が切れないので合わない。"}, {"text": "スープを箱によそって、温かいうちに食べた。", "explanation": "ここは〈器〉の意味。スープをよそうには器が要り、箱では液体を盛れない。"}, {"text": "水を箱で沸かして、お茶をいれた。", "explanation": "ここは〈やかん〉の意味。湯を沸かすのはやかんで、箱は火にかけられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36885, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "箱", "is_correct": true, "explanation": "「工具を箱に入れておけば、なくしません」が自然。空欄に入るのは入れ物の箱だけ。"}, {"text": "写真", "is_correct": false, "explanation": "写真の中に工具は入れられないので、「工具を写真に入れる」は成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は物を収納する容器ではないので、工具を入れる先にならない。"}, {"text": "花", "is_correct": false, "explanation": "花に工具を入れるという行為は不自然で、文脈に合わない。"}], "explanations": {"箱": "「工具を箱に入れておけば、なくしません」が自然。空欄に入るのは入れ物の箱だけ。", "写真": "写真の中に工具は入れられないので、「工具を写真に入れる」は成り立たない。", "窓": "窓は物を収納する容器ではないので、工具を入れる先にならない。", "花": "花に工具を入れるという行為は不自然で、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "箱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "カレーを箱で煮込んで、家族に出した。", "explanation": "ここは〈鍋〉の意味。煮込むには鍋が必要で、箱は火にかけられないので合わない。"}, {"text": "井戸の水を箱で汲み上げて、畑にまいた。", "explanation": "ここは〈桶〉の意味。水を汲むのは桶で、箱では水を汲み上げられない。"}, {"text": "牛乳を箱に注いで、ゆっくり飲んだ。", "explanation": "ここは〈コップ〉の意味。飲み物を注ぐ器として箱は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36885, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い箱を、夏の帽子をしまいました。", "corrected_sentence": "古い箱に、夏の帽子をしまいました。", "error_description": "「しまう」の場所を表す箱には「に」を使うべきところを、対象を示す「を」にしている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36885, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "箱を三枚積み上げて、ベランダに置きました。", "corrected_sentence": "箱を三つ積み上げて、ベランダに置きました。", "error_description": "箱を数えるには「つ」を使うのが自然で、「枚」は紙や板など薄い物に使う助数詞なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36886, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「〜でいっぱい」の「で」。落ち葉で満ちた状態を表す。"}, {"text": "を", "is_correct": false, "explanation": "「落ち葉をいっぱいになる」は目的語を取れず、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「落ち葉にいっぱい」は場所を表す「に」だが、「いっぱいになる」とはつながらない。"}, {"text": "と", "is_correct": false, "explanation": "「落ち葉といっぱい」は並列のように見え、状態を表せない。"}], "correct_answer": "で", "explanations": {"で": "「〜でいっぱい」の「で」。落ち葉で満ちた状態を表す。", "を": "「落ち葉をいっぱいになる」は目的語を取れず、不自然。", "に": "「落ち葉にいっぱい」は場所を表す「に」だが、「いっぱいになる」とはつながらない。", "と": "「落ち葉といっぱい」は並列のように見え、状態を表せない。"}, "error_tags": {"を": "目的語", "に": "場所・方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36886, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「落ち葉が流れてきて」の主語を示す「が」。"}, {"text": "で", "is_correct": false, "explanation": "「落ち葉で流れてきて」は手段や場所を表し、主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、流れてくる主体を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐだけで、動詞の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「落ち葉が流れてきて」の主語を示す「が」。", "で": "「落ち葉で流れてきて」は手段や場所を表し、主語にはならない。", "へ": "「へ」は方向を表し、流れてくる主体を示せない。", "の": "「の」は名詞をつなぐだけで、動詞の主語にはならない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36886, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "木から落ちた葉っぱのことです。", "primary_collocate": null, "pronunciation": "おちば", "ipa": "otɕiba", "syllable_count": 3, "sentences": [{"text": "公園の道に、落ち葉がたくさん積もっています。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "公園[こうえん]の道[みち]に、落[お]ち葉[ば]がたくさん積[つ]もっています。", "sentence_source": "generated"}, {"text": "風が強かったので、庭が落ち葉でいっぱいになりました。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]かったので、庭[にわ]が落[お]ち葉[ば]でいっぱいになりました。", "sentence_source": "generated"}, {"text": "朝早く起きて、家の前の落ち葉を掃きました。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "朝[あさ]早[はや]く起[お]きて、家[いえ]の前[まえ]の落[お]ち葉[ば]を掃[は]きました。", "sentence_source": "generated"}, {"text": "子どもたちは落ち葉を集めて、山を作って遊びました。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "子[こ]どもたちは落[お]ち葉[ば]を集[あつ]めて、山[やま]を作[つく]って遊[あそ]びました。", "sentence_source": "generated"}, {"text": "落ち葉の上を歩くと、かさかさと音がします。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "落[お]ち葉[ば]の上[うえ]を歩[ある]くと、かさかさと音[おと]がします。", "sentence_source": "generated"}, {"text": "雨が降ったあとは、落ち葉が道にはりついて滑りやすいです。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ったあとは、落[お]ち葉[ば]が道[みち]にはりついて滑[すべ]りやすいです。", "sentence_source": "generated"}, {"text": "母は落ち葉をほうきで集めて、ごみ袋に入れました。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "母[はは]は落[お]ち葉[ば]をほうきで集[あつ]めて、ごみ袋[ぶくろ]に入[い]れました。", "sentence_source": "generated"}, {"text": "川に落ち葉が流れてきて、水が少し黄色く見えました。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "川[かわ]に落[お]ち葉[ば]が流[なが]れてきて、水[みず]が少[すこ]し黄色[きいろ]く見[み]えました。", "sentence_source": "generated"}, {"text": "犬は落ち葉の中を走って、うれしそうでした。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "犬[いぬ]は落[お]ち葉[ば]の中[なか]を走[はし]って、うれしそうでした。", "sentence_source": "generated"}, {"text": "私は赤い落ち葉を一枚拾って、本にはさみました。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "私[わたし]は赤[あか]い落[お]ち葉[ば]を一[いち]枚[まい]拾[ひろ]って、本[ほん]にはさみました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "落ち葉", "label": "基本形"}, {"form": "落葉", "label": "別表記"}], "register": "丁寧", "sense_fingerprint": "木から落ちて道や庭にある葉。掃いたり集めたり拾ったりするもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ff364e-4b2f-4e6b-b85e-ab8916606415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36886, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "落ち葉", "is_correct": true, "explanation": "公園の道にたくさん積もるのは落ち葉なので、文に合う。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子が道にたくさん積もることはなく、文に合わない。"}, {"text": "皿", "is_correct": false, "explanation": "皿が道にたくさん積もることはなく、文に合わない。"}, {"text": "傘", "is_correct": false, "explanation": "傘が道にたくさん積もることはなく、文に合わない。"}], "explanations": {"落ち葉": "公園の道にたくさん積もるのは落ち葉なので、文に合う。", "椅子": "椅子が道にたくさん積もることはなく、文に合わない。", "皿": "皿が道にたくさん積もることはなく、文に合わない。", "傘": "傘が道にたくさん積もることはなく、文に合わない。"}, "sentence_index": 0, "correct_answer": "落ち葉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "まだ枝についている落ち葉は、茶色く枯れている。", "explanation": "ここは〈枯れ葉〉の意味。落ち葉は木から落ちた葉なので、枝についたまま枯れている葉には使わない。"}, {"text": "落ち葉は、春になると新しく芽吹く。", "explanation": "ここは〈木の葉〉の意味。枝についたままの葉を指す言葉で、地面に落ちた落ち葉は芽吹かないので合わない。"}, {"text": "落ち葉は、枝について赤く熟す。", "explanation": "ここは〈木の実〉の意味。落ち葉は枝を離れた葉で、実が熟す話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36886, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "落ち葉", "is_correct": true, "explanation": "母が集めて袋に入れるのは落ち葉なので、文に合う。"}, {"text": "洗濯機", "is_correct": false, "explanation": "洗濯機をほうきで集めて袋に入れるのは不自然で、文に合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫をほうきで集めて袋に入れるのは不自然で、文に合わない。"}, {"text": "窓", "is_correct": false, "explanation": "窓をほうきで集めて袋に入れることはなく、文に合わない。"}], "explanations": {"落ち葉": "母が集めて袋に入れるのは落ち葉なので、文に合う。", "洗濯機": "洗濯機をほうきで集めて袋に入れるのは不自然で、文に合わない。", "冷蔵庫": "冷蔵庫をほうきで集めて袋に入れるのは不自然で、文に合わない。", "窓": "窓をほうきで集めて袋に入れることはなく、文に合わない。"}, "sentence_index": 6, "correct_answer": "落ち葉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "落ち葉は、春になると枝の先で一斉に開く。", "explanation": "ここは〈花びら〉の意味。枝の先で開くのは花で、地面に落ちた落ち葉は開かないので合わない。"}, {"text": "落ち葉は、秋になると木の上で色を変える。", "explanation": "ここは〈紅葉〉の意味。木の上で色づくのは紅葉で、落ち葉は地面に落ちたものなので木の上で色を変えることはない。"}, {"text": "落ち葉は、春の日差しを浴びてぐんぐん大きくなる。", "explanation": "ここは〈若葉〉の意味。春に芽吹いて育つのは若葉で、落ち葉は枝を離れているのでもう育つことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36886, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "道に落ち葉を積もった。", "corrected_sentence": "道に落ち葉が積もった。", "error_description": "「落ち葉が積もった」が正しい。「積もる」は主語に「が」を取るので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36886, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "落ち葉を磨いて、袋に入れた。", "corrected_sentence": "落ち葉を掃いて、袋に入れた。", "error_description": "「掃いて」が正しい。「掃く」は地面の落ち葉を集める動作。「磨く」は床や窓などの表面をみがく動作なので、落ち葉には使わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36887, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「落ち葉の季節」と名詞どうしをつなぐ「の」。正解。"}, {"text": "が", "is_correct": false, "explanation": "「落ち葉が季節は」では主語の関係が成り立たず、名詞をつなぐ働きにならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は「季節へ」の形で名詞をつなげず、文の流れに合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は名詞の間に入らず、「季節は」と続く文の形に合わない。"}], "correct_answer": "の", "explanations": {"の": "「落ち葉の季節」と名詞どうしをつなぐ「の」。正解。", "が": "「落ち葉が季節は」では主語の関係が成り立たず、名詞をつなぐ働きにならない。", "へ": "方向を示す「へ」は「季節へ」の形で名詞をつなげず、文の流れに合わない。", "から": "起点を示す「から」は名詞の間に入らず、「季節は」と続く文の形に合わない。"}, "error_tags": {"が": "主語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36887, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「踏む」の対象を示す「を」。落ち葉を踏むという動作に合う。正解。"}, {"text": "に", "is_correct": false, "explanation": "「落ち葉に踏む」では対象が示せず、動詞「踏む」とつながらない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」では「踏む」の対象にならず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」は「踏む」の対象にならず、文の流れに合わない。"}], "correct_answer": "を", "explanations": {"を": "「踏む」の対象を示す「を」。落ち葉を踏むという動作に合う。正解。", "に": "「落ち葉に踏む」では対象が示せず、動詞「踏む」とつながらない。", "で": "場所や手段を示す「で」では「踏む」の対象にならず、文が成り立たない。", "より": "比較を示す「より」は「踏む」の対象にならず、文の流れに合わない。"}, "error_tags": {"に": "相手・位置", "で": "手段・場所", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36887, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "木から地面に落ちた葉。秋に多く見られる。", "primary_collocate": null, "pronunciation": "おちば", "ipa": "otɕiba", "syllable_count": 3, "sentences": [{"text": "秋になると、学校の校庭は落ち葉でいっぱいになります。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "秋[あき]になると、学校[がっこう]の校庭[こうてい]は落[お]ち葉[ば]でいっぱいになります。", "sentence_source": "generated"}, {"text": "落ち葉の季節は、毎週土曜日に近所の人と掃除をします。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "落[お]ち葉[ば]の季節[きせつ]は、毎週[まいしゅう]土曜日[どようび]に近所[きんじょ]の人[ひと]と掃除[そうじ]をします。", "sentence_source": "generated"}, {"text": "木の下に落ち葉が積もって、地面が見えなくなりました。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "木[き]の下[した]に落[お]ち葉[ば]が積[つ]もって、地面[じめん]が見[み]えなくなりました。", "sentence_source": "generated"}, {"text": "冬が近づくと、道ばたの落ち葉も少なくなります。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "冬[ふゆ]が近[ちか]づくと、道[みち]ばたの落[お]ち葉[ば]も少[すく]なくなります。", "sentence_source": "generated"}, {"text": "落ち葉を焼く煙のにおいが、秋の夕方の町に広がりました。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "落[お]ち葉[ば]を焼[や]く煙[けむり]のにおいが、秋[あき]の夕方[ゆうがた]の町[まち]に広[ひろ]がりました。", "sentence_source": "generated"}, {"text": "祖父は落ち葉を集めて、畑の土に混ぜています。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "祖父[そふ]は落[お]ち葉[ば]を集[あつ]めて、畑[はたけ]の土[つち]に混[ま]ぜています。", "sentence_source": "generated"}, {"text": "山の道は落ち葉が厚く積もっていて、歩きにくかったです。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "山[やま]の道[みち]は落[お]ち葉[ば]が厚[あつ]く積[つ]もっていて、歩[ある]きにくかったです。", "sentence_source": "generated"}, {"text": "秋の公園では、落ち葉を踏むたびに、かさかさと音がしました。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "秋[あき]の公園[こうえん]では、落[お]ち葉[ば]を踏[ふ]むたびに、かさかさと音[おと]がしました。", "sentence_source": "generated"}, {"text": "駅前の道は、毎朝掃除をしても、すぐに落ち葉が増えてしまいます。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の道[みち]は、毎朝[まいあさ]掃除[そうじ]をしても、すぐに落[お]ち葉[ば]が増[ふ]えてしまいます。", "sentence_source": "generated"}, {"text": "先生は、落ち葉の形を比べる宿題を出しました。", "target_word": "落ち葉", "complexity_tier": "T3", "furigana": "先生[せんせい]は、落[お]ち葉[ば]の形[かたち]を比[くら]べる宿題[しゅくだい]を出[だ]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "落ち葉", "label": "基本形"}, {"form": "落葉", "label": "別表記"}], "register": "丁寧", "sense_fingerprint": "秋に木から地面に落ちて積もる葉。季節の風景として見られるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ff364e-4b2f-4e6b-b85e-ab8916606415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36887, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "落ち葉", "is_correct": true, "explanation": "校庭を覆うのは地面に落ちた葉なので、ここに合う。"}, {"text": "雨粒", "is_correct": false, "explanation": "秋の校庭が雨粒で埋まる状況は文として不自然で、季節の風景としても合わない。"}, {"text": "氷", "is_correct": false, "explanation": "秋に校庭が氷で埋まることはなく、文脈に合わない。"}, {"text": "花火", "is_correct": false, "explanation": "校庭が花火で埋まるという意味にはならず、秋の風景にも合わない。"}], "explanations": {"落ち葉": "校庭を覆うのは地面に落ちた葉なので、ここに合う。", "雨粒": "秋の校庭が雨粒で埋まる状況は文として不自然で、季節の風景としても合わない。", "氷": "秋に校庭が氷で埋まることはなく、文脈に合わない。", "花火": "校庭が花火で埋まるという意味にはならず、秋の風景にも合わない。"}, "sentence_index": 0, "correct_answer": "落ち葉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "秋の山は、木の枝に残った落ち葉が真っ赤に色づいています。", "explanation": "ここは木の枝に付いたままの葉を指す〈紅葉〉の意味。落ち葉は地面に落ちた葉なので、枝に付いている状態には合わない。"}, {"text": "春になると、公園の桜の下に落ち葉が舞って、ピンク色に染まります。", "explanation": "ここは桜の〈花びら〉の意味。ピンク色に染まる散り花の話で、葉である落ち葉は合わない。"}, {"text": "冬の朝、庭は落ち葉が降り積もって真っ白でした。", "explanation": "真っ白に降り積もるのは〈雪〉の意味。落ち葉は葉なので、白く覆う様子には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36887, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "落ち葉", "is_correct": true, "explanation": "山道を厚く覆って歩きにくくするのは落ち葉なので、ここに合う。"}, {"text": "段ボール", "is_correct": false, "explanation": "段ボールが山道に厚く積もるとは考えにくく、文脈に合わない。"}, {"text": "金魚", "is_correct": false, "explanation": "金魚が山道に厚く積もることはなく、場面として成り立たない。"}, {"text": "教科書", "is_correct": false, "explanation": "山道に教科書が厚く積もることはなく、場面として成り立たない。"}], "explanations": {"落ち葉": "山道を厚く覆って歩きにくくするのは落ち葉なので、ここに合う。", "段ボール": "段ボールが山道に厚く積もるとは考えにくく、文脈に合わない。", "金魚": "金魚が山道に厚く積もることはなく、場面として成り立たない。", "教科書": "山道に教科書が厚く積もることはなく、場面として成り立たない。"}, "sentence_index": 6, "correct_answer": "落ち葉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "結婚式で、新郎新婦に向かって落ち葉を投げました。", "explanation": "ここは祝いの場で投げる紙吹雪の〈紙吹雪〉の意味。落ち葉は木の葉なので、祝いの小物には合わない。"}, {"text": "収穫のあと、畑に残った落ち葉を拾って、お米を集めました。", "explanation": "ここは〈落ち穂〉（刈り取りのあとに落ちた稲の穂）の意味。落ち葉は葉なので、拾って米を集めるものではない。"}, {"text": "夏祭りの夜空に、落ち葉が大きく広がりました。", "explanation": "ここは夜空に大きく開く〈花火〉の意味。落ち葉は地面に積もるもので、夜空に広がる様子には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36887, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "休日に、庭の落ち葉にほうきで掃きました。", "corrected_sentence": "休日に、庭の落ち葉をほうきで掃きました。", "error_description": "「掃く」の対象を表す助詞は「を」。誤りは「落ち葉に」で、正しくは「落ち葉を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36887, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "休みの日に、公園の落ち葉を集まりました。", "corrected_sentence": "休みの日に、公園の落ち葉を集めました。", "error_description": "「を」を取る目的語には他動詞「集める」を使う。誤りは自動詞「集まる」で、正しくは「集めました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36888, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「交互に重ねる」と動詞を修飾する「に」。正解。"}, {"text": "を", "is_correct": false, "explanation": "「交互を重ねる」では対象にならず、副詞の形が崩れて不自然。"}, {"text": "が", "is_correct": false, "explanation": "「交互が重ねると」では主語にならず、動作を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は「交互へ重ねる」の形で成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「交互に重ねる」と動詞を修飾する「に」。正解。", "を": "「交互を重ねる」では対象にならず、副詞の形が崩れて不自然。", "が": "「交互が重ねると」では主語にならず、動作を示せない。", "へ": "方向を示す「へ」は「交互へ重ねる」の形で成り立たない。"}, "error_tags": {"を": "対象", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36888, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「交互に重ねる」と動詞を修飾する「に」。正解。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」は「交互より重ねる」の形で動作を修飾できない。"}, {"text": "の", "is_correct": false, "explanation": "「交互の重ねたら」では動詞を修飾できず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「交互と重ねる」では副詞的な修飾にならず、文の形が合わない。"}], "correct_answer": "に", "explanations": {"に": "「交互に重ねる」と動詞を修飾する「に」。正解。", "より": "比較を示す「より」は「交互より重ねる」の形で動作を修飾できない。", "の": "「交互の重ねたら」では動詞を修飾できず、文が成り立たない。", "と": "「交互と重ねる」では副詞的な修飾にならず、文の形が合わない。"}, "error_tags": {"より": "比較", "の": "連体修飾", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36888, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのものを一つずつ順番に重ねること。", "primary_collocate": null, "pronunciation": "こうご", "ipa": "koːɡo", "syllable_count": 3, "sentences": [{"text": "白いパンと茶色いパンを交互に重ねて、サンドイッチを作りました。", "target_word": "交互", "complexity_tier": "T3", "furigana": "白[しろ]いパンと茶色[ちゃいろ]いパンを交互[こうご]に重[かさ]ねて、サンドイッチを作[つく]りました。", "sentence_source": "generated"}, {"text": "紙と布を交互に重ねると、丈夫な箱になります。", "target_word": "交互", "complexity_tier": "T3", "furigana": "紙[かみ]と布[ぬの]を交互[こうご]に重[かさ]ねると、丈夫[じょうぶ]な箱[はこ]になります。", "sentence_source": "generated"}, {"text": "ケーキの生地とクリームを交互に重ねました。", "target_word": "交互", "complexity_tier": "T3", "furigana": "ケーキの生地[きじ]とクリームを交互[こうご]に重[かさ]ねました。", "sentence_source": "generated"}, {"text": "本と雑誌を交互に重ねて置くと、崩れにくいです。", "target_word": "交互", "complexity_tier": "T3", "furigana": "本[ほん]と雑誌[ざっし]を交互[こうご]に重[かさ]ねて置[お]くと、崩[くず]れにくいです。", "sentence_source": "generated"}, {"text": "赤と青の積み木を交互に重ねて、高い塔を作りました。", "target_word": "交互", "complexity_tier": "T3", "furigana": "赤[あか]と青[あお]の積[つ]み木[き]を交互[こうご]に重[かさ]ねて、高[たか]い塔[とう]を作[つく]りました。", "sentence_source": "generated"}, {"text": "薄切りのじゃがいもとチーズを交互に重ねて、グラタンを作ります。", "target_word": "交互", "complexity_tier": "T3", "furigana": "薄切[うすぎ]りのじゃがいもとチーズを交互[こうご]に重[かさ]ねて、グラタンを作[つく]ります。", "sentence_source": "generated"}, {"text": "薄い板と厚い板を交互に重ねて、机の台にしました。", "target_word": "交互", "complexity_tier": "T3", "furigana": "薄[うす]い板[いた]と厚[あつ]い板[いた]を交互[こうご]に重[かさ]ねて、机[つくえ]の台[だい]にしました。", "sentence_source": "generated"}, {"text": "チーズとハムを交互に重ねたら、きれいな層ができました。", "target_word": "交互", "complexity_tier": "T3", "furigana": "チーズとハムを交互[こうご]に重[かさ]ねたら、きれいな層[そう]ができました。", "sentence_source": "generated"}, {"text": "黒い石と白い石を交互に重ねて、小さな山を作りました。", "target_word": "交互", "complexity_tier": "T3", "furigana": "黒[くろ]い石[いし]と白[しろ]い石[いし]を交互[こうご]に重[かさ]ねて、小[ちい]さな山[やま]を作[つく]りました。", "sentence_source": "generated"}, {"text": "赤と白の色紙を交互に重ねて貼ると、模様が浮かび上がります。", "target_word": "交互", "complexity_tier": "T3", "furigana": "赤[あか]と白[しろ]の色紙[いろがみ]を交互[こうご]に重[かさ]ねて貼[は]ると、模様[もよう]が浮[う]かび上[あ]がります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "交互", "label": "基本形"}, {"form": "交互に", "label": "副詞的な形"}], "register": "丁寧", "sense_fingerprint": "二種類の物を一枚ずつ・一層ずつ順番に積み重ねる並べ方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ff364e-4b2f-4e6b-b85e-ab8916606415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36888, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交互", "is_correct": true, "explanation": "二種類のパンを一つずつ入れ替えて重ねるので「交互に」が合う。正解。"}, {"text": "遠慮", "is_correct": false, "explanation": "「遠慮に重ねて」では意味が通らず、重ねる動作の様子を示せない。"}, {"text": "大騒ぎ", "is_correct": false, "explanation": "「大騒ぎに重ねて」は動作の様子として成り立たず、文脈に合わない。"}, {"text": "手際", "is_correct": false, "explanation": "「手際に重ねて」は様子を示す形にならず、重ねる動作と結びつかない。"}], "explanations": {"交互": "二種類のパンを一つずつ入れ替えて重ねるので「交互に」が合う。正解。", "遠慮": "「遠慮に重ねて」では意味が通らず、重ねる動作の様子を示せない。", "大騒ぎ": "「大騒ぎに重ねて」は動作の様子として成り立たず、文脈に合わない。", "手際": "「手際に重ねて」は様子を示す形にならず、重ねる動作と結びつかない。"}, "sentence_index": 0, "correct_answer": "交互"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜道で、二つの足音が交互に響いていました。", "explanation": "ここは〈順番に現れる〉の意味。足音が順番に響く場面で、物を重ねる意味ではない。"}, {"text": "子どもたちは、交互にブランコをこぎました。", "explanation": "ここは順番に行う動作の意味。ブランコを順番にこぐ場面で、重ねる意味ではない。"}, {"text": "本と雑誌を交互に読んで、夜が過ぎました。", "explanation": "ここは順番に行う動作の意味。読む順番の話で、物を積むことには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36888, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交互", "is_correct": true, "explanation": "二種類の板を一枚ずつ重ねるので「交互に」が合う。正解。"}, {"text": "一礼", "is_correct": false, "explanation": "「一礼に重ねて」は動作として成り立たず、板を重ねる文に合わない。"}, {"text": "不意", "is_correct": false, "explanation": "「不意に重ねて」は計画的な作業の文脈に合わない。"}, {"text": "寝不足", "is_correct": false, "explanation": "「寝不足に重ねて」は様子を示せず、板を重ねる動作と結びつかない。"}], "explanations": {"交互": "二種類の板を一枚ずつ重ねるので「交互に」が合う。正解。", "一礼": "「一礼に重ねて」は動作として成り立たず、板を重ねる文に合わない。", "不意": "「不意に重ねて」は計画的な作業の文脈に合わない。", "寝不足": "「寝不足に重ねて」は様子を示せず、板を重ねる動作と結びつかない。"}, "sentence_index": 6, "correct_answer": "交互"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの時計が交互に鳴って、目が覚めました。", "explanation": "ここは〈順番に現れる〉の意味。時計が順番に鳴る場面で、物を重ねる意味ではない。"}, {"text": "当番を交互に変えて、クラスの掃除を続けました。", "explanation": "ここは〈交代〉の意味。役目を入れ替える話で、物を重ねる意味ではない。"}, {"text": "夕焼けの雲が交互に色を変えていました。", "explanation": "ここは色が順番に移り変わる意味。雲の色の変化の話で、物を重ねる意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36888, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "赤いパンと黒いパンを交互を重ねて、皿に並べました。", "corrected_sentence": "赤いパンと黒いパンを交互に重ねて、皿に並べました。", "error_description": "「交互」は副詞として「交互に」の形で使う。「交互を」は誤りで、正しくは「交互に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36888, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "赤と青の色紙を交互に重なって貼ると、模様が浮かび上がります。", "corrected_sentence": "赤と青の色紙を交互に重ねて貼ると、模様が浮かび上がります。", "error_description": "「色紙を重ねる」は他動詞「重ねる」。誤りは自動詞「重なる」で、目的語の「色紙を」と合わない。正しくは「重ねて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36889, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「交互に犬の散歩に行く」と動詞を修飾する「に」。正解。"}, {"text": "を", "is_correct": false, "explanation": "「交互を行く」では対象にならず、動作の修飾として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「交互が行く」では主語にならず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は「交互へ行く」の形で成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「交互に犬の散歩に行く」と動詞を修飾する「に」。正解。", "を": "「交互を行く」では対象にならず、動作の修飾として成り立たない。", "が": "「交互が行く」では主語にならず、文が成り立たない。", "へ": "方向を示す「へ」は「交互へ行く」の形で成り立たない。"}, "error_tags": {"を": "対象", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36889, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「交互に光る」と動詞を修飾する「に」。正解。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」は「交互より光る」の形で動作を修飾できない。"}, {"text": "の", "is_correct": false, "explanation": "「交互の光っていました」では動詞を修飾できず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「交互と光る」では副詞的な修飾にならず、文の形が合わない。"}], "correct_answer": "に", "explanations": {"に": "「交互に光る」と動詞を修飾する「に」。正解。", "より": "比較を示す「より」は「交互より光る」の形で動作を修飾できない。", "の": "「交互の光っていました」では動詞を修飾できず、文が成り立たない。", "と": "「交互と光る」では副詞的な修飾にならず、文の形が合わない。"}, "error_tags": {"より": "比較", "の": "連体修飾", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36889, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのものが順番に現れたり、置かれたりすること。", "primary_collocate": null, "pronunciation": "こうご", "ipa": "koːɡo", "syllable_count": 3, "sentences": [{"text": "二人の先生が交互に教室に来て、授業をしてくれます。", "target_word": "交互", "complexity_tier": "T3", "furigana": "二[ふた]人[り]の先生[せんせい]が交互[こうご]に教室[きょうしつ]に来[き]て、授業[じゅぎょう]をしてくれます。", "sentence_source": "generated"}, {"text": "弟と私は交互に犬の散歩に行きます。", "target_word": "交互", "complexity_tier": "T3", "furigana": "弟[おとうと]と私[わたし]は交互[こうご]に犬[いぬ]の散歩[さんぽ]に行[い]きます。", "sentence_source": "generated"}, {"text": "晴れと雨が交互に続いて、洗濯物が乾きませんでした。", "target_word": "交互", "complexity_tier": "T3", "furigana": "晴[は]れと雨[あめ]が交互[こうご]に続[つづ]いて、洗濯物[せんたくもの]が乾[かわ]きませんでした。", "sentence_source": "generated"}, {"text": "赤と白の旗が交互に並んでいて、運動会らしい雰囲気でした。", "target_word": "交互", "complexity_tier": "T3", "furigana": "赤[あか]と白[しろ]の旗[はた]が交互[こうご]に並[なら]んでいて、運動会[うんどうかい]らしい雰囲気[ふんいき]でした。", "sentence_source": "generated"}, {"text": "長い道を、兄と交互に運転することにしました。", "target_word": "交互", "complexity_tier": "T3", "furigana": "長[なが]い道[みち]を、兄[あに]と交互[こうご]に運転[うんてん]することにしました。", "sentence_source": "generated"}, {"text": "道の両側に、桜と松が交互に植えられています。", "target_word": "交互", "complexity_tier": "T3", "furigana": "道[みち]の両側[りょうがわ]に、桜[さくら]と松[まつ]が交互[こうご]に植[う]えられています。", "sentence_source": "generated"}, {"text": "試合では、二つのチームが交互に点を取りました。", "target_word": "交互", "complexity_tier": "T3", "furigana": "試合[しあい]では、二[ふた]つのチームが交互[こうご]に点[てん]を取[と]りました。", "sentence_source": "generated"}, {"text": "夜中、赤と青のライトが交互に光っていました。", "target_word": "交互", "complexity_tier": "T3", "furigana": "夜中[よなか]、赤[あか]と青[あお]のライトが交互[こうご]に光[ひか]っていました。", "sentence_source": "generated"}, {"text": "母と父が交互に病院へ行って、祖母の世話をしました。", "target_word": "交互", "complexity_tier": "T3", "furigana": "母[はは]と父[ちち]が交互[こうご]に病院[びょういん]へ行[い]って、祖母[そぼ]の世話[せわ]をしました。", "sentence_source": "generated"}, {"text": "悲しい場面と楽しい場面が交互に出てきて、映画は長く感じませんでした。", "target_word": "交互", "complexity_tier": "T3", "furigana": "悲[かな]しい場面[ばめん]と楽[たの]しい場面[ばめん]が交互[こうご]に出[で]てきて、映画[えいが]は長[なが]く感[かん]じませんでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "交互", "label": "基本形"}, {"form": "交互に", "label": "副詞的な形"}], "register": "丁寧", "sense_fingerprint": "二人・二つの物事が代わる代わる順番に現れる、行う、並ぶこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ff364e-4b2f-4e6b-b85e-ab8916606415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36889, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交互", "is_correct": true, "explanation": "二人の先生が順番に教室に来る意味で「交互に」が合う。正解。"}, {"text": "一礼", "is_correct": false, "explanation": "「一礼に教室に来て」は動作の様子として成り立たず、文脈に合わない。"}, {"text": "寝不足", "is_correct": false, "explanation": "「寝不足に教室に来て」は様子を示せず、来る動作と結びつかない。"}, {"text": "仏頂面", "is_correct": false, "explanation": "「仏頂面に教室に来て」は表情の語で、来る動作の様子にならない。"}], "explanations": {"交互": "二人の先生が順番に教室に来る意味で「交互に」が合う。正解。", "一礼": "「一礼に教室に来て」は動作の様子として成り立たず、文脈に合わない。", "寝不足": "「寝不足に教室に来て」は様子を示せず、来る動作と結びつかない。", "仏頂面": "「仏頂面に教室に来て」は表情の語で、来る動作の様子にならない。"}, "sentence_index": 0, "correct_answer": "交互"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一人の先生が交互に教室に来て、授業をしてくれます。", "explanation": "ここは〈続けて〉の意味。一人が続けて来る場面なので、二つのものが順番に現れる意味とは合わない。"}, {"text": "二人が交互に同時に拍手して、会場が静まりました。", "explanation": "ここは〈同時に〉の意味。交互は一つずつ順番に行うことなので、同時に拍手する場面には合わない。"}, {"text": "薄いクッキーとクリームを交互に重ねて、ケーキの層を作りました。", "explanation": "ここは〈重ねる〉の意味。生地を層に積む場面で、順番に現れる意味とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36889, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交互", "is_correct": true, "explanation": "二つのチームが順番に点を取る意味で「交互に」が合う。正解。"}, {"text": "一礼", "is_correct": false, "explanation": "「一礼に点を取りました」は動作として成り立たず、試合の文脈に合わない。"}, {"text": "手際", "is_correct": false, "explanation": "「手際に点を取りました」は様子を示せず、点を取る動作と結びつかない。"}, {"text": "大騒ぎ", "is_correct": false, "explanation": "「大騒ぎに点を取りました」は動作の様子として成り立たない。"}], "explanations": {"交互": "二つのチームが順番に点を取る意味で「交互に」が合う。正解。", "一礼": "「一礼に点を取りました」は動作として成り立たず、試合の文脈に合わない。", "手際": "「手際に点を取りました」は様子を示せず、点を取る動作と結びつかない。", "大騒ぎ": "「大騒ぎに点を取りました」は動作の様子として成り立たない。"}, "sentence_index": 6, "correct_answer": "交互"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一回だけ交互に手を振りました。", "explanation": "ここは〈一度きり〉の意味。交互は二つのものが入れ替わることなので、一回だけの動作には合わない。"}, {"text": "みんなが一斉に、交互に手を挙げました。", "explanation": "ここは〈同時に〉の意味。一斉に行うことは交互の順番とは逆なので、合わない。"}, {"text": "ひとつのボールを、一人で交互に投げ続けました。", "explanation": "ここは〈連続して〉の意味。一つのものを続けて投げる場面で、二つのものが順番に現れる意味とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36889, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父と母が交互を病院に来て、祖母の世話をします。", "corrected_sentence": "父と母が交互に病院に来て、祖母の世話をします。", "error_description": "「交互」は副詞として「交互に」で使う。「交互を」は誤りで、正しくは「交互に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36889, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大会では、二つのチームが交互に点を取り合わせました。", "corrected_sentence": "大会では、二つのチームが交互に点を取り合いました。", "error_description": "「点を取り合う」は動詞「取り合う」で表す。誤りは「取り合わせる」で、正しくは「取り合いました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36890, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「服を重ねる」で動作の対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「服が重ねて着た」は主語と動詞が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「重ねる」の対象を示せず、「服へ重ねて着た」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「服を重ねる」で動作の対象を示す。", "が": "「服が重ねて着た」は主語と動詞が合わない。", "へ": "方向を表す「へ」は「重ねる」の対象を示せず、「服へ重ねて着た」は成り立たない。", "より": "比較の「より」は対象を示せない。"}, "error_tags": {"が": "subject_object", "へ": "direction", "より": "comparison"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "崩す", "is_correct": true, "explanation": "重ねて積んだものをばらばらにする意味で、重ねるの反対になる。"}, {"text": "積む", "is_correct": false, "explanation": "上に積む意味で、類義語に近い。"}, {"text": "束ねる", "is_correct": false, "explanation": "まとめる意味で反対ではない。"}, {"text": "載せる", "is_correct": false, "explanation": "上に置く意味で反対ではない。"}], "correct_answer": "崩す", "explanations": {"崩す": "重ねて積んだものをばらばらにする意味で、重ねるの反対になる。", "積む": "上に積む意味で、類義語に近い。", "束ねる": "まとめる意味で反対ではない。", "載せる": "上に置く意味で反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36890, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「和紙を重ねる」で動作の対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「和紙が何枚も重ねて」では作る人の動作と合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」は対象を示せない。"}, {"text": "ので", "is_correct": false, "explanation": "理由の「ので」は名詞の後に直接続かない。"}], "correct_answer": "を", "explanations": {"を": "「和紙を重ねる」で動作の対象を示す。", "が": "「和紙が何枚も重ねて」では作る人の動作と合わない。", "から": "起点を表す「から」は対象を示せない。", "ので": "理由の「ので」は名詞の後に直接続かない。"}, "error_tags": {"が": "subject_object", "から": "source", "ので": "reason"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "崩す", "is_correct": true, "explanation": "積んだものをばらす意味で、重ねるの反対になる。"}, {"text": "加える", "is_correct": false, "explanation": "足す意味で反対ではない。"}, {"text": "揃える", "is_correct": false, "explanation": "整える意味で反対ではない。"}, {"text": "足す", "is_correct": false, "explanation": "追加する意味で反対ではない。"}], "correct_answer": "崩す", "explanations": {"崩す": "積んだものをばらす意味で、重ねるの反対になる。", "加える": "足す意味で反対ではない。", "揃える": "整える意味で反対ではない。", "足す": "追加する意味で反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36890, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物の上に、同じような物を何枚も載せること。", "primary_collocate": null, "pronunciation": "かさねる", "ipa": "kasaneɾɯ", "syllable_count": 4, "sentences": [{"text": "皿を三枚重ねます。", "target_word": "重ねます", "complexity_tier": "T2", "furigana": "皿[さら]を三枚[さんまい]重[かさ]ねます。", "sentence_source": "generated"}, {"text": "寒いので、服を重ねて着た。", "target_word": "重ねて", "complexity_tier": "T3", "furigana": "寒[さむ]いので、服[ふく]を重[かさ]ねて着[き]た。", "sentence_source": "generated"}, {"text": "紙を重ねる。", "target_word": "重ねる", "complexity_tier": "T1", "furigana": "紙[かみ]を重[かさ]ねる。", "sentence_source": "generated"}, {"text": "絵の具を重ねて、深い色を出した。", "target_word": "重ねて", "complexity_tier": "T3", "furigana": "絵[え]の具[ぐ]を重[かさ]ねて、深[ふか]い色[いろ]を出[だ]した。", "sentence_source": "generated"}, {"text": "箱を重ねると、倒れやすくなる。", "target_word": "重ねる", "complexity_tier": "T4", "furigana": "箱[はこ]を重[かさ]ねると、倒[たお]れやすくなる。", "sentence_source": "generated"}, {"text": "二人は手を重ねて、写真を撮った。", "target_word": "重ねて", "complexity_tier": "T3", "furigana": "二人[ふたり]は手[て]を重[かさ]ねて、写真[しゃしん]を撮[と]った。", "sentence_source": "generated"}, {"text": "重ねた布団の上に、猫が寝ている。", "target_word": "重ねた", "complexity_tier": "T4", "furigana": "重[かさ]ねた布団[ふとん]の上[うえ]に、猫[ねこ]が寝[ね]ている。", "sentence_source": "generated"}, {"text": "薄い和紙を何枚も重ねて、美しい模様を作った。", "target_word": "重ねて", "complexity_tier": "T5", "furigana": "薄[うす]い和紙[わし]を何枚[なんまい]も重[かさ]ねて、美[うつく]しい模様[もよう]を作[つく]った。", "sentence_source": "generated"}, {"text": "毛布を重ねれば、冬も暖かい。", "target_word": "重ねれば", "complexity_tier": "T4", "furigana": "毛布[もうふ]を重[かさ]ねれば、冬[ふゆ]も暖[あたた]かい。", "sentence_source": "generated"}, {"text": "皿は重ねずに置きました。", "target_word": "重ねず", "complexity_tier": "T3", "furigana": "皿[さら]は重[かさ]ねずに置[お]きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重ねて", "label": "活用"}, {"form": "重ねた", "label": "活用"}, {"form": "重ね", "label": "活用"}, {"form": "重ねれば", "label": "活用"}, {"form": "重ねず", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 同じ物を何度も上に積み重ねる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5211d9c-157e-40de-b755-e90087d97fda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36890, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重ねます", "is_correct": true, "explanation": "皿を何枚も上に積むという意味で自然に合う。"}, {"text": "祈ります", "is_correct": false, "explanation": "形は合うが、皿を三枚祈るという意味が合わない。"}, {"text": "歌います", "is_correct": false, "explanation": "形は合うが、皿を三枚歌うという意味が合わない。"}, {"text": "疑います", "is_correct": false, "explanation": "形は合うが、皿の枚数を疑うという意味が合わない。"}], "explanations": {"重ねます": "皿を何枚も上に積むという意味で自然に合う。", "祈ります": "形は合うが、皿を三枚祈るという意味が合わない。", "歌います": "形は合うが、皿を三枚歌うという意味が合わない。", "疑います": "形は合うが、皿の枚数を疑うという意味が合わない。"}, "sentence_index": 0, "correct_answer": "重ねます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の上に水を重ねて、コップに入れた。", "explanation": "水は積み重ねられないので、「重ねる」の使い方が合わない。"}, {"text": "朝ごはんを重ねて、学校に行った。", "explanation": "「重ねる」は食べるという意味ではなく、物を積む意味なので誤り。"}, {"text": "ドアを重ねて、部屋から出た。", "explanation": "ドアを開ける動作に「重ねる」は使えず、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36890, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重ねた", "is_correct": true, "explanation": "布団を積んだ状態を表し、上に猫が寝ているという文に合う。"}, {"text": "笑った", "is_correct": false, "explanation": "形は合うが、布団が笑うという意味が合わない。"}, {"text": "祈った", "is_correct": false, "explanation": "形は合うが、布団を祈るという意味が合わない。"}, {"text": "疑った", "is_correct": false, "explanation": "形は合うが、布団を疑うという意味が合わない。"}], "explanations": {"重ねた": "布団を積んだ状態を表し、上に猫が寝ているという文に合う。", "笑った": "形は合うが、布団が笑うという意味が合わない。", "祈った": "形は合うが、布団を祈るという意味が合わない。", "疑った": "形は合うが、布団を疑うという意味が合わない。"}, "sentence_index": 6, "correct_answer": "重ねた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水は重ねずにコップに入れました。", "explanation": "水は積み重ねる対象ではないので、「重ねる」の使い方が合わない。"}, {"text": "犬は重ねずに走りました。", "explanation": "走る動作に「重ねる」は結びつかず、意味が合わない。"}, {"text": "雲は重ねずに晴れました。", "explanation": "天気の変化を「重ねる」で表すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36890, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毛布で二枚重ねて寝た。", "corrected_sentence": "毛布を二枚重ねて寝た。", "error_description": "「重ねる」の対象には「で」ではなく「を」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "重ねて", "is_correct": true, "explanation": "「服を重ねて着た」と続く正しいて形。"}, {"text": "重ねよう", "is_correct": false, "explanation": "意志形なので「着た」につながらない。"}, {"text": "重ねろ", "is_correct": false, "explanation": "命令形なので過去の文に合わない。"}, {"text": "重ねたい", "is_correct": false, "explanation": "希望の形で「着た」につながらない。"}], "correct_form": "重ねて", "base_form": "重ねる", "form_label": "て形", "sentence_index": 1, "explanations": {"重ねて": "「服を重ねて着た」と続く正しいて形。", "重ねよう": "意志形なので「着た」につながらない。", "重ねろ": "命令形なので過去の文に合わない。", "重ねたい": "希望の形で「着た」につながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36890, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "洋服が三枚重ねて着た。", "corrected_sentence": "洋服を三枚重ねて着た。", "error_description": "「重ねる」の対象には「が」ではなく「を」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "重ねて", "is_correct": true, "explanation": "「何枚も重ねて、模様を作った」とつながる正しいて形。"}, {"text": "重ねれば", "is_correct": false, "explanation": "仮定形で、過去の「作った」と合わない。"}, {"text": "重ねよう", "is_correct": false, "explanation": "意志形なので、「、美しい模様を作った」という過去の文につながらない。"}, {"text": "重ねろ", "is_correct": false, "explanation": "命令形なので過去の文に合わない。"}], "correct_form": "重ねて", "base_form": "重ねる", "form_label": "て形", "sentence_index": 7, "explanations": {"重ねて": "「何枚も重ねて、模様を作った」とつながる正しいて形。", "重ねれば": "仮定形で、過去の「作った」と合わない。", "重ねよう": "意志形なので、「、美しい模様を作った」という過去の文につながらない。", "重ねろ": "命令形なので過去の文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36891, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「時を重ねる」で重ねる対象を示します。"}, {"text": "が", "is_correct": false, "explanation": "「時が重ねて」では他動詞の対象にならず不自然です。"}, {"text": "の", "is_correct": false, "explanation": "「時の重ねて」は動詞に直接つながりません。"}, {"text": "から", "is_correct": false, "explanation": "「時から重ねて」は対象を示せず不自然です。"}], "correct_answer": "を", "explanations": {"を": "「時を重ねる」で重ねる対象を示します。", "が": "「時が重ねて」では他動詞の対象にならず不自然です。", "の": "「時の重ねて」は動詞に直接つながりません。", "から": "「時から重ねて」は対象を示せず不自然です。"}, "error_tags": {"が": "subject_marker", "の": "possessive", "から": "starting_point"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36891, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「議論を重ねる」で重ねる対象を示します。"}, {"text": "が", "is_correct": false, "explanation": "「議論が重ねた」では他動詞の対象にならず不自然です。"}, {"text": "へ", "is_correct": false, "explanation": "「議論へ重ねた」は方向を表し、意味が通りません。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は重ねる対象を示せず、「議論より重ねた」は成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「議論を重ねる」で重ねる対象を示します。", "が": "「議論が重ねた」では他動詞の対象にならず不自然です。", "へ": "「議論へ重ねた」は方向を表し、意味が通りません。", "より": "比較の「より」は重ねる対象を示せず、「議論より重ねた」は成り立ちません。"}, "error_tags": {"が": "subject_marker", "へ": "direction", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36891, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "経験や努力、時間などを、何度もくり返して積み上げること。", "primary_collocate": null, "pronunciation": "かさねる", "ipa": "kasaneɾɯ", "syllable_count": 4, "sentences": [{"text": "鉢という限定された宇宙の中で、命は水という恩恵を糧に、時を重ねてその緑を深めていく。", "target_word": "重ねて", "complexity_tier": "T6", "furigana": "鉢[はち]という限定[げんてい]された宇宙[うちゅう]の中[なか]で、命[いのち]は水[みず]という恩恵[おんけい]を糧[かて]に、時[とき]を重[かさ]ねてその緑[みどり]を深[ふか]めていく。", "sentence_source": "mined"}, {"text": "話し合いを重ねます。", "target_word": "重ねます", "complexity_tier": "T2", "furigana": "話[はな]し合[あ]いを重[かさ]ねます。", "sentence_source": "generated"}, {"text": "経験を重ねて、仕事が上手になった。", "target_word": "重ねて", "complexity_tier": "T3", "furigana": "経験[けいけん]を重[かさ]ねて、仕事[しごと]が上手[じょうず]になった。", "sentence_source": "generated"}, {"text": "年を重ねました。", "target_word": "重ねました", "complexity_tier": "T2", "furigana": "年[とし]を重[かさ]ねました。", "sentence_source": "generated"}, {"text": "毎日、練習を重ねている。", "target_word": "重ねている", "complexity_tier": "T3", "furigana": "毎日[まいにち]、練習[れんしゅう]を重[かさ]ねている。", "sentence_source": "generated"}, {"text": "失敗を重ねても、あきらめなかった。", "target_word": "重ねても", "complexity_tier": "T4", "furigana": "失敗[しっぱい]を重[かさ]ねても、あきらめなかった。", "sentence_source": "generated"}, {"text": "研究を重ねれば、答えが見えてくるはずだ。", "target_word": "重ねれば", "complexity_tier": "T4", "furigana": "研究[けんきゅう]を重[かさ]ねれば、答[こた]えが見[み]えてくるはずだ。", "sentence_source": "generated"}, {"text": "議論を重ねた結果、新しい計画が決まった。", "target_word": "重ねた", "complexity_tier": "T4", "furigana": "議論[ぎろん]を重[かさ]ねた結果[けっか]、新[あたら]しい計画[けいかく]が決[き]まった。", "sentence_source": "generated"}, {"text": "彼は何度も失敗を重ね、ようやく成功をつかんだ。", "target_word": "重ね", "complexity_tier": "T5", "furigana": "彼[かれ]は何度[なんど]も失敗[しっぱい]を重[かさ]ね、ようやく成功[せいこう]をつかんだ。", "sentence_source": "generated"}, {"text": "努力を重ねる。", "target_word": "重ねる", "complexity_tier": "T1", "furigana": "努力[どりょく]を重[かさ]ねる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重ねて", "label": "活用"}, {"form": "重ねた", "label": "活用"}, {"form": "重ね", "label": "活用"}, {"form": "重ねれば", "label": "活用"}, {"form": "重ねない", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 経験や努力を積み上げ繰り返す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5211d9c-157e-40de-b755-e90087d97fda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36891, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重ねて", "is_correct": true, "explanation": "時を積み上げて経過させるという意味に合います。"}, {"text": "壊して", "is_correct": false, "explanation": "形は合うが意味が合わない。緑を深める流れに反します。"}, {"text": "捨てて", "is_correct": false, "explanation": "形は合うが意味が合わない。時を捨てて緑が深まるとは言えません。"}, {"text": "破って", "is_correct": false, "explanation": "形は合うが意味が合わない。時を破る意味は文脈に合いません。"}], "explanations": {"重ねて": "時を積み上げて経過させるという意味に合います。", "壊して": "形は合うが意味が合わない。緑を深める流れに反します。", "捨てて": "形は合うが意味が合わない。時を捨てて緑が深まるとは言えません。", "破って": "形は合うが意味が合わない。時を破る意味は文脈に合いません。"}, "sentence_index": 0, "correct_answer": "重ねて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電車の中で、傘を重ねてきてしまった。", "explanation": "「重ねる」は積む・繰り返すことで、置き忘れる意味では使えません。"}, {"text": "彼は一度の失敗を重ねて、すぐに成功した。", "explanation": "「重ねる」は繰り返すことなので、一度の失敗には使えません。"}, {"text": "窓を重ねて部屋の空気を入れ替えた。", "explanation": "窓を開けることを「重ねる」とは言いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36891, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重ねれば", "is_correct": true, "explanation": "研究を積み重ねれば答えが見えるという意味に合います。"}, {"text": "捨てれば", "is_correct": false, "explanation": "形は合うが意味が合わない。研究を捨てて答えが見える流れになりません。"}, {"text": "避ければ", "is_correct": false, "explanation": "形は合うが意味が合わない。研究を避けると答えが見えるとは言えません。"}, {"text": "閉じれば", "is_correct": false, "explanation": "形は合うが意味が合わない。研究を閉じても答えは見えてきません。"}], "explanations": {"重ねれば": "研究を積み重ねれば答えが見えるという意味に合います。", "捨てれば": "形は合うが意味が合わない。研究を捨てて答えが見える流れになりません。", "避ければ": "形は合うが意味が合わない。研究を避けると答えが見えるとは言えません。", "閉じれば": "形は合うが意味が合わない。研究を閉じても答えは見えてきません。"}, "sentence_index": 6, "correct_answer": "重ねれば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風邪を重ねて、病院へ行った。", "explanation": "「重ねる」は積み上げる・繰り返すことで、病気にかかる意味では使えません。"}, {"text": "ドアを重ねて外に出た。", "explanation": "ドアを開ける意味で「重ねる」は使えません。"}, {"text": "彼は努力を重ねたが、まったく何もしなかった。", "explanation": "努力を重ねたことと、何もしなかったことが矛盾しています。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36891, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日、練習を重なっている。", "corrected_sentence": "毎日、練習を重ねている。", "error_description": "「練習を」の目的語を取るのは他動詞「重ねる」で、自動詞「重なる」は不適切。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "重ねます", "is_correct": true, "explanation": "文末の丁寧な形で、「話し合いを重ねます」と言えます。"}, {"text": "重ねながら", "is_correct": false, "explanation": "「ながら」は後に別の動作が続く形なので、ここで文を終えられません。"}, {"text": "重ねれば", "is_correct": false, "explanation": "仮定形なので、文末に置けません。"}, {"text": "重ね", "is_correct": false, "explanation": "連用形のままでは文を終われません。"}], "correct_form": "重ねます", "base_form": "重ねる", "form_label": "丁寧形（ます）", "sentence_index": 1, "explanations": {"重ねます": "文末の丁寧な形で、「話し合いを重ねます」と言えます。", "重ねながら": "「ながら」は後に別の動作が続く形なので、ここで文を終えられません。", "重ねれば": "仮定形なので、文末に置けません。", "重ね": "連用形のままでは文を終われません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36891, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は何度も失敗に重ね、成功をつかんだ。", "corrected_sentence": "彼は何度も失敗を重ね、成功をつかんだ。", "error_description": "「重ねる」の対象は「を」で示すので、「失敗に」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "重ねた", "is_correct": true, "explanation": "「結果」を修飾する過去形で自然です。"}, {"text": "重ねて", "is_correct": false, "explanation": "「重ねて結果」となり名詞を修飾できません。"}, {"text": "重ね", "is_correct": false, "explanation": "「重ね結果」となり名詞を修飾できません。"}, {"text": "重ねれば", "is_correct": false, "explanation": "「重ねれば結果」となり名詞を修飾できません。"}], "correct_form": "重ねた", "base_form": "重ねる", "form_label": "過去形（た）", "sentence_index": 7, "explanations": {"重ねた": "「結果」を修飾する過去形で自然です。", "重ねて": "「重ねて結果」となり名詞を修飾できません。", "重ね": "「重ね結果」となり名詞を修飾できません。", "重ねれば": "「重ねれば結果」となり名詞を修飾できません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36892, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「温める」の目的語になる「卵」に「を」が付く。"}, {"text": "が", "is_correct": false, "explanation": "「卵が温める」では主語と動詞の関係が逆になり不自然。"}, {"text": "に", "is_correct": false, "explanation": "「卵に温める」は相手を示すが、温める対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「卵と温める」は並列を示すが、温める対象としては不自然。"}], "correct_answer": "を", "explanations": {"を": "「温める」の目的語になる「卵」に「を」が付く。", "が": "「卵が温める」では主語と動詞の関係が逆になり不自然。", "に": "「卵に温める」は相手を示すが、温める対象にはならない。", "と": "「卵と温める」は並列を示すが、温める対象としては不自然。"}, "error_tags": {"が": "主語", "に": "相手・場所", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36892, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「割れる」の主語になる「卵」に「が」が付く。"}, {"text": "を", "is_correct": false, "explanation": "「割れる」は自動詞で目的語を取らないため、「を」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「卵へ割れてしまった」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、卵を起点に割れるとは言わない。"}], "correct_answer": "が", "explanations": {"が": "「割れる」の主語になる「卵」に「が」が付く。", "を": "「割れる」は自動詞で目的語を取らないため、「を」は合わない。", "へ": "「へ」は方向を示すため、「卵へ割れてしまった」は不自然。", "から": "「から」は起点を示すが、卵を起点に割れるとは言わない。"}, "error_tags": {"を": "目的語（他動詞用）", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36892, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "鳥の赤ちゃんが生まれる前に、中に入っているもの。料理に使う食べ物。", "primary_collocate": null, "pronunciation": "たまご", "ipa": "tamaɡo", "syllable_count": 3, "sentences": [{"text": "卵が一個残っていたので、昼ごはんに目玉焼きを作った。", "target_word": "卵", "complexity_tier": "T3", "furigana": "卵[たまご]が一個[いっこ]残[のこ]っていたので、昼[ひる]ごはんに目玉焼[めだまや]きを作[つく]った。", "sentence_source": "generated"}, {"text": "鳥は巣の中で卵をあたためて、ひなが生まれるのを待つ。", "target_word": "卵", "complexity_tier": "T3", "furigana": "鳥[とり]は巣[す]の中[なか]で卵[たまご]をあたためて、ひなが生[う]まれるのを待[ま]つ。", "sentence_source": "generated"}, {"text": "卵にアレルギーがある子のために、卵を使わないパンを選んだ。", "target_word": "卵", "complexity_tier": "T3", "furigana": "卵[たまご]にアレルギーがある子[こ]のために、卵[たまご]を使[つか]わないパンを選[えら]んだ。", "sentence_source": "generated"}, {"text": "冷蔵庫を開けると、卵と牛乳しか入っていなかった。", "target_word": "卵", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]を開[あ]けると、卵[たまご]と牛乳[ぎゅうにゅう]しか入[はい]っていなかった。", "sentence_source": "generated"}, {"text": "卵をゆでるときは、お湯が沸いてから入れる。", "target_word": "卵", "complexity_tier": "T3", "furigana": "卵[たまご]をゆでるときは、お湯[ゆ]が沸[わ]いてから入[い]れる。", "sentence_source": "generated"}, {"text": "池のそばで、カモが卵を守っているのを見た。", "target_word": "卵", "complexity_tier": "T3", "furigana": "池[いけ]のそばで、カモが卵[たまご]を守[まも]っているのを見[み]た。", "sentence_source": "generated"}, {"text": "卵を割ったら、中から黄身が二つ出てきて驚いた。", "target_word": "卵", "complexity_tier": "T3", "furigana": "卵[たまご]を割[わ]ったら、中[なか]から黄身[きみ]が二[ふた]つ出[で]てきて驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "買い物かごの上に重い物を置いたので、卵が割れてしまった。", "target_word": "卵", "complexity_tier": "T3", "furigana": "買[か]い物[もの]かごの上[うえ]に重[おも]い物[もの]を置[お]いたので、卵[たまご]が割[わ]れてしまった。", "sentence_source": "generated"}, {"text": "卵は栄養があって安いので、ほぼ毎日食べている。", "target_word": "卵", "complexity_tier": "T3", "furigana": "卵[たまご]は栄養[えいよう]があって安[やす]いので、ほぼ毎日[まいにち]食[た]べている。", "sentence_source": "generated"}, {"text": "スズメは木の枝に巣を作って、卵を産む。", "target_word": "卵", "complexity_tier": "T3", "furigana": "スズメは木[き]の枝[えだ]に巣[す]を作[つく]って、卵[たまご]を産[う]む。", "sentence_source": "generated"}], "morphological_forms": [{"form": "卵", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "鳥のひなが生まれる前の殻に入ったもの。料理に使う食材", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: ゆでる (Zipf 2.32)']::text[], '8b8e48ae-ce80-40b8-bedd-e93621d51cd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36892, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "卵", "is_correct": true, "explanation": "一個と数えられ、目玉焼きの材料になるので文に合う。"}, {"text": "殻", "is_correct": false, "explanation": "殻は割った後に残る外側で、目玉焼きの材料としては残っていないので理由の文が成り立たない。"}, {"text": "雛", "is_correct": false, "explanation": "雛は生き物で、一個残って目玉焼きの材料になることはない。"}, {"text": "巣", "is_correct": false, "explanation": "巣は鳥の住まいで、目玉焼きにつながらない。"}], "explanations": {"卵": "一個と数えられ、目玉焼きの材料になるので文に合う。", "殻": "殻は割った後に残る外側で、目玉焼きの材料としては残っていないので理由の文が成り立たない。", "雛": "雛は生き物で、一個残って目玉焼きの材料になることはない。", "巣": "巣は鳥の住まいで、目玉焼きにつながらない。"}, "sentence_index": 0, "correct_answer": "卵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この花は卵から育てると、春に咲く。", "explanation": "ここは〈種〉の意味。植物を種から育てるとは言うが、卵から育てるとは言わない。"}, {"text": "この鳥の卵は木の枝で編まれていて、雨にも強い。", "explanation": "ここは〈巣〉の意味。木の枝で編まれ雨に強いのは巣で、卵の説明としては合わない。"}, {"text": "ヒヨコの卵が生えそろってきた。", "explanation": "ここは〈羽〉の意味。生えそろうのは羽で、卵が生えることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36892, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "卵", "is_correct": true, "explanation": "割ると中から黄身が出てくるものとして、卵を割る文に合う。"}, {"text": "皿", "is_correct": false, "explanation": "皿を割っても中から黄身が出てくることはない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋を割っても中から黄身が出てくることはない。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は黄身を入れる容器ではなく、割って黄身が出る文には合わない。"}], "explanations": {"卵": "割ると中から黄身が出てくるものとして、卵を割る文に合う。", "皿": "皿を割っても中から黄身が出てくることはない。", "鍋": "鍋を割っても中から黄身が出てくることはない。", "包丁": "包丁は黄身を入れる容器ではなく、割って黄身が出る文には合わない。"}, "sentence_index": 6, "correct_answer": "卵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "卵は三週間ほどで巣立つ。", "explanation": "ここは〈雛〉の意味。巣立つのは生まれたひなで、卵は巣立たない。"}, {"text": "玉ねぎの卵をむいてから、薄切りにした。", "explanation": "ここは〈皮〉の意味。玉ねぎの外側を覆う皮をむくのであり、卵とは言わない。"}, {"text": "この卵は春に花が咲き、秋に実をつける。", "explanation": "ここは〈木〉の意味。花が咲き実をつけるのは植物で、卵には当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36892, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭のニワトリが毎朝、新しい卵が一つ産む。", "corrected_sentence": "庭のニワトリが毎朝、新しい卵を一つ産む。", "error_description": "「産む」の目的語には「を」が必要。「が」は主語を示すため、「卵が一つ産む」は誤り。正しくは「卵を一つ産む」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36892, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春になると、ツバメは巣の中で卵が温める。", "corrected_sentence": "春になると、ツバメは巣の中で卵を温める。", "error_description": "「温める」の目的語には「を」が必要。「が」は主語を示すため、「卵が温める」は誤り。正しくは「卵を温める」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36893, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「使う」の目的語になる「卵」に「を」が付く。"}, {"text": "が", "is_correct": false, "explanation": "「卵が使う」では主語と動詞が合わず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「卵に使う」は不自然。「に」は相手や場所を示すため不適。"}, {"text": "と", "is_correct": false, "explanation": "「卵と使う」は並列を示すが、使う対象としては不自然。"}], "correct_answer": "を", "explanations": {"を": "「使う」の目的語になる「卵」に「を」が付く。", "が": "「卵が使う」では主語と動詞が合わず、文が成り立たない。", "に": "「卵に使う」は不自然。「に」は相手や場所を示すため不適。", "と": "「卵と使う」は並列を示すが、使う対象としては不自然。"}, "error_tags": {"が": "主語", "に": "相手・場所", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36893, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「足りない」の主語になる「卵」に「が」が付く。"}, {"text": "を", "is_correct": false, "explanation": "「足りない」は目的語を取らないため、「を」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「卵へ足りなくて」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、卵を起点に足りないとは言わない。"}], "correct_answer": "が", "explanations": {"が": "「足りない」の主語になる「卵」に「が」が付く。", "を": "「足りない」は目的語を取らないため、「を」は合わない。", "へ": "「へ」は方向を示すため、「卵へ足りなくて」は不自然。", "から": "「から」は起点を示すが、卵を起点に足りないとは言わない。"}, "error_tags": {"を": "目的語（他動詞用）", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36893, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "鳥が産む、殻（から）に包まれた球形のもの。特に、ニワトリの卵を指し、料理の材料として広く使われる。", "primary_collocate": null, "pronunciation": "たまご", "ipa": "tamaɡo", "syllable_count": 3, "sentences": [{"text": "日の出と共に目覚める鶏の健康こそが、栄養豊富な卵を産んでもらうための条件だからである。", "target_word": "卵", "complexity_tier": "T3", "furigana": "日[ひ]の出[で]と共[とも]に目覚[めざ]める鶏[にわとり]の健康[けんこう]こそが、栄養[えいよう]豊富[ほうふ]な卵[たまご]を産[う]んでもらうための条件[じょうけん]だからである。", "sentence_source": "mined"}, {"text": "朝ごはんに卵を二つ使って、オムレツを作った。", "target_word": "卵", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんに卵[たまご]を二[ふた]つ使[つか]って、オムレツを作[つく]った。", "sentence_source": "generated"}, {"text": "卵は冷蔵庫に入れて、できるだけ早く食べたほうがいい。", "target_word": "卵", "complexity_tier": "T3", "furigana": "卵[たまご]は冷蔵庫[れいぞうこ]に入[い]れて、できるだけ早[はや]く食[た]べたほうがいい。", "sentence_source": "generated"}, {"text": "卵を落としてしまい、床が汚れてしまった。", "target_word": "卵", "complexity_tier": "T3", "furigana": "卵[たまご]を落[お]としてしまい、床[ゆか]が汚[よご]れてしまった。", "sentence_source": "generated"}, {"text": "ニワトリは毎日のように卵を産む。", "target_word": "卵", "complexity_tier": "T3", "furigana": "ニワトリは毎日[まいにち]のように卵[たまご]を産[う]む。", "sentence_source": "generated"}, {"text": "卵の殻を割ると、中から黄色い黄身が出てきた。", "target_word": "卵", "complexity_tier": "T3", "furigana": "卵[たまご]の殻[から]を割[わ]ると、中[なか]から黄色[きいろ]い黄身[きみ]が出[で]てきた。", "sentence_source": "generated"}, {"text": "スーパーで卵が安売りだったので、二パック買った。", "target_word": "卵", "complexity_tier": "T3", "furigana": "スーパーで卵[たまご]が安売[やすう]りだったので、二[に]パック買[か]った。", "sentence_source": "generated"}, {"text": "卵が足りなくて、ケーキを作ることができなかった。", "target_word": "卵", "complexity_tier": "T3", "furigana": "卵[たまご]が足[た]りなくて、ケーキを作[つく]ることができなかった。", "sentence_source": "generated"}, {"text": "卵を高い所から落とすと割れるのは、殻が薄いからだ。", "target_word": "卵", "complexity_tier": "T3", "furigana": "卵[たまご]を高[たか]い所[ところ]から落[お]とすと割[わ]れるのは、殻[から]が薄[うす]いからだ。", "sentence_source": "generated"}, {"text": "卵と牛乳を混ぜてから、フライパンで焼く。", "target_word": "卵", "complexity_tier": "T3", "furigana": "卵[たまご]と牛乳[ぎゅうにゅう]を混[ま]ぜてから、フライパンで焼[や]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "卵", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "鳥（特にニワトリ）が産む殻に包まれた卵。料理の材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e48ae-ce80-40b8-bedd-e93621d51cd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36893, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "卵", "is_correct": true, "explanation": "鶏が産む、殻に包まれた球形のものを指すので、栄養豊富な卵を産むという文に合う。"}, {"text": "殻", "is_correct": false, "explanation": "殻は卵を包む外側で、鶏が産むものではない。"}, {"text": "羽", "is_correct": false, "explanation": "羽は鶏の体の一部で、産んでもらうものではない。"}, {"text": "巣", "is_correct": false, "explanation": "巣は鳥が作る住まいで、産むものではない。"}], "explanations": {"卵": "鶏が産む、殻に包まれた球形のものを指すので、栄養豊富な卵を産むという文に合う。", "殻": "殻は卵を包む外側で、鶏が産むものではない。", "羽": "羽は鶏の体の一部で、産んでもらうものではない。", "巣": "巣は鳥が作る住まいで、産むものではない。"}, "sentence_index": 0, "correct_answer": "卵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜明けになると、卵が鳴いて村中を起こす。", "explanation": "ここは〈鶏〉の意味。鳴いて人を起こすのは鶏で、卵は鳴かない。"}, {"text": "この花の卵は、乾燥させてから春に蒔く。", "explanation": "ここは〈種〉の意味。乾燥させて蒔くのは植物の種で、卵は蒔かない。"}, {"text": "この卵は深くて、スープを注いでそのまま出せる。", "explanation": "ここは〈器〉の意味。深くてスープを注いで出すのは器で、卵は器ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36893, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "卵", "is_correct": true, "explanation": "二パック単位で安売りされる食品の卵を指すので文に合う。"}, {"text": "黄身", "is_correct": false, "explanation": "黄身は卵の一部で、パック単位で売られるものではない。"}, {"text": "白身", "is_correct": false, "explanation": "白身は卵の一部で、パック単位で売られるものではない。"}, {"text": "雛", "is_correct": false, "explanation": "雛は生き物で、スーパーで二パック安売りされるものではない。"}], "explanations": {"卵": "二パック単位で安売りされる食品の卵を指すので文に合う。", "黄身": "黄身は卵の一部で、パック単位で売られるものではない。", "白身": "白身は卵の一部で、パック単位で売られるものではない。", "雛": "雛は生き物で、スーパーで二パック安売りされるものではない。"}, "sentence_index": 6, "correct_answer": "卵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭で卵がよちよち歩いている。", "explanation": "ここは〈雛〉の意味。よちよち歩くのは生まれた雛で、殻の中の卵は歩けない。"}, {"text": "畑の土から、小さな卵が顔を出した。", "explanation": "ここは〈芽〉の意味。土から顔を出すのは植物の芽で、卵には当てはまらない。"}, {"text": "カニは成長すると卵を脱ぐ。", "explanation": "ここは〈殻〉の意味。成長して脱ぐのは体を覆う殻で、卵を脱ぐとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36893, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝ごはんに卵が焼いて、パンと一緒に食べた。", "corrected_sentence": "朝ごはんに卵を焼いて、パンと一緒に食べた。", "error_description": "「焼く」の目的語には「を」が必要。「が」は主語を示すため、「卵が焼いて」は誤り。正しくは「卵を焼いて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36893, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ボウルに卵に割り入れて、よくかき混ぜる。", "corrected_sentence": "ボウルに卵を割り入れて、よくかき混ぜる。", "error_description": "「割り入れる」の目的語には「を」が必要。「に」は相手や場所を示すため、「卵に割り入れて」は誤り。正しくは「卵を割り入れて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
