INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36894, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「殻を捨てる」の「を」。捨てる対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、殻が捨てるという主語になり意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や対象の位置を示すので、捨てる対象としては使えない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示すので、捨てる動作の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「殻を捨てる」の「を」。捨てる対象を示す。", "が": "「が」は主語を示すので、殻が捨てるという主語になり意味が通らない。", "に": "「に」は到達点や対象の位置を示すので、捨てる対象としては使えない。", "の": "「の」は所属や修飾を示すので、捨てる動作の対象にはならない。"}, "error_tags": {"が": "主語を示す", "に": "到達点・位置を示す", "の": "所属・修飾を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36894, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物の外側の固い部分のことです。", "primary_collocate": null, "pronunciation": "から", "ipa": "kaɾa", "syllable_count": 2, "sentences": [{"text": "卵の殻を割って、フライパンに入れました。", "target_word": "殻", "complexity_tier": "T3", "furigana": "卵(たまご)の殻(から)を割(わ)って、フライパンに入(い)れました。", "sentence_source": "generated"}, {"text": "カニの殻は固くて、手では割れません。", "target_word": "殻", "complexity_tier": "T3", "furigana": "カニの殻(から)は固(かた)くて、手(て)では割(わ)れません。", "sentence_source": "generated"}, {"text": "蝉が出たあとの殻が、木に残っていました。", "target_word": "殻", "complexity_tier": "T3", "furigana": "蝉(せみ)が出(で)たあとの殻(から)が、木(き)に残(のこ)っていました。", "sentence_source": "generated"}, {"text": "ナッツの殻をむいてから、袋に入れます。", "target_word": "殻", "complexity_tier": "T3", "furigana": "ナッツの殻(から)をむいてから、袋(ふくろ)に入(い)れます。", "sentence_source": "generated"}, {"text": "カタツムリは殻の中に隠れました。", "target_word": "殻", "complexity_tier": "T3", "furigana": "カタツムリは殻(から)の中(なか)に隠(かく)れました。", "sentence_source": "generated"}, {"text": "殻が厚いので、この実は割るのに時間がかかります。", "target_word": "殻", "complexity_tier": "T3", "furigana": "殻(から)が厚(あつ)いので、この実(み)は割(わ)るのに時間(じかん)がかかります。", "sentence_source": "generated"}, {"text": "ひよこは小さな殻を破って、外に出てきました。", "target_word": "殻", "complexity_tier": "T3", "furigana": "ひよこは小(ちい)さな殻(から)を破(やぶ)って、外(そと)に出(で)てきました。", "sentence_source": "generated"}, {"text": "殻を捨てるために、小さなごみ袋を用意しました。", "target_word": "殻", "complexity_tier": "T3", "furigana": "殻(から)を捨(す)てるために、小(ちい)さなごみ袋(ぶくろ)を用意(ようい)しました。", "sentence_source": "generated"}, {"text": "亀は固い殻で、体を守っています。", "target_word": "殻", "complexity_tier": "T3", "furigana": "亀(かめ)は固(かた)い殻(から)で、体(からだ)を守(まも)っています。", "sentence_source": "generated"}, {"text": "海辺で白い殻を拾って、友達に見せました。", "target_word": "殻", "complexity_tier": "T3", "furigana": "海辺(うみべ)で白(しろ)い殻(から)を拾(ひろ)って、友達(ともだち)に見(み)せました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "殻", "label": "基本形"}], "register": "丁寧な日常語", "sense_fingerprint": "卵・カニ・実・動物などの外側を包む固い部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e600720-6c23-4799-8dcf-cf155a991805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36894, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "殻", "is_correct": true, "explanation": "「卵の殻を割る」が自然。空欄に入るのは卵を覆う固い外側の殻だけ。"}, {"text": "窓", "is_correct": false, "explanation": "「卵の窓を割る」は成り立たない。窓は卵の外側ではない。"}, {"text": "鍵", "is_correct": false, "explanation": "卵の一部ではないので、「卵の鍵を割る」は意味が通らない。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は卵に含まれないので、「卵の椅子を割る」は不自然。"}], "explanations": {"殻": "「卵の殻を割る」が自然。空欄に入るのは卵を覆う固い外側の殻だけ。", "窓": "「卵の窓を割る」は成り立たない。窓は卵の外側ではない。", "鍵": "卵の一部ではないので、「卵の鍵を割る」は意味が通らない。", "椅子": "椅子は卵に含まれないので、「卵の椅子を割る」は不自然。"}, "sentence_index": 0, "correct_answer": "殻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "さんまの殻をうろこ取りでこすって、きれいにした。", "explanation": "ここは〈うろこ〉の意味。魚の体表を覆うのはうろこで、殻とは言わないので合わない。"}, {"text": "じゃがいもの殻をむいてから、鍋に入れた。", "explanation": "ここは〈皮〉の意味。じゃがいもは皮をむくもので、殻とは言わない。"}, {"text": "キャンディーの殻をはがして、口に入れた。", "explanation": "ここは〈包み紙〉の意味。キャンディーの包装ははがすもので、殻とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36894, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "殻", "is_correct": true, "explanation": "「小さな殻を破って出てくる」が自然。空欄に入るのは卵の殻だけ。"}, {"text": "猫", "is_correct": false, "explanation": "猫は破るものではないので、「小さな猫を破る」は成り立たない。"}, {"text": "花", "is_correct": false, "explanation": "「小さな花を破って出てくる」は不自然で、卵から出る文脈に合わない。"}, {"text": "山", "is_correct": false, "explanation": "山を破るという動作は文脈に合わず、ひよこが出てくる話とは結びつかない。"}], "explanations": {"殻": "「小さな殻を破って出てくる」が自然。空欄に入るのは卵の殻だけ。", "猫": "猫は破るものではないので、「小さな猫を破る」は成り立たない。", "花": "「小さな花を破って出てくる」は不自然で、卵から出る文脈に合わない。", "山": "山を破るという動作は文脈に合わず、ひよこが出てくる話とは結びつかない。"}, "sentence_index": 6, "correct_answer": "殻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "瓶の殻を回して開け、ジャムを取り出した。", "explanation": "ここは〈ふた〉の意味。瓶のふたは殻とは呼ばないので合わない。"}, {"text": "スナック菓子の殻を開けて、友達と分けた。", "explanation": "ここは〈袋〉の意味。菓子を包む袋は殻ではないので、開けるものとしては合わない。"}, {"text": "眼鏡を殻に入れて、かばんにしまった。", "explanation": "ここは〈ケース〉の意味。眼鏡を入れるのはケースで、殻には入れない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36894, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "固ゆで卵の殻に、指でむきました。", "corrected_sentence": "固ゆで卵の殻を、指でむきました。", "error_description": "「むく」の対象は「殻を」で示すべきところを、場所を表す「に」にしているため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36894, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "カニの殻を割れて、中身を取り出しました。", "corrected_sentence": "カニの殻を割って、中身を取り出しました。", "error_description": "「殻を」と続くので、他動詞の「割る」を使うべきところを自動詞の「割れる」の活用形にしている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36895, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「くるみの殻が固い」の「が」。殻の状態の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すので、「殻を固くて」という形にならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や所在を示すので、固さの主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、殻の固さの主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「くるみの殻が固い」の「が」。殻の状態の主語を示す。", "を": "「を」は動作の対象を示すので、「殻を固くて」という形にならない。", "に": "「に」は到達点や所在を示すので、固さの主語にはならない。", "で": "「で」は手段や場所を示すので、殻の固さの主語にはならない。"}, "error_tags": {"を": "対象を示す", "に": "到達点・所在を示す", "で": "手段・場所を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36895, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「貝の殻がたくさん落ちていた」の「が」。落ちている主語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すので、落ちている主語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示すので、落ちている動作の主語にはならない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すが、落ちるという動作は目的語を取らないので不自然。"}], "correct_answer": "が", "explanations": {"が": "「貝の殻がたくさん落ちていた」の「が」。落ちている主語を示す。", "と": "「と」は並列を示すので、落ちている主語にはならない。", "の": "「の」は所属や修飾を示すので、落ちている動作の主語にはならない。", "を": "「を」は動作の対象を示すが、落ちるという動作は目的語を取らないので不自然。"}, "error_tags": {"と": "並列を示す", "の": "所属・修飾を示す", "を": "対象を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36895, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物の表面を覆っている、かたくて丈夫な部分。特に、卵や木の実、貝などの外側の固い皮。", "primary_collocate": null, "pronunciation": "から", "ipa": "kaɾa", "syllable_count": 2, "sentences": [{"text": "ゆで卵の殻は、水で冷やすとむきやすいです。", "target_word": "殻", "complexity_tier": "T3", "furigana": "ゆで卵(たまご)の殻(から)は、水(みず)で冷(ひ)やすとむきやすいです。", "sentence_source": "generated"}, {"text": "くるみの殻が固くて、道具がないと割れません。", "target_word": "殻", "complexity_tier": "T3", "furigana": "くるみの殻(から)が固(かた)くて、道具(どうぐ)がないと割(わ)れません。", "sentence_source": "generated"}, {"text": "貝は殻を閉じて、危険から身を守ります。", "target_word": "殻", "complexity_tier": "T3", "furigana": "貝(かい)は殻(から)を閉(と)じて、危険(きけん)から身(み)を守(まも)ります。", "sentence_source": "generated"}, {"text": "えびの殻をむいて、天ぷらにしました。", "target_word": "殻", "complexity_tier": "T3", "furigana": "えびの殻(から)をむいて、天(てん)ぷらにしました。", "sentence_source": "generated"}, {"text": "栗の殻を割ったら、中から実が出てきました。", "target_word": "殻", "complexity_tier": "T3", "furigana": "栗(くり)の殻(から)を割(わ)ったら、中(なか)から実(み)が出(で)てきました。", "sentence_source": "generated"}, {"text": "鳥の卵は殻が薄いので、落とすとすぐ割れます。", "target_word": "殻", "complexity_tier": "T3", "furigana": "鳥(とり)の卵(たまご)は殻(から)が薄(うす)いので、落(お)とすとすぐ割(わ)れます。", "sentence_source": "generated"}, {"text": "割った殻が料理に入らないよう、気をつけました。", "target_word": "殻", "complexity_tier": "T3", "furigana": "割(わ)った殻(から)が料理(りょうり)に入(はい)らないよう、気(き)をつけました。", "sentence_source": "generated"}, {"text": "海岸には貝の殻がたくさん落ちていました。", "target_word": "殻", "complexity_tier": "T3", "furigana": "海岸(かいがん)には貝(かい)の殻(から)がたくさん落(お)ちていました。", "sentence_source": "generated"}, {"text": "割った卵の殻を、肥料にして庭にまきました。", "target_word": "殻", "complexity_tier": "T3", "furigana": "割(わ)った卵(たまご)の殻(から)を、肥料(ひりょう)にして庭(にわ)にまきました。", "sentence_source": "generated"}, {"text": "卵の殻の内側には、薄い膜があります。", "target_word": "殻", "complexity_tier": "T3", "furigana": "卵(たまご)の殻(から)の内側(うちがわ)には、薄(うす)い膜(まく)があります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "殻", "label": "基本形"}], "register": "丁寧な日常語", "sense_fingerprint": "卵・木の実・貝・えびなどの中身を覆う固い外皮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e600720-6c23-4799-8dcf-cf155a991805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36895, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "殻", "is_correct": true, "explanation": "「ゆで卵の殻はむきやすい」が自然。空欄に入るのは卵の外側の殻だけ。"}, {"text": "机", "is_correct": false, "explanation": "机は卵の一部ではなく、「ゆで卵の机は」と続けても意味が通らない。"}, {"text": "帽子", "is_correct": false, "explanation": "帽子は卵に含まれないので、「ゆで卵の帽子は」は成り立たない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は卵の部位ではないので、「ゆで卵の時計は」は意味が通らない。"}], "explanations": {"殻": "「ゆで卵の殻はむきやすい」が自然。空欄に入るのは卵の外側の殻だけ。", "机": "机は卵の一部ではなく、「ゆで卵の机は」と続けても意味が通らない。", "帽子": "帽子は卵に含まれないので、「ゆで卵の帽子は」は成り立たない。", "時計": "時計は卵の部位ではないので、「ゆで卵の時計は」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "殻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鯛の殻を、うろこ取りでこすって落とした。", "explanation": "ここは〈うろこ〉の意味。魚の体表を覆うのはうろこで、殻とは言わないので合わない。"}, {"text": "みかんの殻をむいて、房を取り出した。", "explanation": "ここは〈皮〉の意味。みかんは皮をむくもので、殻とは言わない。"}, {"text": "チョコレートの殻をはがして、口に入れた。", "explanation": "ここは〈包み紙〉の意味。チョコレートの包装は殻ではなく、はがすのは包み紙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36895, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "殻", "is_correct": true, "explanation": "「割った殻が料理に入らない」が自然。空欄に入るのは卵や貝の固い外側の殻だけ。"}, {"text": "猫", "is_correct": false, "explanation": "猫は割った殻とは関係なく、「割った猫が料理に入る」は成り立たない。"}, {"text": "花", "is_correct": false, "explanation": "花は料理に入る物ではないので、「割った花が料理に入る」は不自然。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は料理に入る物ではなく、「割った椅子が料理に入る」は意味が通らない。"}], "explanations": {"殻": "「割った殻が料理に入らない」が自然。空欄に入るのは卵や貝の固い外側の殻だけ。", "猫": "猫は割った殻とは関係なく、「割った猫が料理に入る」は成り立たない。", "花": "花は料理に入る物ではないので、「割った花が料理に入る」は不自然。", "椅子": "椅子は料理に入る物ではなく、「割った椅子が料理に入る」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "殻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鍋の殻を外して、湯気を逃がした。", "explanation": "ここは〈ふた〉の意味。鍋のふたは殻とは呼ばないので合わない。"}, {"text": "豆腐の殻を開けて、醤油をかけた。", "explanation": "ここは〈パック〉の意味。豆腐を入れるのはパックで、殻とは呼ばないので合わない。"}, {"text": "ヨーグルトを殻に入れて、冷蔵庫で冷やした。", "explanation": "ここは〈カップ〉の意味。ヨーグルトを入れるのはカップで、殻には入れないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36895, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "えびの殻が、指先で少しずつむきました。", "corrected_sentence": "えびの殻を、指先で少しずつむきました。", "error_description": "「むく」の対象は「殻を」で示すべきところを、主語の「が」にしているため、殻が自分でむいたことになって誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36895, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海で貝の殻を三本拾いました。", "corrected_sentence": "海で貝の殻を三個拾いました。", "error_description": "貝殻を数えるには「個」が普通で、「本」は細長い物に使う助数詞なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5015c9e2-0426-4fd9-b8fc-63f3bcb7867c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36896, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『材料に加える』の『に』。加える先を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。『材料が加えてもいい』では材料が動作主になり、意味が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。比べる文脈がなく、『材料より加える』は不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。『材料から加える』は材料から取り出す意味になり、方向が逆になる。"}], "correct_answer": "に", "explanations": {"に": "『材料に加える』の『に』。加える先を示す。", "が": "主語を示す。『材料が加えてもいい』では材料が動作主になり、意味が成り立たない。", "より": "比較を示す。比べる文脈がなく、『材料より加える』は不自然。", "から": "起点を示す。『材料から加える』は材料から取り出す意味になり、方向が逆になる。"}, "error_tags": {"が": "主語（動作主と不一致）", "より": "比較（比べる対象なし）", "から": "起点（方向が逆）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
