INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36896, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "くずやごみなどを、何かの中に入れることです。", "primary_collocate": null, "pronunciation": "くわえる", "ipa": "kɯwaeɾɯ", "syllable_count": 4, "sentences": [{"text": "野菜のくずを堆肥の箱に加えると、数か月で土になる。", "target_word": "加える", "complexity_tier": "T3", "furigana": "野菜[やさい]のくずを堆肥[たいひ]の箱[はこ]に加[くわ]えると、数[すう]か月[げつ]で土[つち]になる。", "sentence_source": "generated"}, {"text": "使い終わった茶がらは、堆肥の材料に加えてもいい。", "target_word": "加えても", "complexity_tier": "T3", "furigana": "使[つか]い終[お]わった茶[ちゃ]がらは、堆肥[たいひ]の材料[ざいりょう]に加[くわ]えてもいい。", "sentence_source": "generated"}, {"text": "庭の雑草は、堆肥の箱に加える前によく乾かしてください。", "target_word": "加える", "complexity_tier": "T3", "furigana": "庭[にわ]の雑草[ざっそう]は、堆肥[たいひ]の箱[はこ]に加[くわ]える前[まえ]によく乾[かわ]かしてください。", "sentence_source": "generated"}, {"text": "燃えないものは堆肥に加えないでください。ガラスや金属が混ざるからです。", "target_word": "加えないで", "complexity_tier": "T3", "furigana": "燃[も]えないものは堆肥[たいひ]に加[くわ]えないでください。ガラスや金属[きんぞく]が混[ま]ざるからです。", "sentence_source": "generated"}, {"text": "卵のからを花壇の土に加えると、植物の栄養になる。", "target_word": "加える", "complexity_tier": "T3", "furigana": "卵[たまご]のからを花壇[かだん]の土[つち]に加[くわ]えると、植物[しょくぶつ]の栄養[えいよう]になる。", "sentence_source": "generated"}, {"text": "切った草は水分が多いため、乾かしてから堆肥に加えるとよい。", "target_word": "加える", "complexity_tier": "T3", "furigana": "切[き]った草[くさ]は水分[すいぶん]が多[おお]いため、乾[かわ]かしてから堆肥[たいひ]に加[くわ]えるとよい。", "sentence_source": "generated"}, {"text": "落ち葉を箱に加えるたびに、中の土がふわふわになった。", "target_word": "加える", "complexity_tier": "T3", "furigana": "落[お]ち葉[ば]を箱[はこ]に加[くわ]えるたびに、中[なか]の土[つち]がふわふわになった。", "sentence_source": "generated"}, {"text": "古い新聞紙も少し加えれば、生ごみの水分が減る。", "target_word": "加えれば", "complexity_tier": "T3", "furigana": "古[ふる]い新聞紙[しんぶんし]も少[すこ]し加[くわ]えれば、生[なま]ごみの水分[すいぶん]が減[へ]る。", "sentence_source": "generated"}, {"text": "魚の骨を堆肥に加えるのは、においが強くなるので避けたほうがいい。", "target_word": "加える", "complexity_tier": "T3", "furigana": "魚[さかな]の骨[ほね]を堆肥[たいひ]に加[くわ]えるのは、においが強[つよ]くなるので避[さ]けたほうがいい。", "sentence_source": "generated"}, {"text": "祖父は毎朝、台所のくずを堆肥の箱に加えている。", "target_word": "加えている", "complexity_tier": "T3", "furigana": "祖父[そふ]は毎朝[まいあさ]、台所[だいどころ]のくずを堆肥[たいひ]の箱[はこ]に加[くわ]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "加える", "label": "辞書形"}, {"form": "加えた", "label": "過去形"}, {"form": "加えて", "label": "て形"}, {"form": "加えない", "label": "否定形"}, {"form": "加えれば", "label": "仮定形"}, {"form": "加えよう", "label": "意志形"}, {"form": "加えられる", "label": "受身形"}], "register": "中立", "sense_fingerprint": "くずやごみなどを容器や穴などの中に入れる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: 茶がら (Zipf 1.03)']::text[], 'e6723961-33ca-4712-8f1a-8170a5f30020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36896, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加える", "is_correct": true, "explanation": "くずを容器の中に入れる意味で、後ろの『〜と、数か月で土になる』の条件節に合う。"}, {"text": "眺める", "is_correct": false, "explanation": "見る意味になり、くずを箱に入れる作業とは合わない。"}, {"text": "凍らせる", "is_correct": false, "explanation": "冷やして固める意味になり、堆肥の材料を入れる文脈に合わない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "箱に向かって声を出す意味になり、材料を入れる文として成立しない。"}], "explanations": {"加える": "くずを容器の中に入れる意味で、後ろの『〜と、数か月で土になる』の条件節に合う。", "眺める": "見る意味になり、くずを箱に入れる作業とは合わない。", "凍らせる": "冷やして固める意味になり、堆肥の材料を入れる文脈に合わない。", "叫ぶ": "箱に向かって声を出す意味になり、材料を入れる文として成立しない。"}, "sentence_index": 0, "correct_answer": "加える"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "堆肥の箱の中身を、くわでよく加えて空気を入れる。", "explanation": "〈かき混ぜる〉と混同した形。『加える』はくずを何かの中に入れる意味で、かき混ぜる動作には使わない。"}, {"text": "堆肥の箱の上に、くずを加えて板でふたをする。", "explanation": "〈上に載せる〉と混同した形。『加える』は何かの中に入れる意味で、上に置く動作には使わない。"}, {"text": "堆肥の箱から、傷んだ野菜を加える。", "explanation": "〈取り除く〉と混同した形。『加える』は中へ入れる意味で、箱から取り出す動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36896, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加える", "is_correct": true, "explanation": "くずを箱に入れる意味で、『〜たびに』に続く形として文が成立する。"}, {"text": "磨く", "is_correct": false, "explanation": "表面をみがく動作で、落ち葉を箱に入れる文脈に合わない。"}, {"text": "歌う", "is_correct": false, "explanation": "声を出す動作で、落ち葉を箱に入れる行為とは合わない。"}, {"text": "笑う", "is_correct": false, "explanation": "感情の表現で、物を箱に入れる文として成立しない。"}], "explanations": {"加える": "くずを箱に入れる意味で、『〜たびに』に続く形として文が成立する。", "磨く": "表面をみがく動作で、落ち葉を箱に入れる文脈に合わない。", "歌う": "声を出す動作で、落ち葉を箱に入れる行為とは合わない。", "笑う": "感情の表現で、物を箱に入れる文として成立しない。"}, "sentence_index": 6, "correct_answer": "加える"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "落ち葉を箱の周りに加えて、雨にぬらす。", "explanation": "〈まき散らす〉と混同した形。『加える』は中へ入れる意味で、箱の周りに撒く動作には使わない。"}, {"text": "くずを紙で加えて、箱に入れる。", "explanation": "〈包む〉と混同した形。『加える』は何かの中へ入れる意味で、紙で覆う動作には使わない。"}, {"text": "箱の下に木くずを加えて、通気をよくする。", "explanation": "〈敷く〉と混同した形。『加える』は中へ入れる意味で、箱の下に広げる動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36896, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "枯れ葉を堆肥の箱を加えると、三週間で土になる。", "corrected_sentence": "枯れ葉を堆肥の箱に加えると、三週間で土になる。", "error_description": "『加える』は入れる先を『に』で表す。『箱を』は誤りで、正しくは『箱に』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "加えても", "is_correct": true, "explanation": "て形＋も。『〜てもいい』で許可を表す形で、文中の形と一致する。"}, {"text": "加えた", "is_correct": false, "explanation": "過去形。『〜てもいい』の許可の形にならず、文が合わない。"}, {"text": "加えない", "is_correct": false, "explanation": "否定形。『加えなくてもいい』となり、文の意味が逆になる。"}, {"text": "加えられる", "is_correct": false, "explanation": "受け身・可能の形。主語が変わり、『材料に加えてもいい』の文が成り立たない。"}], "correct_form": "加えても", "base_form": "加える", "form_label": "て形＋も（許可）", "sentence_index": 1, "explanations": {"加えても": "て形＋も。『〜てもいい』で許可を表す形で、文中の形と一致する。", "加えた": "過去形。『〜てもいい』の許可の形にならず、文が合わない。", "加えない": "否定形。『加えなくてもいい』となり、文の意味が逆になる。", "加えられる": "受け身・可能の形。主語が変わり、『材料に加えてもいい』の文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36896, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭の落ち葉を箱に加えたたびに、中の土がふわふわになる。", "corrected_sentence": "庭の落ち葉を箱に加えるたびに、中の土がふわふわになる。", "error_description": "『〜たびに』は辞書形に続く。『加えた』の過去形は誤りで、正しくは『加えるたびに』。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "加えれば", "is_correct": true, "explanation": "仮定形（〜ば）。『加えれば〜なる』の条件を表す形で、文中の形と一致する。"}, {"text": "加えるば", "is_correct": false, "explanation": "活用として成り立たない形。条件の『〜ば』は仮定形に続き、辞書形には続かない。"}, {"text": "加えよう", "is_correct": false, "explanation": "意志形。自分の意向を表し、条件文には合わない。"}, {"text": "加えている", "is_correct": false, "explanation": "〜ている形。継続や状態を表し、『〜れば減る』の条件に合わない。"}], "correct_form": "加えれば", "base_form": "加える", "form_label": "仮定形（〜ば）", "sentence_index": 7, "explanations": {"加えれば": "仮定形（〜ば）。『加えれば〜なる』の条件を表す形で、文中の形と一致する。", "加えるば": "活用として成り立たない形。条件の『〜ば』は仮定形に続き、辞書形には続かない。", "加えよう": "意志形。自分の意向を表し、条件文には合わない。", "加えている": "〜ている形。継続や状態を表し、『〜れば減る』の条件に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36897, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『砂糖を加える』の『を』。加える対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。『砂糖が加えて』では砂糖が動作主になり、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。比べる文脈がなく不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す。『砂糖で加える』は砂糖を道具にする不自然な文になる。"}], "correct_answer": "を", "explanations": {"を": "『砂糖を加える』の『を』。加える対象を示す。", "が": "主語を示す。『砂糖が加えて』では砂糖が動作主になり、文が成り立たない。", "より": "比較を示す。比べる文脈がなく不自然。", "で": "手段を示す。『砂糖で加える』は砂糖を道具にする不自然な文になる。"}, "error_tags": {"が": "主語（動作主と不一致）", "より": "比較（比べる対象なし）", "で": "手段（道具として不自然）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36897, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『文章に一行加える』の『に』。加える先を示す。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す。一行を文章と並べる意味にならず不自然。"}, {"text": "の", "is_correct": false, "explanation": "修飾を示す。『文章の一行』は加える先を示せず成立しない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。『文章から一行加える』は文章から取り出す意味になり逆になる。"}], "correct_answer": "に", "explanations": {"に": "『文章に一行加える』の『に』。加える先を示す。", "と": "並列を示す。一行を文章と並べる意味にならず不自然。", "の": "修飾を示す。『文章の一行』は加える先を示せず成立しない。", "から": "起点を示す。『文章から一行加える』は文章から取り出す意味になり逆になる。"}, "error_tags": {"と": "並列（比べる対象なし）", "の": "修飾（加える先を示せない）", "から": "起点（方向が逆）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36897, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある物の中に別の物を入れたり、新しい要素を付け加えたりすること。", "primary_collocate": null, "pronunciation": "くわえる", "ipa": "kɯwaeɾɯ", "syllable_count": 4, "sentences": [{"text": "味が薄かったので、塩を少し加えた。", "target_word": "加えた", "complexity_tier": "T3", "furigana": "味[あじ]が薄[うす]かったので、塩[しお]を少[すこ]し加[くわ]えた。", "sentence_source": "generated"}, {"text": "水に砂糖を加えて、よくかき混ぜる。", "target_word": "加えて", "complexity_tier": "T3", "furigana": "水[みず]に砂糖[さとう]を加[くわ]えて、よくかき混[ま]ぜる。", "sentence_source": "generated"}, {"text": "彼は計画に新しい案を加えた。", "target_word": "加えた", "complexity_tier": "T3", "furigana": "彼[かれ]は計画[けいかく]に新[あたら]しい案[あん]を加[くわ]えた。", "sentence_source": "generated"}, {"text": "色が足りないので、赤を少し加えてみよう。", "target_word": "加えて", "complexity_tier": "T3", "furigana": "色[いろ]が足[た]りないので、赤[あか]を少[すこ]し加[くわ]えてみよう。", "sentence_source": "generated"}, {"text": "先生は説明にいくつか例を加えてくれた。", "target_word": "加えて", "complexity_tier": "T3", "furigana": "先生[せんせい]は説明[せつめい]にいくつか例[れい]を加[くわ]えてくれた。", "sentence_source": "generated"}, {"text": "このカレーにはりんごを加えると、甘みが出る。", "target_word": "加える", "complexity_tier": "T3", "furigana": "このカレーにはりんごを加[くわ]えると、甘[あま]みが出[で]る。", "sentence_source": "generated"}, {"text": "会議のメンバーに新人を加えることになった。", "target_word": "加える", "complexity_tier": "T3", "furigana": "会議[かいぎ]のメンバーに新人[しんじん]を加[くわ]えることになった。", "sentence_source": "generated"}, {"text": "文章に一行加えるだけで、意味がはっきりした。", "target_word": "加える", "complexity_tier": "T3", "furigana": "文章[ぶんしょう]に一行[いちぎょう]加[くわ]えるだけで、意味[いみ]がはっきりした。", "sentence_source": "generated"}, {"text": "小麦粉に牛乳を加えれば、生地がやわらかくなる。", "target_word": "加えれば", "complexity_tier": "T3", "furigana": "小麦粉[こむぎこ]に牛乳[ぎゅうにゅう]を加[くわ]えれば、生地[きじ]がやわらかくなる。", "sentence_source": "generated"}, {"text": "曲の最後に鈴の音を加えたら、にぎやかな雰囲気になった。", "target_word": "加えた", "complexity_tier": "T3", "furigana": "曲[きょく]の最後[さいご]に鈴[すず]の音[おと]を加[くわ]えたら、にぎやかな雰囲気[ふんいき]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "加える", "label": "辞書形"}, {"form": "加えた", "label": "過去形"}, {"form": "加えて", "label": "て形"}, {"form": "加えない", "label": "否定形"}, {"form": "加えれば", "label": "仮定形"}, {"form": "加えよう", "label": "意志形"}, {"form": "加えられる", "label": "受身形"}], "register": "中立", "sense_fingerprint": "材料や要素などを今あるものに足して一緒にする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6723961-33ca-4712-8f1a-8170a5f30020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36897, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加えた", "is_correct": true, "explanation": "過去形で、塩を入れた行為を表し、味が薄かった理由に続く文として成立する。"}, {"text": "見上げた", "is_correct": false, "explanation": "上を向く意味になり、塩を入れる文脈に合わない。"}, {"text": "凍らせた", "is_correct": false, "explanation": "冷やして固める意味になり、味を整える文脈に合わない。"}, {"text": "怒った", "is_correct": false, "explanation": "感情を表す語で、食材の調味の文脈に合わない。"}], "explanations": {"加えた": "過去形で、塩を入れた行為を表し、味が薄かった理由に続く文として成立する。", "見上げた": "上を向く意味になり、塩を入れる文脈に合わない。", "凍らせた": "冷やして固める意味になり、味を整える文脈に合わない。", "怒った": "感情を表す語で、食材の調味の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "加えた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鍋から野菜を加えて、よく混ぜる。", "explanation": "〈取り出す〉と混同した形。『加える』は別のものに足す意味で、鍋から取り出す動作には使わない。"}, {"text": "相手を加えて、試合に勝った。", "explanation": "〈倒す〉と混同した形。『加える』は要素を付け足す意味で、相手を負かす動作には使わない。"}, {"text": "体重を加えるために、毎日よく食べる。", "explanation": "〈増やす〉と混同した形。体重を増やすのは『増やす』で言い、『加える』では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36897, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加える", "is_correct": true, "explanation": "新人を会議に入れる意味で、『〜ことになった』に続く形として文が成立する。"}, {"text": "磨く", "is_correct": false, "explanation": "表面をみがく動作で、人を会議に入れる文脈に合わない。"}, {"text": "歌う", "is_correct": false, "explanation": "声を出す動作で、メンバーの加入の文脈に合わない。"}, {"text": "笑う", "is_correct": false, "explanation": "感情の表現で、人事の決定を表す文に合わない。"}], "explanations": {"加える": "新人を会議に入れる意味で、『〜ことになった』に続く形として文が成立する。", "磨く": "表面をみがく動作で、人を会議に入れる文脈に合わない。", "歌う": "声を出す動作で、メンバーの加入の文脈に合わない。", "笑う": "感情の表現で、人事の決定を表す文に合わない。"}, "sentence_index": 6, "correct_answer": "加える"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は作品の完成度を加えて、評判を高めた。", "explanation": "〈上げる〉と混同した形。完成度は上げるもので、『加える』とは言わない。"}, {"text": "睡眠の不足を加えて、体調を整えた。", "explanation": "〈補う〉と混同した形。不足は埋めるもので、加えるものではないため合わない。"}, {"text": "赤ちゃんの歯を加えるごとに、よく泣いた。", "explanation": "〈生える〉と混同した形。歯は生えるもので、加えるものではないため合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36897, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鍋に野菜を加えに、よくかき混ぜる。", "corrected_sentence": "鍋に野菜を加えて、よくかき混ぜる。", "error_description": "『加えて』は『て』で後の動作へつなぐ形。『加えに』は文法上誤りで、正しくは『加えて』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "加えて", "is_correct": true, "explanation": "て形。『加えて、よく混ぜる』という手順の流れに合う。"}, {"text": "加えない", "is_correct": false, "explanation": "否定形。手順を否定して『加えずに混ぜる』となり、文の内容が変わる。"}, {"text": "加えられる", "is_correct": false, "explanation": "受け身の形。砂糖が主語になり、手順の説明として合わない。"}, {"text": "加えよう", "is_correct": false, "explanation": "意志形。意向を表し、手順の説明に合わない。"}], "correct_form": "加えて", "base_form": "加える", "form_label": "て形", "sentence_index": 1, "explanations": {"加えて": "て形。『加えて、よく混ぜる』という手順の流れに合う。", "加えない": "否定形。手順を否定して『加えずに混ぜる』となり、文の内容が変わる。", "加えられる": "受け身の形。砂糖が主語になり、手順の説明として合わない。", "加えよう": "意志形。意向を表し、手順の説明に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36897, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "クラスを転校生を加えることになった。", "corrected_sentence": "クラスに転校生を加えることになった。", "error_description": "『加える』は受け取る先を『に』で表す。『クラスを』は誤りで、正しくは『クラスに』。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "加える", "is_correct": true, "explanation": "辞書形。『加えるだけで』と続き、名詞修飾の基本形として文が成立する。"}, {"text": "加えて", "is_correct": false, "explanation": "て形。『加えてだけで』とは続かず、文として成り立たない。"}, {"text": "加えれば", "is_correct": false, "explanation": "仮定形。『加えればだけで』は条件として続かず不自然。"}, {"text": "加えよう", "is_correct": false, "explanation": "意志形。『加えようだけで』とは続かず、文として成り立たない。"}], "correct_form": "加える", "base_form": "加える", "form_label": "辞書形", "sentence_index": 7, "explanations": {"加える": "辞書形。『加えるだけで』と続き、名詞修飾の基本形として文が成立する。", "加えて": "て形。『加えてだけで』とは続かず、文として成り立たない。", "加えれば": "仮定形。『加えればだけで』は条件として続かず不自然。", "加えよう": "意志形。『加えようだけで』とは続かず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
