INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36898, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "何かが、とてもたくさんあること。", "primary_collocate": null, "pronunciation": "たっぷり", "ipa": "tappɯɾi", "syllable_count": 4, "sentences": [{"text": "今日は時間がたっぷりあるので、ゆっくり買い物ができます。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "今日[きょう]は時間[じかん]がたっぷりあるので、ゆっくり買[か]い物[もの]ができます。", "sentence_source": "generated"}, {"text": "休みの日は、たっぷり寝て元気になりました。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]は、たっぷり寝[ね]て元気[げんき]になりました。", "sentence_source": "generated"}, {"text": "夏の間にたっぷり遊んだので、宿題が終わりません。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "夏[なつ]の間[あいだ]にたっぷり遊[あそ]んだので、宿題[しゅくだい]が終[お]わりません。", "sentence_source": "generated"}, {"text": "駅まで三十分もあるから、時間はたっぷりあるよ。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "駅[えき]まで三十分[さんじゅっぷん]もあるから、時間[じかん]はたっぷりあるよ。", "sentence_source": "generated"}, {"text": "祖母は、朝からたっぷり眠ったそうです。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、朝[あさ]からたっぷり眠[ねむ]ったそうです。", "sentence_source": "generated"}, {"text": "この町には、見る場所がたっぷりあります。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "この町[まち]には、見[み]る場所[ばしょ]がたっぷりあります。", "sentence_source": "generated"}, {"text": "祖父は昔の話をたっぷり聞かせてくれました。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "祖父[そふ]は昔[むかし]の話[はなし]をたっぷり聞[き]かせてくれました。", "sentence_source": "generated"}, {"text": "試験の前に、水をたっぷり飲んで落ち着きました。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]に、水[みず]をたっぷり飲[の]んで落[お]ち着[つ]きました。", "sentence_source": "generated"}, {"text": "彼は貯金がたっぷりあるので、心配していません。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "彼[かれ]は貯金[ちょきん]がたっぷりあるので、心配[しんぱい]していません。", "sentence_source": "generated"}, {"text": "明日は朝からたっぷり練習するつもりです。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "明日[あした]は朝[あさ]からたっぷり練習[れんしゅう]するつもりです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "たっぷり", "label": "基本形"}, {"form": "たっぷりの", "label": "連体形"}], "register": "colloquial", "sense_fingerprint": "plenty: time, money, sleep or other amounts being abundant, with room to spare", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ccc050-8e2e-4945-adb4-0419425842d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36898, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "たっぷり", "is_correct": true, "explanation": "正解。「時間がたっぷりある」は十分に多いことを表し、自然。"}, {"text": "すぐ", "is_correct": false, "explanation": "「時間がすぐある」は不自然。量の多さを表す語ではない。"}, {"text": "すっかり", "is_correct": false, "explanation": "「すっかり」は完全にの意味で、時間の量を表す文には合わない。"}, {"text": "まるで", "is_correct": false, "explanation": "「まるで」は比喩で、「時間がまるである」は文が成り立たない。"}], "explanations": {"たっぷり": "正解。「時間がたっぷりある」は十分に多いことを表し、自然。", "すぐ": "「時間がすぐある」は不自然。量の多さを表す語ではない。", "すっかり": "「すっかり」は完全にの意味で、時間の量を表す文には合わない。", "まるで": "「まるで」は比喩で、「時間がまるである」は文が成り立たない。"}, "sentence_index": 0, "correct_answer": "たっぷり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お茶をたっぷり一滴だけ入れました。", "explanation": "ここは〈わずか〉の意味。たっぷりは多い量を表すので、一滴だけという少量とは矛盾する。"}, {"text": "この靴は足にたっぷり合います。", "explanation": "ここは〈ぴったり〉（ずれずに合う）の意味。たっぷりは量が多いことなので、足の大きさにぴたりと合う状態には合わない。"}, {"text": "寝坊して、朝の準備がたっぷり終わりました。", "explanation": "ここは〈すっかり〉（完全に）の意味。たっぷりは量の多さを表し、完了の完全さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36898, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "たっぷり", "is_correct": true, "explanation": "正解。「昔の話をたっぷり聞かせる」は話の量が多いことを表し、自然。"}, {"text": "まったく", "is_correct": false, "explanation": "「まったく聞かせる」は意味が逆になり、不自然。"}, {"text": "きっぱり", "is_correct": false, "explanation": "「きっぱり」は断定の意味で、話を聞かせる行為には合わない。"}, {"text": "うっかり", "is_correct": false, "explanation": "「うっかり」は不注意の意味で、話を聞かせる行為とは合わない。"}], "explanations": {"たっぷり": "正解。「昔の話をたっぷり聞かせる」は話の量が多いことを表し、自然。", "まったく": "「まったく聞かせる」は意味が逆になり、不自然。", "きっぱり": "「きっぱり」は断定の意味で、話を聞かせる行為には合わない。", "うっかり": "「うっかり」は不注意の意味で、話を聞かせる行為とは合わない。"}, "sentence_index": 6, "correct_answer": "たっぷり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車がたっぷり八時に出発しました。", "explanation": "ここは〈きっかり〉（時刻ぴったり）の意味。たっぷりは量が多いことなので、時刻を表すきっかりの意味には合わない。"}, {"text": "彼は話しかけられて、たっぷり振り向きました。", "explanation": "ここは〈ふと〉（一瞬だけ）の意味。たっぷりは長く多い量を表すので、ちらりと一瞬振り向く動作とは合わない。"}, {"text": "電車にたっぷり乗り損ねるところでした。", "explanation": "ここは〈危うく〉（もう少しで）の意味。たっぷりは十分な量を表すので、危ないところという状況には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36898, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末は時間がたっぷりのあるので、ゆっくり映画を見に行きます。", "corrected_sentence": "週末は時間がたっぷりあるので、ゆっくり映画を見に行きます。", "error_description": "「たっぷり」は「たっぷりある」と続ける。「たっぷりの」は名詞の前に付く形なので、「の」の後に「ある」は続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36898, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "お客さんに、お茶をたっぷりで出しました。", "corrected_sentence": "お客さんに、お茶をたっぷり出しました。", "error_description": "「たっぷり」は副詞で、後ろに「で」を付けると不自然になる。「お茶をたっぷり出す」と続ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
