INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36899, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "あるものが、必要な分よりも多く、十分に含まれているさま。", "primary_collocate": null, "pronunciation": "たっぷり", "ipa": "tappɯɾi", "syllable_count": 4, "sentences": [{"text": "このカレーは野菜がたっぷり入っていて、体にいいです。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "このカレーは野菜[やさい]がたっぷり入[はい]っていて、体[からだ]にいいです。", "sentence_source": "generated"}, {"text": "パンにバターをたっぷり塗って食べました。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "パンにバターをたっぷり塗[ぬ]って食[た]べました。", "sentence_source": "generated"}, {"text": "この果物にはビタミンがたっぷり含まれています。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "この果物[くだもの]にはビタミンがたっぷり含[ふく]まれています。", "sentence_source": "generated"}, {"text": "ケーキにクリームをたっぷりのせると、とても甘くなります。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "ケーキにクリームをたっぷりのせると、とても甘[あま]くなります。", "sentence_source": "generated"}, {"text": "日焼け止めをたっぷり塗らないと、肌が赤くなります。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "日焼[ひや]け止[ど]めをたっぷり塗[ぬ]らないと、肌[はだ]が赤[あか]くなります。", "sentence_source": "generated"}, {"text": "たっぷりのお湯でゆっくり麺をゆでます。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "たっぷりのお湯[ゆ]でゆっくり麺[めん]をゆでます。", "sentence_source": "generated"}, {"text": "この牛乳はカルシウムがたっぷり入っています。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "この牛乳[ぎゅうにゅう]はカルシウムがたっぷり入[はい]っています。", "sentence_source": "generated"}, {"text": "愛情たっぷりのお弁当を、母が作ってくれました。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "愛情[あいじょう]たっぷりのお弁当[べんとう]を、母[はは]が作[つく]ってくれました。", "sentence_source": "generated"}, {"text": "肉にたれをたっぷりつけて焼きました。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "肉[にく]にたれをたっぷりつけて焼[や]きました。", "sentence_source": "generated"}, {"text": "このスープには、クリームがたっぷり使われています。", "target_word": "たっぷり", "complexity_tier": "T3", "furigana": "このスープには、クリームがたっぷり使[つか]われています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "たっぷり", "label": "基本形"}, {"form": "たっぷりの", "label": "連体形"}], "register": "colloquial", "sense_fingerprint": "generously included: an ingredient or element contained or applied in a large, more than sufficient amount", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ccc050-8e2e-4945-adb4-0419425842d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36899, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "たっぷり", "is_correct": true, "explanation": "正解。「野菜がたっぷり入っている」は量が多いことを表し、自然。"}, {"text": "きっぱり", "is_correct": false, "explanation": "「きっぱり入っている」は断定の意味になり、材料の量には合わない。"}, {"text": "うっかり", "is_correct": false, "explanation": "「うっかり入っている」は不注意の意味で、材料の量を表せない。"}, {"text": "まったく", "is_correct": false, "explanation": "「まったく入っている」は否定と一緒に使う語で、肯定文では不自然。"}], "explanations": {"たっぷり": "正解。「野菜がたっぷり入っている」は量が多いことを表し、自然。", "きっぱり": "「きっぱり入っている」は断定の意味になり、材料の量には合わない。", "うっかり": "「うっかり入っている」は不注意の意味で、材料の量を表せない。", "まったく": "「まったく入っている」は否定と一緒に使う語で、肯定文では不自然。"}, "sentence_index": 0, "correct_answer": "たっぷり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は、ケーキを焼く途中でたっぷり立ち上がりました。", "explanation": "ここは〈突然〉（不意に）の意味。たっぷりは量が多いことなので、不意の動作とは合わない。"}, {"text": "ふたをたっぷり閉めました。", "explanation": "ここは〈きっちり〉（隙間なく）の意味。たっぷりは量のことなので、ふたの閉まり方には合わない。"}, {"text": "この箱はふたがたっぷり合います。", "explanation": "ここは〈ぴったり〉（ずれずに合う）の意味。たっぷりは量が多いことなので、ぴたりと合う状態には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36899, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "たっぷり", "is_correct": true, "explanation": "正解。「カルシウムがたっぷり入っている」は量が多いことを表し、自然。"}, {"text": "さっぱり", "is_correct": false, "explanation": "「さっぱり」は否定と一緒に使う語で、肯定文のここでは不自然。"}, {"text": "ずるずる", "is_correct": false, "explanation": "「ずるずる」は続く様子を表し、成分が入っている状態には合わない。"}, {"text": "ぴんと", "is_correct": false, "explanation": "「ぴんと」は張りつめた様子を表し、成分の量には合わない。"}], "explanations": {"たっぷり": "正解。「カルシウムがたっぷり入っている」は量が多いことを表し、自然。", "さっぱり": "「さっぱり」は否定と一緒に使う語で、肯定文のここでは不自然。", "ずるずる": "「ずるずる」は続く様子を表し、成分が入っている状態には合わない。", "ぴんと": "「ぴんと」は張りつめた様子を表し、成分の量には合わない。"}, "sentence_index": 6, "correct_answer": "たっぷり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスープは、ものの五分でたっぷり冷めました。", "explanation": "ここは〈さっと〉（短時間で）の意味。たっぷりは量が多いことなので、時間の短さを表すさっとの意味には合わない。"}, {"text": "このスープは、ちょうど十時にたっぷり仕上がりました。", "explanation": "ここは〈ちょうど〉（その時刻ぴったり）の意味。たっぷりは量のことで、時刻には使わない。"}, {"text": "このスープは、たっぷり軽くて、体にやさしいです。", "explanation": "ここは〈あっさり〉（くどくない）の意味。たっぷりは量が多いことなので、軽い味の性質とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36899, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このスープは玉ねぎがたっぷりの入っていて、甘いです。", "corrected_sentence": "このスープは玉ねぎがたっぷり入っていて、甘いです。", "error_description": "「たっぷりの」は名詞の前に付く形。「の」の後に「入っていて」は続かないので、「たっぷり入っていて」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36899, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "お茶にミルクがたっぷりの入っています。", "corrected_sentence": "お茶にミルクがたっぷり入っています。", "error_description": "「たっぷりの」は名詞の前に付く形。「の」の後に「入っています」は続かないので、「たっぷり入っています」とする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36900, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「掻き混ぜる」に直接続き、「混ぜると〜」という条件を作る。"}, {"text": "が", "is_correct": false, "explanation": "主語を表すが、「掻き混ぜが」では文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は「コーヒーを」に既に付いており、「掻き混ぜを」は続かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は動作の向きを示すが、ここでは続けられない。"}], "correct_answer": "と", "explanations": {"と": "「掻き混ぜる」に直接続き、「混ぜると〜」という条件を作る。", "が": "主語を表すが、「掻き混ぜが」では文が成り立たない。", "を": "目的語の「を」は「コーヒーを」に既に付いており、「掻き混ぜを」は続かない。", "へ": "方向の「へ」は動作の向きを示すが、ここでは続けられない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36900, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "も", "options": [{"text": "も", "is_correct": true, "explanation": "「掻き混ぜて」に直接付き、「〜ても」の譲歩を表す。"}, {"text": "に", "is_correct": false, "explanation": "「掻き混ぜてに」は続かず、文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞の前に来るので、「掻き混ぜての」は続かない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」は名詞に付くもので、「掻き混ぜてで」は続かない。"}], "correct_answer": "も", "explanations": {"も": "「掻き混ぜて」に直接付き、「〜ても」の譲歩を表す。", "に": "「掻き混ぜてに」は続かず、文として成り立たない。", "の": "連体修飾の「の」は名詞の前に来るので、「掻き混ぜての」は続かない。", "で": "手段の「で」は名詞に付くもので、「掻き混ぜてで」は続かない。"}, "error_tags": {"に": "位置・相手", "の": "連体修飾", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36900, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "まぜること。", "primary_collocate": null, "pronunciation": "かきまぜる", "ipa": "kakimazeɾɯ", "syllable_count": 5, "sentences": [{"text": "卵をよく掻き混ぜてから、フライパンに入れた。", "target_word": "掻き混ぜて", "complexity_tier": "T3", "furigana": "卵[たまご]をよく掻[か]き混[ま]ぜてから、フライパンに入[い]れた。", "sentence_source": "generated"}, {"text": "スプーンでコーヒーを掻き混ぜると、砂糖が溶けた。", "target_word": "掻き混ぜる", "complexity_tier": "T3", "furigana": "スプーンでコーヒーを掻[か]き混[ま]ぜると、砂糖[さとう]が溶[と]けた。", "sentence_source": "generated"}, {"text": "鍋のスープが焦げないように、時々掻き混ぜる。", "target_word": "掻き混ぜる", "complexity_tier": "T3", "furigana": "鍋[なべ]のスープが焦[こ]げないように、時々[ときどき]掻[か]き混[ま]ぜる。", "sentence_source": "generated"}, {"text": "絵の具を掻き混ぜて、きれいな緑色を作った。", "target_word": "掻き混ぜて", "complexity_tier": "T3", "furigana": "絵[え]の具[ぐ]を掻[か]き混[ま]ぜて、きれいな緑色[みどりいろ]を作[つく]った。", "sentence_source": "generated"}, {"text": "弟は牛乳に粉を入れて、棒で掻き混ぜていた。", "target_word": "掻き混ぜて", "complexity_tier": "T3", "furigana": "弟[おとうと]は牛乳[ぎゅうにゅう]に粉[こな]を入[い]れて、棒[ぼう]で掻[か]き混[ま]ぜていた。", "sentence_source": "generated"}, {"text": "納豆は、食べる前によく掻き混ぜるとおいしい。", "target_word": "掻き混ぜる", "complexity_tier": "T3", "furigana": "納豆[なっとう]は、食[た]べる前[まえ]によく掻[か]き混[ま]ぜるとおいしい。", "sentence_source": "generated"}, {"text": "泥水を掻き混ぜたので、池の底が見えなくなった。", "target_word": "掻き混ぜた", "complexity_tier": "T3", "furigana": "泥水[どろみず]を掻[か]き混[ま]ぜたので、池[いけ]の底[そこ]が見[み]えなくなった。", "sentence_source": "generated"}, {"text": "粉と水を掻き混ぜても、固まらなかった。", "target_word": "掻き混ぜて", "complexity_tier": "T3", "furigana": "粉[こな]と水[みず]を掻[か]き混[ま]ぜても、固[かた]まらなかった。", "sentence_source": "generated"}, {"text": "ボウルの中身を掻き混ぜ続けて、腕が疲れた。", "target_word": "掻き混ぜ", "complexity_tier": "T3", "furigana": "ボウルの中身[なかみ]を掻[か]き混[ま]ぜ続[つづ]けて、腕[うで]が疲[つか]れた。", "sentence_source": "generated"}, {"text": "カレーを掻き混ぜる母の後ろ姿を見ていた。", "target_word": "掻き混ぜる", "complexity_tier": "T3", "furigana": "カレーを掻[か]き混[ま]ぜる母[はは]の後[うし]ろ姿[すがた]を見[み]ていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "掻き混ぜる", "label": "終止形"}, {"form": "掻き混ぜた", "label": "過去形"}, {"form": "掻き混ぜて", "label": "て形"}, {"form": "掻き混ぜない", "label": "否定形"}, {"form": "掻き混ぜます", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "液体や粉などを動かして混ぜる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6541566-104a-41c9-9aa1-ddb22492a21a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36900, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掻き混ぜて", "is_correct": true, "explanation": "「〜てから」に続くて形。「よく混ぜてから入れる」という順序を表す。"}, {"text": "掻き混ぜよう", "is_correct": false, "explanation": "意志形なので「〜てから」に続かず、文の流れに合わない。"}, {"text": "掻き混ぜ", "is_correct": false, "explanation": "連用形だけでは「〜てから」に続かず、文として成り立たない。"}, {"text": "掻き混ぜます", "is_correct": false, "explanation": "丁寧形で、「〜てから」の前には来ない。普通体の文に合わない。"}], "explanations": {"掻き混ぜて": "「〜てから」に続くて形。「よく混ぜてから入れる」という順序を表す。", "掻き混ぜよう": "意志形なので「〜てから」に続かず、文の流れに合わない。", "掻き混ぜ": "連用形だけでは「〜てから」に続かず、文として成り立たない。", "掻き混ぜます": "丁寧形で、「〜てから」の前には来ない。普通体の文に合わない。"}, "sentence_index": 0, "correct_answer": "掻き混ぜて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "洗濯物を掻き混ぜて、きれいに畳んだ。", "explanation": "ここは〈畳む〉の意味。掻き混ぜるは液体や粉を動かして混ぜることで、洗濯物を畳む動作には使わない。"}, {"text": "シャツのボタンを掻き混ぜて、きちんと留めた。", "explanation": "ここは〈留める〉の意味。掻き混ぜるは中身を混ぜる動きで、ボタンを留める動作には合わない。"}, {"text": "ケーブルを掻き混ぜて、ひもで束ねた。", "explanation": "ここは〈束ねる〉の意味。掻き混ぜるは中身を混ぜる動きで、ばらけた物をひもで縛ってまとめる動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36900, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掻き混ぜた", "is_correct": true, "explanation": "過去形で「〜たので」の前に置け、泥水を混ぜた結果として池が濁ったことを表す。"}, {"text": "掻き混ぜろ", "is_correct": false, "explanation": "命令形で「〜たので」には続かず、文に合わない。"}, {"text": "掻き混ぜれ", "is_correct": false, "explanation": "活用が成り立たず、「〜たので」の前に置けない。"}, {"text": "掻き混ぜよ", "is_correct": false, "explanation": "命令の古い形で、「〜たので」には続かない。"}], "explanations": {"掻き混ぜた": "過去形で「〜たので」の前に置け、泥水を混ぜた結果として池が濁ったことを表す。", "掻き混ぜろ": "命令形で「〜たので」には続かず、文に合わない。", "掻き混ぜれ": "活用が成り立たず、「〜たので」の前に置けない。", "掻き混ぜよ": "命令の古い形で、「〜たので」には続かない。"}, "sentence_index": 6, "correct_answer": "掻き混ぜた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ドアをそっと掻き混ぜて閉めた。", "explanation": "ここは〈閉める〉の意味。掻き混ぜるは中身を混ぜる動きで、ドアを閉める動作には使わない。"}, {"text": "オーブンからケーキを掻き混ぜて取り出した。", "explanation": "ここは〈取り出す〉の意味。掻き混ぜるは混ぜる動きで、中の物を外に出す動作には使わない。"}, {"text": "靴ひもを掻き混ぜて結んだ。", "explanation": "ここは〈結ぶ〉の意味。掻き混ぜるは中身を混ぜることで、ひもを結ぶ動作には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36900, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鍋をよく掻き混ぜし、火を止めた。", "corrected_sentence": "鍋をよく掻き混ぜて、火を止めた。", "error_description": "て形の誤り。「掻き混ぜし」は語幹に「し」を付けた誤った形で、「〜て、火を止めた」と続かない。正しくは「掻き混ぜて」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "掻き混ぜる", "is_correct": true, "explanation": "辞書形と同じ終止形。「混ぜると〜」の条件の形で、一般的な事実を表す。"}, {"text": "掻き混ぜ", "is_correct": false, "explanation": "連用形のみでは「と」に続かず、文として成り立たない。"}, {"text": "掻き混ぜて", "is_correct": false, "explanation": "て形は「と」に続かず、文として成り立たない。"}, {"text": "掻き混ぜ続け", "is_correct": false, "explanation": "連用形で「と」に続かず、文として成り立たない。"}], "correct_form": "掻き混ぜる", "base_form": "掻き混ぜる", "form_label": "終止形", "sentence_index": 1, "explanations": {"掻き混ぜる": "辞書形と同じ終止形。「混ぜると〜」の条件の形で、一般的な事実を表す。", "掻き混ぜ": "連用形のみでは「と」に続かず、文として成り立たない。", "掻き混ぜて": "て形は「と」に続かず、文として成り立たない。", "掻き混ぜ続け": "連用形で「と」に続かず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36900, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ボウルの中身を掻き混ぜへ、牛乳を足した。", "corrected_sentence": "ボウルの中身を掻き混ぜて、牛乳を足した。", "error_description": "て形の誤り。「掻き混ぜへ」の「へ」は助詞で動詞の活用形ではないので成り立たない。正しくは「掻き混ぜて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "掻き混ぜて", "is_correct": true, "explanation": "て形で、「〜ても」に続き、混ぜた後でも固まらなかったという譲歩の文になる。"}, {"text": "掻き混ぜれば", "is_correct": false, "explanation": "仮定形で、「〜ても」には続かず、文の意味に合わない。"}, {"text": "掻き混ぜよう", "is_correct": false, "explanation": "意志形で、「ても」に続かず、文として成り立たない。"}, {"text": "掻き混ぜなかった", "is_correct": false, "explanation": "過去の否定形で、「混ぜても固まらなかった」の意味にならない。"}], "correct_form": "掻き混ぜて", "base_form": "掻き混ぜる", "form_label": "て形", "sentence_index": 7, "explanations": {"掻き混ぜて": "て形で、「〜ても」に続き、混ぜた後でも固まらなかったという譲歩の文になる。", "掻き混ぜれば": "仮定形で、「〜ても」には続かず、文の意味に合わない。", "掻き混ぜよう": "意志形で、「ても」に続かず、文として成り立たない。", "掻き混ぜなかった": "過去の否定形で、「混ぜても固まらなかった」の意味にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36901, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「クリーム」に付く目的語の「を」で、掻き混ぜる動作の対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」だが、「クリームが掻き混ぜた」では他動詞の対象が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は動作の向きを示すが、ここでは対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞の前に来るため、「クリームの掻き混ぜた」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「クリーム」に付く目的語の「を」で、掻き混ぜる動作の対象を示す。", "が": "主語の「が」だが、「クリームが掻き混ぜた」では他動詞の対象が合わない。", "へ": "方向の「へ」は動作の向きを示すが、ここでは対象を示せない。", "の": "連体修飾の「の」は名詞の前に来るため、「クリームの掻き混ぜた」は文として成り立たない。"}, "error_tags": {"が": "主語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36901, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「薬品」に付き、掻き混ぜる動作の対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "位置・相手の「に」で、「薬品に掻き混ぜる」では対象が合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞の後に続くため、「薬品の掻き混ぜる」は文に合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる対象を示すもので、ここでは成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「薬品」に付き、掻き混ぜる動作の対象を示す。", "に": "位置・相手の「に」で、「薬品に掻き混ぜる」では対象が合わない。", "の": "連体修飾の「の」は名詞の後に続くため、「薬品の掻き混ぜる」は文に合わない。", "より": "比較の「より」は比べる対象を示すもので、ここでは成り立たない。"}, "error_tags": {"に": "位置・相手", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36901, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物と物を混ぜ合わせるために、かきまわすこと。", "primary_collocate": null, "pronunciation": "かきまぜる", "ipa": "kakimazeɾɯ", "syllable_count": 5, "sentences": [{"text": "小麦粉と砂糖を掻き混ぜて、ケーキの生地を作る。", "target_word": "掻き混ぜて", "complexity_tier": "T3", "furigana": "小麦粉[こむぎこ]と砂糖[さとう]を掻[か]き混[ま]ぜて、ケーキの生地[きじ]を作[つく]る。", "sentence_source": "generated"}, {"text": "泡立て器でクリームを掻き混ぜた。", "target_word": "掻き混ぜた", "complexity_tier": "T3", "furigana": "泡立[あわだ]て器[き]でクリームを掻[か]き混[ま]ぜた。", "sentence_source": "generated"}, {"text": "ヨーグルトとジャムを掻き混ぜて、朝食に食べた。", "target_word": "掻き混ぜて", "complexity_tier": "T3", "furigana": "ヨーグルトとジャムを掻[か]き混[ま]ぜて、朝食[ちょうしょく]に食[た]べた。", "sentence_source": "generated"}, {"text": "土に肥料を掻き混ぜてから、花の苗を植えた。", "target_word": "掻き混ぜて", "complexity_tier": "T3", "furigana": "土[つち]に肥料[ひりょう]を掻[か]き混[ま]ぜてから、花[はな]の苗[なえ]を植[う]えた。", "sentence_source": "generated"}, {"text": "セメントと砂を水で掻き混ぜて、壁に塗った。", "target_word": "掻き混ぜて", "complexity_tier": "T3", "furigana": "セメントと砂[すな]を水[みず]で掻[か]き混[ま]ぜて、壁[かべ]に塗[ぬ]った。", "sentence_source": "generated"}, {"text": "ご飯に卵を掻き混ぜて、醤油をかけた。", "target_word": "掻き混ぜて", "complexity_tier": "T3", "furigana": "ご飯[はん]に卵[たまご]を掻[か]き混[ま]ぜて、醤油[しょうゆ]をかけた。", "sentence_source": "generated"}, {"text": "薬が底に沈んでいたので、よく掻き混ぜて飲んだ。", "target_word": "掻き混ぜて", "complexity_tier": "T3", "furigana": "薬[くすり]が底[そこ]に沈[しず]んでいたので、よく掻[か]き混[ま]ぜて飲[の]んだ。", "sentence_source": "generated"}, {"text": "先生は薬品を静かに掻き混ぜるように注意した。", "target_word": "掻き混ぜる", "complexity_tier": "T3", "furigana": "先生[せんせい]は薬品[やくひん]を静[しず]かに掻[か]き混[ま]ぜるように注意[ちゅうい]した。", "sentence_source": "generated"}, {"text": "彼は氷を入れたグラスを、ストローで掻き混ぜた。", "target_word": "掻き混ぜた", "complexity_tier": "T3", "furigana": "彼[かれ]は氷[こおり]を入[い]れたグラスを、ストローで掻[か]き混[ま]ぜた。", "sentence_source": "generated"}, {"text": "ペンキを掻き混ぜないで使うと、色がむらになる。", "target_word": "掻き混ぜない", "complexity_tier": "T3", "furigana": "ペンキを掻[か]き混[ま]ぜないで使[つか]うと、色[いろ]がむらになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "掻き混ぜる", "label": "終止形"}, {"form": "掻き混ぜた", "label": "過去形"}, {"form": "掻き混ぜて", "label": "て形"}, {"form": "掻き混ぜない", "label": "否定形"}, {"form": "掻き混ぜます", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "二つ以上の物をかきまわして混ぜ合わせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6541566-104a-41c9-9aa1-ddb22492a21a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36901, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掻き混ぜて", "is_correct": true, "explanation": "て形で、混ぜる動作を続けて「ケーキの生地を作る」という流れにつながる。"}, {"text": "掻き混ぜよう", "is_correct": false, "explanation": "意志形で、説明文の「作る」に続く流れに合わない。"}, {"text": "掻き混ぜろ", "is_correct": false, "explanation": "命令形で、料理の説明文には合わない。"}, {"text": "掻き混ぜれ", "is_correct": false, "explanation": "活用が成り立たず、文に合わない。"}], "explanations": {"掻き混ぜて": "て形で、混ぜる動作を続けて「ケーキの生地を作る」という流れにつながる。", "掻き混ぜよう": "意志形で、説明文の「作る」に続く流れに合わない。", "掻き混ぜろ": "命令形で、料理の説明文には合わない。", "掻き混ぜれ": "活用が成り立たず、文に合わない。"}, "sentence_index": 0, "correct_answer": "掻き混ぜて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新鮮な魚を掻き混ぜて焼いた。", "explanation": "ここは〈焼く〉の意味。掻き混ぜるは中身を混ぜることで、火で焼く調理には使わない。"}, {"text": "床を掻き混ぜて掃いた。", "explanation": "ここは〈掃く〉の意味。掻き混ぜるは混ぜる動きで、ごみを掃き集める動作には使わない。"}, {"text": "ペットボトルを掻き混ぜてから飲んだ。", "explanation": "ここは〈振る〉の意味。掻き混ぜるは道具で中身を動かす動作で、ふたを閉めた容器を揺すって混ぜる場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36901, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掻き混ぜて", "is_correct": true, "explanation": "て形で、「よく〜てから飲んだ」と続き、薬を混ぜてから飲んだという流れになる。"}, {"text": "掻き混ぜた", "is_correct": false, "explanation": "過去形で、「飲んだ」の前に置くと文が成り立たない。"}, {"text": "掻き混ぜる", "is_correct": false, "explanation": "辞書形で、「飲んだ」の前に置くと続かず、文に合わない。"}, {"text": "掻き混ぜられ", "is_correct": false, "explanation": "受身の途中の形で、「飲んだ」の前では成り立たない。"}], "explanations": {"掻き混ぜて": "て形で、「よく〜てから飲んだ」と続き、薬を混ぜてから飲んだという流れになる。", "掻き混ぜた": "過去形で、「飲んだ」の前に置くと文が成り立たない。", "掻き混ぜる": "辞書形で、「飲んだ」の前に置くと続かず、文に合わない。", "掻き混ぜられ": "受身の途中の形で、「飲んだ」の前では成り立たない。"}, "sentence_index": 6, "correct_answer": "掻き混ぜて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ガラスを掻き混ぜて磨いた。", "explanation": "ここは〈磨く〉の意味。掻き混ぜるは混ぜる動きで、ガラスの汚れをこすり落として磨く動作には使わない。"}, {"text": "靴を掻き混ぜて脱いだ。", "explanation": "ここは〈脱ぐ〉の意味。掻き混ぜるは中身を混ぜる動きで、身につけた物を外す動作には使わない。"}, {"text": "ネクタイを掻き混ぜて締めた。", "explanation": "ここは〈締める〉の意味。掻き混ぜるは混ぜる動きで、ネクタイを結んで留める動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36901, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "パンケーキの生地に卵を掻き混ぜで、フライパンで焼いた。", "corrected_sentence": "パンケーキの生地に卵を掻き混ぜて、フライパンで焼いた。", "error_description": "て形の誤り。「掻き混ぜで」は濁音化した誤った形で、正しくは「掻き混ぜて」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "掻き混ぜた", "is_correct": true, "explanation": "過去形で、泡立て器でクリームを混ぜ終えたことを表す。"}, {"text": "掻き混ぜて", "is_correct": false, "explanation": "て形で、文末の「た」と合わない。"}, {"text": "掻き混ぜ", "is_correct": false, "explanation": "連用形のみでは文末に置けず、文として成り立たない。"}, {"text": "掻き混ぜ続け", "is_correct": false, "explanation": "連用形で文末に置けず、文として成り立たない。"}], "correct_form": "掻き混ぜた", "base_form": "掻き混ぜる", "form_label": "過去形", "sentence_index": 1, "explanations": {"掻き混ぜた": "過去形で、泡立て器でクリームを混ぜ終えたことを表す。", "掻き混ぜて": "て形で、文末の「た」と合わない。", "掻き混ぜ": "連用形のみでは文末に置けず、文として成り立たない。", "掻き混ぜ続け": "連用形で文末に置けず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36901, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試薬がゆっくり掻き混ぜてから、結果を記録した。", "corrected_sentence": "試薬をゆっくり掻き混ぜてから、結果を記録した。", "error_description": "「掻き混ぜる」は他動詞で、対象は「を」で示す。「試薬が」は主語になり、文の意味が合わない。正しくは「試薬を」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "掻き混ぜる", "is_correct": true, "explanation": "終止形で、「ように」の前に置く形。注意の内容として「混ぜるように」と続く。"}, {"text": "掻き混ぜれば", "is_correct": false, "explanation": "仮定形で、「ように」の前には続かない。"}, {"text": "掻き混ぜよう", "is_correct": false, "explanation": "意志形で、「ように」の前には続かず、文として成り立たない。"}, {"text": "掻き混ぜ", "is_correct": false, "explanation": "連用形で、「ように」に続かず、文として成り立たない。"}], "correct_form": "掻き混ぜる", "base_form": "掻き混ぜる", "form_label": "終止形", "sentence_index": 7, "explanations": {"掻き混ぜる": "終止形で、「ように」の前に置く形。注意の内容として「混ぜるように」と続く。", "掻き混ぜれば": "仮定形で、「ように」の前には続かない。", "掻き混ぜよう": "意志形で、「ように」の前には続かず、文として成り立たない。", "掻き混ぜ": "連用形で、「ように」に続かず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
