INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36902, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「匂いがして」の主語を示す「が」。正解。"}, {"text": "に", "is_correct": false, "explanation": "「匂いにして」では主語にならず、「する」の形が合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す「で」では主語にならず、文の形が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「匂いの」と連体修飾になり、「して」と続かず文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「匂いがして」の主語を示す「が」。正解。", "に": "「匂いにして」では主語にならず、「する」の形が合わない。", "で": "手段を示す「で」では主語にならず、文の形が成り立たない。", "の": "「匂いの」と連体修飾になり、「して」と続かず文が成り立たない。"}, "error_tags": {"に": "相手・位置", "で": "手段・場所", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36902, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "くさいものやいいものの、鼻で感じるものです。", "primary_collocate": null, "pronunciation": "におい", "ipa": "nioi", "syllable_count": 3, "sentences": [{"text": "台所からカレーのいい匂いがしてきました。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "台所[だいどころ]からカレーのいい匂[にお]いがしてきました。", "sentence_source": "generated"}, {"text": "花に鼻を近づけて、甘い匂いをかぎました。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "花[はな]に鼻[はな]を近[ちか]づけて、甘[あま]い匂[にお]いをかぎました。", "sentence_source": "generated"}, {"text": "魚が古くなったのか、変な匂いがします。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "魚[さかな]が古[ふる]くなったのか、変[へん]な匂[にお]いがします。", "sentence_source": "generated"}, {"text": "雨のあとは、土の匂いが強くなります。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "雨[あめ]のあとは、土[つち]の匂[にお]いが強[つよ]くなります。", "sentence_source": "generated"}, {"text": "新しい本の匂いが好きで、よく図書館に行きます。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "新[あたら]しい本[ほん]の匂[にお]いが好[す]きで、よく図書館[としょかん]に行[い]きます。", "sentence_source": "generated"}, {"text": "この石けんは、レモンの匂いがします。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "この石[せっ]けんは、レモンの匂[にお]いがします。", "sentence_source": "generated"}, {"text": "部屋にたばこの匂いが残っているので、窓を開けました。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "部屋[へや]にたばこの匂[にお]いが残[のこ]っているので、窓[まど]を開[あ]けました。", "sentence_source": "generated"}, {"text": "パン屋の前を通ると、焼きたてのパンの匂いがして、おなかがすきました。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "パン屋[や]の前[まえ]を通[とお]ると、焼[や]きたてのパンの匂[にお]いがして、おなかがすきました。", "sentence_source": "generated"}, {"text": "犬は匂いで、飼い主の帰りを知ります。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "犬[いぬ]は匂[にお]いで、飼[か]い主[ぬし]の帰[かえ]りを知[し]ります。", "sentence_source": "generated"}, {"text": "風邪をひくと、料理の匂いがわからなくなります。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひくと、料理[りょうり]の匂[にお]いがわからなくなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "匂い", "label": "基本形"}, {"form": "匂う", "label": "動詞形"}], "register": "丁寧", "sense_fingerprint": "食べ物・花・物などから出て、鼻で感じるよい香りや嫌なにおい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ff364e-4b2f-4e6b-b85e-ab8916606415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36902, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "匂い", "is_correct": true, "explanation": "カレーのいい香りが漂ってくるので、鼻で感じる「匂い」が合う。正解。"}, {"text": "教科書", "is_correct": false, "explanation": "「いい教科書がしてきました」は意味が通らず、香りとは結びつかない。"}, {"text": "雑巾", "is_correct": false, "explanation": "「いい雑巾がしてきました」は香りの話として成り立たない。"}, {"text": "砂利", "is_correct": false, "explanation": "「いい砂利がしてきました」は香りの表現にならず、文脈に合わない。"}], "explanations": {"匂い": "カレーのいい香りが漂ってくるので、鼻で感じる「匂い」が合う。正解。", "教科書": "「いい教科書がしてきました」は意味が通らず、香りとは結びつかない。", "雑巾": "「いい雑巾がしてきました」は香りの話として成り立たない。", "砂利": "「いい砂利がしてきました」は香りの表現にならず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "匂い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この花は、赤い匂いがとてもきれいです。", "explanation": "ここは〈色〉の意味。赤いのは目で見るもので、鼻で感じる匂いには合わない。"}, {"text": "非常ベルの匂いが大きく響いて、教室中に広がりました。", "explanation": "ここは〈音〉の意味。大きく響くのは音で、鼻で感じる匂いには合わない。"}, {"text": "この飲み物は、甘い匂いが舌にしみます。", "explanation": "ここは〈味〉の意味。舌にしみるのは味で、鼻で感じる匂いには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36902, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "匂い", "is_correct": true, "explanation": "たばこのにおいが部屋に残るので、鼻で感じる「匂い」が合う。正解。"}, {"text": "砂", "is_correct": false, "explanation": "「たばこの砂が残っている」は意味が通らず、部屋の状態として成り立たない。"}, {"text": "段ボール", "is_correct": false, "explanation": "「たばこの段ボールが残っている」は不自然で、文脈に合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "「たばこの鉛筆が残っている」は意味が通らず、部屋の話にも合わない。"}], "explanations": {"匂い": "たばこのにおいが部屋に残るので、鼻で感じる「匂い」が合う。正解。", "砂": "「たばこの砂が残っている」は意味が通らず、部屋の状態として成り立たない。", "段ボール": "「たばこの段ボールが残っている」は不自然で、文脈に合わない。", "鉛筆": "「たばこの鉛筆が残っている」は意味が通らず、部屋の話にも合わない。"}, "sentence_index": 6, "correct_answer": "匂い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓から差す匂いで、部屋が明るくなりました。", "explanation": "ここは〈光〉の意味。部屋を明るくするのは光で、鼻で感じる匂いには合わない。"}, {"text": "この箱は、丸い匂いをしています。", "explanation": "ここは〈形〉の意味。丸いのは見た目の特徴で、鼻で感じる匂いには合わない。"}, {"text": "先生の匂いが大きくて、教室中に響きました。", "explanation": "ここは〈声〉の意味。大きく響くのは声で、鼻で感じる匂いには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36902, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "梅雨の晴れ間は、土の匂いを強くなります。", "corrected_sentence": "梅雨の晴れ間は、土の匂いが強くなります。", "error_description": "「強くなる」は自動詞で、主語の「匂い」は「が」で示す。誤りは「を」で、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36902, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓を開けると、焼きたてのパンの匂いが入れてきました。", "corrected_sentence": "窓を開けると、焼きたてのパンの匂いが入ってきました。", "error_description": "匂いが部屋に入ってくるので自動詞「入る」を使う。誤りは他動詞「入れる」で、正しくは「入ってきました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4438936-3815-4be8-8db8-171d2d368465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36904, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "押さえる動作の対象（肩）を示す格助詞。"}, {"text": "に", "is_correct": false, "explanation": "『肩に押さえる』は位置を示すことになり、力を加える動作の対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "へは方向を表すので、動作の対象である肩には使わない。"}, {"text": "と", "is_correct": false, "explanation": "と は相手や共同を表すので、押さえる対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "押さえる動作の対象（肩）を示す格助詞。", "に": "『肩に押さえる』は位置を示すことになり、力を加える動作の対象にはならない。", "へ": "へは方向を表すので、動作の対象である肩には使わない。", "と": "と は相手や共同を表すので、押さえる対象を示せない。"}, "error_tags": {"に": "位置", "へ": "方向", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36904, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "上を起点とする方向を表し、上から押さえるという動作の仕方を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「上が強く押さえている」は上が主体になり、押さえる動作の起点を表せない。"}, {"text": "で", "is_correct": false, "explanation": "『上で強く押さえている』は場所や手段として不自然で、上からという向きを表せない。"}, {"text": "と", "is_correct": false, "explanation": "と は相手や共同を表すので、上という位置の関係を示せない。"}], "correct_answer": "から", "explanations": {"から": "上を起点とする方向を表し、上から押さえるという動作の仕方を示す。", "が": "主語を示す。「上が強く押さえている」は上が主体になり、押さえる動作の起点を表せない。", "で": "『上で強く押さえている』は場所や手段として不自然で、上からという向きを表せない。", "と": "と は相手や共同を表すので、上という位置の関係を示せない。"}, "error_tags": {"で": "手段", "と": "相手", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36904, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを、手や力で動かないようにする。", "primary_collocate": null, "pronunciation": "おさえる", "ipa": "osaeɾɯ", "syllable_count": 4, "sentences": [{"text": "風で紙が飛ばないように、手で押さえました。", "target_word": "押さえました", "complexity_tier": "T3", "furigana": "風[かぜ]で紙[かみ]が飛[と]ばないように、手[て]で押[お]さえました。", "sentence_source": "generated"}, {"text": "子どもが動かないように、肩をしっかり押さえた。", "target_word": "押さえた", "complexity_tier": "T3", "furigana": "子[こ]どもが動[うご]かないように、肩[かた]をしっかり押[お]さえた。", "sentence_source": "generated"}, {"text": "ドアが閉まらないよう、足で押さえておいてください。", "target_word": "押さえておいて", "complexity_tier": "T3", "furigana": "ドアが閉[し]まらないよう、足[あし]で押[お]さえておいてください。", "sentence_source": "generated"}, {"text": "本が閉じてしまうので、左手でページを押さえて読む。", "target_word": "押さえて", "complexity_tier": "T3", "furigana": "本[ほん]が閉[と]じてしまうので、左手[ひだりて]でページを押[お]さえて読[よ]む。", "sentence_source": "generated"}, {"text": "犬が逃げないように、首をそっと押さえた。", "target_word": "押さえた", "complexity_tier": "T3", "furigana": "犬[いぬ]が逃[に]げないように、首[くび]をそっと押[お]さえた。", "sentence_source": "generated"}, {"text": "定規がずれないよう、指で押さえて線を引きます。", "target_word": "押さえて", "complexity_tier": "T3", "furigana": "定規[じょうぎ]がずれないよう、指[ゆび]で押[お]さえて線[せん]を引[ひ]きます。", "sentence_source": "generated"}, {"text": "地図が丸まるので、四隅を石で押さえた。", "target_word": "押さえた", "complexity_tier": "T3", "furigana": "地図[ちず]が丸[まる]まるので、四隅[よすみ]を石[いし]で押[お]さえた。", "sentence_source": "generated"}, {"text": "ふたが開かないように、上から強く押さえている。", "target_word": "押さえている", "complexity_tier": "T3", "furigana": "ふたが開[あ]かないように、上[うえ]から強[つよ]く押[お]さえている。", "sentence_source": "generated"}, {"text": "切るときに野菜が動くので、左手で押さえます。", "target_word": "押さえます", "complexity_tier": "T3", "furigana": "切[き]るときに野菜[やさい]が動[うご]くので、左手[ひだりて]で押[お]さえます。", "sentence_source": "generated"}, {"text": "暴れる魚を、タオルでしっかり押さえた。", "target_word": "押さえた", "complexity_tier": "T3", "furigana": "暴[あば]れる魚[さかな]を、タオルでしっかり押[お]さえた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "押さえる", "label": "辞書形"}, {"form": "押さえます", "label": "丁寧形"}, {"form": "押さえて", "label": "て形"}, {"form": "押さえた", "label": "た形"}, {"form": "押さえない", "label": "ない形"}, {"form": "押さえれば", "label": "ば形"}, {"form": "押さえよう", "label": "意向形"}, {"form": "押さえられる", "label": "可能形"}], "register": "中立（丁寧体と普通体）", "sense_fingerprint": "手や道具で物や体を押して動かないようにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30c131d8-6c46-402f-b1a0-1841ff6000bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36904, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "押さえました", "is_correct": true, "explanation": "過去の動作を表す形で、風で紙が飛ばないように手で押さえた、という文脈に合う。"}, {"text": "押さえない", "is_correct": false, "explanation": "否定形にすると紙を押さえていないことになり、飛ばないように手で押さえたという流れと矛盾する。"}, {"text": "押さえ", "is_correct": false, "explanation": "語幹だけでは文を終えられず、「手で押さえ」と続かない。"}, {"text": "押さえれば", "is_correct": false, "explanation": "条件形は文を完結できず、『～ば』に続く主節がないので文末に置けない。"}], "explanations": {"押さえました": "過去の動作を表す形で、風で紙が飛ばないように手で押さえた、という文脈に合う。", "押さえない": "否定形にすると紙を押さえていないことになり、飛ばないように手で押さえたという流れと矛盾する。", "押さえ": "語幹だけでは文を終えられず、「手で押さえ」と続かない。", "押さえれば": "条件形は文を完結できず、『～ば』に続く主節がないので文末に置けない。"}, "sentence_index": 0, "correct_answer": "押さえました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は怒りを表そうと、机を押さえた。", "explanation": "ここは〈叩く〉の意味。押さえるは動かないようにすることで、机を打って怒りを表す文には合わない。"}, {"text": "お皿を拭く代わりに、テーブルを押さえてきれいにした。", "explanation": "ここは〈拭く〉の意味。押さえるは動かないようにすることで、表面をこすって汚れを落とす文には合わない。"}, {"text": "会議で、新しい計画の要点を押さえて説明した。", "explanation": "ここは〈要点を理解する〉の意味。押さえるは手や力で動かないようにする意味で、要点を理解する文には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36904, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "押さえた", "is_correct": true, "explanation": "過去形で、地図の四隅を石で押さえた動作を述べ、丸まるのを防いだ流れに合う。"}, {"text": "押さえて", "is_correct": false, "explanation": "て形は文末に置けず、『押さえて』だけでは文が終わらない。"}, {"text": "押さえなかった", "is_correct": false, "explanation": "過去の否定形になり、四隅を石で押さえなかったことになるので、丸まるのを防いだという文脈と矛盾する。"}, {"text": "押さえられない", "is_correct": false, "explanation": "可能形の否定で、石で押さえられないという能力の話になり、押さえた動作と合わない。"}], "explanations": {"押さえた": "過去形で、地図の四隅を石で押さえた動作を述べ、丸まるのを防いだ流れに合う。", "押さえて": "て形は文末に置けず、『押さえて』だけでは文が終わらない。", "押さえなかった": "過去の否定形になり、四隅を石で押さえなかったことになるので、丸まるのを防いだという文脈と矛盾する。", "押さえられない": "可能形の否定で、石で押さえられないという能力の話になり、押さえた動作と合わない。"}, "sentence_index": 6, "correct_answer": "押さえた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コップにお茶を押さえた。", "explanation": "ここは〈注ぐ〉の意味。押さえるは動かないようにすることで、液体を入れる文には合わない。"}, {"text": "ボールを遠くへ押さえた。", "explanation": "ここは〈投げる〉の意味。押さえるは動かないようにすることで、遠くへ飛ばす文には合わない。"}, {"text": "ベルが鳴ったので、ボタンを一度押さえた。", "explanation": "ここは〈押す〉の意味。押さえるは力をかけ続けて動かないようにする動作なので、一度押すだけの場合には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36904, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "強い風でテントが飛ばないように、ロープを手で押さえ。", "corrected_sentence": "強い風でテントが飛ばないように、ロープを手で押さえた。", "error_description": "誤った形：押さえ（た形の『た』が抜けている）。正しい形：押さえた。文末の過去を表す『た』が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "押さえた", "is_correct": true, "explanation": "た形で、子どもが動かないように肩を押さえた過去の動作を述べる。"}, {"text": "押さえて", "is_correct": false, "explanation": "て形は文を完結できず、ここでは文末の述語にならない。"}, {"text": "押さえれば", "is_correct": false, "explanation": "ば形は条件を表すので、過去の一回の動作を述べる文には合わない。"}, {"text": "押さえ", "is_correct": false, "explanation": "語幹だけでは文が終わらず、過去の動作を述べる文として成り立たない。"}], "correct_form": "押さえた", "base_form": "押さえる", "form_label": "た形", "sentence_index": 1, "explanations": {"押さえた": "た形で、子どもが動かないように肩を押さえた過去の動作を述べる。", "押さえて": "て形は文を完結できず、ここでは文末の述語にならない。", "押さえれば": "ば形は条件を表すので、過去の一回の動作を述べる文には合わない。", "押さえ": "語幹だけでは文が終わらず、過去の動作を述べる文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36904, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "風で看板が倒れないように、ロープで看板に押さえた。", "corrected_sentence": "風で看板が倒れないように、ロープで看板を押さえた。", "error_description": "誤った形：看板に（『に』）。正しい形：看板を（『を』）。押さえる動作の対象には『を』を使う。『に』は位置や相手を示すので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "押さえている", "is_correct": true, "explanation": "ている形で、今も上から押さえ続けている状態を表し、ふたが開かない文脈に合う。"}, {"text": "押さえなかった", "is_correct": false, "explanation": "た形の否定で、過去に押さえなかったという意味になり、今も押さえ続けている状態と矛盾する。"}, {"text": "押さえられる", "is_correct": false, "explanation": "可能形の辞書形は押さえることができるという可能を表し、今押さえている状態を述べる文には合わない。"}, {"text": "押さえられない", "is_correct": false, "explanation": "可能形の否定は押さえられないという意味になり、ふたを押さえている事実と矛盾する。"}], "correct_form": "押さえている", "base_form": "押さえる", "form_label": "ている形", "sentence_index": 7, "explanations": {"押さえている": "ている形で、今も上から押さえ続けている状態を表し、ふたが開かない文脈に合う。", "押さえなかった": "た形の否定で、過去に押さえなかったという意味になり、今も押さえ続けている状態と矛盾する。", "押さえられる": "可能形の辞書形は押さえることができるという可能を表し、今押さえている状態を述べる文には合わない。", "押さえられない": "可能形の否定は押さえられないという意味になり、ふたを押さえている事実と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36906, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "行き先を表す「に」で、「海に行く」となる。"}, {"text": "が", "is_correct": false, "explanation": "「海が行く」では海が主語になり、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「海の行く」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「海で行く」は「行く」の行き先を表せず、不自然。"}], "correct_answer": "に", "explanations": {"に": "行き先を表す「に」で、「海に行く」となる。", "が": "「海が行く」では海が主語になり、意味が通らない。", "の": "「海の行く」では文が成り立たない。", "で": "「海で行く」は「行く」の行き先を表せず、不自然。"}, "error_tags": {"が": "subject", "の": "possessive", "で": "location_of_action"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冬", "is_correct": true, "explanation": "夏と反対の、いちばん寒い季節。"}, {"text": "春", "is_correct": false, "explanation": "夏の前の季節で、反対の関係ではない。"}, {"text": "秋", "is_correct": false, "explanation": "夏の次の季節で、反対の関係ではない。"}, {"text": "梅雨", "is_correct": false, "explanation": "夏の前の雨の時期で、反対の関係ではない。"}], "correct_answer": "冬", "explanations": {"冬": "夏と反対の、いちばん寒い季節。", "春": "夏の前の季節で、反対の関係ではない。", "秋": "夏の次の季節で、反対の関係ではない。", "梅雨": "夏の前の雨の時期で、反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
