INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36906, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "夏は、いちばんあつい季節です。", "primary_collocate": null, "pronunciation": "なつ", "ipa": "natsɯ", "syllable_count": 2, "sentences": [{"text": "夏は暑い。", "target_word": "夏", "complexity_tier": "T1", "furigana": "夏[なつ]は暑[あつ]い。", "sentence_source": "generated"}, {"text": "夏は海に行く。", "target_word": "夏", "complexity_tier": "T1", "furigana": "夏[なつ]は海[うみ]に行[い]く。", "sentence_source": "generated"}, {"text": "夏が来ました。", "target_word": "夏", "complexity_tier": "T2", "furigana": "夏[なつ]が来[き]ました。", "sentence_source": "generated"}, {"text": "今年の夏は長いです。", "target_word": "夏", "complexity_tier": "T2", "furigana": "今年[ことし]の夏[なつ]は長[なが]いです。", "sentence_source": "generated"}, {"text": "夏の朝は早く明るくなります。", "target_word": "夏", "complexity_tier": "T2", "furigana": "夏[なつ]の朝[あさ]は早[はや]く明[あか]るくなります。", "sentence_source": "generated"}, {"text": "夏に着る服を買った。", "target_word": "夏", "complexity_tier": "T2", "furigana": "夏[なつ]に着[き]る服[ふく]を買[か]った。", "sentence_source": "generated"}, {"text": "夏を楽しむために、プールへ行った。", "target_word": "夏", "complexity_tier": "T3", "furigana": "夏[なつ]を楽[たの]しむために、プールへ行[い]った。", "sentence_source": "generated"}, {"text": "夏が終わると、すぐ秋になる。", "target_word": "夏", "complexity_tier": "T3", "furigana": "夏[なつ]が終[お]わると、すぐ秋[あき]になる。", "sentence_source": "generated"}, {"text": "夏の間、祖父の家に泊まっていた。", "target_word": "夏", "complexity_tier": "T3", "furigana": "夏[なつ]の間[あいだ]、祖父[そふ]の家[いえ]に泊[と]まっていた。", "sentence_source": "generated"}, {"text": "私の国の夏は、日本ほど暑くない。", "target_word": "夏", "complexity_tier": "T3", "furigana": "私[わたし]の国[くに]の夏[なつ]は、日本[にほん]ほど暑[あつ]くない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "真夏", "label": "派生"}, {"form": "初夏", "label": "派生"}, {"form": "夏休み", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 一年でいちばん暑い季節", "c