INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36907, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「夏の午後」で、夏という季節の午後という修飾関係を表す。"}, {"text": "を", "is_correct": false, "explanation": "「夏を午後」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「夏へ午後」は意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「夏が午後」では、「夏」と「午後」の関係が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「夏の午後」で、夏という季節の午後という修飾関係を表す。", "を": "「夏を午後」は文法的に成り立たない。", "へ": "「へ」は方向を表すので、「夏へ午後」は意味が通らない。", "が": "「夏が午後」では、「夏」と「午後」の関係が成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "が": "subject_marker"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冬", "is_correct": true, "explanation": "暑い季節の夏に対し、冬は寒い季節で、反対の関係。"}, {"text": "春", "is_correct": false, "explanation": "夏の前の季節であって、夏の反対ではない。"}, {"text": "秋", "is_correct": false, "explanation": "夏の次の季節であって、夏の反対ではない。"}, {"text": "休み", "is_correct": false, "explanation": "夏と関連のある語だが、反対の関係ではない。"}], "correct_answer": "冬", "explanations": {"冬": "暑い季節の夏に対し、冬は寒い季節で、反対の関係。", "春": "夏の前の季節であって、夏の反対ではない。", "秋": "夏の次の季節であって、夏の反対ではない。", "休み": "夏と関連のある語だが、反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
