INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36907, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一年のうち、六月から八月ごろまでの暑い季節。", "primary_collocate": null, "pronunciation": "なつ", "ipa": "natsɯ", "syllable_count": 2, "sentences": [{"text": "記録的な暑さが続く夏の午後、公園の入り口で一人の少年が手作りのレモネードを販売していた。", "target_word": "夏", "complexity_tier": "T6", "furigana": "記録的[きろくてき]な暑[あつ]さが続[つづ]く夏[なつ]の午後[ごご]、公園[こうえん]の入[い]り口[ぐち]で一人[ひとり]の少年[しょうねん]が手作[てづく]りのレモネードを販売[はんばい]していた。", "sentence_source": "generated"}, {"text": "夏は暑い。", "target_word": "夏", "complexity_tier": "T1", "furigana": "夏[なつ]は暑[あつ]い。", "sentence_source": "generated"}, {"text": "私は夏が好きです。", "target_word": "夏", "complexity_tier": "T2", "furigana": "私[わたし]は夏[なつ]が好[す]きです。", "sentence_source": "generated"}, {"text": "去年の夏、家族と海へ行きました。", "target_word": "夏", "complexity_tier": "T2", "furigana": "去年[きょねん]の夏[なつ]、家族[かぞく]と海[うみ]へ行[い]きました。", "sentence_source": "generated"}, {"text": "夏に生まれた弟は、水が大好きだ。", "target_word": "夏", "complexity_tier": "T3", "furigana": "夏[なつ]に生[う]まれた弟[おとうと]は、水[みず]が大好[だいす]きだ。", "sentence_source": "generated"}, {"text": "夏になると、毎日かき氷を食べたくなる。", "target_word": "夏", "complexity_tier": "T3", "furigana": "夏[なつ]になると、毎日[まいにち]かき氷[ごおり]を食[た]べたくなる。", "sentence_source": "generated"}, {"text": "夏を待ちながら、新しい水着を買った。", "target_word": "夏", "complexity_tier": "T3", "furigana": "夏[なつ]を待[ま]ちながら、新[あたら]しい水着[みずぎ]を買[か]った。", "sentence_source": "generated"}, {"text": "夏の夜は、窓を開けて寝る人が多い。", "target_word": "夏", "complexity_tier": "T3", "furigana": "夏[なつ]の夜[よる]は、窓[まど]を開[あ]けて寝[ね]る人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "夏が終わる前に、友達と花火を見たい。", "target_word": "夏", "complexity_tier": "T3", "furigana": "夏[なつ]が終[お]わる前[まえ]に、友達[ともだち]と花火[はなび]を見[み]たい。", "sentence_source": "generated"}, {"text": "夏の暑さで体調をくずす人も少なくない。", "target_word": "夏", "complexity_tier": "T3", "furigana": "夏[なつ]の暑[あつ]さで体調[たいちょう]をくずす人[ひと]も少[すく]なくない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "真夏", "label": "派生"}, {"form": "初夏", "label": "派生"}, {"form": "夏休み", "label": "派生"}, {"form": "夏場", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 六月から八月ごろの暑い季節", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: contains vocabulary far above tier T1: くずす (Zipf 1.53)']::text[], 'e809459e-112d-418e-b65d-24a3fcd1f3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36907, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "夏", "is_correct": true, "explanation": "見出し語そのもの。なつ。"}, {"text": "松", "is_correct": false, "explanation": "まつ。1拍目の「な」が「ま」に変わるだけの別語。"}, {"text": "靴", "is_correct": false, "explanation": "くつ。1拍目の「な」が「く」に変わるだけの別語。"}, {"text": "梨", "is_correct": false, "explanation": "なし。2拍目の「つ」が「し」に変わるだけの別語。"}, {"text": "波", "is_correct": false, "explanation": "なみ。2拍目の「つ」が「み」に変わるだけの別語。"}], "explanations": {"夏": "見出し語そのもの。なつ。", "松": "まつ。1拍目の「な」が「ま」に変わるだけの別語。", "靴": "くつ。1拍目の「な」が「く」に変わるだけの別語。", "梨": "なし。2拍目の「つ」が「し」に変わるだけの別語。", "波": "なみ。2拍目の「つ」が「み」に変わるだけの別語。"}, "sentence_index": null, "correct_answer": "夏"}, "level_3": {"options": [{"text": "夏", "is_correct": true, "explanation": "「記録的な暑さが続く」と合い、暑い季節を表す。"}, {"text": "冬", "is_correct": false, "explanation": "名詞として形は合うが、記録的な暑さが続くのは冬ではないので意味が合わない。"}, {"text": "夜", "is_correct": false, "explanation": "形は合うが、「夜の午後」は矛盾するので意味が合わない。"}, {"text": "朝", "is_correct": false, "explanation": "形は合うが、「朝の午後」は矛盾するので意味が合わない。"}], "explanations": {"夏": "「記録的な暑さが続く」と合い、暑い季節を表す。", "冬": "名詞として形は合うが、記録的な暑さが続くのは冬ではないので意味が合わない。", "夜": "形は合うが、「夜の午後」は矛盾するので意味が合わない。", "朝": "形は合うが、「朝の午後」は矛盾するので意味が合わない。"}, "sentence_index": 0, "correct_answer": "夏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "去年の夏は雪がたくさん降って、スキーを楽しみました。", "explanation": "夏は暑い季節で、雪が降ってスキーをする季節ではない。"}, {"text": "夏は一年で一番寒い季節なので、毎日コートを着ます。", "explanation": "夏は一年で一番暑い季節で、寒い季節ではない。"}, {"text": "私の夏は五歳で、毎日幼稚園に通っています。", "explanation": "夏は季節で、人の年齢や名前のように使う語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36907, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "夏", "is_correct": true, "explanation": "見出し語そのもの。なつ。"}, {"text": "鍋", "is_correct": false, "explanation": "なべ。2拍目の「つ」が「べ」に変わるだけの別語。"}, {"text": "中", "is_correct": false, "explanation": "なか。2拍目の「つ」が「か」に変わるだけの別語。"}, {"text": "勝つ", "is_correct": false, "explanation": "かつ。1拍目の「な」が「か」に変わるだけの別語。"}, {"text": "筒", "is_correct": false, "explanation": "つつ。1拍目の「な」が「つ」に変わるだけの別語。"}], "explanations": {"夏": "見出し語そのもの。なつ。", "鍋": "なべ。2拍目の「つ」が「べ」に変わるだけの別語。", "中": "なか。2拍目の「つ」が「か」に変わるだけの別語。", "勝つ": "かつ。1拍目の「な」が「か」に変わるだけの別語。", "筒": "つつ。1拍目の「な」が「つ」に変わるだけの別語。"}, "sentence_index": null, "correct_answer": "夏"}, "level_3": {"options": [{"text": "夏", "is_correct": true, "explanation": "新しい水着を買って待つ季節として、夏が文脈に合う。"}, {"text": "冬", "is_correct": false, "explanation": "名詞として形は合うが、水着を買って冬を待つのは意味が合わない。"}, {"text": "雪", "is_correct": false, "explanation": "形は合うが、水着を買って雪を待つのは意味が合わない。"}, {"text": "寒さ", "is_correct": false, "explanation": "形は合うが、水着を買って寒さを待つのは意味が合わない。"}], "explanations": {"夏": "新しい水着を買って待つ季節として、夏が文脈に合う。", "冬": "名詞として形は合うが、水着を買って冬を待つのは意味が合わない。", "雪": "形は合うが、水着を買って雪を待つのは意味が合わない。", "寒さ": "形は合うが、水着を買って寒さを待つのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "夏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏は十二月に始まり、雪が降る寒い季節だ。", "explanation": "夏は六月から八月ごろの暑い季節で、十二月に始まる寒い季節ではない。"}, {"text": "夏は読む本で、図書館にたくさんある。", "explanation": "夏は季節で、図書館にある本ではない。"}, {"text": "私の夏は赤くて、とても大きな車です。", "explanation": "夏は季節で、車のような物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36907, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎年、夏を海へ行きます。", "corrected_sentence": "毎年、夏に海へ行きます。", "error_description": "季節という時を表す「夏」には、「を」ではなく時の「に」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36907, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎年、夏へ祖父の家に泊まります。", "corrected_sentence": "毎年、夏に祖父の家に泊まります。", "error_description": "季節という時を表す夏には、方向の「へ」ではなく時の「に」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36908, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "2が真ん中にあるという、主語を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "『2を真ん中です』は対象を示すことになり、真ん中という状態の文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『2に真ん中です』は位置を示すことになり、主語として文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "『2で真ん中です』は手段を示すことになり、状態の文として不自然。"}], "correct_answer": "が", "explanations": {"が": "2が真ん中にあるという、主語を示す格助詞。", "を": "『2を真ん中です』は対象を示すことになり、真ん中という状態の文が成り立たない。", "に": "『2に真ん中です』は位置を示すことになり、主語として文が成り立たない。", "で": "『2で真ん中です』は手段を示すことになり、状態の文として不自然。"}, "error_tags": {"を": "目的語", "に": "位置", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
