INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36908, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "かずの二つ目。", "primary_collocate": null, "pronunciation": "に", "ipa": "ni", "syllable_count": 1, "sentences": [{"text": "説明書の手順は、1が最初で、「2」が次です。", "target_word": "2", "complexity_tier": "T3", "furigana": "せつめいしょの てじゅんは、いちが さいしょで、「に」が つぎです。", "sentence_source": "generated"}, {"text": "席は左から1、2、3と並んでいて、2が真ん中です。", "target_word": "2", "complexity_tier": "T3", "furigana": "せきは ひだりから いち、に、さんと ならんでいて、にが まんなかです。", "sentence_source": "generated"}, {"text": "ゴールの順番は、1が先頭で、「2」が次でした。", "target_word": "2", "complexity_tier": "T3", "furigana": "ごーるの じゅんばんは、いちが せんとうで、「に」が つぎでした。", "sentence_source": "generated"}, {"text": "作業は1から始めて、次は「2」に進みます。", "target_word": "2", "complexity_tier": "T3", "furigana": "さぎょうは いちから はじめて、つぎは「に」に すすみます。", "sentence_source": "generated"}, {"text": "行列の先頭は1の人で、その次が「2」の人です。", "target_word": "2", "complexity_tier": "T3", "furigana": "ぎょうれつの せんとうは いちの ひとで、そのつぎが「に」の ひとです。", "sentence_source": "generated"}, {"text": "きょうだいの順番は、1が兄、「2」が私です。", "target_word": "2", "complexity_tier": "T3", "furigana": "きょうだいの じゅんばんは、いちが あに、「に」が わたしです。", "sentence_source": "generated"}, {"text": "手順は、1で電源を入れ、「2」でボタンを押します。", "target_word": "2", "complexity_tier": "T3", "furigana": "てじゅんは、いちで でんげんを いれ、「に」で ぼたんを おします。", "sentence_source": "generated"}, {"text": "ふろくは1が表紙で、「2」が目次です。", "target_word": "2", "complexity_tier": "T3", "furigana": "ふろくは いちが ひょうしで、「に」が もくじです。", "sentence_source": "generated"}, {"text": "レーンは1が左で、「2」が右です。", "target_word": "2", "complexity_tier": "T3", "furigana": "れーんは いちが ひだりで、「に」が みぎです。", "sentence_source": "generated"}, {"text": "くじの番号は、1のあとに「2」が続きました。", "target_word": "2", "complexity_tier": "T3", "furigana": "くじの ばんごうは、いちの あとに「に」が つづきました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "2", "label": "基本形"}], "register": "中立（丁寧体と普通体）", "sense_fingerprint": "順番や回数で二つ目であること（2番目・2位など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30c131d8-6c46-402f-b1a0-1841ff6000bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36908, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "2", "is_correct": true, "explanation": "順番の二つ目を表す数字で、1が最初、次が2という流れに合う。"}, {"text": "3", "is_correct": false, "explanation": "1が最初で次が3だと、二つ目を飛ばすことになり順番の説明と合わない。"}, {"text": "4", "is_correct": false, "explanation": "次が4だと順番が飛んでしまい、二つ目の手順という文脈と合わない。"}, {"text": "5", "is_correct": false, "explanation": "次が5だと順番が飛んでしまい、1の次の手順という文脈と合わない。"}], "explanations": {"2": "順番の二つ目を表す数字で、1が最初、次が2という流れに合う。", "3": "1が最初で次が3だと、二つ目を飛ばすことになり順番の説明と合わない。", "4": "次が4だと順番が飛んでしまい、二つ目の手順という文脈と合わない。", "5": "次が5だと順番が飛んでしまい、1の次の手順という文脈と合わない。"}, "sentence_index": 0, "correct_answer": "2"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "行列の先頭は「2」の人で、その次が1の人です。", "explanation": "ここは〈最初〉の意味。2は二つ目なので、先頭に立つ人を表すこの文には合わない。"}, {"text": "3人が並ぶ列の最後は「2」の人です。", "explanation": "ここは〈最後〉の意味。2は二つ目なので、3人の列の最後を表すこの文には合わない。"}, {"text": "作業は「2」から始めて、次は3に進みます。", "explanation": "ここは〈最初〉の意味。2は二つ目なので、最初の手順を表すこの文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36908, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "2", "is_correct": true, "explanation": "順番の二つ目を表し、1で電源を入れ、次にボタンを押す二つ目の手順に合う。"}, {"text": "6", "is_correct": false, "explanation": "二つ目の手順を6にすると順番が飛び、1の次の手順として合わない。"}, {"text": "7", "is_correct": false, "explanation": "二つ目の手順を7にすると順番が飛び、手順の流れと合わない。"}, {"text": "1", "is_correct": false, "explanation": "1を二回使うと同じ手順を繰り返すことになり、手順の説明として合わない。"}], "explanations": {"2": "順番の二つ目を表し、1で電源を入れ、次にボタンを押す二つ目の手順に合う。", "6": "二つ目の手順を6にすると順番が飛び、1の次の手順として合わない。", "7": "二つ目の手順を7にすると順番が飛び、手順の流れと合わない。", "1": "1を二回使うと同じ手順を繰り返すことになり、手順の説明として合わない。"}, "sentence_index": 6, "correct_answer": "2"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ゴールの順番は、「2」の人が一位で、1の人が二位だった。", "explanation": "ここは〈一番目〉の意味。2は二つ目なので、一位を表すこの文には合わない。"}, {"text": "列の三番目に並んでいるのは「2」の人です。", "explanation": "ここは〈三つ目〉の意味。2は二つ目なので、三番目を表すこの文には合わない。"}, {"text": "説明書の手順は、最初に「2」を読み、次に1を読みます。", "explanation": "ここは〈最初〉の意味。2は二つ目なので、最初の手順を表すこの文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36908, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "列の順番は、1が先頭で、2を次に来ます。", "corrected_sentence": "列の順番は、1が先頭で、2が次に来ます。", "error_description": "誤った形：2を（『を』）。正しい形：2が（『が』）。来るは自動詞なので主語に『が』を使う。『を』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36908, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作業は1で準備をして、2の片付けます。", "corrected_sentence": "作業は1で準備をして、2で片付けます。", "error_description": "誤った形：2の（『の』）。正しい形：2で（『で』）。「片付けます」は動詞なので『の』では述語にならず、手順を示す『で』が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
