INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36909, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "数の一つ。一の次で三の前の数。", "primary_collocate": null, "pronunciation": "に", "ipa": "ni", "syllable_count": 1, "sentences": [{"text": "1の次の数は「2」です。", "target_word": "2", "complexity_tier": "T3", "furigana": "1[いち]の次[つぎ]の数[かず]は「2[に]」です。", "sentence_source": "generated"}, {"text": "「2」に3を足すと5になります。", "target_word": "2", "complexity_tier": "T3", "furigana": "「2[に]」に3[さん]を足[た]すと5[ご]になります。", "sentence_source": "generated"}, {"text": "4を「2」で割ると「2」になります。", "target_word": "2", "complexity_tier": "T3", "furigana": "4[よん]を「2[に]」で割[わ]ると「2[に]」になります。", "sentence_source": "generated"}, {"text": "この問題の答えは「2」か3のどちらかです。", "target_word": "2", "complexity_tier": "T3", "furigana": "この問題[もんだい]の答[こた]えは「2[に]」か3[さん]のどちらかです。", "sentence_source": "generated"}, {"text": "電話番号の最後の数字は「2」です。", "target_word": "2", "complexity_tier": "T3", "furigana": "電話番号[でんわばんごう]の最後[さいご]の数字[すうじ]は「2[に]」です。", "sentence_source": "generated"}, {"text": "3から1を引くと「2」です。", "target_word": "2", "complexity_tier": "T3", "furigana": "3[さん]から1[いち]を引[ひ]くと「2[に]」です。", "sentence_source": "generated"}, {"text": "時計の針が「2」を指しています。", "target_word": "2", "complexity_tier": "T3", "furigana": "時計[とけい]の針[はり]が「2[に]」を指[さ]しています。", "sentence_source": "generated"}, {"text": "「2」と「2」を足すと4になります。", "target_word": "2", "complexity_tier": "T3", "furigana": "「2[に]」と「2[に]」を足[た]すと4[よん]になります。", "sentence_source": "generated"}, {"text": "数字の「2」は、1と3の間にあります。", "target_word": "2", "complexity_tier": "T3", "furigana": "数字[すうじ]の「2[に]」は、1[いち]と3[さん]の間[あいだ]にあります。", "sentence_source": "generated"}, {"text": "くじの番号は、1でも3でもなく「2」だった。", "target_word": "2", "complexity_tier": "T3", "furigana": "くじの番号[ばんごう]は、1[いち]でも3[さん]でもなく「2[に]」だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "2", "label": "基本形"}], "register": "中立（丁寧体と普通体）", "sense_fingerprint": "数字の二、一の次で三の前の数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30c131d8-6c46-402f-b1a0-1841ff6000bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36909, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "2", "is_correct": true, "explanation": "数の一つで、1の次で3の前の数なので、1の次の数として正しい。"}, {"text": "3", "is_correct": false, "explanation": "3は1の次の数ではなく、2の次の数なので、ここでは合わない。"}, {"text": "1", "is_correct": false, "explanation": "1の次の数が1になると、数の順番として成り立たない。"}, {"text": "4", "is_correct": false, "explanation": "4は1の次の数ではないので、この文の答えとして合わない。"}], "explanations": {"2": "数の一つで、1の次で3の前の数なので、1の次の数として正しい。", "3": "3は1の次の数ではなく、2の次の数なので、ここでは合わない。", "1": "1の次の数が1になると、数の順番として成り立たない。", "4": "4は1の次の数ではないので、この文の答えとして合わない。"}, "sentence_index": 0, "correct_answer": "2"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "くじの一番目に引かれたのは「2」です。", "explanation": "ここは〈順番の一つ目〉の意味。数の2は順番を表さないので、一番目を指すこの文には合わない。"}, {"text": "列の先頭は「2」の人で、1の人が後ろに並んでいる。", "explanation": "ここは〈先頭〉の意味。数の2は順番を表さないので、先頭の人を指すこの文には合わない。"}, {"text": "三番目に並んでいるのは「2」の人だ。", "explanation": "ここは〈順番の三つ目〉の意味。数の2は順番を表さないので、三番目を指すこの文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36909, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "2", "is_correct": true, "explanation": "数字の二を表し、時計の針が指す数字として合う。"}, {"text": "ペン", "is_correct": false, "explanation": "時計の針は数字を指すので、物の名前のペンでは文の意味が成り立たない。"}, {"text": "光", "is_correct": false, "explanation": "時計の針は数字を指すので、光を指すという文は意味が合わない。"}, {"text": "ドア", "is_correct": false, "explanation": "時計の針は数字を指すので、ドアを指すという文は合わない。"}], "explanations": {"2": "数字の二を表し、時計の針が指す数字として合う。", "ペン": "時計の針は数字を指すので、物の名前のペンでは文の意味が成り立たない。", "光": "時計の針は数字を指すので、光を指すという文は意味が合わない。", "ドア": "時計の針は数字を指すので、ドアを指すという文は合わない。"}, "sentence_index": 6, "correct_answer": "2"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "くじの三番目に引かれたのは「2」です。", "explanation": "ここは〈順番の三つ目〉の意味。数の2は順番を表さないので、三番目を指すこの文には合わない。"}, {"text": "列の後ろから二番目に並んでいるのは「2」の人です。", "explanation": "ここは〈順番の二つ目〉の意味。数の2は列の位置を表さないので、この文には合わない。"}, {"text": "ゴールの二位は「2」の人です。", "explanation": "ここは〈順位の二位〉の意味。数の2は順位を表さないので、二位を指すこの文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36909, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "2で4を足すと6になります。", "corrected_sentence": "2に4を足すと6になります。", "error_description": "誤った形：2で（『で』）。正しい形：2に（『に』）。足す相手は『に』で示す。『で』は手段を表すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36909, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "3に「2」が足すと5になります。", "corrected_sentence": "3に「2」を足すと5になります。", "error_description": "誤った形：「2」が（『が』）。正しい形：「2」を（『を』）。足すは他動詞なので、足される数には『を』を使う。『が』は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
