INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36910, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「三」という数字のことです。", "primary_collocate": null, "pronunciation": "さん", "ipa": "saɴ", "syllable_count": 2, "sentences": [{"text": "黒板に大きく「3」と書きました。", "target_word": "3", "complexity_tier": "T3", "furigana": "黒板[こくばん]に大[おお]きく「3[さん]」と書[か]きました。", "sentence_source": "generated"}, {"text": "電話番号の最後の数字は「3」です。", "target_word": "3", "complexity_tier": "T3", "furigana": "電話番号[でんわばんごう]の最後[さいご]の数字[すうじ]は「3[さん]」です。", "sentence_source": "generated"}, {"text": "この漢字の「三」は、算用数字では「3」と書きます。", "target_word": "3", "complexity_tier": "T3", "furigana": "この漢字[かんじ]の「三[さん]」は、算用数字[さんようすうじ]では「3[さん]」と書[か]きます。", "sentence_source": "generated"}, {"text": "テストの問題番号は、1、2、「3」の順に並んでいます。", "target_word": "3", "complexity_tier": "T3", "furigana": "テストの問題番号[もんだいばんごう]は、1[いち]、2[に]、「3[さん]」の順[じゅん]に並[なら]んでいます。", "sentence_source": "generated"}, {"text": "時計の文字盤で、右側にある数字は「3」です。", "target_word": "3", "complexity_tier": "T3", "furigana": "時計[とけい]の文字盤[もじばん]で、右側[みぎがわ]にある数字[すうじ]は「3[さん]」です。", "sentence_source": "generated"}, {"text": "鍵の暗証番号は、最初が「3」で、最後が7です。", "target_word": "3", "complexity_tier": "T3", "furigana": "鍵[かぎ]の暗証番号[あんしょうばんごう]は、最初[さいしょ]が「3[さん]」で、最後[さいご]が7[なな]です。", "sentence_source": "generated"}, {"text": "子どもは数字の「3」を、まだ上手に書けません。", "target_word": "3", "complexity_tier": "T3", "furigana": "子[こ]どもは数字[すうじ]の「3[さん]」を、まだ上手[じょうず]に書[か]けません。", "sentence_source": "generated"}, {"text": "「さん」と読む数字は、「3」と書きます。", "target_word": "3", "complexity_tier": "T3", "furigana": "「さん」と読[よ]む数字は、「3[さん]」と書[か]きます。", "sentence_source": "generated"}, {"text": "エレベーターのボタンを見ると、2の次は「3」でした。", "target_word": "3", "complexity_tier": "T3", "furigana": "エレベーターのボタンを見[み]ると、2[に]の次[つぎ]は「3[さん]」でした。", "sentence_source": "generated"}, {"text": "ノートの端に、赤い字で「3」と書いてあります。", "target_word": "3", "complexity_tier": "T3", "furigana": "ノートの端[はし]に、赤[あか]い字[じ]で「3[さん]」と書[か]いてあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "3", "label": "Arabic numeral"}, {"form": "三", "label": "kanji numeral"}], "register": "neutral", "sense_fingerprint": "「三」を表す数字・文字としての3", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: contains vocabulary far above tier T1: 算用 (Zipf 1.91)']::text[], '2e064089-d9b2-48bf-a97c-c43dc8016428') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36910, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "3", "is_correct": true, "explanation": "「黒板に大きく「3」と書きました」の、書かれた数字の3。"}, {"text": "チョーク", "is_correct": false, "explanation": "書く道具の名前で、書かれる文字の位置に入れると文意が成り立たない。"}, {"text": "ピアノ", "is_correct": false, "explanation": "楽器の名前で、黒板に書かれるものとしては合わない。"}, {"text": "ごはん", "is_correct": false, "explanation": "食べ物の名前で、黒板に大きく書く対象としては文が成り立たない。"}], "explanations": {"3": "「黒板に大きく「3」と書きました」の、書かれた数字の3。", "チョーク": "書く道具の名前で、書かれる文字の位置に入れると文意が成り立たない。", "ピアノ": "楽器の名前で、黒板に書かれるものとしては合わない。", "ごはん": "食べ物の名前で、黒板に大きく書く対象としては文が成り立たない。"}, "sentence_index": 0, "correct_answer": "3"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議室は3階にあります。", "explanation": "ここは〈階数〉の意味。階数の3は場所の番号で、数量としての3ではない。"}, {"text": "マラソンで3位になり、表彰台に上がった。", "explanation": "ここは〈順位〉の意味。3位は順位を表し、字形としての「3」の説明には合わない。"}, {"text": "会議は3時に始まる予定です。", "explanation": "ここは〈時刻〉の意味。時刻の3は時間を表し、数字の字形の説明とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36910, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "3", "is_correct": true, "explanation": "「数字の「3」を、まだ上手に書けません」の、書く対象の数字3。"}, {"text": "ドア", "is_correct": false, "explanation": "建物の出入り口の名前で、書く対象の数字としては文が成り立たない。"}, {"text": "ボール", "is_correct": false, "explanation": "遊具の名前で、数字の代わりに書く対象としては合わない。"}, {"text": "ふとん", "is_correct": false, "explanation": "寝具の名前で、数字の文脈に合わない。"}], "explanations": {"3": "「数字の「3」を、まだ上手に書けません」の、書く対象の数字3。", "ドア": "建物の出入り口の名前で、書く対象の数字としては文が成り立たない。", "ボール": "遊具の名前で、数字の代わりに書く対象としては合わない。", "ふとん": "寝具の名前で、数字の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "3"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "3月に新しい学年が始まります。", "explanation": "ここは〈月〉の意味。3月は暦の月名で、数量としての3ではない。"}, {"text": "来月の給料は、3割増えた。", "explanation": "ここは〈割合〉の意味。3割は十分の三の割合を表し、字形の「3」の説明とは合わない。"}, {"text": "バスは3番乗り場から出発します。", "explanation": "ここは〈番号〉の意味。乗り場の番号の3は識別番号で、書かれた字形の説明とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36910, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "1の次は2で、2の次は3かです。", "corrected_sentence": "1の次は2で、2の次は3です。", "error_description": "誤りは「3」の直後の助詞「か」。「3です」が正しく、「3かです」は文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36910, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもは、数字の「3」を一つずつ丁寧に書きまし。", "corrected_sentence": "子どもは、数字の「3」を一つずつ丁寧に書きます。", "error_description": "誤りは動詞「書く」の活用。「書きまし」は途中で切れて文が成り立たない。正しくは「書きます」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
