INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36911, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "2より1大きく、4より1小さい数。", "primary_collocate": null, "pronunciation": "さん", "ipa": "saɴ", "syllable_count": 2, "sentences": [{"text": "2に1を足すと、答えは「3」になります。", "target_word": "3", "complexity_tier": "T3", "furigana": "2[に]に1[いち]を足[た]すと、答[こた]えは「3[さん]」になります。", "sentence_source": "generated"}, {"text": "「3」は1より大きくて、4より小さい数です。", "target_word": "3", "complexity_tier": "T3", "furigana": "「3[さん]」は1[いち]より大[おお]きくて、4[よん]より小[ちい]さい数[かず]です。", "sentence_source": "generated"}, {"text": "6を2で割ると「3」です。", "target_word": "3", "complexity_tier": "T3", "furigana": "6[ろく]を2[に]で割[わ]ると「3[さん]」です。", "sentence_source": "generated"}, {"text": "1、2、「3」と数えてから、いっしょにジャンプしましょう。", "target_word": "3", "complexity_tier": "T3", "furigana": "1[いち]、2[に]、「3[さん]」と数[かぞ]えてから、いっしょにジャンプしましょう。", "sentence_source": "generated"}, {"text": "9を「3」で割ると、答えも「3」になります。", "target_word": "3", "complexity_tier": "T3", "furigana": "9[きゅう]を「3[さん]」で割[わ]ると、答[こた]えも「3[さん]」になります。", "sentence_source": "generated"}, {"text": "「3」から1を引くと2が残ります。", "target_word": "3", "complexity_tier": "T3", "furigana": "「3[さん]」から1[いち]を引[ひ]くと2[に]が残[のこ]ります。", "sentence_source": "generated"}, {"text": "1と「3」の間にある整数は2だけです。", "target_word": "3", "complexity_tier": "T3", "furigana": "1[いち]と「3[さん]」の間[あいだ]にある整数[せいすう]は2[に]だけです。", "sentence_source": "generated"}, {"text": "4より1小さい数は「3」です。", "target_word": "3", "complexity_tier": "T3", "furigana": "4[よん]より1[いち]小[ちい]さい数[かず]は「3[さん]」です。", "sentence_source": "generated"}, {"text": "りんごは最初2つでしたが、1つ増えて「3」になりました。", "target_word": "3", "complexity_tier": "T3", "furigana": "りんごは最初[さいしょ]2[ふた]つでしたが、1[ひと]つ増[ふ]えて「3[さん]」になりました。", "sentence_source": "generated"}, {"text": "「3」は奇数で、2では割り切れません。", "target_word": "3", "complexity_tier": "T3", "furigana": "「3[さん]」は奇数[きすう]で、2[に]では割[わ]り切[き]れません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "3", "label": "Arabic numeral"}, {"form": "三", "label": "kanji numeral"}], "register": "neutral", "sense_fingerprint": "2の次、4の前にある数量としての3", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e064089-d9b2-48bf-a97c-c43dc8016428') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36911, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "3", "is_correct": true, "explanation": "2に1を足した答えの数「3」なので、「答えは「3」になります」で文意が合う。"}, {"text": "ドア", "is_correct": false, "explanation": "ものの名前で、計算の答えとしては「答えは「ドア」になります」が成り立たない。"}, {"text": "ひみつ", "is_correct": false, "explanation": "抽象的な語で、計算の答えとして「なります」に続けられない。"}, {"text": "ボール", "is_correct": false, "explanation": "遊具の名前で、計算結果を表す文脈に合わない。"}], "explanations": {"3": "2に1を足した答えの数「3」なので、「答えは「3」になります」で文意が合う。", "ドア": "ものの名前で、計算の答えとしては「答えは「ドア」になります」が成り立たない。", "ひみつ": "抽象的な語で、計算の答えとして「なります」に続けられない。", "ボール": "遊具の名前で、計算結果を表す文脈に合わない。"}, "sentence_index": 0, "correct_answer": "3"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "マラソンで3位になり、表彰台に上がった。", "explanation": "ここは〈順位〉の意味。3位は順位を表す用法で、1より大きく4より小さい数としての3は指さない。"}, {"text": "待ち合わせは3時に駅前です。", "explanation": "ここは〈時刻〉の意味。時刻の3は時間を表し、数としての3の説明とは合わない。"}, {"text": "3年生の教室で、算数を教えています。", "explanation": "ここは〈学年〉の意味。3年生の3は学年を表し、数量としての3ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36911, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "3", "is_correct": true, "explanation": "「1と「3」の間にある整数は2だけ」と文意が合う数の3。"}, {"text": "ピアノ", "is_correct": false, "explanation": "楽器の名前で、数の範囲を表す文に入れると文が成り立たない。"}, {"text": "ノート", "is_correct": false, "explanation": "文房具の名前で、数の範囲を表す文には合わない。"}, {"text": "ふとん", "is_correct": false, "explanation": "寝具の名前で、数の間にある整数の文脈に合わない。"}], "explanations": {"3": "「1と「3」の間にある整数は2だけ」と文意が合う数の3。", "ピアノ": "楽器の名前で、数の範囲を表す文に入れると文が成り立たない。", "ノート": "文房具の名前で、数の範囲を表す文には合わない。", "ふとん": "寝具の名前で、数の間にある整数の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "3"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議室は3階にあります。", "explanation": "ここは〈階数〉の意味。階数の3は場所の番号で、数量としての3ではない。"}, {"text": "来月の給料は、3割増えた。", "explanation": "ここは〈割合〉の意味。3割は十分の三の割合を表し、数としての3ではない。"}, {"text": "バスは3番乗り場から出発します。", "explanation": "ここは〈番号〉の意味。乗り場の番号の3は識別のための番号で、数量としての3ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36911, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奇数は1、3を5と続きます。", "corrected_sentence": "奇数は1、3、5と続きます。", "error_description": "誤りは「3」の直後の助詞「を」。並べて挙げるときは「、」を使う。「3を」は目的語の形で、文意に合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36911, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "2と4の間にあるのは3にだけです。", "corrected_sentence": "2と4の間にあるのは3だけです。", "error_description": "誤りは「3」の直後に余計な助詞「に」がついている点。「3だけ」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36912, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「元の場所」の「の」は「元」が後ろの名詞「場所」を修飾することを示す。"}, {"text": "を", "is_correct": false, "explanation": "「元を場所」は目的語の形になるが、後ろの名詞を修飾する関係にならない。"}, {"text": "に", "is_correct": false, "explanation": "「元に場所」は「〜に基づいて」の形に合わず、名詞「場所」にもつながらない。"}, {"text": "で", "is_correct": false, "explanation": "「元で場所」は手段や場所の形になるが、「場所」を修飾する文脈に合わない。"}], "correct_answer": "の", "explanations": {"の": "正解。「元の場所」の「の」は「元」が後ろの名詞「場所」を修飾することを示す。", "を": "「元を場所」は目的語の形になるが、後ろの名詞を修飾する関係にならない。", "に": "「元に場所」は「〜に基づいて」の形に合わず、名詞「場所」にもつながらない。", "で": "「元で場所」は手段や場所の形になるが、「場所」を修飾する文脈に合わない。"}, "error_tags": {"を": "目的語の格助詞（修飾にならない）", "に": "方向・基準の格助詞", "で": "手段・場所の格助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36912, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「元の形」の「の」は「元」が「形」を修飾することを示す。"}, {"text": "が", "is_correct": false, "explanation": "「元が形」は主語を示す形になり、「形」を修飾しないので「元の形」の代わりにならない。"}, {"text": "へ", "is_correct": false, "explanation": "「元へ形」は方向の形になり、「形」を修飾する関係にならない。"}, {"text": "より", "is_correct": false, "explanation": "「元より形」は比較の形になり、「形」を修飾する関係にならない。"}], "correct_answer": "の", "explanations": {"の": "正解。「元の形」の「の」は「元」が「形」を修飾することを示す。", "が": "「元が形」は主語を示す形になり、「形」を修飾しないので「元の形」の代わりにならない。", "へ": "「元へ形」は方向の形になり、「形」を修飾する関係にならない。", "より": "「元より形」は比較の形になり、「形」を修飾する関係にならない。"}, "error_tags": {"が": "主語の格助詞（修飾にならない）", "へ": "方向の格助詞", "より": "比較（修飾にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36912, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものごとの、はじめ。もと。", "primary_collocate": null, "pronunciation": "もと", "ipa": "moto", "syllable_count": 2, "sentences": [{"text": "元は小さな店でしたが、今は大きくなりました。", "target_word": "元", "complexity_tier": "T3", "furigana": "元[もと]は小[ちい]さな店[みせ]でしたが、今[いま]は大[おお]きくなりました。", "sentence_source": "generated"}, {"text": "本を元の場所に戻してください。", "target_word": "元", "complexity_tier": "T3", "furigana": "本[ほん]を元[もと]の場所[ばしょ]に戻[もど]してください。", "sentence_source": "generated"}, {"text": "この町は元は海でした。", "target_word": "元", "complexity_tier": "T3", "furigana": "この町[まち]は元[もと]は海[うみ]でした。", "sentence_source": "generated"}, {"text": "元の値段は千円でしたが、半分になりました。", "target_word": "元", "complexity_tier": "T3", "furigana": "元[もと]の値段[ねだん]は千円[せんえん]でしたが、半分[はんぶん]になりました。", "sentence_source": "generated"}, {"text": "彼は元の会社に戻ることにした。", "target_word": "元", "complexity_tier": "T3", "furigana": "彼[かれ]は元[もと]の会社[かいしゃ]に戻[もど]ることにした。", "sentence_source": "generated"}, {"text": "元の持ち主に本を返した。", "target_word": "元", "complexity_tier": "T3", "furigana": "元[もと]の持[も]ち主[ぬし]に本[ほん]を返[かえ]した。", "sentence_source": "generated"}, {"text": "病気が治って、元の生活に戻れた。", "target_word": "元", "complexity_tier": "T3", "furigana": "病気[びょうき]が治[なお]って、元[もと]の生活[せいかつ]に戻[もど]れた。", "sentence_source": "generated"}, {"text": "元の形がわからないほど、壊れていた。", "target_word": "元", "complexity_tier": "T3", "furigana": "元[もと]の形[かたち]がわからないほど、壊[こわ]れていた。", "sentence_source": "generated"}, {"text": "このお菓子は元はヨーロッパのものです。", "target_word": "元", "complexity_tier": "T3", "furigana": "このお菓子[かし]は元[もと]はヨーロッパのものです。", "sentence_source": "generated"}, {"text": "使ったあとは、道具を元の位置に片づけます。", "target_word": "元", "complexity_tier": "T3", "furigana": "使[つか]ったあとは、道具[どうぐ]を元[もと]の位置[いち]に片[かた]づけます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "元", "label": "基本形"}, {"form": "元の", "label": "連体形（名詞＋の）"}, {"form": "元は", "label": "主題形（名詞＋は）"}], "register": "標準（中立）", "sense_fingerprint": "物事のはじめ・もとの状態や場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce42f7e-bdb3-4b75-b684-6dd8db65015b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36912, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "元", "is_correct": true, "explanation": "正解。「元は」で『はじめ・もと』の意味になり、「今は」との対比に合う。"}, {"text": "山", "is_correct": false, "explanation": "「山は小さな店でしたが」は意味が通らない。"}, {"text": "理由", "is_correct": false, "explanation": "「理由は小さな店でしたが」は成り立たず、店の大きさの変化を表せない。"}, {"text": "予定", "is_correct": false, "explanation": "「予定は小さな店でしたが」は不自然で、店が大きくなったという内容に合わない。"}], "explanations": {"元": "正解。「元は」で『はじめ・もと』の意味になり、「今は」との対比に合う。", "山": "「山は小さな店でしたが」は意味が通らない。", "理由": "「理由は小さな店でしたが」は成り立たず、店の大きさの変化を表せない。", "予定": "「予定は小さな店でしたが」は不自然で、店が大きくなったという内容に合わない。"}, "sentence_index": 0, "correct_answer": "元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この機械の元を取るには三年かかった。", "explanation": "ここは〈元金〉の意味。〈元〉は「もと・はじめ」ではなく、払った費用（元手）を指す。"}, {"text": "元首が国民に向けて演説した。", "explanation": "ここは〈元首〉の意味。〈元〉は「はじめ・もと」ではなく、国の最高位の人を指す。"}, {"text": "この国の元首は五年ごとに選ばれる。", "explanation": "ここも〈元首〉の意味。「もとの状態」を表さないので、〈元〉の義項としては誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36912, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "元", "is_correct": true, "explanation": "正解。「元の生活」で、病気が治ってから戻る先の状態を表す。"}, {"text": "窓", "is_correct": false, "explanation": "「窓の生活」は意味をなさず、戻る先を表せない。"}, {"text": "辞書", "is_correct": false, "explanation": "「辞書の生活」は成り立たず、生活の状態には合わない。"}, {"text": "薬", "is_correct": false, "explanation": "「薬の生活」は不自然で、病気が治ったあとの生活とは結びつかない。"}], "explanations": {"元": "正解。「元の生活」で、病気が治ってから戻る先の状態を表す。", "窓": "「窓の生活」は意味をなさず、戻る先を表せない。", "辞書": "「辞書の生活」は成り立たず、生活の状態には合わない。", "薬": "「薬の生活」は不自然で、病気が治ったあとの生活とは結びつかない。"}, "sentence_index": 6, "correct_answer": "元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "元首が年頭の演説を行った。", "explanation": "ここは〈元首〉の意味。〈元〉は「はじめ・もと」ではなく、国の最高位の人を指す。"}, {"text": "元金がなくなって、会社は困った。", "explanation": "ここは〈元金〉の意味。〈元〉は「はじめ・もと」の状態ではなく、資金を指す。"}, {"text": "この商売は元を固めて、着実に進めた。", "explanation": "ここは〈基礎〉の意味。〈元〉は「もと・始まり」を表すが、事業の土台を固める意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36912, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "本は元を場所にあります。", "corrected_sentence": "本は元の場所にあります。", "error_description": "「元」の直後の助詞が「を」になっている。「元の場所」と名詞を修飾するには連体修飾の「の」が必要で、「元を場所」は成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36912, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は元を職場に戻って働いている。", "corrected_sentence": "彼は元の職場に戻って働いている。", "error_description": "「元の」の「の」が「を」になっている。「元の職場」と修飾する形が正しく、「元を職場」は文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36913, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「経験を元にして」の「に」は『〜に基づいて』の形を作る。"}, {"text": "の", "is_correct": false, "explanation": "「元の」は名詞を修飾するが、後ろの「して」が続かず文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「元でして」は手段の形にならず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「元をして」は目的語の形にならず、後ろの「して」と続かない。"}], "correct_answer": "に", "explanations": {"に": "正解。「経験を元にして」の「に」は『〜に基づいて』の形を作る。", "の": "「元の」は名詞を修飾するが、後ろの「して」が続かず文が成り立たない。", "で": "「元でして」は手段の形にならず、文が成り立たない。", "を": "「元をして」は目的語の形にならず、後ろの「して」と続かない。"}, "error_tags": {"の": "名詞修飾の格助詞", "で": "手段・場所の格助詞", "を": "目的語の格助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36913, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「病気の元」の「の」は「元」が「病気」を受けて名詞を修飾する関係を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「病気へ元は」は方向の形になり、文の主語を作れない。"}, {"text": "から", "is_correct": false, "explanation": "「病気から元は」は起点の形になり、「病気の元」という名詞の関係にならない。"}, {"text": "に", "is_correct": false, "explanation": "「病気に元は」は位置や帰着の形になり、「病気の元」の関係にならない。"}], "correct_answer": "の", "explanations": {"の": "正解。「病気の元」の「の」は「元」が「病気」を受けて名詞を修飾する関係を示す。", "へ": "「病気へ元は」は方向の形になり、文の主語を作れない。", "から": "「病気から元は」は起点の形になり、「病気の元」という名詞の関係にならない。", "に": "「病気に元は」は位置や帰着の形になり、「病気の元」の関係にならない。"}, "error_tags": {"へ": "方向の格助詞", "から": "起点の格助詞", "に": "位置・帰着の格助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36913, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の根源や基礎。", "primary_collocate": null, "pronunciation": "もと", "ipa": "moto", "syllable_count": 2, "sentences": [{"text": "この映画は実話を元に作られました。", "target_word": "元", "complexity_tier": "T3", "furigana": "この映画[えいが]は実話[じつわ]を元[もと]に作[つく]られました。", "sentence_source": "generated"}, {"text": "経験を元にして、新しい計画を立てた。", "target_word": "元", "complexity_tier": "T3", "furigana": "経験[けいけん]を元[もと]にして、新[あたら]しい計画[けいかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "火の元をよく確かめてから出かけます。", "target_word": "元", "complexity_tier": "T3", "furigana": "火[ひ]の元[もと]をよく確[たし]かめてから出[で]かけます。", "sentence_source": "generated"}, {"text": "けんかの元は、小さな誤解だった。", "target_word": "元", "complexity_tier": "T3", "furigana": "けんかの元[もと]は、小[ちい]さな誤解[ごかい]だった。", "sentence_source": "generated"}, {"text": "失敗は成功の元と言われている。", "target_word": "元", "complexity_tier": "T3", "furigana": "失敗[しっぱい]は成功[せいこう]の元[もと]と言[い]われている。", "sentence_source": "generated"}, {"text": "古い写真を元に、昔の町の絵をかいた。", "target_word": "元", "complexity_tier": "T3", "furigana": "古[ふる]い写真[しゃしん]を元[もと]に、昔[むかし]の町[まち]の絵[え]をかいた。", "sentence_source": "generated"}, {"text": "調査の結果を元に、先生が意見を述べた。", "target_word": "元", "complexity_tier": "T3", "furigana": "調査[ちょうさ]の結果[けっか]を元[もと]に、先生[せんせい]が意見[いけん]を述[の]べた。", "sentence_source": "generated"}, {"text": "病気の元は、毎日の不規則な生活にあった。", "target_word": "元", "complexity_tier": "T3", "furigana": "病気[びょうき]の元[もと]は、毎日[まいにち]の不規則[ふきそく]な生活[せいかつ]にあった。", "sentence_source": "generated"}, {"text": "このスープは鶏肉の出汁を元に作ります。", "target_word": "元", "complexity_tier": "T3", "furigana": "このスープは鶏肉[とりにく]の出汁[だし]を元[もと]に作[つく]ります。", "sentence_source": "generated"}, {"text": "この手紙の内容を元に、話し合いを始めましょう。", "target_word": "元", "complexity_tier": "T3", "furigana": "この手紙[てがみ]の内容[ないよう]を元[もと]に、話[はな]し合[あ]いを始[はじ]めましょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "元", "label": "基本形"}, {"form": "元に", "label": "「〜を元に」の形（名詞＋に）"}, {"form": "元の", "label": "連体形（名詞＋の）"}], "register": "標準（中立）", "sense_fingerprint": "物事の根源・原因・よりどころ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce42f7e-bdb3-4b75-b684-6dd8db65015b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36913, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "元", "is_correct": true, "explanation": "正解。「実話を元に」で『〜に基づいて』の意味になり、映画の根拠を示す。"}, {"text": "窓", "is_correct": false, "explanation": "「実話を窓に作られました」は意味が通らない。"}, {"text": "影", "is_correct": false, "explanation": "「実話を影に作られました」は成り立たず、根拠を表せない。"}, {"text": "外", "is_correct": false, "explanation": "「実話を外に作られました」は不自然で、根拠を示す文脈に合わない。"}], "explanations": {"元": "正解。「実話を元に」で『〜に基づいて』の意味になり、映画の根拠を示す。", "窓": "「実話を窓に作られました」は意味が通らない。", "影": "「実話を影に作られました」は成り立たず、根拠を表せない。", "外": "「実話を外に作られました」は不自然で、根拠を示す文脈に合わない。"}, "sentence_index": 0, "correct_answer": "元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "元首は国の代表として外国を訪れた。", "explanation": "ここは〈元首〉の意味。〈元〉は根源・基礎ではなく、国の最高位の人を指す。"}, {"text": "この設備の元を取るには三年かかった。", "explanation": "ここは〈元金〉の意味。〈元〉は根源・基礎ではなく、払った費用を指す。"}, {"text": "元首の任期は五年だった。", "explanation": "ここも〈元首〉の意味。根源・基礎の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36913, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "元", "is_correct": true, "explanation": "正解。「結果を元に」で『〜に基づいて』の意味になり、意見の根拠を示す。"}, {"text": "鍵", "is_correct": false, "explanation": "「調査の結果を鍵に」は成り立たず、根拠を表せない。"}, {"text": "泡", "is_correct": false, "explanation": "「調査の結果を泡に」は意味が通らず、根拠の文脈に合わない。"}, {"text": "夢", "is_correct": false, "explanation": "「調査の結果を夢に」は不自然で、意見の根拠を示す文脈に合わない。"}], "explanations": {"元": "正解。「結果を元に」で『〜に基づいて』の意味になり、意見の根拠を示す。", "鍵": "「調査の結果を鍵に」は成り立たず、根拠を表せない。", "泡": "「調査の結果を泡に」は意味が通らず、根拠の文脈に合わない。", "夢": "「調査の結果を夢に」は不自然で、意見の根拠を示す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "元首が年頭の演説を行った。", "explanation": "ここは〈元首〉の意味。〈元〉は根源・基礎ではなく、国の最高位の人を指す。"}, {"text": "元金を銀行に預けて利息を得た。", "explanation": "ここは〈元金〉の意味。根源・基礎ではなく、預けた資金を指す。"}, {"text": "元日に家族で初詣に行った。", "explanation": "ここは〈年の初め〉の意味。〈元〉は根源・基礎ではなく、年の始まりを表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36913, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "過去のデータを元の、この先の天気を予測した。", "corrected_sentence": "過去のデータを元に、この先の天気を予測した。", "error_description": "「元に」の「に」が「の」になっている。「〜を元に」で根拠を示す形が正しく、「元の、」では文が途切れて成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36913, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この小説は実際の事件を元に建てられた。", "corrected_sentence": "この小説は実際の事件を元に書かれた。", "error_description": "「書かれた」が「建てられた」になっている。「元に」と組むのは作品を作る動詞の「書く」「作る」などで、「建てる」は作品には使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
