INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36914, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "ふわふわは、やわらかくて、かるいもののうごきをあらわすことばです。", "primary_collocate": null, "pronunciation": "ふわふわ", "ipa": "ɸɯwaɸɯwa", "syllable_count": 4, "sentences": [{"text": "風船がふわふわと空へ上がっていった。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "風船[ふうせん]がふわふわと空[そら]へ上[あ]がっていった。", "sentence_source": "generated"}, {"text": "白い羽がふわふわと落ちてきた。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "白[しろ]い羽[はね]がふわふわと落[お]ちてきた。", "sentence_source": "generated"}, {"text": "雪がふわふわと舞っている。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "雪[ゆき]がふわふわと舞[ま]っている。", "sentence_source": "generated"}, {"text": "たんぽぽの綿毛がふわふわと風に飛んだ。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "たんぽぽの綿毛[わたげ]がふわふわと風[かぜ]に飛[と]んだ。", "sentence_source": "generated"}, {"text": "シャボン玉がふわふわと庭の上を漂っていた。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "シャボン玉[だま]がふわふわと庭[にわ]の上[うえ]を漂[ただよ]っていた。", "sentence_source": "generated"}, {"text": "窓を開けると、カーテンがふわふわと揺れた。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けると、カーテンがふわふわと揺[ゆ]れた。", "sentence_source": "generated"}, {"text": "雲がふわふわと流れて、空が明るくなった。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "雲[くも]がふわふわと流[なが]れて、空[そら]が明[あか]るくなった。", "sentence_source": "generated"}, {"text": "軽い紙が、ふわふわと机の下に落ちた。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "軽[かる]い紙[かみ]が、ふわふわと机[つくえ]の下[した]に落[お]ちた。", "sentence_source": "generated"}, {"text": "猫の毛が、ふわふわと部屋の中を飛んでいる。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "猫[ねこ]の毛[け]が、ふわふわと部屋[へや]の中[なか]を飛[と]んでいる。", "sentence_source": "generated"}, {"text": "水の中で、海藻がふわふわと動いている。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "水[みず]の中[なか]で、海藻[かいそう]がふわふわと動[うご]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ふわふわ", "label": "基本形"}, {"form": "ふわふわと", "label": "副詞形（と）"}, {"form": "ふわふわする", "label": "動詞形（する）"}], "register": "擬態語（口語的）", "sense_fingerprint": "軽いものが空中をゆっくり漂う動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce42f7e-bdb3-4b75-b684-6dd8db65015b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36914, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ふわふわ", "is_correct": true, "explanation": "正解。軽いものがゆっくり空へ漂う様子を表し、風船の動きに合う。"}, {"text": "ずるずる", "is_correct": false, "explanation": "物を引きずって動く様子を表し、軽く浮かぶ動きには合わない。"}, {"text": "かちかち", "is_correct": false, "explanation": "硬く固まった様子を表す語で、軽く浮かぶ動きとは合わない。"}, {"text": "ごろごろ", "is_correct": false, "explanation": "転がる様子を表す語で、空へ上がっていく動きには合わない。"}], "explanations": {"ふわふわ": "正解。軽いものがゆっくり空へ漂う様子を表し、風船の動きに合う。", "ずるずる": "物を引きずって動く様子を表し、軽く浮かぶ動きには合わない。", "かちかち": "硬く固まった様子を表す語で、軽く浮かぶ動きとは合わない。", "ごろごろ": "転がる様子を表す語で、空へ上がっていく動きには合わない。"}, "sentence_index": 0, "correct_answer": "ふわふわ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドアをふわふわ叩いた。", "explanation": "ここは〈ドンドン〉の意味。〈ふわふわ〉は軽く漂う動きを表し、強く叩く動作には使えない。"}, {"text": "コマがふわふわと回っている。", "explanation": "〈コマ〉は速く回転する動きで、〈ふわふわ〉の軽くゆっくり漂う動きとは合わない。〈ぐるぐる〉などの回転の語の代わりに入れた形。"}, {"text": "金属の塊がふわふわと床に落ちた。", "explanation": "ここは〈どすん〉の意味。〈ふわふわ〉は軽いものの動きを表すので、重い金属の落下には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36914, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ふわふわ", "is_correct": true, "explanation": "正解。雲が軽くゆっくり流れていく様子を表し、文脈に合う。"}, {"text": "ぱさぱさ", "is_correct": false, "explanation": "乾いて潤いがない様子を表し、雲の動きには合わない。"}, {"text": "ばりばり", "is_correct": false, "explanation": "硬いものを勢いよく砕く様子を表し、雲の流れには合わない。"}, {"text": "ぺたぺた", "is_correct": false, "explanation": "物がくっついたり軽く触れたりする様子で、流れる雲には合わない。"}], "explanations": {"ふわふわ": "正解。雲が軽くゆっくり流れていく様子を表し、文脈に合う。", "ぱさぱさ": "乾いて潤いがない様子を表し、雲の動きには合わない。", "ばりばり": "硬いものを勢いよく砕く様子を表し、雲の流れには合わない。", "ぺたぺた": "物がくっついたり軽く触れたりする様子で、流れる雲には合わない。"}, "sentence_index": 6, "correct_answer": "ふわふわ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車がふわふわと揺れている。", "explanation": "〈電車〉の揺れは振動で、〈ふわふわ〉の軽く漂う動きとは合わない。〈がたがた〉の代わりに入れた形。"}, {"text": "頭をふわふわとぶつけた。", "explanation": "ここは〈ゴツン〉の意味。〈ふわふわ〉は軽く漂う動きを表すので、衝突の衝撃や音を表す語の代わりには使えない。"}, {"text": "この箱は中身が多くて、ふわふわと重い。", "explanation": "重さを表す〈ずしり〉の代わりに入れた形。〈ふわふわ〉は軽さを表すので、重さの形容には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36914, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "綿毛がふわふわを風に乗って飛んでいく。", "corrected_sentence": "綿毛がふわふわと風に乗って飛んでいく。", "error_description": "「ふわふわと」の「と」が「を」になっている。副詞として動詞を修飾する「と」が必要で、「を」では目的語になり文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36914, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "紙吹雪がふわふわと突き刺さっている。", "corrected_sentence": "紙吹雪がふわふわと舞っている。", "error_description": "「舞っている」が「突き刺さっている」になっている。〈ふわふわ〉と組む動詞は「舞う」「漂う」などの軽い動きで、「突き刺さる」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
