INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36915, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "物が柔らかく、軽い感じで動いたり、空気を含んで膨らんでいる様子を表す言葉です。", "primary_collocate": null, "pronunciation": "ふわふわ", "ipa": "ɸɯwaɸɯwa", "syllable_count": 4, "sentences": [{"text": "このパンはふわふわで、とてもおいしい。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "このパンはふわふわで、とてもおいしい。", "sentence_source": "generated"}, {"text": "ふわふわのタオルで顔をふいた。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "ふわふわのタオルで顔[かお]をふいた。", "sentence_source": "generated"}, {"text": "新しい布団がふわふわで、よく眠れた。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "新[あたら]しい布団[ふとん]がふわふわで、よく眠[ねむ]れた。", "sentence_source": "generated"}, {"text": "ふわふわの卵焼きを朝ごはんに作った。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "ふわふわの卵焼[たまごや]きを朝[あさ]ごはんに作[つく]った。", "sentence_source": "generated"}, {"text": "子犬の毛はふわふわしていて、さわると気持ちいい。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "子犬[こいぬ]の毛[け]はふわふわしていて、さわると気持[きも]ちいい。", "sentence_source": "generated"}, {"text": "雪がふわふわに積もっている。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "雪[ゆき]がふわふわに積[つ]もっている。", "sentence_source": "generated"}, {"text": "ふわふわのケーキを友だちの誕生日に焼いた。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "ふわふわのケーキを友[とも]だちの誕生日[たんじょうび]に焼[や]いた。", "sentence_source": "generated"}, {"text": "ふわふわのセーターは暖かくて軽い。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "ふわふわのセーターは暖[あたた]かくて軽[かる]い。", "sentence_source": "generated"}, {"text": "娘はふわふわのぬいぐるみをいつも抱いている。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "娘[むすめ]はふわふわのぬいぐるみをいつも抱[だ]いている。", "sentence_source": "generated"}, {"text": "生クリームをふわふわになるまで混ぜます。", "target_word": "ふわふわ", "complexity_tier": "T3", "furigana": "生[なま]クリームをふわふわになるまで混[ま]ぜます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ふわふわ", "label": "基本形"}, {"form": "ふわふわの", "label": "連体形（の）"}, {"form": "ふわふわに", "label": "連用形（に）"}], "register": "擬態語（口語的）", "sense_fingerprint": "空気を含んで柔らかく膨らんだ手ざわり・状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce42f7e-bdb3-4b75-b684-6dd8db65015b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36915, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ふわふわ", "is_correct": true, "explanation": "正解。空気を含んで柔らかく膨らんだパンの食感を表す。"}, {"text": "ぬるぬる", "is_correct": false, "explanation": "ぬるぬるした滑りやすい感触を表し、柔らかく膨らんだパンの食感には合わない。"}, {"text": "ぴかぴか", "is_correct": false, "explanation": "光沢があって輝く様子を表し、パンの食感の説明にはならない。"}, {"text": "ずきずき", "is_correct": false, "explanation": "痛みが脈打つ様子を表す語で、食べ物の食感には使えない。"}], "explanations": {"ふわふわ": "正解。空気を含んで柔らかく膨らんだパンの食感を表す。", "ぬるぬる": "ぬるぬるした滑りやすい感触を表し、柔らかく膨らんだパンの食感には合わない。", "ぴかぴか": "光沢があって輝く様子を表し、パンの食感の説明にはならない。", "ずきずき": "痛みが脈打つ様子を表す語で、食べ物の食感には使えない。"}, "sentence_index": 0, "correct_answer": "ふわふわ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "卵をふわふわ割った。", "explanation": "ここは〈ぱっと〉の意味。〈ふわふわ〉は柔らかく膨らんだ状態を表し、卵を割る動作の様子には合わない。"}, {"text": "薬を飲んだら、頭がふわふわしてきた。", "explanation": "ここはめまいの意味（頭がふわふわする）。物の柔らかさや膨らみは表さない。"}, {"text": "岩の表面がふわふわしている。", "explanation": "〈ごつごつ〉の代わりに入れた形。岩は硬く凸凹で、柔らかく膨らんだ〈ふわふわ〉の性質には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36915, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ふわふわ", "is_correct": true, "explanation": "正解。空気を含んで柔らかく膨らんだケーキの食感を表す。"}, {"text": "ちかちか", "is_correct": false, "explanation": "明かりがまたたく様子を表し、ケーキの食感には使えない。"}, {"text": "ぐらぐら", "is_correct": false, "explanation": "揺れて不安定な様子を表し、ケーキの食感の説明にはならない。"}, {"text": "ぴりぴり", "is_correct": false, "explanation": "舌を刺すような刺激や緊張した様子を表し、柔らかく膨らんだ食感には合わない。"}], "explanations": {"ふわふわ": "正解。空気を含んで柔らかく膨らんだケーキの食感を表す。", "ちかちか": "明かりがまたたく様子を表し、ケーキの食感には使えない。", "ぐらぐら": "揺れて不安定な様子を表し、ケーキの食感の説明にはならない。", "ぴりぴり": "舌を刺すような刺激や緊張した様子を表し、柔らかく膨らんだ食感には合わない。"}, "sentence_index": 6, "correct_answer": "ふわふわ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "箱に荷物をふわふわ詰めた。", "explanation": "ここは〈ぎゅうぎゅう〉の意味。〈ふわふわ〉は柔らかく膨らんだ様子で、力を入れて詰め込む動作には合わない。"}, {"text": "熱で頭がふわふわして、ぼんやりしていた。", "explanation": "ここもめまいの意味。物の柔らかさや膨らみは表さないので、この義項の誤答になる。"}, {"text": "ふわふわした刃物で指を切った。", "explanation": "ここは〈ぎざぎざ〉の意味。〈ふわふわ〉は柔らかく膨らんだ様子で、鋭い刃物の形には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36915, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この蒸しパンはふわふわに、しっとりしている。", "corrected_sentence": "この蒸しパンはふわふわで、しっとりしている。", "error_description": "「ふわふわで」の「で」が「に」になっている。性質を述べる文では「ふわふわで」と続けるのが正しく、「に」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36915, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ふわふわの石を首に巻いた。", "corrected_sentence": "ふわふわのマフラーを首に巻いた。", "error_description": "「マフラー」が「石」になっている。〈ふわふわの〉が修飾する名詞は柔らかい布製品などで、硬い石は柔らかい感触の修飾と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36916, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白い", "is_correct": true, "explanation": "正解。色の「黒い」の対義語は「白い」。"}, {"text": "赤い", "is_correct": false, "explanation": "色の一つで、黒いの対義語ではない。"}, {"text": "青い", "is_correct": false, "explanation": "色の名称で、黒いとの対義関係にはない。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す語で、色の対義語ではない。"}], "correct_answer": "白い", "explanations": {"白い": "正解。色の「黒い」の対義語は「白い」。", "赤い": "色の一つで、黒いの対義語ではない。", "青い": "色の名称で、黒いとの対義関係にはない。", "重い": "重さを表す語で、色の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36916, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白い", "is_correct": true, "explanation": "正解。この色の意味での「黒い」の対義語は「白い」。"}, {"text": "大きい", "is_correct": false, "explanation": "大きさを表す語で、色の対義語ではない。"}, {"text": "丸い", "is_correct": false, "explanation": "形を表す語で、黒いとの対義関係はない。"}, {"text": "細い", "is_correct": false, "explanation": "太さを表す語で、色の対義語ではない。"}], "correct_answer": "白い", "explanations": {"白い": "正解。この色の意味での「黒い」の対義語は「白い」。", "大きい": "大きさを表す語で、色の対義語ではない。", "丸い": "形を表す語で、黒いとの対義関係はない。", "細い": "太さを表す語で、色の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36916, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "黒い色をしていること。", "primary_collocate": null, "pronunciation": "くろい", "ipa": "kɯɾoi", "syllable_count": 3, "sentences": [{"text": "黒い猫が道を歩いている。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "黒[くろ]い猫[ねこ]が道[みち]を歩[ある]いている。", "sentence_source": "generated"}, {"text": "黒いかばんを電車に忘れた。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "黒[くろ]いかばんを電車[でんしゃ]に忘[わす]れた。", "sentence_source": "generated"}, {"text": "父は黒い靴をはいて仕事に行く。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "父[ちち]は黒[くろ]い靴[くつ]をはいて仕事[しごと]に行[い]く。", "sentence_source": "generated"}, {"text": "黒い髪の人が、受付に立っていた。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "黒[くろ]い髪[かみ]の人[ひと]が、受付[うけつけ]に立[た]っていた。", "sentence_source": "generated"}, {"text": "黒い車が家の前に止まった。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "黒[くろ]い車[くるま]が家[いえ]の前[まえ]に止[と]まった。", "sentence_source": "generated"}, {"text": "弟は黒いペンでノートに名前を書いた。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "弟[おとうと]は黒[くろ]いペンでノートに名前[なまえ]を書[か]いた。", "sentence_source": "generated"}, {"text": "黒い服は汚れが目立たないので、よく着ます。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "黒[くろ]い服[ふく]は汚[よご]れが目立[めだ]たないので、よく着[き]ます。", "sentence_source": "generated"}, {"text": "黒い犬がうれしそうにしっぽを振っている。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "黒[くろ]い犬[いぬ]がうれしそうにしっぽを振[ふ]っている。", "sentence_source": "generated"}, {"text": "黒いコートを着て、駅まで歩いた。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "黒[くろ]いコートを着[き]て、駅[えき]まで歩[ある]いた。", "sentence_source": "generated"}, {"text": "黒い傘を持って、雨の中を出かけた。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "黒[くろ]い傘[かさ]を持[も]って、雨[あめ]の中[なか]を出[で]かけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "黒い", "label": "終止形・連体形"}, {"form": "黒く", "label": "連用形"}, {"form": "黒かった", "label": "過去形"}, {"form": "黒くない", "label": "否定形"}], "register": "標準（中立）", "sense_fingerprint": "物の色が黒であること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce42f7e-bdb3-4b75-b684-6dd8db65015b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36916, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黒い", "is_correct": true, "explanation": "正解。色を表す形容詞の連体形で、名詞「猫」を修飾して文が成り立つ。"}, {"text": "甘い", "is_correct": false, "explanation": "味覚を表す語で、猫の色を説明できない。"}, {"text": "熱い", "is_correct": false, "explanation": "温度を表す語で、猫の色を述べる文に合わない。"}, {"text": "柔らかい", "is_correct": false, "explanation": "手触りを表す語で、猫の色の説明にはならない。"}], "explanations": {"黒い": "正解。色を表す形容詞の連体形で、名詞「猫」を修飾して文が成り立つ。", "甘い": "味覚を表す語で、猫の色を説明できない。", "熱い": "温度を表す語で、猫の色を述べる文に合わない。", "柔らかい": "手触りを表す語で、猫の色の説明にはならない。"}, "sentence_index": 0, "correct_answer": "黒い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電気を消したら、部屋がまるで黒くなった。", "explanation": "ここは〈暗い〉の意味（光が少ない）。〈黒い〉は色を表す語なので、明るさの変化には使わない。"}, {"text": "今日は気分が黒くて、何もやる気が出ない。", "explanation": "気分の落ち込みには〈暗い〉を使う。〈黒い〉は色の説明に使うので、気分には合わない。"}, {"text": "この説明は黒いので、すぐに内容が分かった。", "explanation": "ここは〈明らかだ〉の意味（はっきりしている）。〈黒い〉は色の語なので、説明の分かりやすさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36916, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黒い", "is_correct": true, "explanation": "正解。色を表す形容詞の連体形で、名詞「服」を修飾する。"}, {"text": "辛い", "is_correct": false, "explanation": "味覚を表す語で、服の汚れの見えにくさを述べる文に合わない。"}, {"text": "冷たい", "is_correct": false, "explanation": "温度の感覚を表す語で、汚れが目立つかどうかとは関係ない。"}, {"text": "荒い", "is_correct": false, "explanation": "表面の粗さを表す語で、服の色の説明にならない。"}], "explanations": {"黒い": "正解。色を表す形容詞の連体形で、名詞「服」を修飾する。", "辛い": "味覚を表す語で、服の汚れの見えにくさを述べる文に合わない。", "冷たい": "温度の感覚を表す語で、汚れが目立つかどうかとは関係ない。", "荒い": "表面の粗さを表す語で、服の色の説明にならない。"}, "sentence_index": 6, "correct_answer": "黒い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝の光が黒く差し込んだ。", "explanation": "ここは〈明るい〉の意味（光が強い）。〈黒い〉は色の語なので、光の様子には使わない。"}, {"text": "彼女は黒い紫のワンピースを着て、会場に現れた。", "explanation": "濃い紫は〈濃い〉を使う。〈黒い〉は黒色そのものを指すので、紫の色合いには合わない。"}, {"text": "明日の天気は黒いので、傘はいらない。", "explanation": "ここは〈曇り〉の意味（空の様子）。〈黒い〉は色の語で、天気の様子は〈曇り〉などで表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36916, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は黒く帽子をかぶって散歩した。", "corrected_sentence": "祖父は黒い帽子をかぶって散歩した。", "error_description": "連用形「黒く」は名詞「帽子」を直接修飾できない。連体形「黒い」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "黒い", "is_correct": true, "explanation": "正解。名詞「かばん」を修飾する連体形。"}, {"text": "黒く", "is_correct": false, "explanation": "連用形で、名詞を直接修飾できない。「黒くかばん」は不自然。"}, {"text": "黒くて", "is_correct": false, "explanation": "て形は文を続ける形で、「黒くてかばん」のように名詞を修飾できない。"}, {"text": "黒ければ", "is_correct": false, "explanation": "仮定形で、名詞「かばん」を修飾できず文が成り立たない。"}], "correct_form": "黒い", "base_form": "黒い", "form_label": "連体形", "sentence_index": 1, "explanations": {"黒い": "正解。名詞「かばん」を修飾する連体形。", "黒く": "連用形で、名詞を直接修飾できない。「黒くかばん」は不自然。", "黒くて": "て形は文を続ける形で、「黒くてかばん」のように名詞を修飾できない。", "黒ければ": "仮定形で、名詞「かばん」を修飾できず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36916, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "叔父は黒いく背広を着て、式に出た。", "corrected_sentence": "叔父は黒い背広を着て、式に出た。", "error_description": "「黒いく」という活用形は存在しない誤り。名詞「背広」を修飾する連体形「黒い」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "黒い", "is_correct": true, "explanation": "正解。名詞「犬」を修飾する連体形。"}, {"text": "黒かろう", "is_correct": false, "explanation": "推量形で、名詞「犬」を直接修飾できない。「黒かろう犬」は不自然。"}, {"text": "黒けれど", "is_correct": false, "explanation": "逆接の接続形で、名詞「犬」を修飾できず文が成り立たない。"}, {"text": "黒さ", "is_correct": false, "explanation": "名詞化した形で、「黒さ犬」のように形容詞として名詞を修飾できない。"}], "correct_form": "黒い", "base_form": "黒い", "form_label": "連体形", "sentence_index": 7, "explanations": {"黒い": "正解。名詞「犬」を修飾する連体形。", "黒かろう": "推量形で、名詞「犬」を直接修飾できない。「黒かろう犬」は不自然。", "黒けれど": "逆接の接続形で、名詞「犬」を修飾できず文が成り立たない。", "黒さ": "名詞化した形で、「黒さ犬」のように形容詞として名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36917, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白い", "is_correct": true, "explanation": "正解。光を反射しない暗い色の対義語は「白い」。"}, {"text": "甘い", "is_correct": false, "explanation": "味覚を表す語で、色の対義語ではない。"}, {"text": "軽い", "is_correct": false, "explanation": "重さを表す語で、色の対義語ではない。"}, {"text": "赤い", "is_correct": false, "explanation": "色の一つで、黒いの対義語ではない。"}], "correct_answer": "白い", "explanations": {"白い": "正解。光を反射しない暗い色の対義語は「白い」。", "甘い": "味覚を表す語で、色の対義語ではない。", "軽い": "重さを表す語で、色の対義語ではない。", "赤い": "色の一つで、黒いの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36917, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白い", "is_correct": true, "explanation": "正解。暗い色の意味での「黒い」の対義語は「白い」。"}, {"text": "大きい", "is_correct": false, "explanation": "大きさを表す語で、色の対義語ではない。"}, {"text": "丸い", "is_correct": false, "explanation": "形を表す語で、黒いとの対義関係はない。"}, {"text": "細い", "is_correct": false, "explanation": "太さを表す語で、色の対義語ではない。"}], "correct_answer": "白い", "explanations": {"白い": "正解。暗い色の意味での「黒い」の対義語は「白い」。", "大きい": "大きさを表す語で、色の対義語ではない。", "丸い": "形を表す語で、黒いとの対義関係はない。", "細い": "太さを表す語で、色の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36917, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "色が黒であるさま。光がほとんど反射されず、暗い色合いのこと。", "primary_collocate": null, "pronunciation": "くろい", "ipa": "kɯɾoi", "syllable_count": 3, "sentences": [{"text": "夜の海は黒い色をしていて、少し怖かった。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "夜[よる]の海[うみ]は黒[くろ]い色[いろ]をしていて、少[すこ]し怖[こわ]かった。", "sentence_source": "generated"}, {"text": "黒い雲が広がってきたので、傘を持って出かけた。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "黒[くろ]い雲[くも]が広[ひろ]がってきたので、傘[かさ]を持[も]って出[で]かけた。", "sentence_source": "generated"}, {"text": "焦げたパンの表面が黒い。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "焦[こ]げたパンの表面[ひょうめん]が黒[くろ]い。", "sentence_source": "generated"}, {"text": "この石は黒いので、光がほとんど反射されない。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "この石[いし]は黒[くろ]いので、光[ひかり]がほとんど反射[はんしゃ]されない。", "sentence_source": "generated"}, {"text": "炭は黒い色で、触ると手が汚れる。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "炭[すみ]は黒[くろ]い色[いろ]で、触[さわ]ると手[て]が汚[よご]れる。", "sentence_source": "generated"}, {"text": "空が黒い煙でおおわれた。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "空[そら]が黒[くろ]い煙[けむり]でおおわれた。", "sentence_source": "generated"}, {"text": "黒いサングラスをかけると、まぶしさが減る。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "黒[くろ]いサングラスをかけると、まぶしさが減[へ]る。", "sentence_source": "generated"}, {"text": "黒い影が壁に長くのびていた。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "黒[くろ]い影[かげ]が壁[かべ]に長[なが]くのびていた。", "sentence_source": "generated"}, {"text": "墨は黒い色で、字を書くのに使う。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "墨[すみ]は黒[くろ]い色[いろ]で、字[じ]を書[か]くのに使[つか]う。", "sentence_source": "generated"}, {"text": "黒い夜道は見えにくいので、懐中電灯を持った。", "target_word": "黒い", "complexity_tier": "T3", "furigana": "黒[くろ]い夜道[よみち]は見[み]えにくいので、懐中電灯[かいちゅうでんとう]を持[も]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "黒い", "label": "終止形・連体形"}, {"form": "黒く", "label": "連用形"}, {"form": "黒かった", "label": "過去形"}, {"form": "黒くない", "label": "否定形"}], "register": "標準（中立）", "sense_fingerprint": "光をほとんど反射しない暗い色合い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce42f7e-bdb3-4b75-b684-6dd8db65015b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36917, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黒い", "is_correct": true, "explanation": "正解。海の色が暗いことを表す形容詞の連体形で、「色をしていて」に続く。"}, {"text": "甘い", "is_correct": false, "explanation": "味覚を表す語で、海の色の説明に合わない。"}, {"text": "熱い", "is_correct": false, "explanation": "温度を表す語で、色の説明にならない。"}, {"text": "硬い", "is_correct": false, "explanation": "硬さを表す語で、海の色を述べる文には合わない。"}], "explanations": {"黒い": "正解。海の色が暗いことを表す形容詞の連体形で、「色をしていて」に続く。", "甘い": "味覚を表す語で、海の色の説明に合わない。", "熱い": "温度を表す語で、色の説明にならない。", "硬い": "硬さを表す語で、海の色を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "黒い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女の歌は黒くて、会場中がうっとりと聞き入った。", "explanation": "ここは〈美しい〉の意味（歌の良さ）。〈黒い〉は色の語なので、歌の上手さには使わない。"}, {"text": "この話は黒くて、聞いていると退屈になる。", "explanation": "ここは〈退屈だ〉の意味。〈黒い〉は色を表す語なので、話のつまらなさには使わない。"}, {"text": "この犬の吠え方は黒くて、近所の人が驚いた。", "explanation": "ここは〈激しい〉の意味（声の強さ）。〈黒い〉は色の語なので、吠え方の様子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36917, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黒い", "is_correct": true, "explanation": "正解。サングラスの色を表す連体形で、「サングラス」を修飾する。"}, {"text": "辛い", "is_correct": false, "explanation": "味覚を表す語で、サングラスの色の説明に合わない。"}, {"text": "冷たい", "is_correct": false, "explanation": "温度の感覚を表す語で、色を表す文には合わない。"}, {"text": "荒い", "is_correct": false, "explanation": "表面の粗さを表す語で、色の説明にならない。"}], "explanations": {"黒い": "正解。サングラスの色を表す連体形で、「サングラス」を修飾する。", "辛い": "味覚を表す語で、サングラスの色の説明に合わない。", "冷たい": "温度の感覚を表す語で、色を表す文には合わない。", "荒い": "表面の粗さを表す語で、色の説明にならない。"}, "sentence_index": 6, "correct_answer": "黒い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は黒い鼻歌で、友人を励ました。", "explanation": "ここは〈明るい〉の意味（楽しい雰囲気）。〈黒い〉は色を表す語なので、鼻歌の調子には使わない。"}, {"text": "彼の声は黒く、低くて遠くまで響いた。", "explanation": "声の質には〈低い〉〈太い〉などを使う。〈黒い〉は色を表す語で、声には使わない。"}, {"text": "この味噌汁は黒い味がして、おいしかった。", "explanation": "味には〈濃い〉〈薄い〉などを使う。〈黒い〉は色の語で、味の説明には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36917, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓の外は、もう黒いった。", "corrected_sentence": "窓の外は、もう黒かった。", "error_description": "「黒いった」は過去形の誤り。形容詞の過去形は「黒かった」になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "黒い", "is_correct": true, "explanation": "正解。名詞「雲」を修飾する連体形。"}, {"text": "黒く", "is_correct": false, "explanation": "連用形で、名詞「雲」を直接修飾できない。"}, {"text": "黒くて", "is_correct": false, "explanation": "て形は文を続ける形で、「黒くて雲」のように名詞を修飾できない。"}, {"text": "黒ければ", "is_correct": false, "explanation": "仮定形で、名詞「雲」を修飾できず文が成り立たない。"}], "correct_form": "黒い", "base_form": "黒い", "form_label": "連体形", "sentence_index": 1, "explanations": {"黒い": "正解。名詞「雲」を修飾する連体形。", "黒く": "連用形で、名詞「雲」を直接修飾できない。", "黒くて": "て形は文を続ける形で、「黒くて雲」のように名詞を修飾できない。", "黒ければ": "仮定形で、名詞「雲」を修飾できず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36917, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "黒ければ焦げたトーストは、食べられない。", "corrected_sentence": "黒く焦げたトーストは、食べられない。", "error_description": "「黒ければ」は仮定形で、名詞「トースト」を修飾できない。「焦げた」を詳しく述べるには連用形「黒く」が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "黒い", "is_correct": true, "explanation": "正解。名詞「影」を修飾する連体形。"}, {"text": "黒かろう", "is_correct": false, "explanation": "推量形で、名詞「影」を直接修飾できない。「黒かろう影」は不自然。"}, {"text": "黒けれど", "is_correct": false, "explanation": "逆接の接続形で、名詞「影」を修飾できず文が成り立たない。"}, {"text": "黒さ", "is_correct": false, "explanation": "名詞化した形で、「黒さ影」のように形容詞として名詞を修飾できない。"}], "correct_form": "黒い", "base_form": "黒い", "form_label": "連体形", "sentence_index": 7, "explanations": {"黒い": "正解。名詞「影」を修飾する連体形。", "黒かろう": "推量形で、名詞「影」を直接修飾できない。「黒かろう影」は不自然。", "黒けれど": "逆接の接続形で、名詞「影」を修飾できず文が成り立たない。", "黒さ": "名詞化した形で、「黒さ影」のように形容詞として名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36918, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「に」は種をまく場所・対象を示し、「プランターに種をまいた」が自然な文になる。"}, {"text": "を", "is_correct": false, "explanation": "「まく」はすでに「種を」が目的語なので、「プランターを」を重ねると不自然になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、「プランターが種をまいた」では容器が行為者になってしまう。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すため、「プランターから種をまいた」では場所として合わない。"}], "correct_answer": "に", "explanations": {"に": "「に」は種をまく場所・対象を示し、「プランターに種をまいた」が自然な文になる。", "を": "「まく」はすでに「種を」が目的語なので、「プランターを」を重ねると不自然になる。", "が": "「が」は主語を示すため、「プランターが種をまいた」では容器が行為者になってしまう。", "から": "「から」は起点を示すため、「プランターから種をまいた」では場所として合わない。"}, "error_tags": {"を": "object_clash", "が": "subject", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36918, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「捨てる」の対象を示す「を」で、「プランターを捨てて」と意味が通る。"}, {"text": "と", "is_correct": false, "explanation": "「と」は「一緒に」を表すので、「プランターと捨てて」では意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ助詞で、動詞「捨てて」の前には置けない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所を表すので、「プランターで捨てて」では捨てる対象が示せない。"}], "correct_answer": "を", "explanations": {"を": "「捨てる」の対象を示す「を」で、「プランターを捨てて」と意味が通る。", "と": "「と」は「一緒に」を表すので、「プランターと捨てて」では意味が通らない。", "の": "「の」は名詞どうしをつなぐ助詞で、動詞「捨てて」の前には置けない。", "で": "「で」は手段・場所を表すので、「プランターで捨てて」では捨てる対象が示せない。"}, "error_tags": {"と": "companion", "の": "possessive", "で": "means"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36918, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "花や野菜を植えるための、土を入れる箱や入れ物のことです。", "primary_collocate": null, "pronunciation": "ぷらんたー", "ipa": "pɯɾaɴtaː", "syllable_count": 5, "sentences": [{"text": "ベランダのプランターでミニトマトを育てている。", "target_word": "プランター", "complexity_tier": "T3", "furigana": "ベランダのプランターでミニトマトを育[そだ]てている。", "sentence_source": "generated"}, {"text": "庭がないので、プランターにバジルの種をまいた。", "target_word": "プランター", "complexity_tier": "T3", "furigana": "庭[にわ]がないので、プランターにバジルの種[たね]をまいた。", "sentence_source": "generated"}, {"text": "雨が続いたため、プランターの水があふれてしまった。", "target_word": "プランター", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]いたため、プランターの水[みず]があふれてしまった。", "sentence_source": "generated"}, {"text": "母は細長いプランターに赤い花を並べて植えた。", "target_word": "プランター", "complexity_tier": "T3", "furigana": "母[はは]は細長[ほそなが]いプランターに赤[あか]い花[はな]を並[なら]べて植[う]えた。", "sentence_source": "generated"}, {"text": "小さなプランターなので、大きな野菜は育たない。", "target_word": "プランター", "complexity_tier": "T3", "furigana": "小[ちい]さなプランターなので、大[おお]きな野菜[やさい]は育[そだ]たない。", "sentence_source": "generated"}, {"text": "プランターの底に穴があいていて、余った水が出る。", "target_word": "プランター", "complexity_tier": "T3", "furigana": "プランターの底[そこ]に穴[あな]があいていて、余[あま]った水[みず]が出[で]る。", "sentence_source": "generated"}, {"text": "風が強い日は、プランターを部屋の中に入れる。", "target_word": "プランター", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]い日[ひ]は、プランターを部屋[へや]の中[なか]に入[い]れる。", "sentence_source": "generated"}, {"text": "古いプランターを捨てて、新しいのを買った。", "target_word": "プランター", "complexity_tier": "T3", "furigana": "古[ふる]いプランターを捨[す]てて、新[あたら]しいのを買[か]った。", "sentence_source": "generated"}, {"text": "窓の下に置いたプランターから、小さな芽が出てきた。", "target_word": "プランター", "complexity_tier": "T3", "furigana": "窓[まど]の下[した]に置[お]いたプランターから、小[ちい]さな芽[め]が出[で]てきた。", "sentence_source": "generated"}, {"text": "兄はプランターに土を入れて、ネギを植える準備をした。", "target_word": "プランター", "complexity_tier": "T3", "furigana": "兄[あに]はプランターに土[つち]を入[い]れて、ネギを植[う]える準備[じゅんび]をした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プランター", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "家庭で花や野菜を植える、土を入れる箱型の入れ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e61b9b9-2b71-463a-b7c3-934bb8c70858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36918, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "プランター", "is_correct": true, "explanation": "植物を植えて育てる容器なので、ベランダでの栽培の文脈に合う。"}, {"text": "洗濯機", "is_correct": false, "explanation": "洗濯をする家電で、植物を育てる場所にはならないので合わない。"}, {"text": "掃除機", "is_correct": false, "explanation": "掃除に使う家電で、ベランダで野菜を育てる入れ物として置くものではない。"}, {"text": "花火", "is_correct": false, "explanation": "夏の遊びに使う道具で、野菜を育てる入れ物ではないので合わない。"}], "explanations": {"プランター": "植物を植えて育てる容器なので、ベランダでの栽培の文脈に合う。", "洗濯機": "洗濯をする家電で、植物を育てる場所にはならないので合わない。", "掃除機": "掃除に使う家電で、ベランダで野菜を育てる入れ物として置くものではない。", "花火": "夏の遊びに使う道具で、野菜を育てる入れ物ではないので合わない。"}, "sentence_index": 0, "correct_answer": "プランター"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、プランターで髪をとかした。", "explanation": "プランターは植物用の容器で、髪をとかす道具の意味では使わない。"}, {"text": "彼は広告会社で、新商品を企画するプランターとして働いている。", "explanation": "ここは〈プランナー〉（企画をする人）の意味。プランターは植物を植える容器で、人を指す語としては使わない。"}, {"text": "大きなプランターにサラダを盛りつけた。", "explanation": "プランターは植物用の容器で、料理を盛る器の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36918, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "プランター", "is_correct": true, "explanation": "土を入れて植物を育てる容器で、部屋の中に入れられる大きさの対象として合う。"}, {"text": "演説", "is_correct": false, "explanation": "話して伝える行為なので、部屋の中に入れる対象にならない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "空に見える現象で、物として部屋の中に入れることはできない。"}, {"text": "相談", "is_correct": false, "explanation": "人との話し合いで、物のように部屋の中に入れる対象ではない。"}], "explanations": {"プランター": "土を入れて植物を育てる容器で、部屋の中に入れられる大きさの対象として合う。", "演説": "話して伝える行為なので、部屋の中に入れる対象にならない。", "夕焼け": "空に見える現象で、物として部屋の中に入れることはできない。", "相談": "人との話し合いで、物のように部屋の中に入れる対象ではない。"}, "sentence_index": 6, "correct_answer": "プランター"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "湖の水を採って、顕微鏡でプランターを観察した。", "explanation": "プランターは植物用の容器で、水中の生き物の意味では使わない。"}, {"text": "寒い夜は、プランターを体に掛けて寝た。", "explanation": "プランターは植物用の容器で、体に掛ける布の意味では使わない。"}, {"text": "大きなプランターに水をためて、野菜を洗った。", "explanation": "プランターは植物用の容器で、水をためて洗い物に使う器の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36918, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ベランダのプランターを、トマトの苗を育てている。", "corrected_sentence": "ベランダのプランターで、トマトの苗を育てている。", "error_description": "正しくは「プランターで」（手段・場所）。「を」にすると目的語が二つ重なり不自然になる。誤りは「で」を「を」にした一か所。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36918, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日は、プランターが玄関に入れる。", "corrected_sentence": "雨の日は、プランターを玄関に入れる。", "error_description": "正しくは「プランターを」（入れる対象）。「が」にすると主語になり、「入れる」の目的語がなくなる。誤りは「を」を「が」にした一か所。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
