INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36920, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "体の中に力があって、元気なようす。", "primary_collocate": null, "pronunciation": "げんき", "ipa": "ɡeŋki", "syllable_count": 3, "sentences": [{"text": "朝ごはんをしっかり食べると、一日元気に動ける。", "target_word": "元気", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんをしっかり食[た]べると、一日[いちにち]元気[げんき]に動[うご]ける。", "sentence_source": "generated"}, {"text": "熱が下がって、弟はすっかり元気になった。", "target_word": "元気", "complexity_tier": "T3", "furigana": "熱[ねつ]が下[さ]がって、弟[おとうと]はすっかり元気[げんき]になった。", "sentence_source": "generated"}, {"text": "おじいさんは元気で、今も畑で働いています。", "target_word": "元気", "complexity_tier": "T2", "furigana": "おじいさんは元気[げんき]で、今[いま]も畑[はたけ]で働[はたら]いています。", "sentence_source": "generated"}, {"text": "夜よく眠ったので、今朝は体が軽くて元気です。", "target_word": "元気", "complexity_tier": "T3", "furigana": "夜[よる]よく眠[ねむ]ったので、今朝[けさ]は体[からだ]が軽[かる]くて元気[げんき]です。", "sentence_source": "generated"}, {"text": "元気がないときは、無理をしないで休みましょう。", "target_word": "元気", "complexity_tier": "T3", "furigana": "元気[げんき]がないときは、無理[むり]をしないで休[やす]みましょう。", "sentence_source": "generated"}, {"text": "彼女は元気に手を振って、駅で私たちを見送った。", "target_word": "元気", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は元気[げんき]に手[て]を振[ふ]って、駅[えき]で私[わたし]たちを見送[みおく]った。", "sentence_source": "generated"}, {"text": "運動を続けているおかげで、父は年のわりに元気だ。", "target_word": "元気", "complexity_tier": "T3", "furigana": "運動[うんどう]を続[つづ]けているおかげで、父[ちち]は年[とし]のわりに元気[げんき]だ。", "sentence_source": "generated"}, {"text": "元気な赤ちゃんが生まれて、家族みんなが喜んだ。", "target_word": "元気", "complexity_tier": "T3", "furigana": "元気[げんき]な赤[あか]ちゃんが生[う]まれて、家族[かぞく]みんなが喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "毎日野菜を食べて、元気な体をつくりたい。", "target_word": "元気", "complexity_tier": "T3", "furigana": "毎日[まいにち]野菜[やさい]を食[た]べて、元気[げんき]な体[からだ]をつくりたい。", "sentence_source": "generated"}, {"text": "手紙には「私は元気です」と書いてあった。", "target_word": "元気", "complexity_tier": "T2", "furigana": "手紙[てがみ]には「私[わたし]は元気[げんき]です」と書[か]いてあった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "元気", "label": "語幹"}, {"form": "元気な", "label": "連体形"}, {"form": "元気に", "label": "連用形"}, {"form": "元気で", "label": "て形"}, {"form": "元気だ", "label": "終止形"}, {"form": "元気だった", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "体に力があり、病気でなく動ける様子（初級向けの「元気」）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b8cef-ab8c-4182-8873-0e78b475e8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36920, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "元気", "is_correct": true, "explanation": "形状詞の語幹。「一日元気に動ける」と連用形で続き、体の様子を表すので空所に入る。"}, {"text": "元気な", "is_correct": false, "explanation": "連体形。「一日元気な動ける」と続かず、文の形に合わない。"}, {"text": "元気だった", "is_correct": false, "explanation": "過去形。「一日元気だった動ける」と続かない。"}, {"text": "元気だ", "is_correct": false, "explanation": "終止形。「一日元気だに動ける」となり、ここでは続かない。"}], "explanations": {"元気": "形状詞の語幹。「一日元気に動ける」と連用形で続き、体の様子を表すので空所に入る。", "元気な": "連体形。「一日元気な動ける」と続かず、文の形に合わない。", "元気だった": "過去形。「一日元気だった動ける」と続かない。", "元気だ": "終止形。「一日元気だに動ける」となり、ここでは続かない。"}, "sentence_index": 0, "correct_answer": "元気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬は元気なので、よく効く。", "explanation": "薬の効き目の強さは「強い」で表す。「元気」は人の体や気力の様子を表すので、薬の効き目には使わない。"}, {"text": "毎日、元気な食生活を心がけている。", "explanation": "食生活の健全さは「健康な食生活」と言い、「元気な食生活」とは言わない。「元気」は人の体や気力の様子を表す語である。"}, {"text": "弟の元気は、もうすっかり治った。", "explanation": "「元気」は治る対象ではない。病気の回復は「病気が治る」で表し、「元気が治る」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36920, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "元気", "is_correct": true, "explanation": "形状詞の語幹。「年のわりに元気だ」と「だ」で文を結び、空所に入る。"}, {"text": "元気に", "is_correct": false, "explanation": "連用形。「年のわりに元気にだ」と続かず、文末の「だ」に合わない。"}, {"text": "元気で", "is_correct": false, "explanation": "て形。「年のわりに元気でだ」と続かず、文の形に合わない。"}, {"text": "元気なら", "is_correct": false, "explanation": "仮定形。「年のわりに元気ならだ」と続かず、文の形に合わない。"}], "explanations": {"元気": "形状詞の語幹。「年のわりに元気だ」と「だ」で文を結び、空所に入る。", "元気に": "連用形。「年のわりに元気にだ」と続かず、文末の「だ」に合わない。", "元気で": "て形。「年のわりに元気でだ」と続かず、文の形に合わない。", "元気なら": "仮定形。「年のわりに元気ならだ」と続かず、文の形に合わない。"}, "sentence_index": 6, "correct_answer": "元気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この橋は元気で、大型トラックも渡れる。", "explanation": "元気は人や動物の状態を表し、橋の頑丈さには使わない。頑丈さは「丈夫」で表す。"}, {"text": "この料理は元気で、塩気が強すぎて食べられない。", "explanation": "味の濃さは「濃い」で表す。「元気」は人の体や気力の様子を表すので、料理には使わない。"}, {"text": "明日の元気は晴れでしょう。", "explanation": "空模様は「天気」で表す。「元気」は人の体や気力を表すので、空模様には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36920, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は元気な、今も畑で働いている。", "corrected_sentence": "祖父は元気で、今も畑で働いている。", "error_description": "「元気」は後ろに続けるとき「元気で」（て形）になる。連体形の「元気な」では文が切れてしまい、誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "元気", "is_correct": true, "explanation": "語幹。活用語尾のつかない基本の形で、ここで問われる形と一致する。"}, {"text": "元気な", "is_correct": false, "explanation": "連体形。名詞の前に置く形で、「なった」の文に合わない。"}, {"text": "元気で", "is_correct": false, "explanation": "て形。「すっかり元気でになった」と続かない。"}, {"text": "元気だ", "is_correct": false, "explanation": "終止形。「元気だになった」とは続かない。"}], "correct_form": "元気", "base_form": "元気", "form_label": "語幹", "sentence_index": 1, "explanations": {"元気": "語幹。活用語尾のつかない基本の形で、ここで問われる形と一致する。", "元気な": "連体形。名詞の前に置く形で、「なった」の文に合わない。", "元気で": "て形。「すっかり元気でになった」と続かない。", "元気だ": "終止形。「元気だになった」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36920, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は元気を手を振って、駅で私を見送った。", "corrected_sentence": "妹は元気に手を振って、駅で私を見送った。", "error_description": "「手を振る」を修飾する副詞の「元気に」が必要。「元気を」は格助詞が誤りで、「元気を手を振って」は文として成立しない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "元気", "is_correct": true, "explanation": "語幹。「元気な赤ちゃん」の基本の形で、活用語尾のつかない形。"}, {"text": "元気に", "is_correct": false, "explanation": "連用形。「元気に赤ちゃん」と名詞を修飾できず、文の形に合わない。"}, {"text": "元気だった", "is_correct": false, "explanation": "過去形。「元気だった」は「な赤ちゃん」と続かず、「元気だったな赤ちゃん」となって文法的に誤り。"}, {"text": "元気なら", "is_correct": false, "explanation": "仮定形。「元気なら赤ちゃん」と名詞に続かず、文の形に合わない。"}], "correct_form": "元気", "base_form": "元気", "form_label": "語幹", "sentence_index": 7, "explanations": {"元気": "語幹。「元気な赤ちゃん」の基本の形で、活用語尾のつかない形。", "元気に": "連用形。「元気に赤ちゃん」と名詞を修飾できず、文の形に合わない。", "元気だった": "過去形。「元気だった」は「な赤ちゃん」と続かず、「元気だったな赤ちゃん」となって文法的に誤り。", "元気なら": "仮定形。「元気なら赤ちゃん」と名詞に続かず、文の形に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
